function _zymoCargarBackupEmbebido(){
  try {
    var tag = document.getElementById('zymo-backup-data');
    if(tag) return JSON.parse(tag.textContent);
  } catch(e){ console.warn('No se pudo cargar el backup embebido:', e); }
  return null;
}
