if(!db.records) db.records = [];
if(!db.matrizRiesgos) db.matrizRiesgos = {};

let selectedServices = [];
let currentTipo = 'prospecto';

function save() {
  try {
    localStorage.setItem('zymo-db', JSON.stringify(db));
  } catch(e) {
    // Cuota excedida — guardar version comprimida sin imagenes base64
    try {
      var dbLite = JSON.parse(JSON.stringify(db));
      // Eliminar imágenes base64 de biblioteca y cotizaciones que pesan mucho
      if(dbLite.biblioteca){
        Object.keys(dbLite.biblioteca).forEach(function(k){
          var bib = dbLite.biblioteca[k];
          if(bib.logo) bib.logo = '';
          if(bib.firma) bib.firma = '';
          if(bib.imagenes) bib.imagenes = [];
          if(bib.observaciones) bib.observaciones = bib.observaciones.map(function(o){
            if(o && o.html) o.html = o.html.replace(/data:image\/[^;]+;base64,[^"'\s]+/g,'[img]');
            return o;
          });
        });
      }
      // Eliminar imágenes de cotizaciones
      if(dbLite.cotizaciones) dbLite.cotizaciones = dbLite.cotizaciones.map(function(c){
        var nc = Object.assign({}, c);
        if(nc.imagenes) nc.imagenes = [];
        return nc;
      });
      localStorage.setItem('zymo-db', JSON.stringify(dbLite));
      console.warn('Guardado en modo comprimido (imágenes omitidas)');
    } catch(e2) {
      console.error('Error crítico al guardar:', e2);
      throw e2;
    }
  }
}

// Limpiar claves crm-meta-* antiguas de localStorage para liberar espacio
(function cleanOldCrmMeta(){
  try {
    var toDelete = [];
    for(var i=0; i<localStorage.length; i++){
      var k = localStorage.key(i);
      if(k && k.startsWith('crm-meta-')) toDelete.push(k);
    }
    toDelete.forEach(function(k){ localStorage.removeItem(k); });
  } catch(e){}
})();

// ============================================================
// TOAST NOTIFICATION
// ============================================================
function toast(icon, msg, color='#00c2ff'){
  const t = document.getElementById('toast');
  const i = document.getElementById('toast-icon');
  const m = document.getElementById('toast-msg');
  if(!t) return;
  i.textContent = icon; m.textContent = msg;
  t.style.display = 'block';
  t.querySelector('div').style.borderColor = color;
  setTimeout(()=>{ t.style.display='none'; }, 3000);
}

// ============================================================
// FORMATTING HELPERS
// ============================================================
function fmtDate(d){
  if(!d) return '—';
  const dt = new Date(d+'T12:00');
  return isNaN(dt)?d:dt.toLocaleDateString('es-CO',{day:'2-digit',month:'short',year:'numeric'});
}
function fmtMoney(v){
  const n = Number(v)||0;
  return '$'+Math.round(n).toLocaleString('es-CO');
}

// ============================================================
// BILLING LINES (formulario nuevo registro)
// ============================================================
function renderBillingLines(suffix, services){
  const container = document.getElementById(`f-billing-lines-${suffix}`);
  if(!container) return;
  if(!services||services.length===0){
    container.innerHTML='<div style="color:var(--text2);font-size:13px;grid-column:1/-1">Selecciona los servicios de interés primero.</div>';
    const te = document.getElementById(`f-total-${suffix}`);
    if(te) te.textContent='$0';
    return;
  }
  container.innerHTML = services.map(s=>`
    <div class="form-group">
      <label style="display:flex;align-items:center;gap:6px">
        <span style="display:inline-block;width:8px;height:8px;border-radius:2px;background:${SVC_COLORS[s]||'var(--accent)'}"></span>
        ${s}
      </label>
      <input type="number" id="bill-${suffix}-${s.replace(/\s+/g,'-').replace(/\//g,'-')}"
        placeholder="0" min="0"
        oninput="updateBillingTotal('${suffix}')"
        style="text-align:right">
    </div>`).join('');
  updateBillingTotal(suffix);
}

function updateBillingTotal(suffix){
  const inputs = document.querySelectorAll(`[id^="bill-${suffix}-"]`);
  let total = 0;
  inputs.forEach(i=>total+=Number(i.value)||0);
  const el = document.getElementById(`f-total-${suffix}`);
  if(el) el.textContent = '$'+total.toLocaleString('es-CO');
}

function getBillingLines(suffix){
  const inputs = document.querySelectorAll(`[id^="bill-${suffix}-"]`);
  const result = {};
  inputs.forEach(i=>{
    const val = Number(i.value)||0;
    if(val>0){
      const match = SERVICES.find(s=>s.replace(/\s+/g,'-').replace(/\//g,'-')===i.id.replace(`bill-${suffix}-`,''));
      if(match) result[match] = val;
    }
  });
  return result;
}

function onFacturadoChange(val, suffix){
  const block = document.getElementById(`f-billing-block-${suffix}`);
  if(block) block.style.display = (val!=='no')?'block':'none';
}

