// ============================================================
// DASHBOARD
// ============================================================
const charts = {};
function destroyChart(key){
  if(charts[key]){ try{ charts[key].destroy(); }catch(e){} delete charts[key]; }
}

function renderDashboard(){
  const filterCom = document.getElementById('dash-filter-comercial')?.value||'';
  const filterMes = document.getElementById('dash-filter-mes')?.value||'';
  const filterTipo = document.getElementById('dash-filter-tipo')?.value||'';

  let recs = db.records;
  if(filterCom)  recs = recs.filter(r=>r.comercialId===filterCom);
  if(filterMes)  recs = recs.filter(r=>(r.fecha||'').startsWith(filterMes));
  if(filterTipo) recs = recs.filter(r=>r.tipo===filterTipo);

  // Banner filtros activos
  const banner = document.getElementById('dash-comercial-banner');
  const parts = [];
  if(filterCom){ const c=db.comerciales.find(x=>x.id===filterCom); parts.push(`👤 <strong>${c?.nombre||'—'}</strong>`); }
  if(filterMes){ const [y,mo]=filterMes.split('-'); const lbl=new Date(+y,+mo-1,1).toLocaleDateString('es-CO',{month:'long',year:'numeric'}); parts.push(`📅 <strong>${lbl.charAt(0).toUpperCase()+lbl.slice(1)}</strong>`); }
  if(filterTipo) parts.push(filterTipo==='prospecto'?'🎯 <strong>Solo Prospectos</strong>':'🏢 <strong>Solo Clientes</strong>');
  if(parts.length){ banner.style.display='block'; banner.innerHTML='Filtros activos: '+parts.join(' &nbsp;·&nbsp; ')+` &nbsp;<span style="color:var(--text2);font-weight:400;font-size:12px">(${recs.length} registros)</span>`; }
  else banner.style.display='none';

  const total = recs.length;
  const prospectos = recs.filter(r=>r.tipo==='prospecto').length;
  const clientes = recs.filter(r=>r.tipo==='cliente').length;
  const visitas = recs.filter(r=>(r.visita&&r.visita!=='no')||(r.visitaCliente&&r.visitaCliente!=='no')).length;
  // Pipeline activo: estados antes de cierre
  const ESTADOS_ACTIVOS = ['prospecto','reconocimiento','propuesta','aceptacion_propuesta','creacion_sop'];
  const enPipeline = recs.filter(r=>r.tipo==='prospecto'&&ESTADOS_ACTIVOS.includes(r.estadoProspecto||'prospecto')).length;
  const facturados = recs.filter(r=>r.tipo==='prospecto'&&r.estadoProspecto==='facturado').length;
  const perdidos   = recs.filter(r=>r.tipo==='prospecto'&&(r.estadoProspecto==='perdido'||r.estadoProspecto==='frio')).length;

  document.getElementById('stats-row').innerHTML = `
    <div class="stat-card blue"><div class="stat-label">Total Registros</div><div class="stat-value">${total}</div><div class="stat-sub">Empresas en sistema</div></div>
    <div class="stat-card cyan"><div class="stat-label">Prospectos</div><div class="stat-value">${prospectos}</div><div class="stat-sub">En pipeline</div></div>
    <div class="stat-card green"><div class="stat-label">Clientes</div><div class="stat-value">${clientes}</div><div class="stat-sub">Bajo gestión</div></div>
    <div class="stat-card gold"><div class="stat-label">Facturados</div><div class="stat-value">${facturados}</div><div class="stat-sub">Prospectos facturados</div></div>
    <div class="stat-card purple"><div class="stat-label">En Gestión</div><div class="stat-value">${enPipeline}</div><div class="stat-sub">Prospectos activos</div></div>
    <div class="stat-card red"><div class="stat-label">Visitas / Contactos</div><div class="stat-value">${visitas}</div><div class="stat-sub">Total realizados</div></div>`;

  // Recent table
  const recent = [...recs].reverse().slice(0,8);
  const recentTbl = document.getElementById('recent-table');
  if(recentTbl) recentTbl.innerHTML = recent.map(r=>`<tr>
    <td><strong>${r.empresa}</strong></td>
    <td>${r.tipo==='prospecto'?'<span class="badge badge-blue">Prospecto</span>':'<span class="badge badge-green">Cliente</span>'}</td>
    <td style="font-size:12px">${r.comercialNombre}</td>
    <td><div class="service-tags">${(r.servicios||[]).slice(0,3).map(s=>`<span class="stag">${s}</span>`).join('')}${r.servicios?.length>3?`<span class="stag">+${r.servicios.length-3}</span>`:''}</div></td>
    <td>${estadoBadge(r)}</td>
    <td style="font-size:12px;color:var(--text2)">${r.fecha||'—'}</td>
  </tr>`).join('') || `<tr><td colspan="6"><div class="empty-state"><div class="empty-icon">📊</div><div class="empty-title">Sin registros</div></div></td></tr>`;

  // Use rAF to ensure canvases have dimensions before drawing
  requestAnimationFrame(()=>{
    drawCharts(recs, filterCom);
    renderBillingDashboard(recs);
    renderCotDashboard();
  });
}



function renderBillingDashboard(recs){
  const totals = {};
  SERVICES.forEach(s=>totals[s]=0);
  recs.forEach(r=>{
    const lines = r.facturacionLineas||{};
    SERVICES.forEach(s=>{ if(lines[s]) totals[s]+=(Number(lines[s])||0); });
    if(!r.facturacionLineas){
      const val = Number(r.tipo==='prospecto'?r.valorP:r.valor)||0;
      if(val>0 && r.servicios?.length){
        const share = val/r.servicios.length;
        r.servicios.forEach(s=>{ if(totals[s]!==undefined) totals[s]+=share; });
      }
    }
  });

  const grandTotal = Object.values(totals).reduce((a,b)=>a+b,0);
  const maxVal = Math.max(...Object.values(totals),1);

  const list = document.getElementById('billing-lines-list');
  if(list){
    list.innerHTML = SERVICES.map(s=>{
      const val = totals[s]||0;
      const pct = grandTotal>0?Math.round(val/grandTotal*100):0;
      const color = SVC_COLORS[s]||'var(--accent)';
      return `
        <div style="margin-bottom:14px">
          <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px">
            <div style="display:flex;align-items:center;gap:7px">
              <span style="display:inline-block;width:10px;height:10px;border-radius:2px;background:${color}"></span>
              <span style="font-size:13px;font-weight:500">${s}</span>
            </div>
            <div style="text-align:right">
              <span style="font-family:'Barlow Condensed',sans-serif;font-size:15px;font-weight:700;color:${color}">$${Math.round(val).toLocaleString('es-CO')}</span>
              <span style="font-size:11px;color:var(--text2);margin-left:6px">${pct}%</span>
            </div>
          </div>
          <div style="background:var(--surface2);border-radius:4px;height:6px;overflow:hidden">
            <div style="height:100%;border-radius:4px;background:${color};width:${val>0?Math.max(val/maxVal*100,2):0}%;transition:width 0.5s"></div>
          </div>
        </div>`;
    }).join('');
  }

  const totalEl = document.getElementById('billing-total-dash');
  if(totalEl) totalEl.textContent = '$'+Math.round(grandTotal).toLocaleString('es-CO');

  destroyChart('billing');
  const nonZero = SERVICES.filter(s=>totals[s]>0);
  const billingCanvas = document.getElementById('chart-billing');
  if(!billingCanvas) return;
  if(nonZero.length===0){ billingCanvas.style.display='none'; return; }
  billingCanvas.style.display='';
  charts.billing = new Chart(billingCanvas,{
    type:'doughnut',
    data:{
      labels: nonZero,
      datasets:[{
        data: nonZero.map(s=>Math.round(totals[s])),
        backgroundColor: nonZero.map(s=>SVC_COLORS[s]||'var(--accent)'),
        borderColor: '#111827',
        borderWidth: 3
      }]
    },
    options:{
      responsive:true, maintainAspectRatio:false,
      plugins:{
        legend:{display:false},
        tooltip:{callbacks:{
          label: ctx=>`${ctx.label}: $${ctx.parsed.toLocaleString('es-CO')} (${grandTotal>0?Math.round(ctx.parsed/grandTotal*100):0}%)`
        }}
      }
    }
  });
}

function renderCotDashboard(){
  const cots = db.cotizaciones||[];
  const total = cots.length;
  const aprobadas  = cots.filter(c=>c.estado==='aprobada').length;
  const borradores = cots.filter(c=>c.estado==='borrador'||!c.estado).length;
  const enviadas   = cots.filter(c=>c.estado==='enviada').length;
  const negociacion= cots.filter(c=>c.estado==='negociacion').length;
  const rechazadas = cots.filter(c=>c.estado==='rechazada').length;
  const enCurso    = borradores + enviadas + negociacion;
  const hoy = new Date();
  const vencidas = cots.filter(c=>{
    const venc = resolveVigencia(c);
    return venc < hoy && c.estado!=='aprobada' && c.estado!=='rechazada';
  }).length;

  const kpisEl = document.getElementById('dash-cot-kpis');
  if(kpisEl) kpisEl.innerHTML = `
    <div class="stat-card blue"><div class="stat-label">Total Cotizaciones</div><div class="stat-value">${total}</div><div class="stat-sub">Emitidas</div></div>
    <div class="stat-card green"><div class="stat-label">Aprobadas</div><div class="stat-value">${aprobadas}</div><div class="stat-sub">Confirmadas</div></div>
    <div class="stat-card gold"><div class="stat-label">En Curso</div><div class="stat-value">${enCurso}</div><div class="stat-sub">Borrador · Enviada · Neg.</div></div>
    <div class="stat-card red"><div class="stat-label">Vencidas</div><div class="stat-value">${vencidas}</div><div class="stat-sub">Sin respuesta</div></div>`;

  // Pipeline chart
  destroyChart('cot-estados');
  const cotCanvas = document.getElementById('chart-cot-estados');
  if(cotCanvas){
    if(total > 0){
      charts['cot-estados'] = new Chart(cotCanvas,{
        type:'doughnut',
        data:{
          labels:['Aprobada','Borrador','Enviada','Negociación','Rechazada','Vencida'],
          datasets:[{data:[aprobadas,borradores,enviadas,negociacion,rechazadas,vencidas],
            backgroundColor:['rgba(0,230,118,0.8)','rgba(136,153,180,0.5)','rgba(0,194,255,0.8)','rgba(245,166,35,0.8)','rgba(255,68,68,0.8)','rgba(200,50,50,0.6)'],
            borderWidth:2}]
        },
        options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom',labels:{padding:14,usePointStyle:true,font:{size:11}}}}}
      });
      cotCanvas.style.display = '';
      const parent = cotCanvas.parentElement;
      const empty = parent.querySelector('.cot-empty-estado');
      if(empty) empty.remove();
    } else {
      cotCanvas.style.display = 'none';
      const parent = cotCanvas.parentElement;
      if(!parent.querySelector('.cot-empty-estado')){
        const div = document.createElement('div');
        div.className = 'cot-empty-estado empty-state';
        div.style.cssText = 'padding:40px 0;text-align:center';
        div.innerHTML = '<div style="font-size:32px;margin-bottom:8px">📄</div><div style="color:var(--text2);font-size:13px">Sin cotizaciones aún</div>';
        parent.appendChild(div);
      }
    }
  }

  // Cotizaciones por línea
  destroyChart('cot-lineas');
  const cotLineasCanvas = document.getElementById('chart-cot-lineas');
  if(cotLineasCanvas){
    const lineasCount = {};
    SERVICES.forEach(s=>lineasCount[s]=0);
    cots.forEach(c=>{ (c.lineas||[]).forEach(s=>{ if(lineasCount[s]!==undefined) lineasCount[s]++; }); });
    const nonZeroL = SERVICES.filter(s=>lineasCount[s]>0);
    if(nonZeroL.length>0){
      cotLineasCanvas.style.display = '';
      const parent2 = cotLineasCanvas.parentElement;
      const empty2 = parent2.querySelector('.cot-empty-lineas');
      if(empty2) empty2.remove();
      charts['cot-lineas'] = new Chart(cotLineasCanvas,{
        type:'bar',
        data:{
          labels:nonZeroL,
          datasets:[{label:'Cotizaciones',data:nonZeroL.map(s=>lineasCount[s]),
            backgroundColor:nonZeroL.map(s=>SVC_COLORS[s]||'var(--accent)'),borderWidth:0,borderRadius:4}]
        },
        options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{stepSize:1}}}}
      });
    } else {
      cotLineasCanvas.style.display = 'none';
      const parent2 = cotLineasCanvas.parentElement;
      if(!parent2.querySelector('.cot-empty-lineas')){
        const div2 = document.createElement('div');
        div2.className = 'cot-empty-lineas empty-state';
        div2.style.cssText = 'padding:40px 0;text-align:center';
        div2.innerHTML = '<div style="font-size:32px;margin-bottom:8px">📊</div><div style="color:var(--text2);font-size:13px">Sin líneas cotizadas aún</div>';
        parent2.appendChild(div2);
      }
    }
  }

  // Recent cotizaciones table
  const cotTableEl = document.getElementById('dash-cot-table');
  if(cotTableEl){
    const recent = [...cots].reverse().slice(0,6);
    cotTableEl.innerHTML = recent.map(c=>{
      const venc = resolveVigencia(c);
      const isVenc = venc < hoy && c.estado!=='aprobada' && c.estado!=='rechazada';
      const estBadge = c.estado==='aprobada'   ?'<span class="badge badge-green">✅ Aprobada</span>':
        c.estado==='rechazada'  ?'<span class="badge badge-red">❌ Rechazada</span>':
        isVenc                  ?'<span class="badge badge-red">⌛ Vencida</span>':
        c.estado==='negociacion'?'<span class="badge badge-gold">🤝 Negociación</span>':
        c.estado==='enviada'    ?'<span class="badge badge-cyan">📤 Enviada</span>':
        '<span class="badge badge-gray">📝 Borrador</span>';
      return `<tr>
        <td><strong>${c.numero||'—'}</strong></td>
        <td>${c.empresa||'—'}</td>
        <td><div class="service-tags">${(c.lineas||[]).map(s=>`<span class="stag">${s}</span>`).join('')}</div></td>
        <td>${estBadge}</td>
        <td style="font-size:12px;color:var(--text2)">${c.fecha||'—'}</td>
        <td><button class="btn btn-secondary btn-sm" onclick="verCotizacion('${c.id}')">Ver</button></td>
      </tr>`;
    }).join('') || `<tr><td colspan="6"><div class="empty-state"><div class="empty-icon">📄</div><div class="empty-title">Sin cotizaciones</div></div></td></tr>`;
  }
}

function resolveVigencia(cot){
  if(cot.vigencia && /^\d{4}-\d{2}-\d{2}$/.test(cot.vigencia)) return new Date(cot.vigencia+'T12:00');
  const d = new Date((cot.fecha||'')+'T12:00');
  d.setDate(d.getDate()+(+cot.vigencia||30));
  return d;
}

function drawCharts(recs, filterCom){
  if(!recs) recs = db.records;
  if(!filterCom) filterCom = '';
  const C = Chart.defaults;
  C.color = '#8899b4';
  C.font.family = 'Barlow, sans-serif';

  // 1. Tipo doughnut
  destroyChart('tipo');
  const p = recs.filter(r=>r.tipo==='prospecto').length;
  const c = recs.filter(r=>r.tipo==='cliente').length;
  const tipoCanvas = document.getElementById('chart-tipo');
  if(tipoCanvas) charts.tipo = new Chart(tipoCanvas,{
    type:'doughnut',
    data:{labels:['Prospectos','Clientes'],datasets:[{data:[p,c],backgroundColor:['rgba(0,194,255,0.8)','rgba(0,230,118,0.8)'],borderColor:['#00c2ff','#00e676'],borderWidth:2}]},
    options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom',labels:{padding:16,usePointStyle:true}}}}
  });

  // 2. Estado pipeline — embudo completo
  destroyChart('estado');
  const estados = ['prospecto','reconocimiento','propuesta','aceptacion_propuesta','creacion_sop','facturado','frio','perdido'];
  const stateLabels = ['Prospecto','Visita','Propuesta Comercial','Acept. Propuesta Comercial','Creación Ficha Cliente','Facturado','Frío','Perdido'];
  const stateCounts = estados.map(s=>recs.filter(r=>r.estadoProspecto===s).length);
  const stateColors = ['rgba(0,194,255,0.8)','rgba(0,194,255,0.6)','rgba(168,85,247,0.8)','rgba(168,85,247,0.6)','rgba(245,166,35,0.8)','rgba(245,166,35,0.6)','rgba(0,230,118,0.8)','rgba(0,230,118,0.6)','rgba(0,230,118,1)','rgba(136,153,180,0.6)','rgba(255,68,68,0.8)'];
  const estadoCanvas = document.getElementById('chart-estado');
  if(estadoCanvas) charts.estado = new Chart(estadoCanvas,{
    type:'bar',
    data:{labels:stateLabels,datasets:[{data:stateCounts,backgroundColor:stateColors,borderRadius:4,borderWidth:0}]},
    options:{responsive:true,maintainAspectRatio:false,indexAxis:'y',plugins:{legend:{display:false}},scales:{x:{beginAtZero:true,ticks:{precision:0}}}}
  });

  // 3. Servicios bar
  destroyChart('servicios');
  const svcCount = {};
  SERVICES.forEach(s=>svcCount[s]=0);
  recs.forEach(r=>(r.servicios||[]).forEach(s=>{ if(svcCount[s]!==undefined) svcCount[s]++; }));
  const svcCanvas = document.getElementById('chart-servicios');
  if(svcCanvas) charts.servicios = new Chart(svcCanvas,{
    type:'bar',
    data:{
      labels: SERVICES,
      datasets:[{label:'Empresas',data:SERVICES.map(s=>svcCount[s]),
        backgroundColor:SERVICES.map(s=>SVC_COLORS[s]||'var(--accent)'),
        borderWidth:0, borderRadius:6}]
    },
    options:{responsive:true,maintainAspectRatio:false,
      plugins:{legend:{display:false}},
      scales:{y:{beginAtZero:true,ticks:{stepSize:1}},x:{ticks:{font:{size:10}}}}}
  });

  // 4. Comercial bar
  destroyChart('comercial');
  const comCanvas = document.getElementById('chart-comercial');
  if(comCanvas){
    const coms = filterCom ? db.comerciales.filter(x=>x.id===filterCom) : db.comerciales;
    charts.comercial = new Chart(comCanvas,{
      type:'bar',
      data:{
        labels: coms.map(x=>x.nombre.split(' ')[0]),
        datasets:[
          {label:'Prospectos',data:coms.map(x=>recs.filter(r=>r.comercialId===x.id&&r.tipo==='prospecto').length),backgroundColor:'rgba(0,194,255,0.7)',borderWidth:0,borderRadius:4},
          {label:'Clientes',data:coms.map(x=>recs.filter(r=>r.comercialId===x.id&&r.tipo==='cliente').length),backgroundColor:'rgba(0,230,118,0.7)',borderWidth:0,borderRadius:4}
        ]
      },
      options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom'}},scales:{y:{beginAtZero:true,ticks:{stepSize:1}}}}
    });
  }

  // 5. Registros por Mes (timeline line chart)
  destroyChart('timeline');
  const tlCanvas = document.getElementById('chart-timeline');
  if(tlCanvas){
    // Build month buckets from last 12 months
    const now = new Date();
    const monthBuckets = [];
    for(let m = 11; m >= 0; m--){
      const d = new Date(now.getFullYear(), now.getMonth() - m, 1);
      const key = d.toISOString().slice(0,7);
      const label = d.toLocaleDateString('es-CO',{month:'short', year:'2-digit'});
      monthBuckets.push({ key, label, prospectos:0, clientes:0 });
    }
    recs.forEach(r=>{
      const mes = (r.fecha||'').slice(0,7);
      const bucket = monthBuckets.find(b=>b.key===mes);
      if(bucket){
        if(r.tipo==='prospecto') bucket.prospectos++;
        else bucket.clientes++;
      }
    });
    // Only render months that have at least one record, or keep all 12
    charts.timeline = new Chart(tlCanvas,{
      type:'line',
      data:{
        labels: monthBuckets.map(b=>b.label),
        datasets:[
          {
            label:'Prospectos',
            data: monthBuckets.map(b=>b.prospectos),
            borderColor:'#00c2ff', backgroundColor:'rgba(0,194,255,0.08)',
            borderWidth:2, pointRadius:4, pointBackgroundColor:'#00c2ff',
            tension:0.35, fill:true
          },
          {
            label:'Clientes',
            data: monthBuckets.map(b=>b.clientes),
            borderColor:'#00e676', backgroundColor:'rgba(0,230,118,0.08)',
            borderWidth:2, pointRadius:4, pointBackgroundColor:'#00e676',
            tension:0.35, fill:true
          }
        ]
      },
      options:{
        responsive:true, maintainAspectRatio:false,
        interaction:{ mode:'index', intersect:false },
        plugins:{
          legend:{ position:'bottom', labels:{ padding:16, usePointStyle:true } },
          tooltip:{ callbacks:{ title: ctx => ctx[0].label } }
        },
        scales:{
          y:{ beginAtZero:true, ticks:{ stepSize:1 }, grid:{ color:'rgba(136,153,180,0.1)' } },
          x:{ ticks:{ font:{ size:10 } }, grid:{ display:false } }
        }
      }
    });
  }

  // 6. Gestión Clientes (horizontal bar)
  destroyChart('gestion');
  const gestCanvas = document.getElementById('chart-gestion');
  if(gestCanvas){
    const clientes = recs.filter(r=>r.tipo==='cliente');
    const activos   = clientes.filter(r=>r.estadoCliente==='activo').length;
    const enRiesgo  = clientes.filter(r=>r.estadoCliente==='en-riesgo').length;
    const inactivos = clientes.filter(r=>r.estadoCliente==='inactivo').length;
    const conVisita = clientes.filter(r=>r.visitaCliente&&r.visitaCliente!=='no').length;
    const conNuevoSvc = clientes.filter(r=>r.nuevoServicio==='si').length;
    const facturados  = clientes.filter(r=>r.facturado&&r.facturado!=='no').length;

    if(clientes.length === 0){
      gestCanvas.style.display = 'none';
      const parent = gestCanvas.parentElement;
      if(!parent.querySelector('.gest-empty')){
        const div = document.createElement('div');
        div.className = 'gest-empty empty-state';
        div.style.cssText = 'padding:40px 0;text-align:center';
        div.innerHTML = '<div style="font-size:32px;margin-bottom:8px">🏢</div><div style="color:var(--text2);font-size:13px">Sin clientes registrados</div>';
        parent.appendChild(div);
      }
    } else {
      gestCanvas.style.display = '';
      const parent = gestCanvas.parentElement;
      const empty = parent.querySelector('.gest-empty');
      if(empty) empty.remove();
      charts.gestion = new Chart(gestCanvas,{
        type:'bar',
        data:{
          labels:['Activos','En Riesgo','Inactivos','Con Visita','Nuevo Svc','Facturados'],
          datasets:[{
            label:'Clientes',
            data:[activos, enRiesgo, inactivos, conVisita, conNuevoSvc, facturados],
            backgroundColor:[
              'rgba(0,230,118,0.75)',
              'rgba(245,166,35,0.75)',
              'rgba(136,153,180,0.5)',
              'rgba(0,194,255,0.75)',
              'rgba(168,85,247,0.75)',
              'rgba(245,166,35,0.75)'
            ],
            borderWidth:0, borderRadius:6
          }]
        },
        options:{
          indexAxis:'y',
          responsive:true, maintainAspectRatio:false,
          plugins:{ legend:{ display:false } },
          scales:{
            x:{ beginAtZero:true, ticks:{ stepSize:1 }, grid:{ color:'rgba(136,153,180,0.1)' } },
            y:{ ticks:{ font:{ size:11 } }, grid:{ display:false } }
          }
        }
      });
    }
  }
}

function renderProspectos(){
  const search = (document.getElementById('filter-prospectos')?.value||'').toLowerCase();
  const estado = document.getElementById('filter-estado-p')?.value||'';
  const com = document.getElementById('filter-comercial-p')?.value||'';
  const rows = db.records.filter(r=>r.tipo==='prospecto'
    && (!search||r.empresa.toLowerCase().includes(search))
    && (!estado||r.estadoProspecto===estado)
    && (!com||r.comercialId===com)
  );
  const tbody = document.getElementById('tabla-prospectos');
  if(!tbody) return;
  if(rows.length===0){ tbody.innerHTML=`<tr><td colspan="9"><div class="empty-state"><div class="empty-icon">🎯</div><div class="empty-title">Sin prospectos</div><div>Registra tu primer prospecto</div></div></td></tr>`; return; }
  tbody.innerHTML = rows.map(r=>`<tr>
    <td><strong>${r.empresa}</strong>${r.ciudad?`<br><span style="color:var(--text2);font-size:11px">📍 ${r.ciudad}</span>`:''}${r.direccion?`<br><span style="color:var(--text2);font-size:10px">🏠 ${r.direccion}</span>`:''}</td>
    <td>${r.contacto||'—'}</td>
    <td><span style="font-size:13px">${r.comercialNombre}</span></td>
    <td><div class="service-tags">${(r.servicios||[]).map(s=>`<span class="stag">${s}</span>`).join('')}</div></td>
    <td>${estadoBadge(r)}</td>
    <td>${facturaBadge(r.facturadoP||r.facturado)}</td>
    <td style="font-size:12px;color:var(--text2)">${r.proximoSeguimiento||'—'}</td>
    <td><button class="btn btn-secondary btn-sm" onclick="abrirDetalle('${r.id}')">✏️ Ver</button></td>
  </tr>`).join('');
}

function renderClientes(){
  const search   = (document.getElementById('filter-clientes')?.value||'').toLowerCase();
  const estado   = document.getElementById('filter-estado-c')?.value||'';
  const fact     = document.getElementById('filter-facturado')?.value||'';
  const company  = document.getElementById('filter-company-c')?.value||'';
  const rows = db.records.filter(r=>r.tipo==='cliente'
    && (!search||r.empresa.toLowerCase().includes(search))
    && (!estado||r.estadoCliente===estado)
    && (!fact||r.facturado===fact)
    && (!company||gdCompaniasCliente(r).includes(company))
  );
  const tbody = document.getElementById('tabla-clientes');
  if(!tbody) return;
  if(rows.length===0){ tbody.innerHTML=`<tr><td colspan="9"><div class="empty-state"><div class="empty-icon">🏢</div><div class="empty-title">Sin clientes registrados</div></div></td></tr>`; return; }
  tbody.innerHTML = rows.map(r=>`<tr>
    <td><strong>${r.empresa}</strong>${r.ciudad?`<br><span style="color:var(--text2);font-size:11px">📍 ${r.ciudad}</span>`:''}${r.direccion?`<br><span style="color:var(--text2);font-size:10px">🏠 ${r.direccion}</span>`:''}</td>
    <td>${r.contacto||'—'}</td>
    <td>${r.comercialNombre}</td>
    <td><div class="service-tags">${(r.servicios||[]).map(s=>{
      var comp = COMPANIAS_LOGISTICAS.find(c=>c.key===s);
      return `<span class="stag" title="${s}">${comp?comp.label:s}</span>`;
    }).join('')}</div></td>
    <td>${visitaBadge(r.visitaCliente)}</td>
    <td>${r.nuevoServicio==='si'?`<span class="badge badge-green">✓ ${r.servicioNuevo||'Sí'}</span>`:'<span class="badge badge-gray">No</span>'}</td>
    <td>${facturaBadge(r.facturado)}${r.valor&&r.facturado!=='no'?`<br><span style="font-size:11px;color:var(--gold)">$${Number(r.valor).toLocaleString('es-CO')}</span>`:''}</td>
    <td>${estadoBadge(r)}</td>
    <td><button class="btn btn-secondary btn-sm" onclick="abrirDetalle('${r.id}')">✏️ Ver</button></td>
  </tr>`).join('');
}

// ============================================================
// PÁGINA DETALLE / EDICIÓN DE REGISTRO (pantalla completa)
// ============================================================
let _detalleFromPage = 'prospectos';
let _detalleContactos = [];
let _detalleSelectedSvcs = [];

function abrirDetalle(id){
  const rec = db.records.find(r=>r.id===id);
  if(!rec) return;

  _detalleFromPage = rec.tipo === 'prospecto' ? 'prospectos' : 'clientes';

  document.getElementById('det-record-id').value = id;
  setTipoDetalle(rec.tipo, true);

  document.getElementById('detalle-titulo').innerHTML =
    (rec.tipo==='prospecto'?'🎯':'🏢') + ' <span>' + rec.empresa + '</span>';

  document.getElementById('det-empresa').value = rec.empresa||'';
  document.getElementById('det-nit').value      = rec.nit||'';
  document.getElementById('det-ciudad').value     = rec.ciudad||'';
  const dirEl = document.getElementById('det-direccion');
  if(dirEl) dirEl.value = rec.direccion||'';
  document.getElementById('det-fecha').value    = rec.fecha||'';
  const catEl = document.getElementById('det-categoria');
  if(catEl) catEl.value = rec.categoria||'';

  const comSel = document.getElementById('det-comercial');
  comSel.innerHTML = '<option value="">— Seleccionar —</option>' +
    db.comerciales.map(c=>`<option value="${c.id}"${c.id===rec.comercialId?' selected':''}>${c.nombre}</option>`).join('');

  if(rec.tipo === 'cliente'){
    const tc = rec.tipoCliente||'directo';
    document.getElementById('det-tipo-cliente').value = tc;
    onTipoClienteDetalle(tc, rec);
    const comEl = document.getElementById('det-comision');
    if(comEl) comEl.value = rec.comision||'';
    document.getElementById('det-section-tipo-cliente').style.display = 'block';
  }

  _detalleContactos = rec.contactos?.length
    ? JSON.parse(JSON.stringify(rec.contactos))
    : [{nombre:rec.contacto||'',cargo:rec.cargo||'',telefono:rec.telefono||'',email:rec.email||''}];
  renderContactosDetalle();

  _detalleSelectedSvcs = [...(rec.servicios||[])];
  const chipsEl = document.getElementById('det-services-chips');
  if(chipsEl) chipsEl.innerHTML = SERVICES.map(s=>{
    const sel = _detalleSelectedSvcs.includes(s);
    return `<div class="service-chip${sel?' selected':''}" data-service="${s}"
      onclick="toggleDetService(this,'${s}')">${s}</div>`;
  }).join('');

  if(rec.tipo==='prospecto'){
    document.getElementById('det-estado-prospecto').value = rec.estadoProspecto||'prospecto';
    document.getElementById('det-visita').value = rec.visita||'no';
    document.getElementById('det-fecha-visita').value = rec.fechaVisita||'';
    document.getElementById('det-proximo-seguimiento').value = rec.proximoSeguimiento||'';
    document.getElementById('det-obs-prospecto').value = rec.observaciones||'';
    const fp = rec.facturadoP||'no';
    document.getElementById('det-facturado-p').value = fp;
    if(fp!=='no'){
      document.getElementById('det-billing-block-p').style.display='block';
      document.getElementById('det-billing-lines-p').innerHTML = buildDetBillingHTML('p', rec.servicios||[], rec.facturacionLineas||{});
      document.getElementById('det-total-p').textContent = '$'+calcTotalBilling(rec.facturacionLineas||{}).toLocaleString('es-CO');
    } else {
      document.getElementById('det-billing-block-p').style.display='none';
    }
  } else {
    document.getElementById('det-estado-cliente').value = rec.estadoCliente||'activo';
    document.getElementById('det-visita-cliente').value = rec.visitaCliente||'no';
    document.getElementById('det-fecha-visita-cliente').value = rec.fechaVisitaCliente||'';
    document.getElementById('det-nuevo-servicio').value = rec.nuevoServicio||'no';
    document.getElementById('det-grupo-svc-nuevo').style.display = rec.nuevoServicio==='si'?'block':'none';
    document.getElementById('det-servicio-nuevo').value = rec.servicioNuevo||'';
    document.getElementById('det-obs-cliente').value = rec.observaciones||'';
    const fc = rec.facturado||'no';
    document.getElementById('det-facturado-c').value = fc;
    if(fc!=='no'){
      document.getElementById('det-billing-block-c').style.display='block';
      document.getElementById('det-billing-lines-c').innerHTML = buildDetBillingHTML('dc', rec.servicios||[], rec.facturacionLineas||{});
      document.getElementById('det-total-c').textContent = '$'+calcTotalBilling(rec.facturacionLineas||{}).toLocaleString('es-CO');
    } else {
      document.getElementById('det-billing-block-c').style.display='none';
    }
  }

  showPage('detalle');
}

function setTipoDetalle(t, skipStyle){
  // Mostrar botón convertir solo si es prospecto
  var btnConv = document.getElementById('btn-convertir-cliente');
  if(btnConv) btnConv.style.display = t==='prospecto' ? 'inline-flex' : 'none';
  const tipoEl = document.getElementById('det-tipo-registro') || document.getElementById('det-tipo');
  if(tipoEl) tipoEl.value = t;
  const bp = document.getElementById('det-btn-prospecto');
  const bc = document.getElementById('det-btn-cliente');
  const sp = document.getElementById('det-section-prospecto');
  const sc = document.getElementById('det-section-cliente');
  const stc = document.getElementById('det-section-tipo-cliente');
  if(t==='prospecto'){
    if(bp) bp.className='type-btn active-prospecto';
    if(bc) bc.className='type-btn';
    if(sp) sp.style.display='block';
    if(sc) sc.style.display='none';
    if(stc) stc.style.display='none';
  } else {
    if(bc) bc.className='type-btn active-cliente';
    if(bp) bp.className='type-btn';
    if(sc) sc.style.display='block';
    if(sp) sp.style.display='none';
    if(stc) stc.style.display='block';
  }
}

function onTipoClienteDetalle(val, rec){
  const grpInd = document.getElementById('det-grupo-indirecto');
  const grpCom = document.getElementById('det-grupo-comision');
  if(val==='referido'){
    if(grpInd) grpInd.style.display='block';
    if(grpCom) grpCom.style.display='none';
    const sel = document.getElementById('det-cliente-indirecto');
    if(sel){
      const indirectos = db.records.filter(r=>r.tipo==='cliente'&&r.tipoCliente==='indirecto');
      sel.innerHTML = '<option value="">— Seleccionar aliado —</option>' +
        indirectos.map(r=>`<option value="${r.id}"${rec&&rec.clienteIndirectoId===r.id?' selected':''}>${r.empresa}</option>`).join('');
    }
  } else if(val==='indirecto'){
    if(grpInd) grpInd.style.display='none';
    if(grpCom) grpCom.style.display='block';
  } else {
    if(grpInd) grpInd.style.display='none';
    if(grpCom) grpCom.style.display='none';
  }
}

function renderContactosDetalle(){
  const el = document.getElementById('det-contactos-list');
  if(!el) return;
  el.innerHTML = _detalleContactos.map((c,i)=>`
    <div class="contact-card" style="margin-bottom:10px;background:var(--surface2);border:1px solid var(--border);border-radius:10px;padding:16px">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px">
        <span style="font-size:11px;color:var(--text2);letter-spacing:1.5px;text-transform:uppercase;font-weight:600">
          ${i===0?'<span style="color:var(--gold)">⭐ Principal</span>':'Contacto '+(i+1)}
        </span>
        ${i>0?`<button type="button" onclick="eliminarContactoDetalle(${i})" style="background:none;border:none;cursor:pointer;color:var(--red);font-size:18px;line-height:1">✕</button>`:''}
      </div>
      <div class="form-grid" style="margin-bottom:0">
        <div class="form-group" style="margin-bottom:0"><label>Nombre</label>
          <input type="text" placeholder="Nombre" value="${escHtml(c.nombre||'')}" oninput="_detalleContactos[${i}].nombre=this.value"></div>
        <div class="form-group" style="margin-bottom:0"><label>Cargo</label>
          <input type="text" placeholder="Cargo" value="${escHtml(c.cargo||'')}" oninput="_detalleContactos[${i}].cargo=this.value"></div>
        <div class="form-group" style="margin-bottom:0"><label>Tipo de Contacto</label>
          <select onchange="_detalleContactos[${i}].tipoContacto=this.value">
            <option value="" ${!c.tipoContacto?'selected':''}>— Sin definir —</option>
            <option value="principal" ${c.tipoContacto==='principal'?'selected':''}>⭐ Principal</option>
            <option value="comercial" ${c.tipoContacto==='comercial'?'selected':''}>💼 Comercial</option>
            <option value="gestion-documental" ${c.tipoContacto==='gestion-documental'?'selected':''}>📁 Gestión Documental</option>
            <option value="financiero" ${c.tipoContacto==='financiero'?'selected':''}>💰 Financiero</option>
            <option value="operativo" ${c.tipoContacto==='operativo'?'selected':''}>⚙️ Operativo</option>
          </select></div>
        <div class="form-group" style="margin-bottom:0"><label>Teléfono</label>
          <input type="text" placeholder="+57 300..." value="${escHtml(c.telefono||'')}" oninput="_detalleContactos[${i}].telefono=this.value"></div>
        <div class="form-group" style="margin-bottom:0"><label>Email</label>
          <input type="email" placeholder="correo@empresa.com" value="${escHtml(c.email||'')}" oninput="_detalleContactos[${i}].email=this.value"></div>
        <div class="form-group" style="margin-bottom:0"><label>🎂 Fecha de Cumpleaños</label>
          <input type="date" value="${escHtml(c.cumpleanos||'')}" oninput="_detalleContactos[${i}].cumpleanos=this.value"></div>
        <div class="form-group" style="margin-bottom:0"><label>🎁 ¿Puede recibir regalos?</label>
          <select onchange="_detalleContactos[${i}].recibeRegalos=this.value">
            <option value="" ${!c.recibeRegalos?'selected':''}>— Sin definir —</option>
            <option value="si" ${c.recibeRegalos==='si'?'selected':''}>✅ Sí</option>
            <option value="no" ${c.recibeRegalos==='no'?'selected':''}>❌ No</option>
          </select></div>
      </div>
    </div>`).join('');
}

function agregarContactoDetalle(){
  _detalleContactos.push({nombre:'',cargo:'',telefono:'',email:'',cumpleanos:'',recibeRegalos:''});
  renderContactosDetalle();
}

function eliminarContactoDetalle(idx){
  if(idx===0) return;
  _detalleContactos.splice(idx,1);
  renderContactosDetalle();
}

function toggleDetService(el, svc){
  el.classList.toggle('selected');
  if(el.classList.contains('selected')){
    if(!_detalleSelectedSvcs.includes(svc)) _detalleSelectedSvcs.push(svc);
  } else {
    _detalleSelectedSvcs = _detalleSelectedSvcs.filter(s=>s!==svc);
  }
}

function buildDetBillingHTML(suffix, services, existing){
  if(!services||services.length===0) return '<div style="color:var(--text2);font-size:13px;grid-column:1/-1">Sin servicios seleccionados.</div>';
  return services.map(s=>{
    const key = s.replace(/\s+/g,'-').replace(/\//g,'-');
    const val = existing[s]||0;
    const color = SVC_COLORS[s]||'var(--accent)';
    return `<div class="form-group">
      <label style="display:flex;align-items:center;gap:6px">
        <span style="display:inline-block;width:8px;height:8px;border-radius:2px;background:${color}"></span>${s}
      </label>
      <input type="number" id="det-bill-${suffix}-${key}" value="${val||''}" placeholder="0" min="0"
        oninput="updateDetTotal('${suffix}')" style="text-align:right">
    </div>`;
  }).join('');
}

function updateDetTotal(suffix){
  const inputs = document.querySelectorAll(`[id^="det-bill-${suffix}-"]`);
  let total = 0;
  inputs.forEach(i=>total+=Number(i.value)||0);
  const el = suffix==='p' ? document.getElementById('det-total-p') : document.getElementById('det-total-c');
  if(el) el.textContent='$'+total.toLocaleString('es-CO');
}

function onDetFacturadoChangeV2(suffix, val){
  const blockId = suffix==='p' ? 'det-billing-block-p' : 'det-billing-block-c';
  const linesId = suffix==='p' ? 'det-billing-lines-p' : 'det-billing-lines-c';
  const block = document.getElementById(blockId);
  if(!block) return;
  if(val==='no'){ block.style.display='none'; return; }
  block.style.display='block';
  document.getElementById(linesId).innerHTML = buildDetBillingHTML(suffix==='p'?'p':'dc', _detalleSelectedSvcs, {});
  updateDetTotal(suffix);
}

function getDetBillingLines(suffix){
  const lines = {};
  _detalleSelectedSvcs.forEach(s=>{
    const key = s.replace(/\s+/g,'-').replace(/\//g,'-');
    const el = document.getElementById(`det-bill-${suffix}-${key}`);
    if(el) lines[s] = Number(el.value)||0;
  });
  return lines;
}

function volverDesdeDetalle(){
  showPage(_detalleFromPage);
}

function eliminarRegistroDetalle(){
  const id = document.getElementById('det-record-id').value;
  if(!id) return;
  if(!confirm('¿Estás seguro de eliminar este registro? Esta acción no se puede deshacer.')) return;
  db.records = db.records.filter(r=>r.id!==id);
  save();
  renderProspectos(); renderClientes(); renderDashboard();
  toast('🗑','Registro eliminado','#ff4444');
  volverDesdeDetalle();
}

function guardarDetalle(){
  const id = document.getElementById('det-record-id').value;
  const rec = db.records.find(r=>r.id===id);
  if(!rec){ toast('⚠️','Registro no encontrado','#f5a623'); return; }

  const empresa = document.getElementById('det-empresa').value.trim();
  if(!empresa){ toast('⚠️','Ingresa el nombre de la empresa','#f5a623'); return; }
  if(_detalleSelectedSvcs.length===0){ toast('⚠️','Selecciona al menos un servicio','#f5a623'); return; }

  const nuevoTipo = document.getElementById('det-tipo-registro')?.value || document.getElementById('det-tipo')?.value || rec.tipo;
  const comId = document.getElementById('det-comercial').value;
  const tipoAnterior = rec.tipo;

  rec.empresa  = empresa;
  rec.nit      = document.getElementById('det-nit').value;
  rec.ciudad    = document.getElementById('det-ciudad').value;
  rec.direccion  = document.getElementById('det-direccion')?.value.trim()||'';
  rec.fecha    = document.getElementById('det-fecha').value || rec.fecha;
  rec.categoria = document.getElementById('det-categoria')?.value ?? rec.categoria ?? '';
  rec.servicios = [..._detalleSelectedSvcs];
  rec.tipo = nuevoTipo;

  if(comId){ rec.comercialId=comId; rec.comercialNombre=db.comerciales.find(c=>c.id===comId)?.nombre||rec.comercialNombre; }

  const conts = _detalleContactos.filter(c=>c.nombre||c.email||c.telefono);
  if(conts.length){
    rec.contactos=conts;
    rec.contacto=conts[0].nombre||'';
    rec.cargo=conts[0].cargo||'';
    rec.telefono=conts[0].telefono||'';
    rec.email=conts[0].email||'';
  }

  if(nuevoTipo==='cliente'){
    const tc = document.getElementById('det-tipo-cliente').value;
    rec.tipoCliente = tc;
    if(tc==='referido'){
      const ind = document.getElementById('det-cliente-indirecto').value;
      rec.clienteIndirectoId = ind;
      rec.clienteIndirectoNombre = db.records.find(r=>r.id===ind)?.empresa||'';
    }
    const comisionEl = document.getElementById('det-comision');
    if(tc==='indirecto' && comisionEl) rec.comision = comisionEl.value;
    rec.estadoCliente      = document.getElementById('det-estado-cliente').value;
    rec.visitaCliente      = document.getElementById('det-visita-cliente').value;
    rec.fechaVisitaCliente = document.getElementById('det-fecha-visita-cliente').value;
    rec.nuevoServicio      = document.getElementById('det-nuevo-servicio').value;
    rec.servicioNuevo      = document.getElementById('det-servicio-nuevo').value;
    rec.observaciones      = document.getElementById('det-obs-cliente').value;
    rec.facturado          = document.getElementById('det-facturado-c').value;
    if(rec.facturado!=='no'){ rec.facturacionLineas=getDetBillingLines('dc'); rec.valor=calcTotalBilling(rec.facturacionLineas); }
    else { rec.facturacionLineas={}; rec.valor=0; }
    if(tipoAnterior==='prospecto'){
      if(!rec.actividades) rec.actividades=[];
      rec.actividades.push({tipo:'service',fecha:today(),desc:'Convertido a cliente activo'});
    }
  } else {
    rec.estadoProspecto    = document.getElementById('det-estado-prospecto').value;
    rec.visita             = document.getElementById('det-visita').value;
    rec.fechaVisita        = document.getElementById('det-fecha-visita').value;
    rec.proximoSeguimiento = document.getElementById('det-proximo-seguimiento').value;
    rec.observaciones      = document.getElementById('det-obs-prospecto').value;
    rec.facturadoP         = document.getElementById('det-facturado-p').value;
    if(rec.facturadoP!=='no'){ rec.facturacionLineas=getDetBillingLines('p'); rec.valorP=calcTotalBilling(rec.facturacionLineas); }
    else { rec.facturacionLineas={}; rec.valorP=0; }
  }

  save();
  populateMesFilter();
  renderProspectos(); renderClientes(); renderDashboard();

  const cambioTipo = tipoAnterior!==nuevoTipo;
  const msg = cambioTipo
    ? rec.empresa+' convertido a '+(nuevoTipo==='cliente'?'Cliente Activo':'Prospecto')
    : '✅ Cambios guardados correctamente';
  toast('✅', msg, '#00e676');

  // Feedback visual en el botón
  const btnG = document.querySelector('[onclick="guardarDetalle()"]');
  if(btnG){
    const originalText = btnG.innerHTML;
    btnG.innerHTML = '✅ Guardado';
    btnG.disabled = true;
    btnG.style.background = '#00e676';
    btnG.style.color = '#000';
    setTimeout(function(){
      btnG.innerHTML = originalText;
      btnG.disabled = false;
      btnG.style.background = '';
      btnG.style.color = '';
    }, 2000);
  }

  if(cambioTipo) _detalleFromPage = nuevoTipo==='cliente'?'clientes':'prospectos';
  setTimeout(()=>volverDesdeDetalle(), 2000);
}

// openModal redirige a la página de detalle completa
function openModal(id){
  abrirDetalle(id);
}

// ============================================================
// MODAL DETALLE / EDICIÓN DE REGISTROS
// ============================================================
function openModal_legacy(id){
  const rec = db.records.find(r=>r.id===id);
  if(!rec) return;

  const tipoLabel = rec.tipo==='prospecto' ? '🎯 Prospecto' : '🏢 Cliente';
  document.getElementById('modal-titulo').textContent = `✏️ ${rec.empresa}  ·  ${tipoLabel}`;

  const svcChips = SERVICES.map(s=>{
    const sel = (rec.servicios||[]).includes(s);
    return `<div class="service-chip${sel?' selected':''}" onclick="this.classList.toggle('selected')" data-svc="${s}">${s}</div>`;
  }).join('');

  const comOpts = db.comerciales.map(c=>`<option value="${c.id}"${c.id===rec.comercialId?' selected':''}>${c.nombre}</option>`).join('');

  const colLeft = `
    <div class="modal-section">
      <div class="modal-section-title" style="color:var(--accent)">📋 Datos Generales</div>
      <div class="form-grid">
        <div class="form-group"><label>Empresa *</label><input type="text" id="e-empresa" value="${rec.empresa||''}"></div>
        <div class="form-group"><label>NIT</label><input type="text" id="e-nit" value="${rec.nit||''}"></div>
        <div class="form-group"><label>Contacto</label><input type="text" id="e-contacto" value="${rec.contacto||''}"></div>
        <div class="form-group"><label>Cargo</label><input type="text" id="e-cargo" value="${rec.cargo||''}"></div>
        <div class="form-group"><label>Teléfono</label><input type="text" id="e-telefono" value="${rec.telefono||''}"></div>
        <div class="form-group"><label>Email</label><input type="email" id="e-email" value="${rec.email||''}"></div>
        <div class="form-group modal-col-full"><label>Dirección</label><input type="text" id="e-direccion" value="${rec.direccion||''}" placeholder="Dirección de la empresa"></div>
         <div class="form-group"><label>Ciudad</label><input type="text" id="e-ciudad" value="${rec.ciudad||''}"></div>
        <div class="form-group"><label>Comercial</label><select id="e-comercial">${comOpts}</select></div>
        <div class="form-group"><label>Fecha Registro</label><input type="date" id="e-fecha" value="${rec.fecha||''}"></div>
      </div>
      <div style="margin-top:18px">
        <label style="font-size:11px;color:var(--text2);letter-spacing:1.5px;text-transform:uppercase;font-weight:600;display:block;margin-bottom:8px">Servicios de Interés</label>
        <div class="services-grid" id="e-svc-chips">${svcChips}</div>
      </div>
    </div>`;

  let colRight = '';
  if(rec.tipo==='prospecto'){
    colRight = `
      <div style="display:flex;flex-direction:column;gap:20px">
        <div class="modal-section">
          <div class="modal-section-title" style="color:var(--accent)">🎯 Seguimiento del Prospecto</div>
          <div class="form-grid">
            <div class="form-group"><label>Estado</label>
              <select id="e-estado-p">
                <option value="prospecto"${rec.estadoProspecto==='prospecto'?' selected':''}>🎯 Prospecto</option>
                <option value="reconocimiento"${rec.estadoProspecto==='reconocimiento'?' selected':''}>🏢 Visita</option>
                <option value="propuesta"${rec.estadoProspecto==='propuesta'?' selected':''}>📄 Propuesta Comercial</option>
                <option value="aceptacion_propuesta"${rec.estadoProspecto==='aceptacion_propuesta'?' selected':''}>🤝 Aceptación Propuesta Comercial</option>
                <option value="creacion_sop"${rec.estadoProspecto==='creacion_sop'?' selected':''}>📋 Creación Ficha Cliente</option>
                <option value="facturado"${rec.estadoProspecto==='facturado'?' selected':''}>💰 Facturado</option>
                <option value="frio"${rec.estadoProspecto==='frio'?' selected':''}>🧊 Frío</option>
                <option value="perdido"${rec.estadoProspecto==='perdido'?' selected':''}>❌ Perdido</option>
              </select></div>
            <div class="form-group"><label>Visita Realizada</label>
              <select id="e-visita">
                <option value="no"${rec.visita==='no'?' selected':''}>No</option>
                <option value="si"${rec.visita==='si'?' selected':''}>Sí — Presencial</option>
                <option value="virtual"${rec.visita==='virtual'?' selected':''}>Sí — Virtual</option>
                <option value="llamada"${rec.visita==='llamada'?' selected':''}>Sí — Llamada</option>
              </select></div>
            <div class="form-group"><label>Fecha Visita</label><input type="date" id="e-fecha-visita" value="${rec.fechaVisita||''}"></div>
            <div class="form-group"><label>Próximo Seguimiento</label><input type="date" id="e-prox-seg" value="${rec.proximoSeguimiento||''}"></div>
          </div>
          <div class="form-group" style="margin-top:12px"><label>Observaciones</label>
            <textarea id="e-obs" style="min-height:90px">${rec.observaciones||''}</textarea></div>
        </div>
        <div class="modal-section">
          <div class="modal-section-title" style="color:var(--gold)">💰 Facturación</div>
          <div class="form-group" style="margin-bottom:0">
            <label>¿Se facturó?</label>
            <select id="e-facturado-p" onchange="toggleEditBillingP(this.value)">
              <option value="no"${!rec.facturadoP||rec.facturadoP==='no'?' selected':''}>No</option>
              <option value="si"${rec.facturadoP==='si'?' selected':''}>Sí</option>
              <option value="parcial"${rec.facturadoP==='parcial'?' selected':''}>Parcial</option>
            </select>
          </div>
          <div id="e-billing-block-p" style="display:${rec.facturadoP&&rec.facturadoP!=='no'?'block':'none'};margin-top:16px;padding-top:14px;border-top:1px solid rgba(245,166,35,0.2)">
            <div style="font-size:12px;color:var(--text2);margin-bottom:12px">Valor facturado por cada servicio:</div>
            <div id="e-billing-lines-p" class="form-grid">${buildEditBillingHTML('p', rec.servicios||[], rec.facturacionLineas||{})}</div>
            <div style="display:flex;justify-content:space-between;align-items:center;margin-top:14px;padding-top:12px;border-top:1px solid var(--border)">
              <span style="font-size:12px;color:var(--text2);text-transform:uppercase;letter-spacing:1px;font-weight:600">Total Facturado</span>
              <span id="e-total-p" style="font-family:'Barlow Condensed',sans-serif;font-size:26px;font-weight:800;color:var(--gold)">$${calcTotalBilling(rec.facturacionLineas||{}).toLocaleString('es-CO')}</span>
            </div>
          </div>
        </div>
      </div>`;
  } else {
    colRight = `
      <div style="display:flex;flex-direction:column;gap:20px">
        <div class="modal-section">
          <div class="modal-section-title" style="color:var(--green)">🏢 Gestión del Cliente</div>
          <div class="form-grid">
            <div class="form-group"><label>Estado Relación</label>
              <select id="e-estado-c">
                <option value="activo"${rec.estadoCliente==='activo'?' selected':''}>✅ Activo</option>
                <option value="en-riesgo"${rec.estadoCliente==='en-riesgo'?' selected':''}>⚠️ En Riesgo</option>
                <option value="inactivo"${rec.estadoCliente==='inactivo'?' selected':''}>💤 Inactivo</option>
              </select></div>
            <div class="form-group"><label>Visita Realizada</label>
              <select id="e-visita-c">
                <option value="no"${rec.visitaCliente==='no'?' selected':''}>No</option>
                <option value="si"${rec.visitaCliente==='si'?' selected':''}>Sí — Presencial</option>
                <option value="virtual"${rec.visitaCliente==='virtual'?' selected':''}>Sí — Virtual</option>
              </select></div>
            <div class="form-group"><label>¿Nuevo Servicio Cerrado?</label>
              <select id="e-nuevo-svc" onchange="document.getElementById('e-svc-nuevo-grp').style.display=this.value==='si'?'block':'none'">
                <option value="no"${rec.nuevoServicio!=='si'?' selected':''}>No</option>
                <option value="si"${rec.nuevoServicio==='si'?' selected':''}>Sí</option>
              </select></div>
            <div class="form-group" id="e-svc-nuevo-grp" style="display:${rec.nuevoServicio==='si'?'block':'none'}"><label>Servicio Cerrado</label>
              <select id="e-svc-nuevo">
                ${SERVICES.map(s=>`<option${s===rec.servicioNuevo?' selected':''}>${s}</option>`).join('')}
              </select></div>
          </div>
          <div class="form-group" style="margin-top:12px"><label>Notas / Gestión Realizada</label>
            <textarea id="e-obs" style="min-height:90px">${rec.observaciones||''}</textarea></div>
        </div>
        <div class="modal-section">
          <div class="modal-section-title" style="color:var(--gold)">💰 Facturación</div>
          <div class="form-group" style="margin-bottom:0">
            <label>¿Se facturó?</label>
            <select id="e-facturado-c" onchange="toggleEditBillingC(this.value,'${rec.servicios?.join(',')||''}',${JSON.stringify(rec.facturacionLineas||{})})">
              <option value="no"${rec.facturado==='no'||!rec.facturado?' selected':''}>No</option>
              <option value="si"${rec.facturado==='si'?' selected':''}>Sí</option>
              <option value="parcial"${rec.facturado==='parcial'?' selected':''}>Parcial</option>
            </select>
          </div>
          <div id="e-billing-block-c" style="display:${rec.facturado&&rec.facturado!=='no'?'block':'none'};margin-top:16px;padding-top:14px;border-top:1px solid rgba(245,166,35,0.2)">
            <div style="font-size:12px;color:var(--text2);margin-bottom:12px">Valor facturado por cada servicio:</div>
            <div id="e-billing-lines-c" class="form-grid">${buildEditBillingHTML('ec', rec.servicios||[], rec.facturacionLineas||{})}</div>
            <div style="display:flex;justify-content:space-between;align-items:center;margin-top:14px;padding-top:12px;border-top:1px solid var(--border)">
              <span style="font-size:12px;color:var(--text2);text-transform:uppercase;letter-spacing:1px;font-weight:600">Total Facturado</span>
              <span id="e-total-c" style="font-family:'Barlow Condensed',sans-serif;font-size:26px;font-weight:800;color:var(--gold)">$${calcTotalBilling(rec.facturacionLineas||{}).toLocaleString('es-CO')}</span>
            </div>
          </div>
        </div>
      </div>`;
  }

  document.getElementById('modal-content').innerHTML = colLeft + colRight;
  document.getElementById('modal-footer').innerHTML = `
    <button class="btn btn-danger btn-sm" onclick="deleteRecord('${rec.id}')">🗑 Eliminar Registro</button>
    <div style="display:flex;gap:12px;margin-left:auto">
      <button class="btn btn-secondary" onclick="closeModal()">Cancelar</button>
      <button class="btn btn-primary" onclick="saveEdit('${rec.id}')">💾 Guardar Cambios</button>
    </div>`;
  document.getElementById('modal-detalle').classList.add('open');
}

function buildEditBillingHTML(suffix, services, existing){
  if(!services||services.length===0) return '<div style="color:var(--text2);font-size:13px;grid-column:1/-1">Sin servicios seleccionados.</div>';
  return services.map(s=>{
    const val = existing[s]||0;
    const color = SVC_COLORS[s]||'var(--accent)';
    return `<div class="form-group">
      <label style="color:${color}">${s}</label>
      <input type="number" min="0" id="ebill-${suffix}-${s.replace(/\s+/g,'-')}"
        value="${val}" placeholder="0"
        oninput="recalcEditTotal('${suffix}')">
    </div>`;
  }).join('');
}

function recalcEditTotal(suffix){
  const lines = getEditBillingLines(suffix);
  const total = calcTotalBilling(lines);
  const el = document.getElementById(`e-total-${suffix==='p'?'p':'c'}`);
  if(el) el.textContent = '$'+Math.round(total).toLocaleString('es-CO');
}

function getEditBillingLines(suffix, services){
  const lines = {};
  const svcs = services || Array.from(document.querySelectorAll(`#e-billing-lines-${suffix==='p'?'p':'c'} input`)).map(i=>i.id.replace(`ebill-${suffix}-`,'').replace(/-/g,' '));
  svcs.forEach(s=>{
    const key = s.replace(/\s+/g,'-');
    const inp = document.getElementById(`ebill-${suffix}-${key}`);
    if(inp) lines[s] = Number(inp.value)||0;
  });
  return lines;
}

function calcTotalBilling(lines){
  return Object.values(lines||{}).reduce((a,b)=>a+(Number(b)||0),0);
}

function toggleEditBillingP(val){
  const block = document.getElementById('e-billing-block-p');
  if(block) block.style.display = val!=='no' ? 'block' : 'none';
}

function toggleEditBillingC(val, svcsStr, existing){
  const block = document.getElementById('e-billing-block-c');
  if(!block) return;
  block.style.display = val!=='no' ? 'block' : 'none';
  if(val!=='no'){
    const svcs = svcsStr ? svcsStr.split(',').filter(Boolean) : [];
    const linesEl = document.getElementById('e-billing-lines-c');
    if(linesEl) linesEl.innerHTML = buildEditBillingHTML('ec', svcs, existing||{});
  }
}

function saveEdit(id){
  const rec = db.records.find(r=>r.id===id);
  if(!rec) return;
  rec.empresa   = document.getElementById('e-empresa')?.value.trim()||rec.empresa;
  rec.nit       = document.getElementById('e-nit')?.value||rec.nit;
  rec.contacto  = document.getElementById('e-contacto')?.value||rec.contacto;
  rec.cargo     = document.getElementById('e-cargo')?.value||rec.cargo;
  rec.telefono  = document.getElementById('e-telefono')?.value||rec.telefono;
  rec.email     = document.getElementById('e-email')?.value||rec.email;
  rec.ciudad    = document.getElementById('e-ciudad')?.value||rec.ciudad;
  rec.direccion = document.getElementById('e-direccion')?.value.trim()||rec.direccion||'';
  rec.fecha     = document.getElementById('e-fecha')?.value||rec.fecha;
  const comId = document.getElementById('e-comercial')?.value;
  if(comId){ rec.comercialId=comId; rec.comercialNombre=db.comerciales.find(c=>c.id===comId)?.nombre||rec.comercialNombre; }
  const chips = document.querySelectorAll('#e-svc-chips .service-chip');
  const svcs = [];
  chips.forEach(ch=>{ if(ch.classList.contains('selected')) svcs.push(ch.dataset.svc); });
  if(svcs.length>0) rec.servicios = svcs;
  rec.observaciones = document.getElementById('e-obs')?.value||rec.observaciones;
  if(rec.tipo==='prospecto'){
    rec.estadoProspecto    = document.getElementById('e-estado-p')?.value||rec.estadoProspecto;
    rec.visita             = document.getElementById('e-visita')?.value||rec.visita;
    rec.fechaVisita        = document.getElementById('e-fecha-visita')?.value||rec.fechaVisita;
    rec.proximoSeguimiento = document.getElementById('e-prox-seg')?.value||rec.proximoSeguimiento;
    rec.facturadoP = document.getElementById('e-facturado-p')?.value||'no';
    if(rec.facturadoP!=='no'){
      const newLines = getEditBillingLines('p', rec.servicios);
      rec.facturacionLineas = newLines;
      rec.valorP = calcTotalBilling(newLines);
    } else { rec.facturacionLineas={}; rec.valorP=0; }
  } else {
    rec.estadoCliente  = document.getElementById('e-estado-c')?.value||rec.estadoCliente;
    rec.visitaCliente  = document.getElementById('e-visita-c')?.value||rec.visitaCliente;
    rec.nuevoServicio  = document.getElementById('e-nuevo-svc')?.value||rec.nuevoServicio;
    rec.servicioNuevo  = document.getElementById('e-svc-nuevo')?.value||rec.servicioNuevo;
    rec.facturado      = document.getElementById('e-facturado-c')?.value||rec.facturado||'no';
    if(rec.facturado!=='no'){
      const newLines = getEditBillingLines('ec', rec.servicios);
      rec.facturacionLineas = newLines;
      rec.valor = calcTotalBilling(newLines)||'';
    } else { rec.facturacionLineas={}; rec.valor=''; }
  }
  save(); populateMesFilter();
  renderDashboard(); renderProspectos(); renderClientes(); renderEquipo();

  // Feedback visual en el botón antes de cerrar
  const btnSave = document.querySelector('[onclick*="saveEdit"]');
  if(btnSave){
    btnSave.innerHTML = '✅ Guardado';
    btnSave.disabled = true;
    btnSave.style.background = '#00e676';
    btnSave.style.color = '#000';
  }
  toast('✅','Cambios guardados correctamente','#00e676');
  setTimeout(function(){ closeModal(); }, 1200);
}

function closeModal(){ document.getElementById('modal-detalle').classList.remove('open'); }
document.getElementById('modal-detalle').onclick = e => { if(e.target===e.currentTarget) closeModal(); };

function deleteRecord(id){
  db.records = db.records.filter(r=>r.id!==id);
  save(); closeModal();
  renderProspectos(); renderClientes(); renderDashboard();
  toast('🗑','Registro eliminado','#ff4444');
}

function editComercial(id){
  const c = db.comerciales.find(x=>x.id===id);
  if(!c) return;
  document.getElementById('modal-titulo').textContent = '✏️ Editar Comercial';
  document.getElementById('modal-content').innerHTML = `
    <div class="modal-section">
      <div class="form-grid">
        <div class="form-group"><label>Nombre *</label><input type="text" id="ec-nombre" value="${c.nombre||''}"></div>
        <div class="form-group"><label>Cargo</label><input type="text" id="ec-cargo" value="${c.cargo||''}"></div>
        <div class="form-group"><label>Email</label><input type="email" id="ec-email" value="${c.email||''}"></div>
        <div class="form-group"><label>Teléfono</label><input type="text" id="ec-tel" value="${c.tel||''}"></div>
      </div>
    </div>`;
  document.getElementById('modal-footer').innerHTML = `
    <div style="display:flex;gap:12px;margin-left:auto">
      <button class="btn btn-secondary" onclick="closeModal()">Cancelar</button>
      <button class="btn btn-primary" onclick="saveComercial('${id}')">💾 Guardar</button>
    </div>`;
  document.getElementById('modal-detalle').classList.add('open');
}

function saveComercial(id){
  const c = db.comerciales.find(x=>x.id===id);
  if(!c) return;
  c.nombre = document.getElementById('ec-nombre')?.value.trim()||c.nombre;
  c.cargo  = document.getElementById('ec-cargo')?.value||c.cargo;
  c.email  = document.getElementById('ec-email')?.value||c.email;
  c.tel    = document.getElementById('ec-tel')?.value||c.tel;
  save(); closeModal(); populateComercialSelects(); renderEquipo();
  toast('✅','Comercial actualizado','#00e676');
}

// ============================================================
// RENDER HELPERS
// ============================================================
function estadoBadge(rec){
  if(rec.tipo==='prospecto'){
    const map={
      prospecto:'badge-blue',
      reconocimiento:'badge-blue',
      propuesta:'badge-purple',
      resolucion:'badge-purple',
      aceptacion_alcance:'badge-gold',
      aceptacion_propuesta:'badge-gold',
      firma_contrato:'badge-green',
      creacion_sop:'badge-green',
      facturado:'badge-green',
      frio:'badge-gray',
      perdido:'badge-red',
      // legado
      seguimiento:'badge-blue', cerrado:'badge-green'
    };
    const labels={
      prospecto:'Prospecto',
      reconocimiento:'Visita',
      propuesta:'Propuesta Comercial',
      resolucion:'Resolución de Dudas',
      aceptacion_alcance:'Acept. Alcance',
      aceptacion_propuesta:'Acept. Propuesta',
      firma_contrato:'Firma Contrato',
      creacion_sop:'Creación Ficha Cliente',
      facturado:'Facturado',
      frio:'Frío',
      perdido:'Perdido',
      seguimiento:'En Seguimiento', cerrado:'Cerrado'
    };
    const est = rec.estadoProspecto||'prospecto';
    return `<span class="badge ${map[est]||'badge-gray'}">${labels[est]||est}</span>`;
  } else {
    const map={activo:'badge-green',inactivo:'badge-gray',riesgo:'badge-red'};
    const labels={activo:'Activo',inactivo:'Inactivo',riesgo:'En Riesgo'};
    const est = rec.estadoCliente||'activo';
    return `<span class="badge ${map[est]||'badge-gray'}">${labels[est]||est}</span>`;
  }
}

function categoriaBadge(cat){
  if(!cat) return '<span style="color:var(--text2);font-size:12px">—</span>';
  const base = 'display:inline-flex;align-items:center;justify-content:center;gap:3px;font-size:11px;font-weight:700;padding:3px 10px;border-radius:4px;letter-spacing:1px';
  const map = {
    'A':`<span style="${base};background:rgba(0,230,118,0.15);color:#00e676">🏆&nbsp;A</span>`,
    'B':`<span style="${base};background:rgba(0,194,255,0.15);color:#00c2ff">🥈&nbsp;B</span>`,
    'C':`<span style="${base};background:rgba(136,153,180,0.15);color:#8899b4">🥉&nbsp;C</span>`
  };
  return map[cat]||'<span style="color:var(--text2);font-size:12px">—</span>';
}

function visitaBadge(v){
  if(!v||v==='no') return '<span class="badge badge-gray">No</span>';
  if(v==='si'||v==='sí') return '<span class="badge badge-green">✓ Sí</span>';
  return `<span class="badge badge-green">✓ ${v}</span>`;
}

function facturaBadge(v){
  if(!v||v==='no') return '<span class="badge badge-gray">No</span>';
  if(v==='si'||v==='sí') return '<span class="badge badge-green">✓ Facturado</span>';
  if(v==='parcial') return '<span class="badge badge-gold">Parcial</span>';
  return `<span class="badge badge-green">✓ ${v}</span>`;
}

// ============================================================
// RENDER EQUIPO
// ============================================================
function renderEquipo(){
  const tbody = document.getElementById('tabla-equipo');
  if(!tbody) return;
  tbody.innerHTML = db.comerciales.map(c=>{
    const prospectos = db.records.filter(r=>r.comercialId===c.id&&r.tipo==='prospecto').length;
    const clientes = db.records.filter(r=>r.comercialId===c.id&&r.tipo==='cliente').length;
    const visitas = db.records.filter(r=>r.comercialId===c.id&&(r.visita&&r.visita!=='no'||r.visitaCliente&&r.visitaCliente!=='no')).length;
    return `<tr>
      <td><strong>${c.nombre}</strong></td>
      <td><span style="color:var(--text2);font-size:12px">${c.cargo||'—'}</span></td>
      <td style="font-size:12px">${c.email||'—'}</td>
      <td style="font-size:12px">${c.tel||'—'}</td>
      <td><span class="badge badge-blue">${prospectos}</span></td>
      <td><span class="badge badge-green">${clientes}</span></td>
      <td><span class="badge badge-gold">${visitas}</span></td>
      <td><button class="btn btn-secondary btn-sm" onclick="editComercial('${c.id}')" style="margin-right:6px">✏️</button><button class="btn btn-danger btn-sm" onclick="deleteComercial('${c.id}')">🗑</button></td>
    </tr>`;
  }).join('');
  renderRanking();
}

function renderRanking(){
  const el = document.getElementById('ranking-comerciales');
  if(!el) return;
  const ranked = db.comerciales.map(c=>({
    nombre: c.nombre,
    total: db.records.filter(r=>r.comercialId===c.id).length,
    cerrados: db.records.filter(r=>r.comercialId===c.id&&r.estadoProspecto==='facturado').length,
    visitas: db.records.filter(r=>r.comercialId===c.id&&((r.visita&&r.visita!=='no')||(r.visitaCliente&&r.visitaCliente!=='no'))).length,
    facturado: db.records.filter(r=>r.comercialId===c.id&&(r.facturadoP!=='no'||r.facturado!=='no')).reduce((acc,r)=>{
      const v = Number(r.tipo==='prospecto'?r.valorP:r.valor)||0; return acc+v;
    },0)
  })).sort((a,b)=>b.total-a.total);
  const medals = ['🥇','🥈','🥉'];
  el.innerHTML = ranked.map((r,i)=>`
    <div style="display:flex;align-items:center;gap:12px;padding:10px 0;border-bottom:1px solid var(--border)">
      <span style="font-size:20px;width:28px;text-align:center">${medals[i]||'👤'}</span>
      <div style="flex:1">
        <div style="font-weight:600;font-size:14px">${r.nombre}</div>
        <div style="font-size:11px;color:var(--text2);margin-top:3px">
          <span style="color:var(--accent)">${r.total} registros</span> · 
          <span style="color:var(--green)">${r.cerrados} cerrados</span> · 
          <span style="color:var(--gold)">${r.visitas} visitas</span>
        </div>
      </div>
      <div style="font-family:'Barlow Condensed',sans-serif;font-weight:700;font-size:15px;color:var(--gold)">
        $${Math.round(r.facturado).toLocaleString('es-CO')}
      </div>
    </div>`).join('') || '<div style="color:var(--text2);font-size:13px;text-align:center;padding:20px">Sin registros aún</div>';
}

function deleteComercial(id){
  if(db.records.some(r=>r.comercialId===id)){ toast('⚠️','No se puede eliminar: tiene registros asociados','#f5a623'); return; }
  db.comerciales = db.comerciales.filter(c=>c.id!==id);
  save(); populateComercialSelects(); renderEquipo();
}

// ============================================================
// CONTACTOS MÚLTIPLES
// ============================================================
function renderContactosList(){
  const cont = document.getElementById('f-contactos-list');
  if(!cont) return;
  const contactos = window._contactosForm || [];
  if(contactos.length === 0){
    agregarContacto(); // always start with at least one
    return;
  }
  cont.innerHTML = contactos.map((c,i)=>`
    <div class="contact-card" id="ccard-${i}">
      <div class="contact-card-header">
        <span class="contact-card-label">
          ${i===0?'<span class="contact-principal-badge">⭐ Principal</span>':'Contacto '+(i+1)}
        </span>
        ${i>0?`<button type="button" onclick="eliminarContacto(${i})" style="background:none;border:none;cursor:pointer;color:var(--text2);font-size:18px;line-height:1" title="Eliminar contacto">✕</button>`:''}
      </div>
      <div class="form-grid" style="margin-bottom:0">
        <div class="form-group" style="margin-bottom:0">
          <label>Nombre</label>
          <input type="text" placeholder="Nombre del contacto" value="${escHtml(c.nombre||'')}"
            oninput="updateContacto(${i},'nombre',this.value)">
        </div>
        <div class="form-group" style="margin-bottom:0">
          <label>Cargo</label>
          <input type="text" placeholder="Ej: Gerente Logístico" value="${escHtml(c.cargo||'')}"
            oninput="updateContacto(${i},'cargo',this.value)">
        </div>
        <div class="form-group" style="margin-bottom:0">
          <label>Teléfono</label>
          <input type="text" placeholder="+57 300 000 0000" value="${escHtml(c.telefono||'')}"
            oninput="updateContacto(${i},'telefono',this.value)">
        </div>
        <div class="form-group" style="margin-bottom:0">
          <label>Email</label>
          <input type="email" placeholder="correo@empresa.com" value="${escHtml(c.email||'')}"
            oninput="updateContacto(${i},'email',this.value)">
        </div>
        <div class="form-group" style="margin-bottom:0">
          <label>🎂 Fecha de Cumpleaños</label>
          <input type="date" value="${escHtml(c.cumpleanos||'')}"
            oninput="updateContacto(${i},'cumpleanos',this.value)">
        </div>
        <div class="form-group" style="margin-bottom:0">
          <label>🎁 ¿Puede recibir regalos?</label>
          <select onchange="updateContacto(${i},'recibeRegalos',this.value)">
            <option value="" ${!c.recibeRegalos?'selected':''}>— Sin definir —</option>
            <option value="si" ${c.recibeRegalos==='si'?'selected':''}>✅ Sí</option>
            <option value="no" ${c.recibeRegalos==='no'?'selected':''}>❌ No</option>
          </select>
        </div>
        <div class="form-group" style="margin-bottom:0">
          <label>🏷️ Tipo de Contacto</label>
          <select onchange="updateContacto(${i},'tipoContacto',this.value)">
            <option value="" ${!c.tipoContacto?'selected':''}>— Sin definir —</option>
            <option value="principal" ${c.tipoContacto==='principal'?'selected':''}>⭐ Principal</option>
            <option value="comercial" ${c.tipoContacto==='comercial'?'selected':''}>💼 Comercial</option>
            <option value="gestion-documental" ${c.tipoContacto==='gestion-documental'?'selected':''}>📁 Gestión Documental</option>
            <option value="financiero" ${c.tipoContacto==='financiero'?'selected':''}>💰 Financiero</option>
            <option value="operativo" ${c.tipoContacto==='operativo'?'selected':''}>⚙️ Operativo</option>
          </select>
        </div>
      </div>
    </div>`).join('');
}

function agregarContacto(){
  if(!window._contactosForm) window._contactosForm = [];
  window._contactosForm.push({nombre:'',cargo:'',telefono:'',email:'',cumpleanos:'',recibeRegalos:'',tipoContacto: window._contactosForm.length===0 ? 'principal' : ''});
  renderContactosList();
}

function eliminarContacto(idx){
  if(!window._contactosForm || idx===0) return;
  window._contactosForm.splice(idx,1);
  renderContactosList();
}

function updateContacto(idx, field, val){
  if(!window._contactosForm) return;
  if(!window._contactosForm[idx]) return;
  window._contactosForm[idx][field] = val;
}

function getContactosForm(){
  return (window._contactosForm||[]).filter(c=>c.nombre||c.email||c.telefono);
}

// ============================================================
// TIPO DE CLIENTE
// ============================================================
function onTipoClienteChange(val){
  const grpInd = document.getElementById('grupo-cliente-indirecto');

  if(val === 'referido'){
    grpInd.style.display = 'block';

    const sel = document.getElementById('f-cliente-indirecto');
    const indirectos = db.records.filter(r=>r.tipoCliente==='indirecto');
    sel.innerHTML = '<option value="">— Seleccionar aliado —</option>' +
      indirectos.map(r=>`<option value="${r.id}">${r.empresa} (${r.tipo==='prospecto'?'Prospecto':'Cliente'})</option>`).join('');
  } else if(val === 'indirecto'){
    grpInd.style.display = 'none';

  } else {
    grpInd.style.display = 'none';

  }
}

function convertirACliente(){
  var recId = document.getElementById('det-record-id').value;
  if(!recId){ toast('⚠️','No hay registro activo','#f5a623'); return; }
  var rec = db.records.find(function(r){ return r.id===recId; });
  if(!rec){ toast('⚠️','Registro no encontrado','#f5a623'); return; }
  if(rec.tipo==='cliente'){ toast('ℹ️','Este registro ya es un cliente','#00c2ff'); return; }

  // Confirm
  if(!confirm('¿Confirmas convertir "'+rec.empresa+'" de Prospecto a Cliente?')) return;

  // Change tipo
  rec.tipo = 'cliente';
  rec.estadoCliente = 'activo';
  rec.fechaConversion = new Date().toISOString().slice(0,10);
  // Keep prospect data as history
  rec.estadoProspectoFinal = rec.estadoProspecto || 'facturado';
  delete rec.estadoProspecto;

  save();
  toast('🏢', rec.empresa+' convertido a Cliente', '#00e676');

  // Update UI
  setTipoDetalle('cliente');
  var btn = document.getElementById('btn-convertir-cliente');
  if(btn) btn.style.display='none';
  renderProspectos();
  renderClientes();
  renderCRM();
  renderDashboard();
}

function saveRecord(){
  const empresa = document.getElementById('f-empresa').value.trim();
  const comercialId = document.getElementById('f-comercial').value;
  if(!empresa){ toast('⚠️','Ingresa el nombre de la empresa','#f5a623'); return; }
  if(!comercialId){ toast('⚠️','Selecciona un comercial responsable','#f5a623'); return; }
  if(selectedServices.length===0){ toast('⚠️','Selecciona al menos un servicio','#f5a623'); return; }

  const tipo = document.getElementById('tipo-registro').value;
  const comercial = db.comerciales.find(c=>c.id===comercialId);

  const contactos = getContactosForm();
  const contactoPrincipal = contactos[0] || {};

  const rec = {
    id: 'r'+Date.now(),
    tipo,
    empresa,
    nit: document.getElementById('f-nit').value,
    contacto:  contactoPrincipal.nombre  || '',
    cargo:     contactoPrincipal.cargo   || '',
    telefono:  contactoPrincipal.telefono|| '',
    email:     contactoPrincipal.email   || '',
    contactos,
    ciudad:     document.getElementById('f-ciudad').value,
    direccion: document.getElementById('f-direccion')?.value.trim()||'',
    comercialId,
    comercialNombre: comercial?.nombre||'—',
    servicios: [...selectedServices],
    fecha: document.getElementById('f-fecha').value || today(),
    categoria: document.getElementById('f-categoria')?.value || '',
    actividades: []
  };

  if(tipo === 'cliente'){
    rec.tipoCliente = document.getElementById('f-tipo-cliente')?.value || 'directo';
    if(rec.tipoCliente === 'referido'){
      rec.clienteIndirectoId = document.getElementById('f-cliente-indirecto')?.value || '';
      const ind = db.records.find(r=>r.id===rec.clienteIndirectoId);
      rec.clienteIndirectoNombre = ind?.empresa || '';
    }
    if(rec.tipoCliente === 'indirecto'){
      rec.comision = document.getElementById('f-comision')?.value || '';
    }
  }

  if(tipo==='prospecto'){
    rec.estadoProspecto    = document.getElementById('f-estado-prospecto').value;
    rec.visita             = document.getElementById('f-visita').value;
    rec.fechaVisita        = document.getElementById('f-fecha-visita').value;
    rec.proximoSeguimiento = document.getElementById('f-proximo-seguimiento').value;
    rec.ingresosEsperados  = Number(document.getElementById('f-ingresos-esperados').value)||0;
    rec.observaciones      = document.getElementById('f-obs-prospecto').value;
    rec.facturadoP         = document.getElementById('f-facturado-p').value;
    if(rec.facturadoP !== 'no'){
      rec.facturacionLineas = getBillingLines('p');
      rec.valorP = calcTotalBilling(rec.facturacionLineas);
    } else {
      rec.facturacionLineas = {};
      rec.valorP = 0;
    }
    if(rec.visita!=='no') rec.actividades.push({tipo:'visit',fecha:rec.fechaVisita||rec.fecha,desc:'Visita/Contacto: '+rec.visita});
    if(rec.valorP>0) rec.actividades.push({tipo:'invoice',fecha:rec.fecha,desc:'Facturación: $'+rec.valorP.toLocaleString('es-CO')});
  } else {
    rec.estadoCliente      = document.getElementById('f-estado-cliente').value;
    rec.visitaCliente      = document.getElementById('f-visita-cliente').value;
    rec.fechaVisitaCliente = document.getElementById('f-fecha-visita-cliente').value;
    rec.nuevoServicio      = document.getElementById('f-nuevo-servicio').value;
    rec.servicioNuevo      = document.getElementById('f-servicio-nuevo').value;
    rec.facturado          = document.getElementById('f-facturado').value;
    rec.observaciones      = document.getElementById('f-obs-cliente').value;
    if(rec.facturado !== 'no'){
      rec.facturacionLineas = getBillingLines('c');
      rec.valor = calcTotalBilling(rec.facturacionLineas);
    } else {
      rec.facturacionLineas = {};
      rec.valor = 0;
    }
    if(rec.visitaCliente!=='no') rec.actividades.push({tipo:'visit',fecha:rec.fechaVisitaCliente||rec.fecha,desc:'Visita cliente: '+rec.visitaCliente});
    if(rec.nuevoServicio==='si') rec.actividades.push({tipo:'service',fecha:rec.fecha,desc:'Nuevo servicio: '+(rec.servicioNuevo||'Sin especificar')});
    if(rec.valor>0) rec.actividades.push({tipo:'invoice',fecha:rec.fecha,desc:'Facturación: $'+Number(rec.valor).toLocaleString('es-CO')});
  }

  db.records.push(rec);
  if(rec.tipo==='cliente'){ mrGetData(rec.id); }
  save();
  clearForm();
  toast('✅','Registro guardado exitosamente','#00e676');
  setTimeout(()=>showPage('dashboard'),1200);
}

function clearForm(){
  ['f-empresa','f-nit','f-ciudad',
   'f-obs-prospecto','f-obs-cliente','f-fecha-visita','f-proximo-seguimiento','f-fecha-visita-cliente'
  ].forEach(id=>{ const el=document.getElementById(id); if(el) el.value=''; });

  document.getElementById('f-fecha').value = today();
  document.getElementById('f-comercial').value = '';

  // Reset tipo cliente
  const ftc = document.getElementById('f-tipo-cliente');
  if(ftc){ ftc.value='directo'; onTipoClienteChange('directo'); }
  const fci = document.getElementById('f-comision'); if(fci) fci.value='';

  // Reset contactos
  window._contactosForm = [{nombre:'',cargo:'',telefono:'',email:'',cumpleanos:'',recibeRegalos:''}];
  const fcat = document.getElementById('f-categoria'); if(fcat) fcat.value='';
  const fdir = document.getElementById('f-direccion'); if(fdir) fdir.value='';
  renderContactosList();

  // Reset billing selectors
  const fpP = document.getElementById('f-facturado-p');
  if(fpP) fpP.value = 'no';
  const fpC = document.getElementById('f-facturado');
  if(fpC) fpC.value = 'no';

  // Hide billing blocks
  const bkP = document.getElementById('f-billing-block-p');
  if(bkP) bkP.style.display = 'none';
  const bkC = document.getElementById('f-billing-block-c');
  if(bkC) bkC.style.display = 'none';

  // Reset totals
  const tp = document.getElementById('f-total-p'); if(tp) tp.textContent='$0';
  const tc = document.getElementById('f-total-c'); if(tc) tc.textContent='$0';

  selectedServices = [];
  buildServiceChips();
  setTipo('prospecto');
}

