function initPaqueteoGrupos(){
  const bib = db.biblioteca['Paqueteo'];
  if(!bib) return;
  const allTipos = [...PAQUETEO_GRUPOS_COORD, ...PAQUETEO_GRUPOS_TCC, ...PAQUETEO_GRUPOS_SERVIENTREGA];
  // Seed with predefined groups if empty
  if(!bib.grupos || bib.grupos.length === 0){
    bib.grupos = allTipos.map(tipo => ({
      id: 'g-paq-' + tipo,
      nombre: PAQUETEO_SCHEMA[tipo].label,
      tipo,
      items: [],
      obsEcommerce: ''
    }));
    save();
  }
  // Ensure all expected groups exist (backwards compat)
  allTipos.forEach(tipo => {
    if(!bib.grupos.find(g => g.tipo === tipo)){
      bib.grupos.push({ id:'g-paq-'+tipo+Date.now(), nombre: PAQUETEO_SCHEMA[tipo].label, tipo, items:[], obsEcommerce:'' });
    }
  });
}

function togglePaqTab(bodyId, arrowId){
  const body = document.getElementById(bodyId);
  const arrow = document.getElementById(arrowId);
  if(!body) return;
  if(body.style.display === 'none'){ body.style.display = 'block'; if(arrow) arrow.textContent = '▲'; }
  else { body.style.display = 'none'; if(arrow) arrow.textContent = '▼'; }
}

function addBibGrupoPaqueteo(tipo){
  const svc = 'Paqueteo';
  if(!db.biblioteca[svc]) return;
  const schema = PAQUETEO_SCHEMA[tipo];
  const g = { id:'g'+Date.now(), nombre: schema.label, tipo, items:[], obsEcommerce:'' };
  db.biblioteca[svc].grupos.push(g);
  save(); renderBiblioteca();
  const key = svc.replace(/\s/g,'-');
  document.getElementById('bib-body-'+key).style.display='block';
  document.getElementById('bib-arrow-'+key).textContent='▲';
}

function addBibItemPaqueteo(gid){
  const svc = 'Paqueteo';
  const g = db.biblioteca[svc]?.grupos.find(g=>g.id===gid);
  if(!g) return;
  const schema = PAQUETEO_SCHEMA[g.tipo] || PAQUETEO_SCHEMA.coord_industrial;
  const campos = {};
  schema.cols.forEach(col => { campos[col.id] = ''; });
  g.items.push({ id:'i'+Date.now(), campos });
  save(); renderBiblioteca();
}

function updatePaqItemTipoCampo(gid, iid, campo, tipoCampo){
  const svc = 'Paqueteo';
  const g = db.biblioteca[svc]?.grupos.find(g=>g.id===gid);
  if(!g) return;
  const item = g.items.find(i=>i.id===iid);
  if(!item) return;
  if(!item.tiposCampo) item.tiposCampo = {};
  item.tiposCampo[campo] = tipoCampo;
  save(); renderBiblioteca();
}

function updatePaqItemCampo(gid, iid, campo, val){
  const svc = 'Paqueteo';
  const g = db.biblioteca[svc]?.grupos.find(g=>g.id===gid);
  if(!g) return;
  const item = g.items.find(i=>i.id===iid);
  if(!item) return;
  if(!item.campos) item.campos = {};
  item.campos[campo] = val;
  save();
}

function updatePaqGrupoObs(gid, val){
  const svc = 'Paqueteo';
  const g = db.biblioteca[svc]?.grupos.find(g=>g.id===gid);
  if(!g) return;
  g.obsEcommerce = val;
  save();
}

function renderBibGrupoPaqueteo(g){
  const svc = 'Paqueteo';
  const schema = PAQUETEO_SCHEMA[g.tipo];
  if(!schema) return renderBibGrupo(svc, g);
  const cols = schema.cols;

  const iS = 'width:100%;background:transparent;border:none;color:var(--text);font-size:12px;outline:none;border-bottom:1px solid transparent;padding:2px 0';
  const mS = 'width:100%;background:transparent;border:none;color:var(--gold);font-size:12px;font-weight:600;outline:none;border-bottom:1px solid transparent;padding:2px 0;text-align:right';
  const nS = 'width:100%;background:transparent;border:none;color:var(--accent);font-size:12px;outline:none;border-bottom:1px solid transparent;padding:2px 0;text-align:right';
  const pS = 'width:100%;background:transparent;border:none;color:var(--text2);font-size:12px;outline:none;border-bottom:1px solid transparent;padding:2px 0;text-align:right';
  const selS = 'background:var(--surface);border:1px solid var(--border);border-radius:4px;color:var(--text2);padding:2px 4px;font-size:10px;cursor:pointer';

  const focus  = (type) => { const m={'moneda':'var(--gold)','numero':'var(--accent)','porcentaje':'var(--text2)','texto':'var(--accent)'}; return m[type]||'var(--accent)'; };
  const getStyle = (tipo) => tipo==='moneda'?mS : tipo==='numero'?nS : tipo==='porcentaje'?pS : iS;
  const getPrefix = (tipo) => tipo==='moneda'?'<span style="color:var(--gold);font-size:11px;margin-right:2px">$</span>': tipo==='porcentaje'?'<span style="color:var(--text2);font-size:11px;margin-right:2px">%</span>':'';
  const getPlaceholder = (tipo) => tipo==='texto'?'—': tipo==='porcentaje'?'0.00':'0';

  const itemsHtml = g.items.map(item => {
    if(!item.campos) item.campos = {};
    if(!item.tiposCampo) item.tiposCampo = {};
    const cells = cols.map(col => {
      const val = item.campos[col.id] || '';
      // 'mixta' type: moneda | porcentaje | texto selectable per cell
      if(col.tipo === 'mixta'){
        const tc = item.tiposCampo[col.id] || 'moneda';
        const inpS = tc==='moneda'?mS : tc==='porcentaje'?pS : iS;
        return `<td style="padding:5px 8px;white-space:nowrap">
          <div style="display:flex;align-items:center;gap:3px">
            <select style="${selS}" onchange="updatePaqItemTipoCampo('${g.id}','${item.id}','${col.id}',this.value)">
              <option value="moneda"${tc==='moneda'?' selected':''}>$</option>
              <option value="porcentaje"${tc==='porcentaje'?' selected':''}>%</option>
              <option value="texto"${tc==='texto'?' selected':''}>Txt</option>
            </select>
            <input type="text" value="${val}" style="${inpS}"
              onfocus="this.style.borderBottomColor='${focus(tc)}'"
              onblur="this.style.borderBottomColor='transparent'"
              onchange="updatePaqItemCampo('${g.id}','${item.id}','${col.id}',this.value)"
              placeholder="${tc==='texto'?'—':'0'}">
          </div></td>`;
      }
      return `<td style="padding:5px 8px;white-space:nowrap">
        <div style="display:flex;align-items:center;gap:2px">
          ${getPrefix(col.tipo)}
          <input type="text" value="${val}"
            style="${getStyle(col.tipo)}"
            placeholder="${getPlaceholder(col.tipo)}"
            onfocus="this.style.borderBottomColor='${focus(col.tipo)}'"
            onblur="this.style.borderBottomColor='transparent'"
            onchange="updatePaqItemCampo('${g.id}','${item.id}','${col.id}',this.value)">
        </div></td>`;
    }).join('');
    return `<tr>${cells}
      <td style="width:36px;text-align:center"><button onclick="deleteBibItem('${svc}','${g.id}','${item.id}')" style="background:none;border:none;cursor:pointer;color:var(--text2);font-size:14px" title="Eliminar">✕</button></td>
    </tr>`;
  }).join('');

  // Build headers — with optional colspan group row for tcc_radicacion
  let theads = '';
  if(schema.colspanGroups && schema.colspanGroups.length){
    // First column (Trayecto) spans across
    const firstCol = cols.find(col => !schema.colspanGroups.some(cg => cg.cols.includes(col.id)));
    const groupRow = `<th rowspan="2" style="font-size:11px;white-space:nowrap;vertical-align:middle">${firstCol ? firstCol.nombre : ''}</th>` +
      schema.colspanGroups.map(cg =>
        `<th colspan="${cg.cols.length}" style="font-size:11px;text-align:center;background:rgba(0,194,255,0.08);border-bottom:1px solid var(--border)">${cg.label}</th>`
      ).join('');
    const subRow = schema.colspanGroups.map(cg =>
      cg.cols.map(cid => {
        const col = cols.find(c => c.id === cid);
        return `<th style="font-size:10px;white-space:nowrap;font-weight:500">${col ? col.nombre : cid}</th>`;
      }).join('')
    ).join('');
    theads = `<tr>${groupRow}</tr><tr>${subRow}</tr>`;
  } else {
    theads = `<tr>${cols.map(col => `<th style="font-size:11px;white-space:nowrap">${col.nombre}</th>`).join('')}</tr>`;
  }

  // Optional observation field (Ecommerce)
  const obsBlock = schema.hasObs ? `
    <div style="margin-top:14px;padding:12px 14px;background:var(--surface3);border-radius:6px;border:1px solid rgba(245,166,35,0.2)">
      <div style="font-size:11px;color:var(--gold);font-weight:700;letter-spacing:1.5px;text-transform:uppercase;margin-bottom:8px">📝 Observación Ecommerce (aparece en cotización debajo de la tabla)</div>
      <textarea rows="3" style="width:100%;background:var(--surface2);border:1px solid var(--border);border-radius:6px;color:var(--text);font-size:13px;padding:8px;outline:none;resize:vertical;box-sizing:border-box"
        onfocus="this.style.borderColor='var(--gold)'" onblur="this.style.borderColor='var(--border)'"
        onchange="updatePaqGrupoObs('${g.id}',this.value)"
        placeholder="Ej: Tarifas sujetas a cambio sin previo aviso. IVA no incluido...">${g.obsEcommerce||''}</textarea>
    </div>` : '';

  return `
    <div class="bib-grupo-row" id="bib-grupo-${g.id}"
      draggable="true"
      ondragstart="bibGrupoDragStart(event,'${svc}','${g.id}')"
      ondragover="bibGrupoDragOver(event)"
      ondrop="bibGrupoDrop(event,'${svc}','${g.id}')"
      ondragend="bibGrupoDragEnd(event)"
      style="">
      <div class="bib-grupo-title-row">
        <span title="Arrastrar para reordenar"
          style="cursor:grab;color:var(--border);font-size:20px;flex-shrink:0;padding:0 4px;line-height:1;user-select:none">⠿</span>
        <input type="text" value="${g.nombre}"
          style="flex:1;background:transparent;border:none;color:var(--accent);font-family:'Barlow Condensed',sans-serif;font-size:15px;font-weight:700;letter-spacing:1px;text-transform:uppercase;outline:none"
          onchange="updateBibGrupoNombre('${svc}','${g.id}',this.value)">
        <button class="btn btn-danger btn-sm" style="padding:4px 8px;font-size:11px" onclick="deleteBibGrupo('${svc}','${g.id}')">🗑 Grupo</button>
      </div>
      <div style="padding:0 14px 14px;overflow-x:auto">
        <table class="bib-items-table">
          <thead>${theads}</thead>
          <tbody id="bib-items-${g.id}">${itemsHtml}</tbody>
        </table>
        <button class="btn btn-secondary btn-sm" style="margin-top:8px" onclick="addBibItemPaqueteo('${g.id}')">+ Ítem</button>
        ${obsBlock}
      </div>
    </div>`;
}

function renderBibGrupo(svc, g){
  const svcKey = svc.replace(/\s/g,'-');
  const extraCols = db.biblioteca[svc]?.columnas || [];
  const ch = db.biblioteca[svc]?.colHeaders || {};
  const h1 = ch.col1 || 'Servicio';
  const h2 = ch.col2 || 'Tarifa';
  const h3 = ch.col3 || 'Observación';
  const itemsHtml = g.items.map((item,ii)=>`
    <tr>
      <td><input type="text" value="${item.nombre}" style="width:100%;background:transparent;border:none;color:var(--text);font-size:13px;outline:none;border-bottom:1px solid transparent" onfocus="this.style.borderBottomColor='var(--accent)'" onblur="this.style.borderBottomColor='transparent'" onchange="updateBibItem('${svc}','${g.id}','${item.id}','nombre',this.value)"></td>
      <td style="width:150px">
        <div style="display:flex;gap:4px;align-items:center">
          <select style="background:var(--surface);border:1px solid var(--border);border-radius:4px;color:var(--text2);padding:3px 6px;font-size:11px" onchange="updateBibItem('${svc}','${g.id}','${item.id}','tipoTarifa',this.value)">
            <option value="moneda"${item.tipoTarifa==='moneda'?' selected':''}>$</option>
            <option value="porcentaje"${item.tipoTarifa==='porcentaje'?' selected':''}>%</option>
          </select>
          <input type="text" value="${item.tarifa}" style="width:90px;background:transparent;border:none;color:var(--gold);font-size:13px;font-weight:600;outline:none;border-bottom:1px solid transparent" onfocus="this.style.borderBottomColor='var(--gold)'" onblur="this.style.borderBottomColor='transparent'" onchange="updateBibItem('${svc}','${g.id}','${item.id}','tarifa',this.value)">
        </div>
      </td>
      <td><input type="text" value="${item.obs||''}" style="width:100%;background:transparent;border:none;color:var(--text2);font-size:12px;outline:none;border-bottom:1px solid transparent" onfocus="this.style.borderBottomColor='var(--accent)'" onblur="this.style.borderBottomColor='transparent'" onchange="updateBibItem('${svc}','${g.id}','${item.id}','obs',this.value)"></td>
      ${extraCols.map(col=>`
      <td><input type="text" value="${(item.extraCols&&item.extraCols[col.id])||''}" style="width:100%;background:transparent;border:none;color:var(--text2);font-size:12px;outline:none;border-bottom:1px solid transparent" onfocus="this.style.borderBottomColor='var(--accent)'" onblur="this.style.borderBottomColor='transparent'" placeholder="${col.nombre}" onchange="updateBibItemExtra('${svc}','${g.id}','${item.id}','${col.id}',this.value)"></td>`).join('')}
      <td style="width:40px;text-align:center"><button onclick="deleteBibItem('${svc}','${g.id}','${item.id}')" style="background:none;border:none;cursor:pointer;color:var(--text2);font-size:14px" title="Eliminar">✕</button></td>
    </tr>`).join('');
  return `
    <div class="bib-grupo-row" id="bib-grupo-${g.id}" data-gid="${g.id}" data-svc="${svc}"
      draggable="true"
      ondragstart="bibGrupoDragStart(event,'${svc}','${g.id}')"
      ondragover="bibGrupoDragOver(event)"
      ondrop="bibGrupoDrop(event,'${svc}','${g.id}')"
      ondragend="bibGrupoDragEnd(event)">
      <div class="bib-grupo-title-row">
        <span title="Arrastrar para reordenar" style="cursor:grab;color:var(--border);font-size:20px;padding:0 6px 0 0;line-height:1;flex-shrink:0" onmousedown="this.style.cursor='grabbing'" onmouseup="this.style.cursor='grab'">⠿</span>
        <input type="text" value="${g.nombre}" style="flex:1;background:transparent;border:none;color:var(--accent);font-family:'Barlow Condensed',sans-serif;font-size:15px;font-weight:700;letter-spacing:1px;text-transform:uppercase;outline:none" onchange="updateBibGrupoNombre('${svc}','${g.id}',this.value)">
        <button class="btn btn-danger btn-sm" style="padding:4px 8px;font-size:11px" onclick="deleteBibGrupo('${svc}','${g.id}')">🗑 Grupo</button>
      </div>
      <div style="padding:0 14px 14px;overflow-x:auto">
        <table class="bib-items-table">
          <thead><tr>
            <th>${h1}</th><th>${h2}</th><th>${h3}</th>
            ${extraCols.map(col=>`<th>${col.nombre}</th>`).join('')}
            <th></th>
          </tr></thead>
          <tbody id="bib-items-${g.id}">${itemsHtml}</tbody>
        </table>
        <button class="btn btn-secondary btn-sm" style="margin-top:8px" onclick="addBibItem('${svc}','${g.id}')">+ Ítem</button>
      </div>
    </div>`;
}

function renderBiblioteca(){
  initBiblioteca();
  const cont = document.getElementById('bib-lineas-container');
  if(!cont) return;
  try {
  cont.innerHTML = SERVICES.map(svc=>{
    const bib = db.biblioteca[svc];
    const color = SVC_COLORS[svc]||'var(--accent)';
    const svcKey = svc.replace(/\s/g,'-');

    // Build grupos HTML
    let gruposHtml = '';
    if(svc === 'Transporte'){
      gruposHtml = bib.grupos.map(g => renderBibGrupoTransporte(svc, g)).join('');
    } else if(svc === 'Paqueteo'){
      gruposHtml = PAQUETEO_PAQUETEADORAS.map(paq => {
        const paqGrupos = bib.grupos.filter(g => PAQUETEO_SCHEMA[g.tipo]?.paqueteadora === paq);
        if(!paqGrupos.length) return '';
        const paqColor = paq==='COORDINADORA'?'var(--accent)':'#e8312a';
        const paqId     = 'paq-tab-'+paq.toLowerCase();
        const paqBodyId = 'paq-body-'+paq.toLowerCase();
        const innerContent = paqGrupos.map(g => renderBibGrupoPaqueteo(g)).join('');
        const paqOnclick = 'togglePaqTab(\'' + paqBodyId + '\',\'' + paqId + '\')';
        return [
          '<div style="margin-bottom:12px;border:1px solid var(--border);border-radius:10px;overflow:hidden">',
          '<div style="display:flex;align-items:center;justify-content:space-between;padding:12px 16px;background:var(--surface3);cursor:pointer"',
          ' onclick="' + paqOnclick + '">',
          '<div style="display:flex;align-items:center;gap:10px">',
          '<span style="font-family:Barlow Condensed,sans-serif;font-size:16px;font-weight:800;letter-spacing:2px;text-transform:uppercase;color:'+paqColor+'">'+paq+'</span>',
          '<span style="font-size:11px;color:var(--text2)">'+paqGrupos.length+' grupos &middot; '+paqGrupos.reduce((a,g)=>a+g.items.length,0)+' ítems</span>',
          '</div>',
          '<span style="color:var(--text2);font-size:16px" id="'+paqId+'">&#9660;</span>',
          '</div>',
          '<div id="'+paqBodyId+'" style="display:none;padding:12px">'+innerContent+'</div>',
          '</div>'
        ].join('');
      }).join('');
    } else {
      gruposHtml = bib.grupos.map(g => renderBibGrupo(svc, g)).join('');
    }

    // Add group button
    let addGrupoBtn = '';
    if(svc==='Transporte'){
      addGrupoBtn = `<div style="display:flex;gap:8px;margin-bottom:20px;flex-wrap:wrap">
        <button class="btn btn-secondary btn-sm" onclick="addBibGrupoTransporte('Transporte','local')">+ Nuevo grupo Transporte Local</button>
        <button class="btn btn-secondary btn-sm" onclick="addBibGrupoTransporte('Transporte','otros')">+ Nuevo grupo Otros Servicios</button>
      </div>`;
    } else if(svc==='Paqueteo'){
      addGrupoBtn = '';
    } else {
      addGrupoBtn = `<button class="btn btn-secondary btn-sm" style="margin-bottom:20px" onclick="addBibGrupo('${svc}')">+ Nuevo grupo</button>`;
    }

    // Extra columns section (not for Transporte/Paqueteo)
    const extraColsHtml = (svc==='Transporte'||svc==='Paqueteo') ? `
      <div style="font-size:12px;color:var(--text2);margin-bottom:10px">
        Las columnas para <strong>${svc}</strong> están definidas por esquema fijo.
      </div>` : (() => {
        const extraCols = bib.columnas||[];
        const ch = bib.colHeaders||{};
        return `
        <div style="font-size:12px;color:var(--text2);margin-bottom:10px">
          Columnas por defecto: <strong>${ch.col1||'Servicio'}</strong>, <strong>${ch.col2||'Tarifa'}</strong>, <strong>${ch.col3||'Observaciones'}</strong>.
          Puedes renombrarlas:
        </div>
        <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px">
          ${['col1','col2','col3'].map(k=>`
            <input type="text" value="${ch[k]||{col1:'Servicio',col2:'Tarifa',col3:'Observaciones'}[k]}"
              placeholder="${{col1:'Servicio',col2:'Tarifa',col3:'Observaciones'}[k]}"
              style="background:var(--surface2);border:1px solid var(--border);border-radius:6px;color:var(--text);padding:6px 10px;font-size:12px;outline:none;width:140px"
              onchange="updateBibColHeader('${svc}','${k}',this.value)">`).join('')}
        </div>
        ${extraCols.map(col=>`
          <div style="display:flex;align-items:center;gap:6px;margin-bottom:6px">
            <input type="text" value="${col.nombre}"
              style="background:var(--surface2);border:1px solid var(--border);border-radius:6px;color:var(--text);padding:6px 10px;font-size:12px;outline:none;width:160px"
              onchange="updateBibColNombre('${svc}','${col.id}',this.value)">
            <button onclick="deleteBibCol('${svc}','${col.id}')" style="background:none;border:none;color:var(--red);cursor:pointer;font-size:14px">✕</button>
          </div>`).join('')}
        <button class="btn btn-secondary btn-sm" onclick="addBibCol('${svc}')">+ Columna extra</button>`;
      })();

    // Obs section
    const obsHtml = renderBibObsCards(svc);

    return `
    <div style="background:var(--surface2);border:1px solid var(--border);border-radius:12px;margin-bottom:12px;overflow:hidden">
      <div style="display:flex;align-items:center;justify-content:space-between;padding:14px 18px;cursor:pointer;background:var(--surface3)"
           onclick="toggleBibLinea('${svcKey}')">
        <div style="display:flex;align-items:center;gap:12px">
          <span style="font-size:22px">${SVC_ICONS[svc]||'📋'}</span>
          <div>
            <div style="font-family:'Barlow Condensed',sans-serif;font-size:17px;font-weight:700;letter-spacing:1px;color:${color}">${svc}</div>
            <div style="font-size:12px;color:var(--text2)">${bib.grupos.length} grupos · ${bib.grupos.reduce((a,g)=>a+g.items.length,0)} ítems</div>
          </div>
        </div>
        <span style="color:var(--text2);font-size:18px" id="bib-arrow-${svcKey}">▼</span>
      </div>
      <div id="bib-body-${svcKey}" style="display:none;padding:18px">
        <div style="margin-bottom:20px;padding:14px 16px;background:var(--surface3);border-radius:8px;border:1px solid var(--border)">
          <div style="font-family:'Barlow Condensed',sans-serif;font-size:13px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:var(--accent);margin-bottom:10px">
            🗂 Columnas de la tabla en cotización
          </div>
          ${extraColsHtml}
        </div>
        <div id="bib-grupos-${svcKey}">${gruposHtml}</div>
        ${addGrupoBtn}
        <div style="margin-top:20px;border-top:1px solid var(--border);padding-top:16px">
          <div style="font-family:'Barlow Condensed',sans-serif;font-size:13px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:var(--accent);margin-bottom:10px">
            📝 Observaciones de cotización
          </div>
          ${obsHtml}
          <button class="btn btn-secondary btn-sm" style="margin-top:8px" onclick="addBibObsRich('${svc}')">+ Nueva observación</button>
        </div>
      </div>
    </div>`;
  }).join('');
  } catch(err){ console.error('renderBiblioteca error:', err); }
}


function toggleBibLinea(key){
  const body = document.getElementById('bib-body-'+key);
  const arrow = document.getElementById('bib-arrow-'+key);
  if(body.style.display==='none'){ body.style.display='block'; arrow.textContent='▲'; }
  else { body.style.display='none'; arrow.textContent='▼'; }
}

function addBibGrupo(svc){
  const g = {id:'g'+Date.now(), nombre:'Nuevo Grupo', items:[]};
  db.biblioteca[svc].grupos.push(g);
  save();
  renderBiblioteca();
  const key = svc.replace(/\s/g,'-');
  document.getElementById('bib-body-'+key).style.display='block';
  document.getElementById('bib-arrow-'+key).textContent='▲';
}

function deleteBibGrupo(svc, gid){
  const g = db.biblioteca[svc].grupos.find(g=>g.id===gid);
  if(!g) return;
  const nItems = g.items?.length || 0;
  const itemsMsg = nItems > 0 ? `\n\nEste grupo contiene ${nItems} ítem(s) que también se eliminarán.` : '';
  if(!confirm(`¿Estás seguro de eliminar el grupo "${g.nombre}"?${itemsMsg}\n\nEsta acción no se puede deshacer.`)) return;
  db.biblioteca[svc].grupos = db.biblioteca[svc].grupos.filter(g=>g.id!==gid);
  save(); renderBiblioteca();
}

function updateBibGrupoNombre(svc, gid, val){
  const g = db.biblioteca[svc].grupos.find(g=>g.id===gid);
  if(g){ g.nombre=val; save(); }
}

function addBibItem(svc, gid){
  const g = db.biblioteca[svc].grupos.find(g=>g.id===gid);
  if(!g) return;
  g.items.push({id:'i'+Date.now(), nombre:'Nuevo ítem', tarifa:'0', tipoTarifa:'moneda', obs:''});
  save(); renderBiblioteca();
}

function updateBibItem(svc, gid, iid, field, val){
  const g = db.biblioteca[svc].grupos.find(g=>g.id===gid);
  if(!g) return;
  const item = g.items.find(i=>i.id===iid);
  if(item){ item[field]=val; save(); }
}

function deleteBibItem(svc, gid, iid){
  const g = db.biblioteca[svc].grupos.find(g=>g.id===gid);
  if(!g) return;
  const item = g.items.find(i=>i.id===iid);
  const nombre = item?.nombre || 'este ítem';
  if(!confirm(`¿Estás seguro de eliminar "${nombre}"?\n\nEsta acción no se puede deshacer.`)) return;
  g.items = g.items.filter(i=>i.id!==iid);
  save(); renderBiblioteca();
}

function addBibObs(svc){
  db.biblioteca[svc].observaciones.push('Nueva observación');
  save(); renderBiblioteca();
}

function updateBibObs(svc, idx, val){
  db.biblioteca[svc].observaciones[idx] = val; save();
}

function deleteBibObs(svc, idx){
  db.biblioteca[svc].observaciones.splice(idx,1);
  save(); renderBiblioteca();
}

// ---- Gestión de columnas extra por línea ----
function updateBibColHeader(svc, key, val){
  if(!db.biblioteca[svc]) return;
  if(!db.biblioteca[svc].colHeaders) db.biblioteca[svc].colHeaders = {};
  db.biblioteca[svc].colHeaders[key] = val.trim()||{col1:'Servicio',col2:'Tarifa',col3:'Observación'}[key];
  save();
}

// ============================================================
// TRANSPORTE — estructura de columnas fija predefinida
// ============================================================




function renderBibGrupoTransporte(svc, g){
  const tipo = g.tipo || 'local';
  const schema = TRANSP_SCHEMA[tipo] || TRANSP_SCHEMA.local;
  const cols = schema.cols;
  const inputStyle = `width:100%;min-width:80px;background:transparent;border:none;border-bottom:1px solid transparent;color:var(--text);font-size:12px;outline:none;padding:2px 0`;
  const tarifaStyle = `min-width:70px;flex:1;background:transparent;border:none;border-bottom:1px solid transparent;color:var(--gold);font-size:12px;font-weight:600;outline:none;padding:2px 0`;
  const selStyle = `background:var(--surface);border:1px solid var(--border);border-radius:4px;color:var(--text2);padding:2px 4px;font-size:10px;cursor:pointer`;

  const itemsHtml = g.items.map(item=>{
    if(!item.campos) item.campos = {};
    if(!item.tiposCampo) item.tiposCampo = {};
    return `<tr>${cols.map(col=>{
      const val = item.campos[col.id]||'';
      const tipoCampo = item.tiposCampo[col.id] || 'moneda';

      if(col.tipo==='tarifa'){
        return `<td style="padding:6px 8px;white-space:nowrap">
          <div style="display:flex;align-items:center;gap:4px">
            <span style="color:var(--gold);font-size:11px">$</span>
            <input type="text" value="${val}" style="${tarifaStyle}" onfocus="this.style.borderBottomColor='var(--gold)'" onblur="this.style.borderBottomColor='transparent'" onchange="updateTranspItemCampo('${svc}','${g.id}','${item.id}','${col.id}',this.value)" placeholder="0">
          </div></td>`;
      }

      if(col.tipo==='tarifa-mixta'){
        // moneda o porcentaje
        return `<td style="padding:6px 8px;white-space:nowrap">
          <div style="display:flex;align-items:center;gap:3px">
            <select style="${selStyle}" onchange="updateTranspItemTipoCampo('${svc}','${g.id}','${item.id}','${col.id}',this.value)">
              <option value="moneda"${tipoCampo==='moneda'?' selected':''}>$</option>
              <option value="porcentaje"${tipoCampo==='porcentaje'?' selected':''}>%</option>
            </select>
            <input type="text" value="${val}" style="${tarifaStyle}" onfocus="this.style.borderBottomColor='var(--gold)'" onblur="this.style.borderBottomColor='transparent'" onchange="updateTranspItemCampo('${svc}','${g.id}','${item.id}','${col.id}',this.value)" placeholder="0">
          </div></td>`;
      }

      if(col.tipo==='tarifa-texto'){
        // moneda o texto libre
        return `<td style="padding:6px 8px;white-space:nowrap">
          <div style="display:flex;align-items:center;gap:3px">
            <select style="${selStyle}" onchange="updateTranspItemTipoCampo('${svc}','${g.id}','${item.id}','${col.id}',this.value)">
              <option value="moneda"${tipoCampo==='moneda'?' selected':''}>$</option>
              <option value="texto"${tipoCampo==='texto'?' selected':''}>Texto</option>
            </select>
            <input type="text" value="${val}" style="${tipoCampo==='texto'?inputStyle:tarifaStyle}" onfocus="this.style.borderBottomColor='${tipoCampo==='texto'?'var(--accent)':'var(--gold)'}" onblur="this.style.borderBottomColor='transparent'" onchange="updateTranspItemCampo('${svc}','${g.id}','${item.id}','${col.id}',this.value)" placeholder="${tipoCampo==='texto'?'ej: 2 Horas':'0'}">
          </div></td>`;
      }

      return `<td style="padding:6px 8px">
        <input type="text" value="${val}" style="${inputStyle}" onfocus="this.style.borderBottomColor='var(--accent)'" onblur="this.style.borderBottomColor='transparent'" onchange="updateTranspItemCampo('${svc}','${g.id}','${item.id}','${col.id}',this.value)" placeholder="${col.nombre}">
      </td>`;
    }).join('')}
    <td style="padding:6px;text-align:center;width:32px"><button onclick="deleteBibItem('${svc}','${g.id}','${item.id}')" style="background:none;border:none;cursor:pointer;color:var(--text2);font-size:13px" title="Eliminar">✕</button></td>
    </tr>`;
  }).join('');

  const thStyle = `padding:7px 8px;font-size:10px;color:var(--accent);text-align:left;text-transform:uppercase;letter-spacing:0.5px;white-space:normal;min-width:80px`;

  return `
  <div class="bib-grupo-row" id="bib-grupo-${g.id}">
    <div class="bib-grupo-title-row">
      <div style="display:flex;align-items:center;gap:8px;flex:1">
        <span style="font-size:11px;padding:2px 8px;border-radius:10px;background:${tipo==='local'?'rgba(0,194,255,0.12)':'rgba(245,166,35,0.12)'};color:${tipo==='local'?'var(--accent)':'var(--gold)'};font-weight:700;letter-spacing:1px;text-transform:uppercase;white-space:nowrap">${tipo==='local'?'🚛 Local':'📦 Otros'}</span>
        <input type="text" value="${g.nombre}" style="flex:1;background:transparent;border:none;color:var(--accent);font-family:'Barlow Condensed',sans-serif;font-size:15px;font-weight:700;letter-spacing:1px;text-transform:uppercase;outline:none" onchange="updateBibGrupoNombre('${svc}','${g.id}',this.value)">
      </div>
      <button class="btn btn-danger btn-sm" style="padding:4px 8px;font-size:11px" onclick="deleteBibGrupo('${svc}','${g.id}')">🗑 Grupo</button>
    </div>
    <div style="padding:0 14px 14px;overflow-x:auto">
      <table class="bib-items-table" style="min-width:700px">
        <thead><tr>
          ${cols.map(col=>`<th style="${thStyle}">${col.nombre}</th>`).join('')}
          <th style="width:32px"></th>
        </tr></thead>
        <tbody>${itemsHtml}</tbody>
      </table>
      <button class="btn btn-secondary btn-sm" style="margin-top:8px" onclick="addBibItemTransporte('${svc}','${g.id}')">+ Fila</button>
    </div>
  </div>`;
}


// ── Drag-drop para reordenar grupos en Biblioteca de Servicios ──
let _bibDragGid = null, _bibDragSvc = null;

function bibGrupoDragStart(e, svc, gid){
  _bibDragGid = gid;
  _bibDragSvc = svc;
  e.dataTransfer.effectAllowed = 'move';
  e.dataTransfer.setData('text/plain', gid);
  e.currentTarget.style.opacity = '0.4';
}

function bibGrupoDragEnd(e){
  e.currentTarget.style.opacity = '1';
  document.querySelectorAll('.bib-grupo-row').forEach(el => {
    el.style.borderTop = '';
  });
  _bibDragGid = null;
  _bibDragSvc = null;
}

function bibGrupoDragOver(e){
  e.preventDefault();
  e.stopPropagation();
  e.dataTransfer.dropEffect = 'move';
  document.querySelectorAll('.bib-grupo-row').forEach(el => el.style.borderTop = '');
  e.currentTarget.style.borderTop = '3px solid var(--accent)';
}

function bibGrupoDrop(e, svc, targetGid){
  e.preventDefault();
  e.stopPropagation();
  document.querySelectorAll('.bib-grupo-row').forEach(el => el.style.borderTop = '');
  const fromGid = e.dataTransfer.getData('text/plain') || _bibDragGid;
  if(!fromGid || fromGid === targetGid) return;

  const grupos = db.biblioteca[svc]?.grupos;
  if(!grupos) return;

  const fromIdx = grupos.findIndex(g => g.id === fromGid);
  const toIdx   = grupos.findIndex(g => g.id === targetGid);
  if(fromIdx < 0 || toIdx < 0) return;

  const [moved] = grupos.splice(fromIdx, 1);
  grupos.splice(toIdx, 0, moved);
  _bibDragGid = null;
  _bibDragSvc = null;
  save();

  // Re-render only this service's grupos container
  const svcKey = svc.replace(/\s/g,'-');
  const container = document.getElementById('bib-grupos-' + svcKey);
  if(container){
    if(svc === 'Transporte'){
      container.innerHTML = db.biblioteca[svc].grupos.map(g => renderBibGrupoTransporte(svc, g)).join('');
    } else if(svc === 'Paqueteo'){
      renderBiblioteca();
    } else {
      container.innerHTML = db.biblioteca[svc].grupos.map(g => renderBibGrupo(svc, g)).join('');
    }
    // Keep accordion open
    const body = document.getElementById('bib-body-' + svcKey);
    if(body) body.style.display = 'block';
    const arrow = document.getElementById('bib-arrow-' + svcKey);
    if(arrow) arrow.textContent = '▲';
  }
}

function initTransporteGrupos(){
  const bib = db.biblioteca['Transporte'];
  if(!bib) return;
  // If empty, seed with the two predefined groups
  if(!bib.grupos || bib.grupos.length === 0){
    bib.grupos = [
      { id:'g-transp-local',  nombre:'TRANSPORTE LOCAL',               tipo:'local',  items:[] },
      { id:'g-transp-otros',  nombre:'OTROS SERVICIOS DE TRANSPORTE',  tipo:'otros',  items:[] }
    ];
    save();
  }
}

function addBibGrupoTransporte(svc, tipo){
  if(!db.biblioteca[svc]) return;
  const schema = TRANSP_SCHEMA[tipo];
  const g = { id:'g'+Date.now(), nombre: schema.label, tipo, items:[] };
  db.biblioteca[svc].grupos.push(g);
  save(); renderBiblioteca();
  const key = svc.replace(/\s/g,'-');
  document.getElementById('bib-body-'+key).style.display='block';
  document.getElementById('bib-arrow-'+key).textContent='▲';
}

function addBibItemTransporte(svc, gid){
  const g = db.biblioteca[svc]?.grupos.find(g=>g.id===gid);
  if(!g) return;
  const tipo = g.tipo || 'local';
  const schema = TRANSP_SCHEMA[tipo] || TRANSP_SCHEMA.local;
  const campos = {};
  schema.cols.forEach(c=>{ campos[c.id] = ''; });
  g.items.push({ id:'i'+Date.now(), campos });
  save(); renderBiblioteca();
}

function updateTranspItemTipoCampo(svc, gid, iid, campo, tipoCampo){
  const g = db.biblioteca[svc]?.grupos.find(g=>g.id===gid);
  if(!g) return;
  const item = g.items.find(i=>i.id===iid);
  if(!item) return;
  if(!item.tiposCampo) item.tiposCampo = {};
  item.tiposCampo[campo] = tipoCampo;
  save(); renderBiblioteca();
}

function updateTranspItemCampo(svc, gid, iid, campo, val){
  const g = db.biblioteca[svc]?.grupos.find(g=>g.id===gid);
  if(!g) return;
  const item = g.items.find(i=>i.id===iid);
  if(!item) return;
  if(!item.campos) item.campos = {};
  item.campos[campo] = val;
  save();
}


function addBibCol(svc){
  if(!db.biblioteca[svc].columnas) db.biblioteca[svc].columnas = [];
  const id = 'col'+Date.now();
  db.biblioteca[svc].columnas.push({id, nombre:'Nueva columna'});
  save(); renderBiblioteca();
  // Auto-expand
  const key = svc.replace(/\s/g,'-');
  const body = document.getElementById('bib-body-'+key);
  if(body) body.style.display='block';
  const arrow = document.getElementById('bib-arrow-'+key);
  if(arrow) arrow.textContent='▲';
}

function updateBibColNombre(svc, colId, val){
  const col = (db.biblioteca[svc]?.columnas||[]).find(c=>c.id===colId);
  if(col){ col.nombre=val; save(); }
}

function deleteBibCol(svc, colId){
  if(!db.biblioteca[svc].columnas) return;
  db.biblioteca[svc].columnas = db.biblioteca[svc].columnas.filter(c=>c.id!==colId);
  save(); renderBiblioteca();
}

function updateBibItemExtra(svc, gid, iid, colId, val){
  const g = db.biblioteca[svc]?.grupos.find(g=>g.id===gid);
  if(!g) return;
  const item = g.items.find(i=>i.id===iid);
  if(!item) return;
  if(!item.extraCols) item.extraCols = {};
  item.extraCols[colId] = val;
  save();
}

// ============================================================
// WIZARD NUEVA COTIZACIÓN
// ============================================================
function nuevaCotizacion(){
  // Clean any leftover imported groups from biblioteca
  SERVICES.forEach(svc=>{
    if(db.biblioteca[svc]) db.biblioteca[svc].grupos = (db.biblioteca[svc].grupos||[]).filter(g=>!g._imported);
  });
  initBiblioteca();
  const defVig = new Date(); defVig.setDate(defVig.getDate()+30);
  cotWizard = {
    id: null, step:1,
    empresa:'', nit:'', contacto:'', cargo:'', email:'', telefono:'',
    comercialId:'', fecha:today(), vigencia:defVig.toISOString().slice(0,10),
    estado:'borrador', asunto:'',
    lineas:[], paqueteadora:'', tarifaTipo:{}, tarifaEspecialId:{}, items:{}, obsPlantillas:{}, obsLibre:''
  };
  document.getElementById('cot-fecha').value   = today();
  document.getElementById('cot-vigencia').value = defVig.toISOString().slice(0,10);
  document.getElementById('nueva-cot-titulo').innerHTML = '📄 <span>Nueva Cotización</span>';
  // Hide contact selector
  const csg = document.getElementById('cot-contacto-sel-group');
  if(csg) csg.style.display = 'none';

  // Poblar selects
  const comSel = document.getElementById('cot-comercial');
  comSel.innerHTML = '<option value="">— Seleccionar —</option>' +
    db.comerciales.map(c=>`<option value="${c.id}">${c.nombre}</option>`).join('');

  const empSel = document.getElementById('cot-empresa-sel');
  empSel.innerHTML = '<option value="">— Empresa nueva / manual —</option>' +
    [...new Map(db.records.map(r=>[r.empresa,r])).values()]
      .map(r=>`<option value="${r.empresa}|${r.nit||''}">${r.empresa}</option>`).join('');

  // ── Restaurar todos los servicios en modo editable ──────────────
  if(!cotWizard._espEdit)   cotWizard._espEdit   = {};
  if(!cotWizard._espEditId) cotWizard._espEditId = {};
  if(!cotWizard._espItems)  cotWizard._espItems  = {};

  (cotWizard.lineas||[]).forEach(function(svc){
    var espKey = (svc==='Paqueteo' && cotWizard.paqueteadora) ? 'Paqueteo-'+cotWizard.paqueteadora : svc;
    var espId  = cotWizard.tarifaEspecialId ? cotWizard.tarifaEspecialId[svc] : '';
    var tipo   = cotWizard.tarifaTipo ? cotWizard.tarifaTipo[svc] : 'general';

    // Fuente 1: _espItems guardados en la cotización (estado real de lo cotizado)
    var savedEspItems = cotWizard._espItems && cotWizard._espItems[svc];
    // Fuente 2: tarifa especial en biblioteca
    var te = espId && espId!=='nueva' ? (db.tarifasEspeciales[espKey]||[]).find(function(t){return t.id===espId;}) : null;
    // Fuente 3: items generales guardados
    var savedItems = cotWizard.items && cotWizard.items[svc];

    if(tipo === 'especial'){
      // Prioridad: _espItems de la cotización > tarifa de biblioteca
      var source = savedEspItems || (te ? te.grupos.map(function(g){
        return {id:g.gid||g.id, nombre:g.nombre, tipo:g.tipo||'', sel:true,
                items:(g.items||[]).map(function(i){return Object.assign({},i,{sel:true});}),
                obsEcommerce:g.obsEcommerce||''};
      }) : []);

      if(source.length){
        // Restaurar _espEdit con los datos reales de la cotización
        cotWizard._espEdit[svc] = JSON.parse(JSON.stringify(source)).map(function(g){
          return {id:g.gid||g.id||g.nombre, nombre:g.nombre, tipo:g.tipo||'', sel:true,
                  items:(g.items||[]).map(function(i){return Object.assign({},i,{sel:true});}),
                  obsEcommerce:g.obsEcommerce||''};
        });
        cotWizard._espItems[svc] = JSON.parse(JSON.stringify(source));
        if(te) cotWizard._espEditId[svc] = te.id;
        cotWizard.tarifaEspecialId[svc] = 'nueva'; // modo edición
      }
    } else {
      // Tarifa general: restaurar items editables desde los items guardados
      if(savedItems && Object.keys(savedItems).length){
        // Los items ya están en cotWizard.items[svc] — el paso 3 los leerá directamente
        // Solo asegurarnos que sel=true para que sean visibles
        Object.values(savedItems).forEach(function(grp){
          if(grp && grp.items) grp.items.forEach(function(i){ if(i.sel===undefined) i.sel=true; });
        });
      }
    }
  });

  buildStepBar();
  cotStep(1);
  showPage('nueva-cot');
}

function onCotEmpresaChange(val){
  if(!val) return;
  const [emp,nit] = val.split('|');

  // Find the record to get full contactos array
  const rec = db.records.find(r=>r.empresa===emp);

  document.getElementById('cot-empresa').value = emp||'';
  document.getElementById('cot-nit').value     = nit||'';

  const selGroup = document.getElementById('cot-contacto-sel-group');
  const selEl    = document.getElementById('cot-contacto-sel');

  if(rec && rec.contactos && rec.contactos.length > 1){
    // Multiple contacts — show selector
    selEl.innerHTML = '<option value="">— Seleccionar contacto —</option>' +
      rec.contactos.map((c,i)=>`<option value="${i}">${c.nombre}${c.cargo?' — '+c.cargo:''}</option>`).join('');
    selGroup.style.display = 'block';
    // Pre-fill with first contact
    fillCotContacto(rec.contactos[0]);
    selEl.value = '0';
    // Store contactos for later selection
    selEl.dataset.recordId = rec.id;
  } else {
    // Single contact or no record — hide selector
    selGroup.style.display = 'none';
    if(rec && rec.contactos && rec.contactos.length === 1){
      // Has exactly one contact — fill from it
      fillCotContacto(rec.contactos[0]);
    } else if(!rec || !rec.contactos || rec.contactos.length === 0){
      // No record found or no contacts — clear all contact fields
      fillCotContacto({ nombre:'', cargo:'', email:'', telefono:'' });
    }
  }
  // Always update cotWizard empresa/nit immediately
  cotWizard.empresa = document.getElementById('cot-empresa').value;
  cotWizard.nit     = document.getElementById('cot-nit').value;
}

function onCotContactoChange(idxStr){
  const selEl = document.getElementById('cot-contacto-sel');
  const recId = selEl.dataset.recordId;
  const rec   = db.records.find(r=>r.id===recId);
  if(!rec || !rec.contactos) return;
  const idx = parseInt(idxStr);
  if(!isNaN(idx) && rec.contactos[idx]) fillCotContacto(rec.contactos[idx]);
}

function fillCotContacto(c){
  document.getElementById('cot-contacto').value = c.nombre   || '';
  document.getElementById('cot-cargo').value    = c.cargo    || '';
  document.getElementById('cot-email').value    = c.email    || '';
  const telEl = document.getElementById('cot-telefono');
  if(telEl) telEl.value = c.telefono || '';
}

function onCotEmpresaTexto(val){
  // When user types empresa manually, try to match a record
  const trimmed = val.trim().toLowerCase();
  const rec = db.records.find(r => r.empresa.toLowerCase() === trimmed);
  const selGroup = document.getElementById('cot-contacto-sel-group');
  if(selGroup) selGroup.style.display = 'none';

  if(rec && rec.contactos && rec.contactos.length > 0){
    // Match found — fill first contact
    fillCotContacto(rec.contactos[0]);
    document.getElementById('cot-nit').value = rec.nit||'';
    // If multiple contacts show selector
    const selEl = document.getElementById('cot-contacto-sel');
    if(rec.contactos.length > 1 && selEl && selGroup){
      selEl.innerHTML = '<option value="">— Seleccionar contacto —</option>' +
        rec.contactos.map((ct,i)=>`<option value="${i}">${ct.nombre}${ct.cargo?' — '+ct.cargo:''}</option>`).join('');
      selGroup.style.display = 'block';
      selEl.dataset.recordId = rec.id;
    }
  } else if(trimmed === ''){
    // Empty — clear everything
    fillCotContacto({nombre:'',cargo:'',email:'',telefono:''});
    document.getElementById('cot-nit').value = '';
  }
  // If no match found, leave contact as-is (user may be typing a new empresa)
}

function buildStepBar(){
  const labels = ['Datos','Servicios','Ítems','Observaciones','Vista Previa'];
  const bar = document.getElementById('step-bar');
  const lbl = document.getElementById('step-labels');
  bar.innerHTML = labels.map((l,i)=>{
    const n = i+1;
    const isLast = i===labels.length-1;
    return `<div class="step-item">
      <div class="step-dot" id="sdot-${n}">${n}</div>
      ${!isLast?'<div class="step-line" id="sline-'+n+'"></div>':''}
    </div>`;
  }).join('');
  lbl.innerHTML = `<div style="display:grid;grid-template-columns:repeat(${labels.length},1fr);gap:0;width:100%">` +
    labels.map(l=>`<div style="font-size:11px;color:var(--text2);text-align:center;margin-top:6px;letter-spacing:0.5px">${l}</div>`).join('') +
    '</div>';
}

function cotStep(n){
  cotWizard.step = n;
  // Collect current step data before moving
  collectStepData(n);

  document.querySelectorAll('.cot-step').forEach(el=>el.classList.remove('active'));
  document.getElementById('cot-step-'+n).classList.add('active');

  // Update step bar
  for(let i=1;i<=5;i++){
    const dot = document.getElementById('sdot-'+i);
    const line = document.getElementById('sline-'+i);
    if(!dot) continue;
    dot.className = 'step-dot' + (i<n?' done':(i===n?' active':''));
    if(line) line.className = 'step-line'+(i<n?' done':'');
  }

  // Render step content
  if(n===2) renderCotLineasStep();
  if(n===3) renderCotItemsStep();
  if(n===4) renderCotObsStep();
  if(n===5) renderCotPreview();
}

function collectStepData(goingTo){
  cotWizard.empresa     = document.getElementById('cot-empresa')?.value    || cotWizard.empresa    || '';
  cotWizard.nit         = document.getElementById('cot-nit')?.value        || cotWizard.nit        || '';
  cotWizard.contacto    = document.getElementById('cot-contacto')?.value   || cotWizard.contacto   || '';
  cotWizard.cargo       = document.getElementById('cot-cargo')?.value      || cotWizard.cargo      || '';
  cotWizard.email       = document.getElementById('cot-email')?.value      || cotWizard.email      || '';
  cotWizard.telefono    = document.getElementById('cot-telefono')?.value   || cotWizard.telefono   || '';
  cotWizard.comercialId = document.getElementById('cot-comercial')?.value  || cotWizard.comercialId|| '';
  cotWizard.fecha       = document.getElementById('cot-fecha')?.value      || cotWizard.fecha      || today();
  cotWizard.vigencia    = document.getElementById('cot-vigencia')?.value   || cotWizard.vigencia   || '';
  cotWizard.estado      = document.getElementById('cot-estado')?.value     || cotWizard.estado     || 'borrador';
  cotWizard.asunto      = document.getElementById('cot-asunto')?.value     || cotWizard.asunto     || '';
  const obsLibreEl = document.getElementById('cot-obs-libre');
  if(obsLibreEl) cotWizard.obsLibre = obsLibreEl.value;
}

// Paso 2 — seleccionar líneas
const TARIFA_SERVICES = ['Zona Franca','Depósito Aduanero','CEDI','Transporte','Paqueteo','Aduana'];

function _paqIcon(p){ return p==='COORDINADORA'?'📦':p==='TCC'?'🚚':'🟢'; }

function _espKey(svc){
  if(svc === 'Paqueteo' && cotWizard.paqueteadora){
    return 'Paqueteo-' + cotWizard.paqueteadora;
  }
  return svc;
}

function renderCotLineasStep(){
  const grid = document.getElementById('cot-lineas-grid');
  if(!grid) return;

  // ── 1. Service cards ─────────────────────────────────────────
  let html = SERVICES.map(s=>`
    <div class="svc-selector-card${cotWizard.lineas.includes(s)?' selected':''}"
         onclick="toggleCotLinea('${s}',this)">
      <div class="svc-icon">${SVC_ICONS[s]||'📋'}</div>
      <div class="svc-name">${s}</div>
      <div style="font-size:11px;color:var(--text2);margin-top:4px">
        ${(db.biblioteca[s]?.grupos||[]).length} grupos
      </div>
    </div>`).join('');

  // ── 2. Paquetera selector ──────────────────────────────────
  if(cotWizard.lineas.includes('Paqueteo')){
    const paqCards = PAQUETEO_PAQUETEADORAS.map(p=>`
      <div class="svc-selector-card${cotWizard.paqueteadora===p?' selected':''}"
           style="min-width:140px;cursor:pointer"
           onclick="selectPaqueteadora('${p}')">
        <div class="svc-icon">${_paqIcon(p)}</div>
        <div class="svc-name" style="font-size:13px">${p}</div>
      </div>`).join('');
    html += `
    <div style="margin-top:20px;padding:16px;background:var(--surface3);border-radius:10px;border:1px solid var(--border)">
      <div style="font-family:'Barlow Condensed',sans-serif;font-size:13px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;color:var(--accent);margin-bottom:12px">
        📦 Selecciona la Paquetera a cotizar
      </div>
      <div style="display:flex;gap:12px;flex-wrap:wrap">${paqCards}</div>
    </div>`;
  }

  // ── 3. Tarifa Especial per service (separate full-width container) ──
  const espContainer = document.getElementById('cot-tarifa-esp-container');
  const tarifaSvcs = cotWizard.lineas.filter(s=>TARIFA_SERVICES.includes(s));
  if(tarifaSvcs.length){
    let tHtml = `
    <div style="margin-top:8px;border-radius:12px;border:1px solid rgba(245,166,35,0.3);overflow:hidden;width:100%">
      <div style="padding:12px 16px;background:linear-gradient(135deg,rgba(245,166,35,0.12),rgba(245,166,35,0.04));border-bottom:1px solid rgba(245,166,35,0.2);display:flex;align-items:center;gap:10px">
        <span style="font-size:18px">⭐</span>
        <div style="font-family:'Barlow Condensed',sans-serif;font-size:13px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;color:var(--gold)">Tarifas Especiales</div>
      </div>
      <div style="padding:14px 16px;display:flex;flex-direction:column;gap:10px">`;

    tarifaSvcs.forEach(svc=>{
      const tipo       = cotWizard.tarifaTipo[svc] || 'general';
      const especiales = db.tarifasEspeciales[_espKey(svc)] || [];
      const selEspId   = cotWizard.tarifaEspecialId[svc] || '';
      const svcKey     = svc.replace(/\s/g,'-');
      const isActive   = tipo === 'especial';

      // Build saved tariffs dropdown list
      let savedList = '';
      if(isActive && especiales.length){
        savedList = '<div style="margin:10px 0 6px">'
          + '<div style="font-size:11px;color:var(--text2);font-weight:600;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:8px">Tarifas guardadas</div>'
          + [...especiales].reverse().map(te=>{
              const isSel = selEspId === te.id;
              const itemCount = (te.grupos||[]).reduce((a,g)=>a+(g.items||[]).length,0);
              return '<div style="display:flex;align-items:center;justify-content:space-between;padding:8px 12px;margin-bottom:4px;border-radius:8px;border:1px solid '+(isSel?'var(--gold)':'var(--border)')+';background:'+(isSel?'rgba(245,166,35,0.1)':'var(--surface3)')+';gap:8px">'
                + '<div style="display:flex;align-items:center;gap:8px;flex:1;cursor:pointer;min-width:0" onclick="selectTarifaEspecial(\''+svc+'\',\''+te.id+'\')">'
                + '<span style="font-size:14px;flex-shrink:0">'+(isSel?'⭐':'☆')+'</span>'
                + '<span style="font-size:13px;color:'+(isSel?'var(--gold)':'var(--text)')+';font-weight:'+(isSel?700:500)+';white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+te.nombre+'</span>'
                + '<span style="font-size:10px;color:var(--text2);flex-shrink:0;margin-left:auto;padding-left:8px">'+itemCount+' ítems · '+(te.creadoEn?new Date(te.creadoEn).toLocaleDateString('es-CO',{day:'2-digit',month:'2-digit',year:'numeric'}):''  )+'</span>'
                + '</div>'
                + '<div style="display:flex;gap:4px;flex-shrink:0">'
                + '<button style="background:var(--surface2);border:1px solid var(--border);border-radius:5px;color:var(--text2);font-size:11px;padding:3px 8px;cursor:pointer" onclick="editarTarifaEspecial(\''+svc+'\',\''+te.id+'\')">✏️ Editar</button>'
                + '<button style="background:none;border:none;cursor:pointer;color:var(--red);font-size:16px;line-height:1;padding:0 4px" onclick="deleteTarifaEspecial(\''+svc+'\',\''+te.id+'\')" title="Eliminar">✕</button>'
                + '</div>'
                + '</div>';
            }).join('')
          + '</div>';
      }

      const newBtnTxt = selEspId==='nueva' ? '✏️ Editando nueva...' : '+ Nueva tarifa especial';
      const editBtnTxt = selEspId && selEspId!=='nueva' && (cotWizard._espEditId?.[svc]===selEspId) ? '✏️ Editando...' : '';

      tHtml += `
      <div style="padding:12px;background:${isActive?'rgba(245,166,35,0.06)':'var(--surface2)'};border-radius:8px;border:1px solid ${isActive?'rgba(245,166,35,0.3)':'var(--border)'}">
        <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px">
          <div style="display:flex;align-items:center;gap:8px">
            <span style="font-size:16px">${SVC_ICONS[svc]||'📋'}</span>
            <span style="font-size:13px;font-weight:700;color:${isActive?'var(--gold)':'var(--text)'}">${svc}</span>
          </div>
          <label style="display:flex;align-items:center;gap:8px;cursor:pointer;user-select:none">
            <div style="position:relative;width:38px;height:20px" onclick="toggleTarifaEspecial('${svc}')">
              <div style="position:absolute;inset:0;border-radius:10px;background:${isActive?'var(--gold)':'var(--border)'};transition:background 0.2s"></div>
              <div style="position:absolute;top:2px;left:${isActive?'20':'2'}px;width:16px;height:16px;border-radius:50%;background:#fff;transition:left 0.2s"></div>
            </div>
            <span style="font-size:12px;color:${isActive?'var(--gold)':'var(--text2)'};">${isActive?'Activa':'Inactiva'}</span>
          </label>
        </div>
        ${isActive ? `
        <div style="margin-top:10px">
          ${savedList}
          <button class="btn btn-secondary btn-sm" style="${selEspId==='nueva'?'border-color:var(--gold);color:var(--gold)':''}" onclick="abrirNuevaTarifaEspecial('${svc}')">${newBtnTxt}</button>
        </div>` : ''}
      </div>`;
    });

    tHtml += '</div></div>';
    if(espContainer) espContainer.innerHTML = tHtml;
  } else {
    if(espContainer) espContainer.innerHTML = '';
  }

  grid.innerHTML = html;
}


function toggleTarifaEspecial(svc){
  const current = cotWizard.tarifaTipo[svc] || 'general';
  if(current === 'especial'){
    // Deactivate — go back to general
    cotWizard.tarifaTipo[svc] = 'general';
    cotWizard.tarifaEspecialId[svc] = '';
    cotWizard.items[svc] = {};
  } else {
    cotWizard.tarifaTipo[svc] = 'especial';
  }
  renderCotLineasStep();
}

function selectTarifaTipo(svc, tipo){
  cotWizard.tarifaTipo[svc] = tipo;
  if(tipo === 'general') cotWizard.tarifaEspecialId[svc] = '';
  cotWizard.items[svc] = {};
  renderCotLineasStep();
}

function editarTarifaEspecial(svc, id){
  const te = (db.tarifasEspeciales[_espKey(svc)]||[]).find(t=>t.id===id);
  if(!te) return;
  if(!cotWizard._espEdit) cotWizard._espEdit = {};
  if(!cotWizard._espEditId) cotWizard._espEditId = {};
  cotWizard._espEditId[svc] = id; // track which saved tarifa we're editing
  // Deep copy the saved tarifa's grupos into _espEdit
  cotWizard._espEdit[svc] = JSON.parse(JSON.stringify(te.grupos)).map(g => ({
    id: g.gid,
    nombre: g.nombre,
    tipo: g.tipo || '',
    items: (g.items||[]).map(i => ({...i, sel: true})),
    sel: true,
    obsEcommerce: g.obsEcommerce || ''
  }));
  cotWizard.tarifaEspecialId[svc] = 'nueva'; // puts step 3 in edit mode
  cotWizard.tarifaTipo[svc] = 'especial';
  renderCotLineasStep();
  cotStep(3);
}

function _cargarItemsDesdeEspecial(svc, te){
  // Store the tarifa's grupos in a way buildCotHTML can use
  // We'll put them under cotWizard._espItems[svc] keyed by gid
  if(!cotWizard._espItems) cotWizard._espItems = {};
  cotWizard._espItems[svc] = te.grupos.map(g => ({
    ...g,
    sel: true,
    items: g.items.map(i => ({...i, sel: true}))
  }));
}

function selectTarifaEspecial(svc, id){
  cotWizard.tarifaEspecialId[svc] = id;
  const te = (db.tarifasEspeciales[_espKey(svc)]||[]).find(t=>t.id===id);
  if(te) _cargarItemsDesdeEspecial(svc, te);
  renderCotLineasStep();
}

function deleteTarifaEspecial(svc, id){
  if(!confirm('¿Eliminar esta tarifa especial?')) return;
  const _dk = _espKey(svc);
  db.tarifasEspeciales[_dk] = (db.tarifasEspeciales[_dk]||[]).filter(t=>t.id!==id);
  if(cotWizard.tarifaEspecialId[svc]===id) cotWizard.tarifaEspecialId[svc]='';
  save(); renderCotLineasStep();
}

function abrirNuevaTarifaEspecial(svc){
  cotWizard.tarifaEspecialId[svc] = 'nueva';
  if(!cotWizard._espEdit) cotWizard._espEdit = {};
  if(!cotWizard._espEditId) cotWizard._espEditId = {};
  delete cotWizard._espEditId[svc]; // fresh — not editing an existing one

  // If _espEdit already has data for this service (e.g. from PDF import), keep it
  if(cotWizard._espEdit[svc] && cotWizard._espEdit[svc].length > 0){
    renderCotLineasStep();
    cotStep(3);
    return;
  }
  // Fallback: use _impGrupos (all groups from PDF import) for any service
  if(cotWizard._impGrupos?.length > 0){
    cotWizard._espEdit[svc] = JSON.parse(JSON.stringify(cotWizard._impGrupos));
    renderCotLineasStep();
    cotStep(3);
    return;
  }

  // Make sure library is initialized (initBiblioteca may not have run yet)
  initBiblioteca();
  const bib = db.biblioteca[svc] || {grupos:[]};

  // For Transporte: if no groups at all, ensure standard groups exist
  if(svc === 'Transporte' && bib.grupos.length === 0){
    initTransporteGrupos();
  }

  // For Paqueteo: only include grupos of the selected paquetera
  const bibGrupos = (svc === 'Paqueteo' && cotWizard.paqueteadora)
    ? bib.grupos.filter(g => PAQUETEO_SCHEMA[g.tipo]?.paqueteadora === cotWizard.paqueteadora)
    : bib.grupos;

  cotWizard._espEdit[svc] = JSON.parse(JSON.stringify(bibGrupos)).map(g => {
    let items = (g.items||[]).map(i => ({...i, sel:true}));

    // For Transporte: seed one blank row if empty
    if(svc === 'Transporte' && items.length === 0){
      const schema = TRANSP_SCHEMA[g.tipo || 'local'] || TRANSP_SCHEMA.local;
      const campos = {};
      schema.cols.forEach(col => { campos[col.id] = ''; });
      items = [{ id:'et'+Date.now()+Math.random(), campos, tiposCampo:{}, sel:true }];
    }
    // For Paqueteo: seed one blank row if empty
    if(svc === 'Paqueteo' && items.length === 0){
      const schema = PAQUETEO_SCHEMA[g.tipo];
      if(schema){
        const campos = {};
        schema.cols.forEach(col => { campos[col.id] = ''; });
        items = [{ id:'ep'+Date.now()+Math.random(), campos, tiposCampo:{}, sel:true }];
      }
    }

    return { id: g.id, nombre: g.nombre, tipo: g.tipo || '', items, sel: true, obsEcommerce: g.obsEcommerce || '' };
  });

  cotWizard.items[svc] = {};
  renderCotLineasStep();
  cotStep(3);
}

function iniciarGuardarTarifa(svc){
  const svcKey = svc.replace(/\s/g,'-');
  const btn = document.getElementById('btn-guardar-te-'+svcKey);
  if(btn){ btn.disabled=true; btn.textContent='💾 Guardando...'; }
  guardarNuevaTarifaEspecial(svc);
}

function guardarNuevaTarifaEspecial(svc){
  const svcKey = svc.replace(/\s/g,'-');
  const inputEl = document.getElementById('te-nombre-'+svcKey);
  const nombre = inputEl ? inputEl.value.trim() : '';
  if(!nombre){
    alert('Por favor escribe un nombre para la tarifa especial.');
    const btnV = document.getElementById('btn-guardar-te-'+svcKey);
    if(btnV){ btnV.disabled=false; btnV.textContent='💾 Guardar tarifa'; }
    return;
  }

  // Build from _espEdit — the isolated copy
  const editGrupos = cotWizard._espEdit?.[svc] || [];
  const grupos = editGrupos
    .filter(g => g.sel)
    .map(g => ({
      gid: 'esp_'+g.id,
      nombre: g.nombre,
      tipo: g.tipo || '',
      items: (g.items||[]).filter(i=>i.sel).map(i=>({...i})),
      obsEcommerce: g.obsEcommerce || ''
    }))
    .filter(g => g.items.length > 0);

  if(!grupos.length){
    alert('Selecciona al menos un grupo con ítems para guardar.');
    const btnG = document.getElementById('btn-guardar-te-'+svcKey);
    if(btnG){ btnG.disabled=false; btnG.textContent='💾 Guardar tarifa'; }
    return;
  }
  const espKey = _espKey(svc);
  if(!db.tarifasEspeciales[espKey]) db.tarifasEspeciales[espKey] = [];
  const editingId = cotWizard._espEditId?.[svc];
  let te;
  if(editingId){
    // Overwrite existing tarifa
    const existIdx = db.tarifasEspeciales[espKey].findIndex(t=>t.id===editingId);
    te = { id: editingId, nombre, svc, grupos, creadoEn: new Date().toISOString() };
    if(existIdx>=0) db.tarifasEspeciales[espKey][existIdx] = te;
    else db.tarifasEspeciales[espKey].push(te);
    if(cotWizard._espEditId) delete cotWizard._espEditId[svc];
  } else {
    te = { id:'te'+Date.now(), nombre, svc, grupos, creadoEn: new Date().toISOString() };
    db.tarifasEspeciales[espKey].push(te);
  }
  // ── Update button FIRST, while banner is still in the DOM ──
  const saveBtn = document.getElementById('btn-guardar-te-'+svcKey);
  if(saveBtn){
    saveBtn.disabled = true;
    saveBtn.textContent = '✅ Guardada';
    saveBtn.style.background = '#00c853';
    saveBtn.style.color = '#fff';
    saveBtn.style.opacity = '1';
  }

  // Now update state (tarifaEspecialId change removes the banner from DOM)
  cotWizard.tarifaEspecialId[svc] = te.id;
  _cargarItemsDesdeEspecial(svc, te);
  if(cotWizard._espEdit) delete cotWizard._espEdit[svc];
  save();
  showToast('\u2b50 Tarifa "'+nombre+'" guardada');
}

function selectPaqueteadora(p){
  cotWizard.paqueteadora = p;
  cotWizard.items['Paqueteo'] = {}; // reset items when paquetera changes
  renderCotLineasStep();
}

function toggleCotLinea(svc, el){
  const idx = cotWizard.lineas.indexOf(svc);
  if(idx===-1){
    cotWizard.lineas.push(svc);
    if(svc==='Paqueteo') cotWizard.paqueteadora='';
    // If PDF import loaded data for this service, auto-activate especial
    if(!cotWizard.tarifaTipo[svc]){
      const hasEspEdit = cotWizard._espEdit?.[svc]?.length > 0;
      const hasImpGrupos = cotWizard._impGrupos?.length > 0;
      if(hasEspEdit || hasImpGrupos){
        cotWizard.tarifaTipo[svc] = 'especial';
        cotWizard.tarifaEspecialId[svc] = 'nueva';
        // If no specific data for this service, use _impGrupos
        if(!hasEspEdit && hasImpGrupos){
          if(!cotWizard._espEdit) cotWizard._espEdit = {};
          cotWizard._espEdit[svc] = JSON.parse(JSON.stringify(cotWizard._impGrupos));
        }
      }
    }
  } else {
    cotWizard.lineas.splice(idx,1);
    if(svc==='Paqueteo'){ cotWizard.paqueteadora=''; }
    // Clean up tarifa state when deselecting
    delete cotWizard.tarifaTipo[svc];
    delete cotWizard.tarifaEspecialId[svc];
    delete cotWizard.items[svc];
  }
  // Always re-render so tarifa section updates immediately
  renderCotLineasStep();
}

// Paso 3 — seleccionar ítems
function renderCotItemsStep(){
  const c = document.getElementById('cot-items-container');
  if(cotWizard.lineas.length===0){
    c.innerHTML='<div style="color:var(--text2);text-align:center;padding:40px">No seleccionaste ningún servicio. Vuelve al paso anterior.</div>';
    return;
  }
  if(cotWizard.lineas.includes('Paqueteo') && !cotWizard.paqueteadora){
    c.innerHTML='<div style="text-align:center;padding:40px">'
      +'<div style="font-size:32px;margin-bottom:12px">📦</div>'
      +'<div style="color:var(--text);font-size:15px;font-weight:600;margin-bottom:8px">Selecciona la paquetera</div>'
      +'<div style="color:var(--text2);font-size:13px;margin-bottom:20px">Vuelve al paso anterior y elige COORDINADORA, TCC o SERVIENTREGA.</div>'
      +'<button class="btn btn-secondary" onclick="cotStep(2)">← Volver a Líneas de Negocio</button>'
      +'</div>';
    return;
  }

  // Build save-special-tariff banners for services in 'nueva' mode
  const nuevasBanners = cotWizard.lineas
    .filter(s => cotWizard.tarifaTipo[s]==='especial' && cotWizard.tarifaEspecialId[s]==='nueva')
    .map(s => {
      const svcKey = s.replace(/\s/g,'-');
      return '<div style="margin-bottom:16px;padding:14px 16px;background:rgba(245,166,35,0.1);border:1px solid var(--gold);border-radius:10px;display:flex;align-items:center;gap:12px;flex-wrap:wrap">'
        +'<span style="font-size:18px">⭐</span>'
        +'<div style="flex:1;min-width:200px">'
        +'<div style="font-size:12px;font-weight:700;color:var(--gold);text-transform:uppercase;letter-spacing:1px;margin-bottom:4px">Guardar como Tarifa Especial — '+s+'</div>'
        +(()=>{
            const existingName = cotWizard._espEditId?.[s]
              ? ((db.tarifasEspeciales[s]||[]).find(t=>t.id===cotWizard._espEditId[s])?.nombre || '')
              : '';
            return '<input id="te-nombre-'+svcKey+'" type="text" value="'+existingName+'" placeholder="Nombre de la tarifa especial (ej: Tarifa Cliente VIP)" ';
          })()
        +'style="width:100%;background:var(--surface2);border:1px solid var(--border);border-radius:6px;color:var(--text);padding:6px 10px;font-size:13px;outline:none;box-sizing:border-box">'
        +'</div>'
        +'<button id="btn-guardar-te-'+svcKey+'" class="btn btn-sm" style="background:var(--gold);color:#000;font-weight:700" onclick="iniciarGuardarTarifa(\'' + s + '\')">💾 Guardar tarifa</button>'
        +'</div>';
    }).join('');
  c.innerHTML = nuevasBanners + cotWizard.lineas.map(svc=>{
    const bib = db.biblioteca[svc]||{grupos:[]};
    const color = SVC_COLORS[svc]||'var(--accent)';
    const extraCols = bib.columnas||[];
    const ch = bib.colHeaders||{};
    const wh1 = ch.col1||'Servicio';
    const wh2 = ch.col2||'Tarifa';
    const wh3 = ch.col3||'Observación';
    if(!cotWizard.items[svc]) cotWizard.items[svc] = {};

    // In edit mode, use the isolated _espEdit copy; otherwise use library
    const isEditSvc = cotWizard.tarifaEspecialId[svc] === 'nueva';
    const hasEspecial = cotWizard.tarifaTipo?.[svc] === 'especial'
                        && cotWizard.tarifaEspecialId[svc]
                        && cotWizard.tarifaEspecialId[svc] !== 'nueva';
    const renderGrupos = isEditSvc
      ? (cotWizard._espEdit?.[svc] || [])
      : hasEspecial
        ? (cotWizard._espItems?.[svc] || [])
        : bib.grupos;

    const isEditMode = isEditSvc; // Available to ALL grupo blocks

    const gruposHtml = renderGrupos.map(g=>{
      // TRANSPORTE — estructura especial de campos
      if(svc === 'Transporte'){
        const tipo = g.tipo || 'local';
        const schema = TRANSP_SCHEMA[tipo] || TRANSP_SCHEMA.local;
        const cols = schema.cols;
        let grpState;
        if(isEditSvc || hasEspecial){
          grpState = g;
        } else {
          if(!cotWizard.items[svc][g.id]) cotWizard.items[svc][g.id] = { sel:true, items: (g.items||[]).map(i=>({...i, sel:true})) };
          grpState = cotWizard.items[svc][g.id];
        }
        const thS = `padding:6px 8px;font-size:10px;color:var(--accent);text-align:left;text-transform:uppercase;letter-spacing:0.5px;min-width:80px;white-space:normal`;
        const transpRows = grpState.items.map((item,ii)=>{
          if(!item.campos) item.campos = {};
          if(!item.tiposCampo) item.tiposCampo = {};
          const inpNum = `width:80px;background:var(--surface2);border:1px solid var(--border);border-radius:4px;color:var(--gold);padding:4px 6px;font-size:12px;font-weight:600`;
          const inpTxt = `width:100%;min-width:80px;background:var(--surface2);border:1px solid var(--border);border-radius:4px;color:var(--text2);padding:4px 6px;font-size:12px`;
          const selS  = `background:var(--surface3);border:1px solid var(--border);border-radius:4px;color:var(--text2);padding:2px 3px;font-size:10px`;
          const cells = cols.map(col=>{
            const val = item.campos[col.id]||'';
            const tipoCampo = item.tiposCampo[col.id]||'moneda';
            const onC = isEditMode
              ? `updateCotEspTranspCampo('${svc}','${g.id}',${ii},'${col.id}',this.value)`
              : `updateTranspCotItemCampo('${svc}','${g.id}',${ii},'${col.id}',this.value)`;
            const onT = isEditMode
              ? `updateCotEspTranspTipo('${svc}','${g.id}',${ii},'${col.id}',this.value)`
              : `updateTranspCotItemTipoCampo('${svc}','${g.id}',${ii},'${col.id}',this.value)`;
            if(col.tipo==='tarifa') return `<td style="padding:6px 8px"><div style="display:flex;align-items:center;gap:3px"><span style="color:var(--gold);font-size:11px">$</span><input type="text" value="${val}" style="${inpNum}" oninput="${onC}" placeholder="0"></div></td>`;
            if(col.tipo==='tarifa-mixta') return `<td style="padding:6px 8px"><div style="display:flex;align-items:center;gap:3px"><select style="${selS}" onchange="${onT}"><option value="moneda"${tipoCampo==='moneda'?' selected':''}>$</option><option value="porcentaje"${tipoCampo==='porcentaje'?' selected':''}>%</option></select><input type="text" value="${val}" style="${inpNum}" oninput="${onC}" placeholder="0"></div></td>`;
            if(col.tipo==='tarifa-texto') return `<td style="padding:6px 8px"><div style="display:flex;align-items:center;gap:3px"><select style="${selS}" onchange="${onT}"><option value="moneda"${tipoCampo==='moneda'?' selected':''}>$</option><option value="texto"${tipoCampo==='texto'?' selected':''}>Txt</option></select><input type="text" value="${val}" style="${tipoCampo==='texto'?inpTxt:inpNum}" oninput="${onC}" placeholder="${tipoCampo==='texto'?'ej: 2 Horas':'0'}"></div></td>`;
            return `<td style="padding:6px 8px"><input type="text" value="${val}" style="${inpTxt}" oninput="${onC}" placeholder="${col.nombre}"></td>`;
          }).join('');
          const delBtn = isEditMode ? `<td style="padding:4px;width:28px;text-align:center"><button onclick="delCotEspItem('${svc}','${g.id}',${ii})" style="background:none;border:none;cursor:pointer;color:var(--red);font-size:16px;line-height:1" title="Eliminar fila">✕</button></td>` : '';
          const chk = isEditMode ? `toggleCotEspItem('${svc}','${g.id}',${ii},this.checked)` : `toggleCotItem('${svc}','${g.id}',${ii},this.checked)`;
          return `<tr style="border-bottom:1px solid var(--border)">
            <td style="padding:6px;width:32px"><input type="checkbox" ${item.sel?'checked':''} style="accent-color:var(--accent)" onchange="${chk}"></td>
            ${cells}${delBtn}
          </tr>`;
        }).join('');

        const grpChk = isEditMode ? `toggleCotEspGrupo('${svc}','${g.id}',this.checked)` : `toggleCotGrupo('${svc}','${g.id}',this.checked)`;
        const grpTitle = isEditMode
          ? `<input type="text" value="${g.nombre}" style="background:var(--surface2);border:1px solid var(--border);border-radius:6px;color:${color};font-family:'Barlow Condensed',sans-serif;font-size:14px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:4px 10px;outline:none;width:100%;max-width:500px;box-sizing:border-box" oninput="updateCotEspGrupoNombre('${svc}','${g.id}',this.value)">`
          : `<div class="grupo-title" style="color:${color}">${g.nombre}</div>`;
        const transpFooter = isEditMode ? `
          <div style="padding:10px 14px;border-top:1px solid var(--border);display:flex;gap:8px;align-items:center;flex-wrap:wrap">
            <button class="btn btn-secondary btn-sm" onclick="addCotEspTranspItem('${svc}','${g.id}','${tipo}')">+ Nueva fila</button>
            <button class="btn btn-danger btn-sm" style="padding:4px 8px;font-size:11px" onclick="delCotEspGrupo('${svc}','${g.id}')">🗑 Eliminar grupo</button>
          </div>` : '';

        return `<div class="grupo-card" data-gid="${g.id}" data-svc="${svc}"
          style="${isEditMode?'border:1px solid rgba(245,166,35,0.3);':''}"
          ${isEditMode?`draggable="true" ondragstart="sacGrupoDragStart(event,'${svc}','${g.id}')" ondragover="sacGrupoDragOver(event)" ondrop="sacGrupoDrop(event,'${svc}','${g.id}')" ondragend="sacGrupoDragEnd(event)"`:''}>
          <div class="grupo-header">
            <div style="display:flex;align-items:center;gap:10px;flex:1">
              ${isEditMode?`<span title="Arrastrar para reordenar" style="cursor:grab;color:var(--border);font-size:18px;flex-shrink:0;line-height:1;padding:0 2px">⠿</span>`:''}
              <input type="checkbox" ${grpState.sel?'checked':''} style="width:16px;height:16px;accent-color:var(--accent);flex-shrink:0" onchange="${grpChk}">
              ${grpTitle}
            </div>
            <div style="font-size:12px;color:var(--text2);flex-shrink:0">${grpState.items.length} filas</div>
          </div>
          <div class="grupo-body" style="padding:0;overflow-x:auto">
            <table style="width:100%;border-collapse:collapse;min-width:600px">
              <thead><tr style="background:var(--surface3)">
                <th style="padding:6px;width:32px"></th>
                ${cols.map(col=>`<th style="${thS}">${col.nombre}</th>`).join('')}
                ${isEditMode ? '<th style="padding:6px;width:28px"></th>' : ''}
              </tr></thead>
              <tbody>${transpRows}</tbody>
            </table>
            ${transpFooter}
          </div>
        </div>`;
      }


      // PAQUETEO — estructura especial de campos por schema
      if(svc === 'Paqueteo'){
        const schema = PAQUETEO_SCHEMA[g.tipo];
        if(!schema) return '';
        // Always filter by selected paquetera
        if(cotWizard.paqueteadora && schema.paqueteadora !== cotWizard.paqueteadora) return '';
        const cols = schema.cols;

        // grpState: use _espEdit in edit/especial mode
        let grpState;
        if(isEditSvc || hasEspecial){
          grpState = g;
        } else {
          if(!cotWizard.items[svc][g.id]) cotWizard.items[svc][g.id] = { sel:true, items: g.items.map(i=>({...i, sel:true})) };
          grpState = cotWizard.items[svc][g.id];
        }

        const thS = `padding:6px 8px;font-size:10px;color:var(--accent);text-align:left;text-transform:uppercase;letter-spacing:0.5px;white-space:nowrap`;
        const inpStyle = `background:var(--surface2);border:1px solid var(--border);border-radius:4px;padding:4px 6px;font-size:12px;outline:none`;

        // Headers with colspan support
        let theads;
        if(schema.colspanGroups && schema.colspanGroups.length){
          const firstCol2 = cols.find(c2 => !schema.colspanGroups.some(cg => cg.cols.includes(c2.id)));
          const groupRow2 = `<th rowspan="2" style="padding:6px;width:32px"></th>` +
            `<th rowspan="2" style="${thS};vertical-align:middle">${firstCol2 ? firstCol2.nombre : ''}</th>` +
            schema.colspanGroups.map(cg =>
              `<th colspan="${cg.cols.length}" style="${thS};text-align:center;background:rgba(0,194,255,0.08)">${cg.label}</th>`
            ).join('');
          const subRow2 = schema.colspanGroups.map(cg =>
            cg.cols.map(cid => {
              const col2 = cols.find(c2 => c2.id === cid);
              return `<th style="${thS}">${col2 ? col2.nombre : cid}</th>`;
            }).join('')
          ).join('');
          const delTh = isEditMode ? `<th rowspan="2" style="padding:6px;width:28px"></th>` : '';
          theads = `<tr style="background:var(--surface3)">${groupRow2}${delTh}</tr><tr style="background:var(--surface3)">${subRow2}</tr>`;
        } else {
          const delTh = isEditMode ? `<th style="padding:6px;width:28px"></th>` : '';
          theads = `<tr style="background:var(--surface3)"><th style="padding:6px;width:32px"></th>${cols.map(col => `<th style="${thS.replace('white-space:nowrap','white-space:normal')}">${col.nombre}</th>`).join('')}${delTh}</tr>`;
        }

        const paqRows = grpState.items.map((item, ii)=>{
          if(!item.campos) item.campos = {};
          if(!item.tiposCampo) item.tiposCampo = {};
          const onC = isEditMode
            ? `updateCotEspPaqCampo('${svc}','${g.id}',${ii},'COL_ID',this.value)`
            : `updatePaqCotItemCampo('${svc}','${g.id}',${ii},'COL_ID',this.value)`;
          const onT = isEditMode
            ? `updateCotEspPaqTipo('${svc}','${g.id}',${ii},'COL_ID',this.value)`
            : `updatePaqCotItemTipoCampo('${svc}','${g.id}',${ii},'COL_ID',this.value)`;

          const cells = cols.map(col=>{
            const val = item.campos[col.id]||'';
            const colOnC = onC.replace(/COL_ID/g, col.id);
            const colOnT = onT.replace(/COL_ID/g, col.id);
            if(col.tipo === 'mixta'){
              const tc2 = item.tiposCampo[col.id] || 'moneda';
              const mixS = tc2==='moneda'
                ? `color:var(--gold);font-weight:600;width:70px;text-align:right;${inpStyle}`
                : tc2==='porcentaje'
                  ? `color:var(--text2);width:50px;text-align:center;${inpStyle}`
                  : `color:var(--text);min-width:60px;width:100%;${inpStyle}`;
              const mixSel = `background:var(--surface3);border:1px solid var(--border);border-radius:4px;color:var(--text2);padding:2px 3px;font-size:10px`;
              return `<td style="padding:5px 6px;white-space:nowrap">
                <div style="display:flex;align-items:center;gap:2px">
                  <select style="${mixSel}" onchange="${colOnT}">
                    <option value="moneda"${tc2==='moneda'?' selected':''}>$</option>
                    <option value="porcentaje"${tc2==='porcentaje'?' selected':''}>%</option>
                    <option value="texto"${tc2==='texto'?' selected':''}>T</option>
                  </select>
                  <input type="text" value="${val}" style="${mixS}" oninput="${colOnC}" placeholder="${tc2==='texto'?'—':'0'}">
                </div></td>`;
            }
            const colS = col.tipo==='moneda'
              ? `color:var(--gold);font-weight:600;width:90px;${inpStyle}`
              : col.tipo==='numero'
                ? `color:var(--accent);width:70px;text-align:right;${inpStyle}`
                : col.tipo==='porcentaje'
                  ? `color:var(--text2);width:60px;text-align:center;${inpStyle}`
                  : `color:var(--text);min-width:80px;width:100%;${inpStyle}`;
            const prefix = col.tipo==='moneda'
              ? `<span style="color:var(--gold);font-size:11px;margin-right:2px">$</span>`
              : col.tipo==='porcentaje'
                ? `<span style="color:var(--text2);font-size:11px;margin-right:2px">%</span>`
                : '';
            return `<td style="padding:5px 8px;white-space:nowrap">
              <div style="display:flex;align-items:center;gap:2px">
                ${prefix}
                <input type="text" value="${val}" style="${colS}" oninput="${colOnC}" placeholder="${col.tipo==='texto'?'—':'0'}">
              </div></td>`;
          }).join('');

          const delBtn = isEditMode
            ? `<td style="padding:4px;width:28px;text-align:center"><button onclick="delCotEspItem('${svc}','${g.id}',${ii})" style="background:none;border:none;cursor:pointer;color:var(--red);font-size:16px;line-height:1" title="Eliminar fila">✕</button></td>`
            : '';
          const chk = isEditMode
            ? `toggleCotEspItem('${svc}','${g.id}',${ii},this.checked)`
            : `toggleCotItem('${svc}','${g.id}',${ii},this.checked)`;

          return `<tr style="border-bottom:1px solid var(--border)">
            <td style="padding:6px;width:32px"><input type="checkbox" ${item.sel?'checked':''} style="accent-color:var(--accent)" onchange="${chk}"></td>
            ${cells}${delBtn}
          </tr>`;
        }).join('');

        // Ecommerce obs
        const obsBlock = schema.hasObs ? `
          <div style="padding:10px 12px;background:var(--surface3);border-top:1px solid var(--border)">
            <label style="font-size:10px;color:var(--gold);text-transform:uppercase;letter-spacing:1px;font-weight:700">📝 Observación Ecommerce</label>
            <textarea rows="2" style="width:100%;margin-top:6px;background:var(--surface2);border:1px solid var(--border);border-radius:5px;color:var(--text);font-size:12px;padding:6px 8px;resize:vertical;box-sizing:border-box"
              onchange="updatePaqCotGrupoObs('${g.id}',this.value)">${g.obsEcommerce||''}</textarea>
          </div>` : '';

        const paqFooter = isEditMode ? `
          <div style="padding:10px 14px;border-top:1px solid var(--border);display:flex;gap:8px;align-items:center;flex-wrap:wrap">
            <button class="btn btn-secondary btn-sm" onclick="addCotEspPaqItem('${svc}','${g.id}')">+ Nueva fila</button>
            <button class="btn btn-danger btn-sm" style="padding:4px 8px;font-size:11px" onclick="delCotEspGrupo('${svc}','${g.id}')">🗑 Eliminar grupo</button>
          </div>` : '';

        const paqChk = isEditMode
          ? `toggleCotEspGrupo('${svc}','${g.id}',this.checked)`
          : `toggleCotGrupo('${svc}','${g.id}',this.checked)`;
        const paqTitle = isEditMode
          ? `<input type="text" value="${g.nombre}" style="background:var(--surface2);border:1px solid var(--border);border-radius:6px;color:${color};font-family:'Barlow Condensed',sans-serif;font-size:14px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:4px 10px;outline:none;width:100%;max-width:500px;box-sizing:border-box" oninput="updateCotEspGrupoNombre('${svc}','${g.id}',this.value)">`
          : `<div class="grupo-title" style="color:${color}">${g.nombre}</div>`;

        return `<div class="grupo-card" data-gid="${g.id}" data-svc="${svc}"
          style="${isEditMode?'border:1px solid rgba(245,166,35,0.3);':''}"
          ${isEditMode?`draggable="true" ondragstart="sacGrupoDragStart(event,'${svc}','${g.id}')" ondragover="sacGrupoDragOver(event)" ondrop="sacGrupoDrop(event,'${svc}','${g.id}')" ondragend="sacGrupoDragEnd(event)"`:''}>
          <div class="grupo-header">
            <div style="display:flex;align-items:center;gap:10px;flex:1">
              ${isEditMode?`<span title="Arrastrar para reordenar" style="cursor:grab;color:var(--border);font-size:18px;flex-shrink:0;line-height:1;padding:0 2px">⠿</span>`:''}
              <input type="checkbox" ${grpState.sel?'checked':''} style="width:16px;height:16px;accent-color:var(--accent);flex-shrink:0" onchange="${paqChk}">
              ${paqTitle}
            </div>
            <div style="font-size:12px;color:var(--text2);flex-shrink:0">${grpState.items.length} filas</div>
          </div>
          <div class="grupo-body" style="padding:0;overflow-x:auto">
            <table style="width:100%;border-collapse:collapse">
              <thead>${theads}</thead>
              <tbody>${paqRows}</tbody>
            </table>
            ${obsBlock}
            ${paqFooter}
          </div>
        </div>`;
      }


      // RESTO DE SERVICIOS — estructura estándar
      let grpState;
      if(isEditSvc || hasEspecial){
        grpState = g; // g is _espEdit or _espItems grupo — already has sel + items
      } else {
        if(!cotWizard.items[svc][g.id]) cotWizard.items[svc][g.id] = { sel:true, items: (g.items||[]).map(i=>({...i, sel:true})) };
        grpState = cotWizard.items[svc][g.id];
      }

      // Delete-item column only in edit mode
      const delItemCol = isEditMode
        ? `<td style="padding:4px;width:28px;text-align:center">
             <button onclick="delCotEspItem('${svc}','${g.id}',${0 /* ii */})" style="display:none"></button>
           </td>` : '';

      const itemsHtmlEdit = grpState.items.map((item,ii)=>`
        <tr style="border-bottom:1px solid var(--border)">
          <td style="padding:8px;width:32px"><input type="checkbox" ${item.sel?'checked':''} style="accent-color:var(--accent)" onchange="${isEditMode?`toggleCotEspItem('${svc}','${g.id}',${ii},this.checked)`:`toggleCotItem('${svc}','${g.id}',${ii},this.checked)`}"></td>
          <td style="padding:8px;font-size:13px;color:${item.sel?'var(--text)':'var(--text2)'}">
            ${isEditMode
              ? `<input type="text" value="${item.nombre||''}" style="width:100%;background:var(--surface2);border:1px solid var(--border);border-radius:4px;color:var(--text);padding:4px 6px;font-size:12px" oninput="updateCotEspItemField('${svc}','${g.id}',${ii},'nombre',this.value)" placeholder="Nombre del ítem">`
              : (item.nombre||'')}
          </td>
          <td style="padding:8px;width:160px">
            <div style="display:flex;gap:4px;align-items:center">
              <select style="background:var(--surface2);border:1px solid var(--border);border-radius:4px;color:var(--text2);padding:3px 5px;font-size:11px" onchange="${isEditMode?`updateCotEspItemField('${svc}','${g.id}',${ii},'tipoTarifa',this.value)`:`updateCotItemField('${svc}','${g.id}',${ii},'tipoTarifa',this.value)`}">
                <option value="moneda"${item.tipoTarifa==='moneda'?' selected':''}>$</option>
                <option value="porcentaje"${item.tipoTarifa==='porcentaje'?' selected':''}>%</option>
              </select>
              <input type="text" value="${item.tarifa||''}" style="width:90px;background:var(--surface2);border:1px solid var(--border);border-radius:5px;color:var(--gold);padding:5px 7px;font-size:13px;font-weight:600" oninput="${isEditMode?`updateCotEspItemField('${svc}','${g.id}',${ii},'tarifa',this.value)`:`updateCotItemField('${svc}','${g.id}',${ii},'tarifa',this.value)`}">
            </div>
          </td>
          <td style="padding:8px"><input type="text" value="${item.obs||''}" style="width:100%;background:var(--surface2);border:1px solid var(--border);border-radius:5px;color:var(--text2);padding:5px 8px;font-size:12px" oninput="${isEditMode?`updateCotEspItemField('${svc}','${g.id}',${ii},'obs',this.value)`:`updateCotItemField('${svc}','${g.id}',${ii},'obs',this.value)`}" placeholder="Observación"></td>
          ${extraCols.map(col=>`
          <td style="padding:8px"><input type="text" value="${(item.extraCols&&item.extraCols[col.id])||''}" style="width:100%;min-width:90px;background:var(--surface2);border:1px solid var(--border);border-radius:5px;color:var(--text2);padding:5px 8px;font-size:12px" onchange="updateCotItemFieldExtra('${svc}','${g.id}',${ii},'${col.id}',this.value)" placeholder="${col.nombre}"></td>`).join('')}
          ${isEditMode ? `<td style="padding:4px;width:28px;text-align:center"><button onclick="delCotEspItem('${svc}','${g.id}',${ii})" style="background:none;border:none;cursor:pointer;color:var(--red);font-size:14px" title="Eliminar ítem">✕</button></td>` : ''}
        </tr>`).join('');

      const editFooter = isEditMode ? `
        <div style="padding:10px 14px;border-top:1px solid var(--border);display:flex;gap:8px;align-items:center;flex-wrap:wrap">
          <button class="btn btn-secondary btn-sm" onclick="addCotEspItem('${svc}','${g.id}')">+ Nuevo ítem</button>
          <button class="btn btn-danger btn-sm" style="padding:4px 8px;font-size:11px" onclick="delCotEspGrupo('${svc}','${g.id}')">🗑 Eliminar grupo</button>
        </div>` : '';

      // In edit mode, add ✕ delete to each item row
      const delCell = isEditMode
        ? `<th style="padding:8px;width:28px"></th>` : '';

      return `
        <div class="grupo-card" data-gid="${g.id}" data-svc="${svc}"
          style="${isEditMode?'border:1px solid rgba(245,166,35,0.3);border-radius:10px;overflow:hidden':''}"
          ${isEditMode?`draggable="true" ondragstart="sacGrupoDragStart(event,'${svc}','${g.id}')" ondragover="sacGrupoDragOver(event)" ondrop="sacGrupoDrop(event,'${svc}','${g.id}')" ondragend="sacGrupoDragEnd(event)"`:''}>
          <div class="grupo-header">
            <div style="display:flex;align-items:center;gap:10px;flex:1">
              ${isEditMode?`<span title="Arrastrar para reordenar" style="cursor:grab;color:var(--border);font-size:18px;flex-shrink:0;padding:0 2px">⠿</span>`:''}
              <input type="checkbox" ${grpState.sel?'checked':''} style="width:16px;height:16px;accent-color:var(--accent);flex-shrink:0" onchange="${isEditMode?`toggleCotEspGrupo('${svc}','${g.id}',this.checked)`:`toggleCotGrupo('${svc}','${g.id}',this.checked)`}">
              ${isEditMode
                ? `<input type="text" value="${g.nombre}" style="flex:1;min-width:160px;background:var(--surface2);border:1px solid var(--border);border-radius:6px;color:${color};font-family:'Barlow Condensed',sans-serif;font-size:14px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:4px 10px;outline:none" oninput="updateCotEspGrupoNombre('${svc}','${g.id}',this.value)">`
                : `<div class="grupo-title" style="color:${color}">${g.nombre}</div>`
              }
            </div>
            <div style="font-size:12px;color:var(--text2);flex-shrink:0">${grpState.items.length} ítems</div>
          </div>
          <div class="grupo-body" style="padding:0;overflow-x:auto">
            <table style="width:100%;border-collapse:collapse">
              <thead><tr style="background:var(--surface3)">
                <th style="padding:8px;width:32px"></th>
                <th style="padding:8px;font-size:11px;color:var(--text2);text-align:left">${wh1}</th>
                <th style="padding:8px;font-size:11px;color:var(--text2);text-align:left">${wh2}</th>
                <th style="padding:8px;font-size:11px;color:var(--text2);text-align:left">${wh3}</th>
                ${extraCols.map(col=>`<th style="padding:8px;font-size:11px;color:var(--accent);text-align:left">${col.nombre}</th>`).join('')}
                ${isEditMode ? '<th style="padding:8px;width:28px"></th>' : ''}
              </tr></thead>
              <tbody>${itemsHtmlEdit}</tbody>
            </table>
            ${editFooter}
          </div>
        </div>`;
    }).join('');

    let addGrupoBtn = '';
    if(isEditSvc){
      if(svc === 'Paqueteo'){
        // For Paqueteo: show schema selector to add a specific group type
        const paq = cotWizard.paqueteadora || 'COORDINADORA';
        const paqGrupoKeys = Object.keys(PAQUETEO_SCHEMA).filter(k => PAQUETEO_SCHEMA[k].paqueteadora === paq);
        const opts = paqGrupoKeys.map(k =>
          `<option value="${k}">${PAQUETEO_SCHEMA[k].label}</option>`
        ).join('');
        addGrupoBtn = `
          <div style="margin-top:10px;display:flex;align-items:center;gap:8px;flex-wrap:wrap">
            <select id="paq-add-tipo-${svc.replace(/\s/g,'-')}" style="background:var(--surface2);border:1px solid var(--border);border-radius:6px;color:var(--text);padding:6px 10px;font-size:12px;outline:none">
              ${opts}
            </select>
            <button class="btn btn-secondary btn-sm" onclick="addCotEspPaqGrupo('${svc}')">+ Agregar grupo</button>
          </div>`;
      } else if(svc === 'Transporte'){
        addGrupoBtn = `
          <div style="margin-top:10px;display:flex;align-items:center;gap:8px;flex-wrap:wrap">
            <select id="transp-add-tipo-${svc.replace(/\s/g,'-')}" style="background:var(--surface2);border:1px solid var(--border);border-radius:6px;color:var(--text);padding:6px 10px;font-size:12px;outline:none">
              <option value="local">🚛 Transporte Local</option>
              <option value="otros">🔧 Otros Servicios de Transporte</option>
            </select>
            <button class="btn btn-secondary btn-sm" onclick="addCotEspTranspGrupo('${svc}')">+ Agregar grupo</button>
          </div>`;
      } else {
        // RESTO services (Zona Franca, Depósito, CEDI, Aduana, etc.)
        // Show existing bib groups as quick options + free text input
        const bibGrpOpts = (db.biblioteca[svc]?.grupos||[])
          .map(g => `<option value="${g.nombre}">${g.nombre}</option>`)
          .join('');
        addGrupoBtn = `
          <div style="margin-top:10px;display:flex;align-items:center;gap:8px;flex-wrap:wrap">
            ${bibGrpOpts
              ? `<select id="resto-add-nombre-${svc.replace(/\s/g,'-')}"
                   style="background:var(--surface2);border:1px solid var(--border);border-radius:6px;color:var(--text);padding:6px 10px;font-size:12px;outline:none">
                   <option value="">— Selecciona un grupo —</option>
                   ${bibGrpOpts}
                 </select>`
              : `<input type="text" id="resto-add-nombre-${svc.replace(/\s/g,'-')}"
                   placeholder="Nombre del nuevo grupo"
                   style="background:var(--surface2);border:1px solid var(--border);border-radius:6px;color:var(--text);padding:6px 10px;font-size:12px;outline:none;min-width:200px">`
            }
            <button class="btn btn-secondary btn-sm" onclick="addCotEspRestoGrupo('${svc}')">+ Agregar grupo</button>
          </div>`;
      }
    }

    return `
      <div style="margin-bottom:28px">
        <div style="display:flex;align-items:center;gap:10px;margin-bottom:14px;padding-bottom:10px;border-bottom:2px solid ${color}">
          <span style="font-size:22px">${SVC_ICONS[svc]||'📋'}</span>
          <div style="font-family:'Barlow Condensed',sans-serif;font-size:20px;font-weight:800;letter-spacing:1.5px;color:${color}">${svc}</div>
          ${extraCols.length?`<span style="font-size:11px;color:var(--text2);margin-left:8px">${extraCols.length} columna(s) extra</span>`:''}
        </div>
        ${gruposHtml.length?gruposHtml:'<div style="color:var(--text2);font-size:13px;padding:16px">Esta línea no tiene grupos configurados. Ve a ⚙️ Servicios para agregarlos.</div>'}
        ${addGrupoBtn}
      </div>`;
  }).join('');
}



// ── Drag-drop para reordenar grupos en Biblioteca de Servicios ──
// ── Drag-drop para reordenar grupos en cotización especial ──
let _dragGid = null, _dragSvc = null;

function sacGrupoDragStart(e, svc, gid){
  _dragGid = gid; _dragSvc = svc;
  e.dataTransfer.effectAllowed = 'move';
  e.currentTarget.style.opacity = '0.5';
}
function sacGrupoDragEnd(e){
  e.currentTarget.style.opacity = '1';
  // Remove all drop indicators
  document.querySelectorAll('.grupo-card').forEach(el => el.style.borderTop = '');
}
function sacGrupoDragOver(e){
  e.preventDefault();
  e.dataTransfer.dropEffect = 'move';
  e.currentTarget.style.borderTop = '3px solid var(--gold)';
}
function sacGrupoDrop(e, svc, targetGid){
  e.preventDefault();
  e.currentTarget.style.borderTop = '';
  if(!_dragGid || _dragGid === targetGid || _dragSvc !== svc) return;
  const arr = cotWizard._espEdit?.[svc];
  if(!arr) return;
  const fromIdx = arr.findIndex(g => g.id === _dragGid);
  const toIdx   = arr.findIndex(g => g.id === targetGid);
  if(fromIdx < 0 || toIdx < 0) return;
  const [moved] = arr.splice(fromIdx, 1);
  arr.splice(toIdx, 0, moved);
  _dragGid = null; _dragSvc = null;
  renderCotItemsStep();
}

// ---- Tarifa Especial Edit Helpers (operate on cotWizard._espEdit only) ----
function _getEspGrupo(svc, gid){
  return (cotWizard._espEdit?.[svc]||[]).find(g=>g.id===gid);
}

function addCotEspItem(svc, gid){
  const g = _getEspGrupo(svc, gid);
  if(!g) return;
  g.items.push({id:'ei'+Date.now(), nombre:'', tarifa:'', tipoTarifa:'moneda', obs:'', sel:true});
  renderCotItemsStep();
}

function delCotEspItem(svc, gid, idx){
  const g = _getEspGrupo(svc, gid);
  if(g) g.items.splice(idx, 1);
  renderCotItemsStep();
}

function addCotEspPaqGrupo(svc){
  const sel = document.getElementById('paq-add-tipo-'+svc.replace(/\s/g,'-'));
  const tipo = sel ? sel.value : '';
  if(!tipo || !PAQUETEO_SCHEMA[tipo]) return;
  if(!cotWizard._espEdit) cotWizard._espEdit = {};
  if(!cotWizard._espEdit[svc]) cotWizard._espEdit[svc] = [];
  const schema = PAQUETEO_SCHEMA[tipo];
  const campos = {};
  schema.cols.forEach(col => { campos[col.id] = ''; });
  cotWizard._espEdit[svc].push({
    id: 'epg'+Date.now(),
    nombre: schema.label,
    tipo,
    items: [{ id:'ep'+Date.now(), campos, tiposCampo:{}, sel:true }],
    sel: true,
    obsEcommerce: ''
  });
  renderCotItemsStep();
}

function addCotEspTranspGrupo(svc){
  const sel = document.getElementById('transp-add-tipo-'+svc.replace(/\s/g,'-'));
  const tipo = sel ? sel.value : 'local';
  const schema = TRANSP_SCHEMA[tipo] || TRANSP_SCHEMA.local;
  if(!cotWizard._espEdit) cotWizard._espEdit = {};
  if(!cotWizard._espEdit[svc]) cotWizard._espEdit[svc] = [];

  // Find existing library group with this tipo to copy its items
  const bibGrupo = (db.biblioteca[svc]?.grupos||[]).find(g => g.tipo === tipo);
  let items = [];
  if(bibGrupo && bibGrupo.items && bibGrupo.items.length > 0){
    items = bibGrupo.items.map(it => ({
      id: 'eti'+Date.now()+Math.random().toString(36).slice(2),
      campos: it.campos ? JSON.parse(JSON.stringify(it.campos)) : {},
      tiposCampo: it.tiposCampo ? JSON.parse(JSON.stringify(it.tiposCampo)) : {},
      sel: true
    }));
  } else {
    // Empty item with schema columns
    const campos = {};
    schema.cols.forEach(col => { campos[col.id] = ''; });
    items = [{ id:'eti'+Date.now(), campos, tiposCampo:{}, sel:true }];
  }

  cotWizard._espEdit[svc].push({
    id: 'etg'+Date.now(),
    nombre: bibGrupo?.nombre || schema.label,
    tipo,
    items,
    sel: true
  });
  renderCotItemsStep();
}

function addCotEspRestoGrupo(svc){
  const svcKey = svc.replace(/\s/g,'-');
  const sel = document.getElementById('resto-add-nombre-'+svcKey);
  let nombre = '';
  if(sel) nombre = sel.value.trim();
  if(!nombre){ alert('Selecciona un grupo de la lista.'); return; }
  if(!cotWizard._espEdit) cotWizard._espEdit = {};
  if(!cotWizard._espEdit[svc]) cotWizard._espEdit[svc] = [];

  // Find existing group in library to copy its items
  const bibGrupo = (db.biblioteca[svc]?.grupos||[]).find(g => g.nombre === nombre);
  let items = [];
  if(bibGrupo && bibGrupo.items && bibGrupo.items.length > 0){
    // Deep copy all items from the library group
    items = bibGrupo.items.map(it => ({
      id: 'eri'+Date.now()+Math.random().toString(36).slice(2),
      nombre:    it.nombre    || '',
      tarifa:    it.tarifa    || '',
      tipoTarifa: it.tipoTarifa || 'moneda',
      obs:       it.obs       || '',
      extraCols: it.extraCols ? JSON.parse(JSON.stringify(it.extraCols)) : {},
      sel: true
    }));
  } else {
    // No library group found — start with one empty item
    items = [{ id:'eri'+Date.now(), nombre:'', tarifa:'', tipoTarifa:'moneda', obs:'', sel:true }];
  }

  cotWizard._espEdit[svc].push({
    id: 'erg'+Date.now(),
    nombre,
    tipo: bibGrupo?.tipo || '',
    items,
    sel: true
  });
  renderCotItemsStep();
}

function addCotEspGrupo(svc){
  if(!cotWizard._espEdit) cotWizard._espEdit = {};
  if(!cotWizard._espEdit[svc]) cotWizard._espEdit[svc] = [];
  cotWizard._espEdit[svc].push({id:'eg'+Date.now(), nombre:'Nuevo Grupo', tipo:'', items:[], sel:true});
  renderCotItemsStep();
}

function delCotEspGrupo(svc, gid){
  if(cotWizard._espEdit?.[svc]){
    cotWizard._espEdit[svc] = cotWizard._espEdit[svc].filter(g=>g.id!==gid);
  }
  renderCotItemsStep();
}

// Paqueteo especial item campo update
function updateCotEspPaqCampo(svc, gid, idx, campo, val){
  const g = _getEspGrupo(svc, gid);
  if(!g || !g.items[idx]) return;
  if(!g.items[idx].campos) g.items[idx].campos = {};
  g.items[idx].campos[campo] = val;
}

function updateCotEspPaqTipo(svc, gid, idx, campo, val){
  const g = _getEspGrupo(svc, gid);
  if(!g || !g.items[idx]) return;
  if(!g.items[idx].tiposCampo) g.items[idx].tiposCampo = {};
  g.items[idx].tiposCampo[campo] = val;
  renderCotItemsStep();
}

function addCotEspPaqItem(svc, gid){
  const g = _getEspGrupo(svc, gid);
  if(!g) return;
  const schema = PAQUETEO_SCHEMA[g.tipo];
  if(!schema) return;
  const campos = {};
  schema.cols.forEach(col => { campos[col.id] = ''; });
  g.items.push({ id:'ep'+Date.now(), campos, tiposCampo:{}, sel:true });
  renderCotItemsStep();
}

