function updateCotEspGrupoNombre(svc, gid, val){
  const arr = cotWizard._espEdit?.[svc];
  if(!arr) return;
  const idx = arr.findIndex(g=>g.id===gid);
  if(idx>=0) arr[idx].nombre = val;
}

function updateCotEspItemField(svc, gid, idx, field, val){
  const g = _getEspGrupo(svc, gid);
  if(g && g.items[idx]) g.items[idx][field] = val;
}

function toggleCotEspGrupo(svc, gid, sel){
  const g = _getEspGrupo(svc, gid);
  if(g) g.sel = sel;
}

function toggleCotEspItem(svc, gid, idx, sel){
  const g = _getEspGrupo(svc, gid);
  if(g && g.items[idx]) g.items[idx].sel = sel;
}

function toggleCotGrupo(svc, gid, checked){
  if(cotWizard.items[svc]?.[gid]){
    cotWizard.items[svc][gid].sel = checked;
    cotWizard.items[svc][gid].items.forEach(i=>i.sel=checked);
    renderCotItemsStep();
  }
}

function updatePaqCotItemTipoCampo(svc, gid, idx, campo, tipoCampo){
  if(cotWizard.items[svc]?.[gid]?.items?.[idx]){
    if(!cotWizard.items[svc][gid].items[idx].tiposCampo)
      cotWizard.items[svc][gid].items[idx].tiposCampo = {};
    cotWizard.items[svc][gid].items[idx].tiposCampo[campo] = tipoCampo;
  }
}

function updatePaqCotItemCampo(svc, gid, idx, campo, val){
  if(cotWizard.items[svc]?.[gid]?.items?.[idx]){
    if(!cotWizard.items[svc][gid].items[idx].campos)
      cotWizard.items[svc][gid].items[idx].campos = {};
    cotWizard.items[svc][gid].items[idx].campos[campo] = val;
  }
}

function updatePaqCotGrupoObs(gid, val){
  // Update obsEcommerce in the library group AND persist
  const bib = db.biblioteca['Paqueteo'];
  if(!bib) return;
  const g = bib.grupos.find(g=>g.id===gid);
  if(g){ g.obsEcommerce = val; save(); }
}

function toggleCotItem(svc, gid, idx, checked){
  if(cotWizard.items[svc]?.[gid]) cotWizard.items[svc][gid].items[idx].sel = checked;
}

function updateCotItemField(svc, gid, idx, field, val){
  if(cotWizard.items[svc]?.[gid]) cotWizard.items[svc][gid].items[idx][field] = val;
}

function updateTranspCotItemTipoCampo(svc, gid, idx, campo, tipoCampo){
  if(cotWizard.items[svc]?.[gid]){
    if(!cotWizard.items[svc][gid].items[idx].tiposCampo) cotWizard.items[svc][gid].items[idx].tiposCampo = {};
    cotWizard.items[svc][gid].items[idx].tiposCampo[campo] = tipoCampo;
    renderCotItemsStep();
  }
}

function updateTranspCotItemCampo(svc, gid, idx, campo, val){
  if(cotWizard.items[svc]?.[gid]){
    if(!cotWizard.items[svc][gid].items[idx].campos) cotWizard.items[svc][gid].items[idx].campos = {};
    cotWizard.items[svc][gid].items[idx].campos[campo] = val;
  }
}

function updateCotItemFieldExtra(svc, gid, idx, colId, val){
  if(cotWizard.items[svc]?.[gid]){
    if(!cotWizard.items[svc][gid].items[idx].extraCols) cotWizard.items[svc][gid].items[idx].extraCols = {};
    cotWizard.items[svc][gid].items[idx].extraCols[colId] = val;
  }
}

// Paso 4 — observaciones
function renderCotObsStep(){
  const cont = document.getElementById('cot-obs-container');
  if(!cotWizard._obsEdits) cotWizard._obsEdits = {}; // stores per-obs edits for this cotizacion

  cont.innerHTML = cotWizard.lineas.map(svc=>{
    migrateObsToRich(svc);
    const obs = db.biblioteca[svc]?.observaciones||[];
    if(!cotWizard.obsPlantillas[svc]) cotWizard.obsPlantillas[svc] = [];
    if(!cotWizard._obsEdits[svc]) cotWizard._obsEdits[svc] = {};
    if(obs.length===0) return '';
    const color = SVC_COLORS[svc]||'var(--accent)';
    const svcKey = svc.replace(/\s/g,'-');

    return `
      <div style="margin-bottom:28px">
        <div style="font-family:'Barlow Condensed',sans-serif;font-size:15px;font-weight:700;letter-spacing:1px;color:${color};margin-bottom:12px;display:flex;align-items:center;gap:8px">
          ${SVC_ICONS[svc]} ${svc}
          <span style="font-size:11px;font-weight:400;color:var(--text2)">— selecciona y edita las observaciones para esta cotización</span>
        </div>
        ${obs.map((o,i)=>{
          const sel = cotWizard.obsPlantillas[svc].includes(o.id);
          const editedHtml = cotWizard._obsEdits[svc][o.id] ?? o.html ?? '';
          const preview = editedHtml.replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim().slice(0,100);
          return `
          <div class="obs-sel-card ${sel?'selected':''}" id="obscard-${svcKey}-${o.id}" style="padding:0;overflow:hidden">
            <!-- Header row -->
            <div style="display:flex;align-items:center;gap:10px;padding:12px 14px;cursor:pointer" onclick="toggleCotObsRich('${svc}','${o.id}')">
              <span style="color:${color};font-size:18px;flex-shrink:0">${sel?'☑':'☐'}</span>
              <div style="flex:1;min-width:0">
                <div style="font-size:13px;font-weight:600;color:var(--text)">${o.nombre||'Sin nombre'}</div>
                <div class="obs-sel-preview" id="obs-preview-${svcKey}-${o.id}" style="margin-top:2px">${preview}${preview.length>=100?'…':''}</div>
              </div>
              ${sel?`<button onclick="event.stopPropagation();cotObsToggleEditor('${svc}','${o.id}')"
                style="background:var(--surface3);border:1px solid var(--border);border-radius:6px;color:var(--text2);font-size:11px;padding:4px 10px;cursor:pointer;flex-shrink:0">
                ✏️ Editar
              </button>`:''}
            </div>
            <!-- Inline editor (hidden by default) -->
            ${sel?`
            <div id="obs-editor-wrap-${svcKey}-${o.id}" style="display:none;border-top:1px solid var(--border);padding:12px 14px;background:var(--surface3)">
              <!-- Toolbar -->
              <div style="display:flex;gap:4px;flex-wrap:wrap;margin-bottom:8px;padding:6px 8px;background:var(--surface2);border-radius:6px;border:1px solid var(--border)">
                <button onclick="cotObsFmt('${svcKey}','${o.id}','bold')" title="Negrita"
                  style="background:none;border:1px solid var(--border);border-radius:4px;color:var(--text);padding:3px 8px;cursor:pointer;font-weight:700;font-size:13px">B</button>
                <button onclick="cotObsFmt('${svcKey}','${o.id}','italic')" title="Cursiva"
                  style="background:none;border:1px solid var(--border);border-radius:4px;color:var(--text);padding:3px 8px;cursor:pointer;font-style:italic;font-size:13px">I</button>
                <button onclick="cotObsFmt('${svcKey}','${o.id}','underline')" title="Subrayado"
                  style="background:none;border:1px solid var(--border);border-radius:4px;color:var(--text);padding:3px 8px;cursor:pointer;text-decoration:underline;font-size:13px">U</button>
                <span style="width:1px;background:var(--border);margin:0 2px"></span>
                <button onclick="cotObsFmt('${svcKey}','${o.id}','justifyLeft')" title="Izquierda"
                  style="background:none;border:1px solid var(--border);border-radius:4px;color:var(--text);padding:3px 7px;cursor:pointer;font-size:13px">⬅</button>
                <button onclick="cotObsFmt('${svcKey}','${o.id}','justifyCenter')" title="Centrar"
                  style="background:none;border:1px solid var(--border);border-radius:4px;color:var(--text);padding:3px 7px;cursor:pointer;font-size:13px">☰</button>
                <button onclick="cotObsFmt('${svcKey}','${o.id}','justifyRight')" title="Derecha"
                  style="background:none;border:1px solid var(--border);border-radius:4px;color:var(--text);padding:3px 7px;cursor:pointer;font-size:13px">➡</button>
                <span style="width:1px;background:var(--border);margin:0 2px"></span>
                <button onclick="cotObsFmt('${svcKey}','${o.id}','insertUnorderedList')" title="Lista"
                  style="background:none;border:1px solid var(--border);border-radius:4px;color:var(--text);padding:3px 7px;cursor:pointer;font-size:13px">• Lista</button>
                <button onclick="cotObsRestoreOriginal('${svc}','${o.id}')" title="Restaurar original"
                  style="background:none;border:1px solid var(--border);border-radius:4px;color:var(--text2);padding:3px 8px;cursor:pointer;font-size:11px">↺ Original</button>
              </div>
              <!-- Editable content -->
              <div id="obs-editor-${svcKey}-${o.id}"
                contenteditable="true"
                oninput="cotObsSaveEdit('${svc}','${o.id}',this)"
                style="min-height:80px;padding:10px 12px;background:var(--surface);border:1px solid var(--border);border-radius:6px;color:var(--text);font-size:13px;line-height:1.7;outline:none">${editedHtml}</div>
              <!-- Save as new -->
              <div style="display:flex;gap:8px;align-items:center;margin-top:10px;flex-wrap:wrap">
                <input type="text" id="obs-newname-${svcKey}-${o.id}" placeholder="Nombre para la nueva observación..."
                  style="flex:1;min-width:180px;background:var(--surface2);border:1px solid var(--border);border-radius:6px;color:var(--text);padding:6px 10px;font-size:12px;outline:none">
                <button onclick="cotObsGuardarNueva('${svc}','${o.id}')"
                  style="background:var(--green);border:none;border-radius:6px;color:#000;font-size:12px;font-weight:700;padding:6px 14px;cursor:pointer;white-space:nowrap">
                  💾 Guardar como nueva
                </button>
              </div>
            </div>`:''}
          </div>`;
        }).join('')}
      </div>`;
  }).join('') || '<p style="color:var(--text2);font-size:13px">No hay plantillas configuradas. Ve a ⚙️ Servicios para crearlas.</p>';

  document.getElementById('cot-obs-libre').value = cotWizard.obsLibre||'';
}

function toggleCotObsRich(svc, obsId){
  if(!cotWizard.obsPlantillas[svc]) cotWizard.obsPlantillas[svc]=[];
  const arr = cotWizard.obsPlantillas[svc];
  const idx = arr.indexOf(obsId);
  if(idx>=0) arr.splice(idx,1);
  else arr.push(obsId);
  // Re-render to show/hide edit button correctly
  renderCotObsStep();
  // Re-open editor if it was open before
  if(arr.includes(obsId)){
    // Keep editor closed on first selection — user opens manually
  }
}

function toggleCotObs(svc, idx, checked){
  if(!cotWizard.obsPlantillas[svc]) cotWizard.obsPlantillas[svc]=[];
  if(checked && !cotWizard.obsPlantillas[svc].includes(idx)) cotWizard.obsPlantillas[svc].push(idx);
  else cotWizard.obsPlantillas[svc] = cotWizard.obsPlantillas[svc].filter(i=>i!==idx);
}

// ── Obs editor helpers ─────────────────────────────────────
function cotObsToggleEditor(svc, obsId){
  const svcKey = svc.replace(/\s/g,'-');
  const wrap = document.getElementById('obs-editor-wrap-'+svcKey+'-'+obsId);
  if(!wrap) return;
  const visible = wrap.style.display !== 'none';
  wrap.style.display = visible ? 'none' : 'block';
  if(!visible){
    // Set content in editor
    const ed = document.getElementById('obs-editor-'+svcKey+'-'+obsId);
    if(ed && !cotWizard._obsEdits[svc]?.[obsId]){
      const orig = db.biblioteca[svc]?.observaciones?.find(o=>o.id===obsId);
      if(orig && ed.innerHTML !== orig.html) ed.innerHTML = orig.html||'';
    }
  }
}

function cotObsFmt(svcKey, obsId, cmd){
  const ed = document.getElementById('obs-editor-'+svcKey+'-'+obsId);
  if(!ed) return;
  ed.focus();
  document.execCommand(cmd, false, null);
  // Save the edit
  const svc = svcKey.replace(/-/g,' ');
  cotObsSaveEdit(svc, obsId, ed);
}

function cotObsSaveEdit(svc, obsId, el){
  if(!cotWizard._obsEdits) cotWizard._obsEdits = {};
  if(!cotWizard._obsEdits[svc]) cotWizard._obsEdits[svc] = {};
  cotWizard._obsEdits[svc][obsId] = el.innerHTML;
  // Update preview
  const svcKey = svc.replace(/\s/g,'-');
  const prev = document.getElementById('obs-preview-'+svcKey+'-'+obsId);
  if(prev){
    const txt = el.innerHTML.replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim().slice(0,100);
    prev.textContent = txt + (txt.length>=100?'…':'');
  }
}

function cotObsRestoreOriginal(svc, obsId){
  const orig = db.biblioteca[svc]?.observaciones?.find(o=>o.id===obsId);
  if(!orig) return;
  const svcKey = svc.replace(/\s/g,'-');
  const ed = document.getElementById('obs-editor-'+svcKey+'-'+obsId);
  if(ed) ed.innerHTML = orig.html||'';
  if(cotWizard._obsEdits?.[svc]) delete cotWizard._obsEdits[svc][obsId];
  cotObsSaveEdit(svc, obsId, ed);
}

function cotObsGuardarNueva(svc, obsId){
  const svcKey = svc.replace(/\s/g,'-');
  const nameInput = document.getElementById('obs-newname-'+svcKey+'-'+obsId);
  const nombre = nameInput?.value.trim();
  if(!nombre){ alert('Escribe un nombre para la nueva observación'); return; }

  const ed = document.getElementById('obs-editor-'+svcKey+'-'+obsId);
  const html = ed?.innerHTML || cotWizard._obsEdits?.[svc]?.[obsId] || '';
  if(!html.trim()){ alert('El contenido está vacío'); return; }

  initBiblioteca();
  const newObs = { id:'obs'+Date.now(), nombre, html };
  db.biblioteca[svc].observaciones.push(newObs);
  save();

  nameInput.value = '';
  toast('✅', 'Observación "'+nombre+'" guardada en '+svc, '#00e676');
  renderCotObsStep();
}

// ============================================================
// VISTA PREVIA HTML
// ============================================================

// ── Firmas digitales por comercial ───────────────────────────────────────
var _FIRMAS = {'oscar burgos': IMG_FIRMA_OSCAR, 'ana milena trujillo': IMG_FIRMA_ANA_MILENA};
function _firmaImg(nombre){
  var url = _FIRMAS[(nombre||''). toLowerCase().trim()];
  if(!url) return '<div style="height:60px"></div>';
  return '<img src="'+url+'" style="max-height:60px;max-width:220px;object-fit:contain;display:block;margin:0 auto 4px">' ;
}

function buildCotHTML(wiz, forPrint=false){
  const comercial = db.comerciales.find(c=>c.id===wiz.comercialId);
  const fmtDate = d=>{ try{ const dd=new Date(d+'T12:00'); return dd.toLocaleDateString('es-CO',{day:'2-digit',month:'long',year:'numeric'}); }catch(e){ return d||'—';} };

  // Vigencia: new format = date string, legacy = number of days
  let vigenciaFecha;
  if(wiz.vigencia && /^\d{4}-\d{2}-\d{2}$/.test(wiz.vigencia)){
    vigenciaFecha = wiz.vigencia;
  } else {
    const v = new Date(wiz.fecha||today());
    v.setDate(v.getDate() + (+wiz.vigencia||30));
    vigenciaFecha = v.toISOString().slice(0,10);
  }

  // Detect if any Transporte LOCAL group (6 cols) is included → landscape
  const hasLocalGroup = wiz.lineas.includes('Transporte') &&
    Object.keys(wiz.items['Transporte']||{}).some(gid=>{
      const g = (db.biblioteca['Transporte']?.grupos||[]).find(g=>g.id===gid);
      return g && g.tipo==='local' && wiz.items['Transporte'][gid]?.sel;
    });
  const pageRule = hasLocalGroup
    ? '@page{size:A4 landscape;margin:8mm 6mm}'
    : '@page{margin:12mm 10mm}';

  let seccionesHtml = '';
  wiz.lineas.forEach(svc=>{
    const bib = db.biblioteca[svc]||{grupos:[]};
    const extraCols = bib.columnas||[];
    const ph = bib.colHeaders||{};
    const ph1 = ph.col1||'Servicio';
    const ph2 = ph.col2||'Tarifa';
    const ph3 = ph.col3||'Observaciones';
    let tablas = '';

    // Determine source: especial tarifa OR general library
    const espItems = wiz._espItems?.[svc];
    const usandoEspecial = wiz.tarifaTipo?.[svc]==='especial' && espItems && espItems.length;
    const fuenteGrupos = usandoEspecial ? espItems : null;
    const gruposGen = wiz.items[svc]||{};

    // Iterator: especial uses _espItems array, general uses bib.grupos + wiz.items
    const iterGrupos = usandoEspecial
      ? espItems
      : bib.grupos.map(g=>{ const grp=gruposGen[g.id]; return grp?{...g,...grp}:null; }).filter(Boolean);

    iterGrupos.forEach(g=>{
      if(!g.sel) return;
      const selItems = (g.items||[]).filter(i=>i.sel);
      if(!selItems.length) return;

      // TRANSPORTE — estructura especial de campos
      if(svc === 'Transporte'){
        const tipo = g.tipo || 'local';
        const schema = TRANSP_SCHEMA[tipo] || TRANSP_SCHEMA.local;
        const cols = schema.cols;
        const tblClass = tipo==='local' ? 'cot-tabla cot-tabla-local' : 'cot-tabla cot-tabla-otros';
        // colgroup: generate one <col> per column so CSS nth-child widths apply
        const colgroup = `<colgroup>${cols.map(()=>'<col>').join('')}</colgroup>`;
        // For LOCAL table use short names to fit the page
        const LOCAL_HEADERS = {
          tipoVehiculo: 'TIPO VEHÍCULO',
          capacidades:  'CAPACIDADES',
          valorMax:     'VALOR MÁX.<br>MERCANCÍA',
          viaje4h:      'VIAJE<br>4 HORAS',
          viaje8h:      'VIAJE<br>8 HORAS',
          horaAdc:      'HORA<br>ADICIONAL'
        };
        const getHeader = col => tipo==='local' && LOCAL_HEADERS[col.id]
          ? LOCAL_HEADERS[col.id] : col.nombre;
        tablas += `
          <div class="cot-grupo-titulo transp-section">${g.nombre}</div>
          <table class="${tblClass}">
            ${colgroup}
            <thead><tr>
              ${cols.map(col=>`<th>${getHeader(col)}</th>`).join('')}
            </tr></thead>
            <tbody>
              ${selItems.map(i=>{
                const campos = i.campos||{};
                const tiposCampo = i.tiposCampo||{};
                return `<tr>${cols.map(col=>{
                  const val = campos[col.id]||'—';
                  const tipoCampo = tiposCampo[col.id]||'moneda';
                  const fmtMoney = v => {
                    const n = parseFloat(String(v).replace(/\./g,'').replace(',','.'));
                    return !isNaN(n) ? '$'+Math.round(n).toLocaleString('es-CO') : v;
                  };
                  if(col.tipo==='tarifa'){
                    return `<td class="tarifa">${fmtMoney(val)}</td>`;
                  }
                  if(col.tipo==='tarifa-mixta'){
                    if(tipoCampo==='porcentaje') return `<td class="tarifa">${val}${String(val).includes('%')?'':'%'}</td>`;
                    return `<td class="tarifa">${fmtMoney(val)}</td>`;
                  }
                  if(col.tipo==='tarifa-texto'){
                    if(tipoCampo==='texto') return `<td>${val}</td>`;
                    return `<td class="tarifa">${fmtMoney(val)}</td>`;
                  }
                  return `<td>${val}</td>`;
                }).join('')}</tr>`;
              }).join('')}
            </tbody>
          </table>`;
        return;
      }


      // PAQUETEO — estructura especial de campos por schema
      if(svc === 'Paqueteo'){
        const schema = PAQUETEO_SCHEMA[g.tipo];
        if(!schema){ return; } // fallback seguro
        // Only render groups matching selected paquetera
        if(wiz.paqueteadora && schema.paqueteadora !== wiz.paqueteadora) return;
        const cols = schema.cols;
        const fmtMoney = v => {
          const n = parseFloat(String(v).replace(/\./g,'').replace(',','.'));
          return !isNaN(n) && v!=='' ? '$'+Math.round(n).toLocaleString('es-CO') : (v||'—');
        };
        const fmtNum = v => {
          const n = parseFloat(String(v).replace(/\./g,'').replace(',','.'));
          return !isNaN(n) && v!=='' ? Math.round(n).toLocaleString('es-CO') : (v||'—');
        };
        const fmtPct = v => v ? (String(v).includes('%') ? v : v+'%') : '—';

        // Build headers with colspan support for tcc_radicacion
        let theads;
        if(schema.colspanGroups && schema.colspanGroups.length){
          const firstCol = cols.find(col => !schema.colspanGroups.some(cg => cg.cols.includes(col.id)));
          const groupRow = `<th rowspan="2" style="vertical-align:middle">${firstCol ? firstCol.nombre : ''}</th>` +
            schema.colspanGroups.map(cg =>
              `<th colspan="${cg.cols.length}" style="text-align:center;background:#002366;color:#fff;letter-spacing:0.5px">${cg.label}</th>`
            ).join('');
          const subRow = schema.colspanGroups.map(cg =>
            cg.cols.map(cid => {
              const col = cols.find(c => c.id === cid);
              return `<th>${col ? col.nombre : cid}</th>`;
            }).join('')
          ).join('');
          theads = `<tr>${groupRow}</tr><tr>${subRow}</tr>`;
        } else {
          theads = `<tr>${cols.map(col => `<th>${col.nombre}</th>`).join('')}</tr>`;
        }

        const rowsHtml = selItems.map(item => {
          if(!item.campos) item.campos = {};
          const cells = cols.map(col => {
            const val = item.campos[col.id]||'';
            if(col.tipo === 'moneda')   return `<td class="tarifa" style="text-align:center">${fmtMoney(val)}</td>`;
            if(col.tipo === 'numero')   return `<td style="text-align:center">${fmtNum(val)}</td>`;
            if(col.tipo === 'porcentaje') return `<td style="text-align:center">${fmtPct(val)}</td>`;
            if(col.tipo === 'mixta'){
              const tc3 = (item.tiposCampo||{})[col.id] || 'moneda';
              if(tc3==='moneda') return `<td class="tarifa" style="text-align:center">${fmtMoney(val)}</td>`;
              if(tc3==='porcentaje') return `<td style="text-align:center">${fmtPct(val)}</td>`;
              return `<td style="text-align:center">${val||'—'}</td>`;
            }
            return `<td>${val||'—'}</td>`;
          }).join('');
          return `<tr>${cells}</tr>`;
        }).join('');

        // Optional ecommerce observation
        const ecomObs = schema.hasObs && g.obsEcommerce
          ? `<div style="margin-top:10px;padding:10px 14px;background:#f8f9fd;border-left:3px solid #002366;font-family:'Barlow',sans-serif;font-size:12px;color:#444;line-height:1.6">${g.obsEcommerce}</div>`
          : '';

        tablas += `
          <div class="cot-grupo-titulo">${g.nombre}</div>
          <table class="cot-tabla cot-tabla-paq">
            <thead>${theads}</thead>
            <tbody>${rowsHtml}</tbody>
          </table>${ecomObs}`;
        return;
      }

      // Resto de servicios — estructura estándar
      // Fixed column widths so all groups align consistently
      const nExtra = extraCols.length;
      const w1 = nExtra ? '35%' : '40%';  // Servicio
      const w2 = nExtra ? '18%' : '22%';  // Tarifa
      const w3 = nExtra ? '25%' : '38%';  // Observación
      const wExtra = nExtra ? Math.floor(22/nExtra)+'%' : '0%';
      const colgroup = `<colgroup>
        <col style="width:${w1}">
        <col style="width:${w2}">
        <col style="width:${w3}">
        ${extraCols.map(()=>`<col style="width:${wExtra}">`).join('')}
      </colgroup>`;
      tablas += `
        <div class="cot-grupo-titulo">${g.nombre}</div>
        <table class="cot-tabla" style="width:100%;table-layout:fixed">
          ${colgroup}
          <thead><tr>
            <th>${ph1}</th><th>${ph2}</th><th>${ph3}</th>
            ${extraCols.map(col=>`<th>${col.nombre}</th>`).join('')}
          </tr></thead>
          <tbody>
            ${selItems.map(i=>`
              <tr>
                <td style="word-wrap:break-word">${i.nombre||'—'}</td>
                <td class="tarifa">${fmtTarifa(i.tarifa||'',i.tipoTarifa||'moneda')}</td>
                <td style="word-wrap:break-word">${i.obs||'—'}</td>
                ${extraCols.map(col=>`<td style="word-wrap:break-word">${(i.extraCols&&i.extraCols[col.id])||'—'}</td>`).join('')}
              </tr>`).join('')}
          </tbody>
        </table>`;
    });
    if(!tablas) return;
    seccionesHtml += `<div class="cot-seccion-titulo">${SVC_ICONS[svc]||''} ${svc}</div>${tablas}`;
  });

  // Observaciones ricas
  let obsBlocks = [];
  wiz.lineas.forEach(svc=>{
    migrateObsToRich(svc);
    const obs = db.biblioteca[svc]?.observaciones||[];
    const sel = wiz.obsPlantillas[svc]||[];
    obs.forEach(o=>{
      // Soporta sel por id (nuevo) o por índice numérico (legacy)
      const included = sel.includes(o.id) || sel.includes(obs.indexOf(o));
      if(included){
        // Use edited version if exists, otherwise original
        const editedHtml = wiz._obsEdits?.[svc]?.[o.id];
        obsBlocks.push({nombre: o.nombre, html: editedHtml || o.html || ''});
      }
    });
  });
  // Texto libre
  if(wiz.obsLibre){
    const libreHtml = wiz.obsLibre.split('\n').filter(Boolean).map(l=>`<p style="margin:4px 0">${l}</p>`).join('');
    if(libreHtml) obsBlocks.push({nombre:'Observaciones Adicionales', html: libreHtml});
  }

  const obsHtml = obsBlocks.length ? `
    <div class="cot-obs-box">
      <div class="cot-obs-titulo">Observaciones y Condiciones</div>
      ${obsBlocks.map(b=>`
        <div style="margin-bottom:14px">
          <div style="font-family:'Barlow',sans-serif;font-size:13px;color:#333;line-height:1.7">${b.html}</div>
        </div>`).join('')}
    </div>` : '';

  const logoHtml = `<img src="${IMG_LOGO_COT}" alt="Grupo ZYMO" style="height:80px;max-width:220px;object-fit:contain;display:block">`;

  // Logo de empresa por línea de negocio (esquina superior derecha)
  // Logo de línea de negocio (esquina superior derecha) — deduplicado por src
  // Estilos por logo según ratio de cada imagen
  const SVC_LOGO_STYLE = {
    'Zona Franca':       'max-width:190px;height:auto;display:block;object-fit:contain',
    'Depósito Aduanero': 'max-height:90px;width:auto;display:block;object-fit:contain',
    'CEDI':              'max-height:90px;width:auto;display:block;object-fit:contain',
    'Transporte':        'max-height:90px;width:auto;display:block;object-fit:contain',
    'Paqueteo':          'max-height:90px;width:auto;display:block;object-fit:contain',
    'Aduana':            'max-width:200px;height:auto;display:block;object-fit:contain',
  };
  const seenLogos = new Set();
  const svcLogoHtml = wiz.lineas.map(svc => {
    if(SVC_LOGOS[svc] && !seenLogos.has(SVC_LOGOS[svc])){
      seenLogos.add(SVC_LOGOS[svc]);
      const st = SVC_LOGO_STYLE[svc] || 'max-width:200px;max-height:90px;width:auto;height:auto;display:block';
      return `<img src="${SVC_LOGOS[svc]}" alt="${svc}" style="${st}">`;
    }
    return '';
  }).filter(Boolean).join('');

  return `
    <div class="cot-preview" id="cot-doc-${wiz.id||'draft'}">
      <div class="cot-preview-header">
        ${logoHtml}
        <div style="display:flex;flex-direction:column;align-items:flex-end;gap:8px">
          <div style="display:flex;flex-direction:row;align-items:center;justify-content:flex-end;gap:20px;flex-wrap:nowrap">
            ${svcLogoHtml}
          </div>
          <div class="cot-preview-meta">
            <strong>${wiz.numero||'BORRADOR'}</strong>
            <span>Fecha: ${fmtDate(wiz.fecha)}</span><br>
            <span>Vigencia: ${fmtDate(vigenciaFecha)}</span>
          </div>
        </div>
      </div>
      <div class="cot-cliente-box">
        <strong>${wiz.empresa||'—'}</strong>
        ${wiz.contacto?`<div style="margin-top:4px;font-size:13px;color:#444">${wiz.contacto}</div>`:''}
        ${wiz.cargo?`<div style="font-size:12px;color:#666;margin-top:2px">${wiz.cargo}</div>`:''}
        ${wiz.asunto?`<div style="margin-top:8px;font-weight:600;color:#002366">${wiz.asunto}</div>`:''}
      </div>
      ${seccionesHtml}
      ${obsHtml}
      <div style="margin-top:40px;padding-top:24px;border-top:2px solid #002366;display:flex;justify-content:flex-end">
        <div style="min-width:260px;text-align:center">
          ${_firmaImg(comercial?.nombre)}
          <div style="border-bottom:2px solid #002366;margin-bottom:10px"></div>
          <div style="font-size:14px;font-weight:700;color:#002366">${comercial?.nombre||''}</div>
          <div style="font-size:12px;color:#555;margin-top:3px">${comercial?.cargo||'Asesor Comercial'} · Grupo ZYMO</div>
          ${comercial?.email?`<div style="font-size:11px;color:#888;margin-top:2px">${comercial.email}</div>`:''}
          ${comercial?.tel?`<div style="font-size:11px;color:#888">${comercial.tel}</div>`:''}
        </div>
      </div>
      <div class="cot-footer-line">
        <span>Grupo ZYMO · www.logimat.com.co</span>
        <span>${wiz.numero||''} · ${fmtDate(wiz.fecha)}</span>
      </div>
    </div>`;
}

function renderCotPreview(){
  cotWizard.obsLibre = document.getElementById('cot-obs-libre')?.value||'';
  _ensureEspItems(cotWizard);
  document.getElementById('cot-preview-wrapper').innerHTML = buildCotHTML(cotWizard);
}

// ============================================================
// GUARDAR / EDITAR
// ============================================================
function guardarCotizacion(silentMode=false){
  // Remove temporarily injected imported groups from biblioteca
  if(cotWizard._impGrupos?.length > 0){
    SERVICES.forEach(svc=>{
      if(db.biblioteca[svc]){
        db.biblioteca[svc].grupos = db.biblioteca[svc].grupos.filter(g=>!g._imported);
      }
    });
  }
  collectStepData(99);
  if(!cotWizard.empresa){ toast('⚠️','Ingresa el nombre de la empresa','#f5a623'); cotStep(1); return; }

  if(!cotWizard.id){
    cotWizard.id = 'cot'+Date.now();
    cotWizard.numero = nextCotNumero();
    cotWizard.createdAt = Date.now();
    db.cotizaciones.push(JSON.parse(JSON.stringify(cotWizard)));
  } else {
    const idx = db.cotizaciones.findIndex(c=>c.id===cotWizard.id);
    if(idx>=0) db.cotizaciones[idx] = JSON.parse(JSON.stringify(cotWizard));
    else db.cotizaciones.push(JSON.parse(JSON.stringify(cotWizard)));
  }
  save();

  if(silentMode){
    toast('💾','Borrador guardado: '+cotWizard.numero,'#00c2ff');
  } else {
    renderCotizaciones();
    toast('✅','Cotización guardada: '+cotWizard.numero,'#00e676');
    setTimeout(()=>showPage('cotizaciones'),1200);
  }
}

// ============================================================
// LISTADO DE COTIZACIONES
// ============================================================
function renderCotizaciones(){
  initBiblioteca();
  const tbody = document.getElementById('cot-tabla-body');
  if(!tbody) return;

  // Populate filter comercial
  const comFil = document.getElementById('cot-filter-com');
  if(comFil && comFil.options.length===1){
    db.comerciales.forEach(c=>{ const o=document.createElement('option'); o.value=c.id; o.textContent=c.nombre; comFil.appendChild(o); });
  }

  const search = document.getElementById('cot-search')?.value.toLowerCase()||'';
  const filEst = document.getElementById('cot-filter-estado')?.value||'';
  const filCom = document.getElementById('cot-filter-com')?.value||'';

  let rows = (db.cotizaciones||[]).filter(c=>{
    if(search && !c.empresa.toLowerCase().includes(search)) return false;
    if(filEst && c.estado!==filEst) return false;
    if(filCom && c.comercialId!==filCom) return false;
    return true;
  }).sort((a,b)=> (b.createdAt||0) - (a.createdAt||0) || (b.id||'').localeCompare(a.id||''));

  if(rows.length===0){
    tbody.innerHTML=`<tr><td colspan="8" style="text-align:center;color:var(--text2);padding:40px">No hay cotizaciones aún. Crea la primera con el botón "+ Nueva Cotización".</td></tr>`;
    return;
  }

  const estTags = {borrador:'tag-borrador',enviada:'tag-enviada',negociacion:'tag-negociacion',aprobada:'tag-aprobada',rechazada:'tag-rechazada',
};
  const estLabel = {borrador:'Borrador',enviada:'Enviada',negociacion:'Negociación',aprobada:'✅ Aprobada',rechazada:'❌ Rechazada'};

  tbody.innerHTML = rows.map(c=>{
    const com = db.comerciales.find(x=>x.id===c.comercialId);
    const comNombre = com?.nombre||'—';
    const comInitials = comNombre!=='—' ? comNombre.split(' ').map(w=>w[0]).join('').slice(0,2).toUpperCase() : '—';
    return `<tr>
      <td style="white-space:nowrap"><span style="font-family:'Barlow Condensed',sans-serif;font-weight:700;font-size:15px;color:var(--accent)">${c.numero||'—'}</span></td>
      <td style="overflow:hidden"><div style="font-weight:600;word-break:break-word;line-height:1.3;font-size:13px">${c.empresa}</div><div style="font-size:11px;color:var(--text2)">${c.nit||''}</div></td>
      <td><div style="display:flex;flex-wrap:wrap;gap:3px">${(c.lineas||[]).map(s=>`<span style="background:rgba(0,194,255,0.1);color:var(--accent);border-radius:4px;padding:1px 6px;font-size:10px;white-space:nowrap">${s}</span>`).join('')}</div></td>
      <td style="font-size:12px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis" title="${comNombre}">${comNombre}</td>
      <td style="font-size:12px;white-space:nowrap">${c.fecha||'—'}</td>
      <td><span class="tag-estado-cot ${estTags[c.estado]||'tag-borrador'}">${estLabel[c.estado]||c.estado}</span></td>
      <td>
        <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:2px">
          <button class="btn btn-secondary btn-sm" onclick="verCotizacion('${c.id}')" title="Ver" style="padding:3px 0;font-size:12px">👁</button>
          <button class="btn btn-secondary btn-sm" onclick="editarCotizacion('${c.id}')" title="Editar" style="padding:3px 0;font-size:12px">✏️</button>
          <button class="btn btn-secondary btn-sm" onclick="duplicarCotizacion('${c.id}')" title="Duplicar" style="padding:3px 0;font-size:12px">⧉</button>
          <button class="btn btn-secondary btn-sm" onclick="copiarLinkCotById('${c.id}')" title="Copiar link" style="padding:3px 0;font-size:12px">🔗</button>
          <button class="btn btn-secondary btn-sm" onclick="exportCotPDFById('${c.id}')" title="PDF" style="padding:3px 0;font-size:12px">📥</button>
          <button class="btn btn-danger btn-sm" onclick="eliminarCotizacion('${c.id}')" title="Eliminar" style="padding:3px 0;font-size:12px">🗑</button>
        </div>
      </td>
    </tr>`;
  }).join('');
}

function verCotizacion(id){
  const cot = db.cotizaciones.find(c=>c.id===id);
  if(!cot) return;
  _ensureEspItems(cot);
  currentPublicCotId = id;
  document.getElementById('cot-publica-content').innerHTML = buildCotHTML(cot, true);
  showPage('cot-publica');
}

function editarCotizacion(id){
  const cot = db.cotizaciones.find(c=>c.id===id);
  if(!cot) return;
  cotWizard = JSON.parse(JSON.stringify(cot));
  document.getElementById('nueva-cot-titulo').innerHTML = `📄 <span>Editar ${cot.numero}</span>`;

  const comSel = document.getElementById('cot-comercial');
  comSel.innerHTML = '<option value="">— Seleccionar —</option>' +
    db.comerciales.map(c=>`<option value="${c.id}"${c.id===cot.comercialId?' selected':''}>${c.nombre}</option>`).join('');

  const empSel = document.getElementById('cot-empresa-sel');
  empSel.innerHTML = '<option value="">— Empresa nueva / manual —</option>' +
    [...new Map(db.records.map(r=>[r.empresa,r])).values()]
      .map(r=>`<option value="${r.empresa}|${r.nit||''}">${r.empresa}</option>`).join('');

  // Pre-select the empresa in the dropdown
  const matchOpt = [...empSel.options].find(o => o.value.split('|')[0] === cot.empresa);
  if(matchOpt) empSel.value = matchOpt.value;

  // Fill empresa/nit from cotizacion
  document.getElementById('cot-empresa').value = cot.empresa||'';
  document.getElementById('cot-nit').value     = cot.nit||'';

  // Fill contact from the RECORD if it exists (not from the cotizacion copy)
  // This ensures duplicated cotizaciones get fresh contact data from the record
  const recMatch = db.records.find(r => r.empresa === cot.empresa);
  if(recMatch && recMatch.contactos && recMatch.contactos.length > 0){
    // Record exists with contacts — use record's contact data
    fillCotContacto(recMatch.contactos[0]);
    if(recMatch.contactos.length > 1){
      const selEl = document.getElementById('cot-contacto-sel');
      const selGroup = document.getElementById('cot-contacto-sel-group');
      if(selEl && selGroup){
        selEl.innerHTML = '<option value="">— Seleccionar contacto —</option>' +
          recMatch.contactos.map((ct,i)=>`<option value="${i}">${ct.nombre}${ct.cargo?' — '+ct.cargo:''}</option>`).join('');
        selGroup.style.display = 'block';
        selEl.dataset.recordId = recMatch.id;
        selEl.value = '0';
      }
    }
  } else {
    // No record or no contacts — use whatever is in the cotizacion
    document.getElementById('cot-contacto').value = cot.contacto||'';
    document.getElementById('cot-cargo').value    = cot.cargo||'';
    document.getElementById('cot-email').value    = cot.email||'';
    const telEl = document.getElementById('cot-telefono');
    if(telEl) telEl.value = cot.telefono||'';
  }
  document.getElementById('cot-fecha').value    = cot.fecha||today();

  // Vigencia: handle legacy (number of days) and new (date string)
  const vigEl = document.getElementById('cot-vigencia');
  if(cot.vigencia && /^\d{4}-\d{2}-\d{2}$/.test(cot.vigencia)){
    vigEl.value = cot.vigencia;
  } else {
    // Legacy numeric — calculate date
    const d = new Date(cot.fecha||today());
    d.setDate(d.getDate() + (+cot.vigencia||30));
    vigEl.value = d.toISOString().slice(0,10);
  }

  document.getElementById('cot-estado').value  = cot.estado||'borrador';
  document.getElementById('cot-asunto').value  = cot.asunto||'';

  // Populate contact selector if the empresa has multiple contacts
  const rec = db.records.find(r => r.empresa === cot.empresa);
  const csg = document.getElementById('cot-contacto-sel-group');
  const cse = document.getElementById('cot-contacto-sel');
  if(rec && rec.contactos && rec.contactos.length > 1 && csg && cse){
    cse.innerHTML = '<option value="">— Seleccionar contacto —</option>' +
      rec.contactos.map((c,i)=>`<option value="${i}">${c.nombre}${c.cargo?' — '+c.cargo:''}</option>`).join('');
    // Try to match saved contact by name
    const savedIdx = rec.contactos.findIndex(c => c.nombre === cot.contacto);
    cse.value = savedIdx >= 0 ? String(savedIdx) : '';
    cse.dataset.recordId = rec.id;
    csg.style.display = 'block';
  } else {
    if(csg) csg.style.display = 'none';
  }

  // ── Restaurar todos los servicios en modo editable ──────────────
  if(!cotWizard._espEdit)   cotWizard._espEdit   = {};
  if(!cotWizard._espEditId) cotWizard._espEditId = {};
  if(!cotWizard._espItems)  cotWizard._espItems  = {};

  (cotWizard.lineas||[]).forEach(function(svc){
    var espKey = (svc==='Paqueteo' && cotWizard.paqueteadora) ? 'Paqueteo-'+cotWizard.paqueteadora : svc;
    var espId  = cotWizard.tarifaEspecialId ? cotWizard.tarifaEspecialId[svc] : '';
    var tipo   = cotWizard.tarifaTipo ? cotWizard.tarifaTipo[svc] : 'general';

    // Fuente 1: _espItems guardados en la cotización (estado real de lo cotizado)
    var savedEspItems = cotWizard._espItems && cotWizard._espItems[svc];
    // Fuente 2: tarifa especial en biblioteca
    var te = espId && espId!=='nueva' ? (db.tarifasEspeciales[espKey]||[]).find(function(t){return t.id===espId;}) : null;
    // Fuente 3: items generales guardados
    var savedItems = cotWizard.items && cotWizard.items[svc];

    if(tipo === 'especial'){
      // Prioridad: _espItems de la cotización > tarifa de biblioteca
      var source = savedEspItems || (te ? te.grupos.map(function(g){
        return {id:g.gid||g.id, nombre:g.nombre, tipo:g.tipo||'', sel:true,
                items:(g.items||[]).map(function(i){return Object.assign({},i,{sel:true});}),
                obsEcommerce:g.obsEcommerce||''};
      }) : []);

      if(source.length){
        // Restaurar _espEdit con los datos reales de la cotización
        cotWizard._espEdit[svc] = JSON.parse(JSON.stringify(source)).map(function(g){
          return {id:g.gid||g.id||g.nombre, nombre:g.nombre, tipo:g.tipo||'', sel:true,
                  items:(g.items||[]).map(function(i){return Object.assign({},i,{sel:true});}),
                  obsEcommerce:g.obsEcommerce||''};
        });
        cotWizard._espItems[svc] = JSON.parse(JSON.stringify(source));
        if(te) cotWizard._espEditId[svc] = te.id;
        cotWizard.tarifaEspecialId[svc] = 'nueva'; // modo edición
      }
    } else {
      // Tarifa general: restaurar items editables desde los items guardados
      if(savedItems && Object.keys(savedItems).length){
        // Los items ya están en cotWizard.items[svc] — el paso 3 los leerá directamente
        // Solo asegurarnos que sel=true para que sean visibles
        Object.values(savedItems).forEach(function(grp){
          if(grp && grp.items) grp.items.forEach(function(i){ if(i.sel===undefined) i.sel=true; });
        });
      }
    }
  });

  buildStepBar();
  cotStep(1);
  showPage('nueva-cot');
}

function duplicarCotizacion(id){
  const orig = db.cotizaciones.find(c=>c.id===id);
  if(!orig) return;
  const dup = JSON.parse(JSON.stringify(orig));
  dup.id = 'cot'+Date.now();
  dup.numero = nextCotNumero();
  dup.estado = 'borrador';
  dup.fecha = today();
  dup.createdAt = Date.now(); // ensure it sorts first
  db.cotizaciones.push(dup);
  save();
  renderCotizaciones();
  toast('✅','Cotización duplicada: '+dup.numero+' — Edítala para ajustar los datos','#00c2ff');
}

function eliminarCotizacion(id){
  if(!confirm('¿Eliminar esta cotización? Se moverá a la papelera y podrás restaurarla si fue un error.')) return;
  const idx = db.cotizaciones.findIndex(c=>c.id===id);
  if(idx<0) return;
  const cot = db.cotizaciones.splice(idx,1)[0];
  cot.deletedAt = Date.now();
  if(!db.papeleraCotizaciones) db.papeleraCotizaciones = [];
  db.papeleraCotizaciones.push(cot);
  save(); renderCotizaciones();
  toast('🗑','Cotización movida a la papelera','#ff4444');
}

function abrirPapeleraCotizaciones(){
  const items = (db.papeleraCotizaciones||[]).slice().sort((a,b)=>(b.deletedAt||0)-(a.deletedAt||0));
  document.getElementById('modal-titulo').textContent = '🗑️ Papelera de Cotizaciones';
  document.getElementById('modal-content').innerHTML = items.length ? `
    <div class="modal-section">
      ${items.map(c=>`
        <div style="display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid var(--border)">
          <div>
            <div style="font-weight:600">${c.numero||'—'} · ${c.empresa||'—'}</div>
            <div style="font-size:11px;color:var(--text2)">Eliminada: ${new Date(c.deletedAt).toLocaleString('es-CO')}</div>
          </div>
          <button class="btn btn-secondary btn-sm" onclick="restaurarCotizacion('${c.id}')">♻️ Restaurar</button>
        </div>`).join('')}
    </div>` : `<div class="modal-section" style="color:var(--text2);text-align:center;padding:30px">La papelera está vacía.</div>`;
  document.getElementById('modal-footer').innerHTML = `
    <div style="display:flex;gap:12px;margin-left:auto">
      <button class="btn btn-secondary" onclick="closeModal()">Cerrar</button>
    </div>`;
  document.getElementById('modal-detalle').classList.add('open');
}

function restaurarCotizacion(id){
  const idx = (db.papeleraCotizaciones||[]).findIndex(c=>c.id===id);
  if(idx<0) return;
  const cot = db.papeleraCotizaciones.splice(idx,1)[0];
  delete cot.deletedAt;
  db.cotizaciones.push(cot);
  save(); renderCotizaciones();
  abrirPapeleraCotizaciones();
  toast('♻️','Cotización restaurada: '+(cot.numero||''),'#00e676');
}

// ============================================================
// EXPORTACIÓN PDF
// ============================================================
function exportCotPDF(){
  const wiz = JSON.parse(JSON.stringify(cotWizard));
  wiz.obsLibre = document.getElementById('cot-obs-libre')?.value||'';
  _ensureEspItems(wiz);
  printCot(wiz);
}

function _ensureEspItems(cot){
  if(!cot._espItems) cot._espItems = {};
  (cot.lineas||[]).forEach(svc=>{
    if(cot.tarifaTipo?.[svc] !== 'especial') return;
    if(cot._espItems[svc] && cot._espItems[svc].length) return;
    const teId = cot.tarifaEspecialId?.[svc];
    if(!teId) return;
    const keys = svc === 'Paqueteo'
      ? ['Paqueteo-COORDINADORA','Paqueteo-TCC','Paqueteo-SERVIENTREGA','Paqueteo']
      : [svc];
    for(const key of keys){
      const te = (db.tarifasEspeciales[key]||[]).find(t=>t.id===teId);
      if(te){
        cot._espItems[svc] = te.grupos.map(g=>({...g, sel:true, items:(g.items||[]).map(i=>({...i,sel:true}))}));
        break;
      }
    }
  });
}

function exportCotPDFById(id){
  const cot = db.cotizaciones.find(c=>c.id===id);
  if(!cot) return;
  _ensureEspItems(cot);
  printCot(cot);
}

function printCot(wiz){
  if(typeof html2canvas === 'undefined' || typeof jspdf === 'undefined'){
    toast('⚠️','Cargando librerías PDF, intenta en 3 segundos','#f5a623');
    return;
  }
  const { jsPDF } = jspdf;

  // ── 1. Inyectar HTML en la vista pública ──────────────────────────────
  const cotContent = document.getElementById('cot-publica-content');
  const prevHtml   = cotContent.innerHTML;
  const prevTitle  = document.title;
  cotContent.innerHTML = buildCotHTML(wiz, true);
  document.title = (wiz.numero||'Cotización') + ' — ' + (wiz.empresa||'');

  const allPages = document.querySelectorAll('.page');
  const prevActive = [];
  allPages.forEach(p => {
    if(p.classList.contains('active')){ prevActive.push(p.id); p.classList.remove('active'); }
  });
  document.getElementById('page-cot-publica').classList.add('active');
  const btnBar = document.getElementById('cot-publica-actions');
  if(btnBar) btnBar.style.visibility = 'hidden';

  toast('⏳','Generando PDF...','#00c2ff');

  const restoreView = () => {
    if(btnBar) btnBar.style.visibility = '';
    cotContent.innerHTML = prevHtml;
    document.title = prevTitle;
    document.getElementById('page-cot-publica').classList.remove('active');
    prevActive.forEach(id => { const el = document.getElementById(id); if(el) el.classList.add('active'); });
  };

  // ── 2. Esperar render completo ────────────────────────────────────────
  setTimeout(()=>{
    const target = document.querySelector('#page-cot-publica .cot-preview') || cotContent;

    // Reducir padding temporalmente para el PDF (la vista en pantalla usa 48px)
    const prevPadding = target.style.padding;
    const prevRadius  = target.style.borderRadius;
    const prevShadow  = target.style.boxShadow;
    target.style.padding      = '24px 28px';
    target.style.borderRadius = '0';
    target.style.boxShadow    = 'none';
    const sections = target.querySelectorAll(
      '.cot-preview-header, .cot-cliente-box, .cot-seccion, .transp-section, .cot-grupo, .cot-obs-box, .cot-footer-line'
    );

    // Si no hay secciones marcadas, capturar todo junto con altura libre
    const captureTarget = target;

    html2canvas(captureTarget, {
      scale: 2.5,
      useCORS: true,
      allowTaint: true,
      backgroundColor: '#ffffff',
      logging: false,
      scrollX: 0,
      scrollY: -window.scrollY,
      windowWidth: document.documentElement.scrollWidth,
      windowHeight: captureTarget.scrollHeight
    }).then(canvas => {
      // Restaurar estilos del preview y la vista
      target.style.padding      = prevPadding;
      target.style.borderRadius = prevRadius;
      target.style.boxShadow    = prevShadow;
      restoreView();

      // ── Recortar filas blancas del final del canvas (evita hoja en blanco) ──
      const ctxTrim  = canvas.getContext('2d');
      let trimBottom = canvas.height;
      for(let row = canvas.height - 1; row >= 0; row--){
        const rowData = ctxTrim.getImageData(0, row, canvas.width, 1).data;
        let allWhite = true;
        for(let i = 0; i < rowData.length; i += 4){
          if(rowData[i] < 240 || rowData[i+1] < 240 || rowData[i+2] < 240){ allWhite = false; break; }
        }
        if(!allWhite){ trimBottom = row + 1; break; }
      }
      // Canvas recortado
      const trimmedCanvas = document.createElement('canvas');
      trimmedCanvas.width  = canvas.width;
      trimmedCanvas.height = trimBottom;
      trimmedCanvas.getContext('2d').drawImage(canvas, 0, 0, canvas.width, trimBottom, 0, 0, canvas.width, trimBottom);

      const pdf   = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
      const pageW = 210, pageH = 297;
      const margin = 3;  // margen mínimo — el contenido ya trae su propio padding
      const imgW  = pageW - margin * 2;
      const imgH  = pageH - margin * 2;

      const mmPerPx = imgW / trimmedCanvas.width;
      const totalMM = trimmedCanvas.height * mmPerPx;

      if(totalMM <= imgH){
        // ── Cabe en una sola página ──────────────────────────────────────
        pdf.addImage(trimmedCanvas.toDataURL('image/jpeg', 0.92), 'JPEG', margin, margin, imgW, totalMM);
      } else {
        // ── Paginar detectando filas blancas para no cortar contenido ────
        const ctx       = trimmedCanvas.getContext('2d');
        const pxPerPage = Math.floor(imgH / mmPerPx);
        let offsetPx    = 0;
        let page        = 0;

        while(offsetPx < trimmedCanvas.height){
          if(page > 0) pdf.addPage();

          let cutPx = Math.min(offsetPx + pxPerPage, trimmedCanvas.height);
          if(cutPx < trimmedCanvas.height){
            const searchRange = Math.floor(pxPerPage * 0.05);
            let bestRow = cutPx;
            let maxWhite = -1;
            for(let row = cutPx - searchRange; row <= cutPx + searchRange && row < trimmedCanvas.height; row++){
              const rowData = ctx.getImageData(0, row, trimmedCanvas.width, 1).data;
              let whites = 0;
              for(let i = 0; i < rowData.length; i += 4){
                if(rowData[i] > 240 && rowData[i+1] > 240 && rowData[i+2] > 240) whites++;
              }
              if(whites > maxWhite){ maxWhite = whites; bestRow = row; }
            }
            cutPx = bestRow;
          }

          const sliceH  = cutPx - offsetPx;
          const sliceMM = sliceH * mmPerPx;

          const slice = document.createElement('canvas');
          slice.width  = trimmedCanvas.width;
          slice.height = sliceH;
          slice.getContext('2d').drawImage(
            trimmedCanvas,
            0, offsetPx, trimmedCanvas.width, sliceH,
            0, 0,        trimmedCanvas.width, sliceH
          );

          pdf.addImage(slice.toDataURL('image/jpeg', 0.92), 'JPEG', margin, margin, imgW, sliceMM);
          offsetPx = cutPx;
          page++;
        }
      }
      const fileName = (wiz.numero||'Cotizacion')
        .replace(/[^a-z0-9\-]/gi,'') + '_'
        + (wiz.empresa||'ZYMO').replace(/[^a-z0-9áéíóúñ]/gi,'_').substring(0,25)
        + '.pdf';
      pdf.save(fileName);
      toast('✅','PDF descargado: ' + fileName,'#00e676');

    }).catch(err => {
      target.style.padding      = prevPadding;
      target.style.borderRadius = prevRadius;
      target.style.boxShadow    = prevShadow;
      restoreView();
      console.error('PDF error:', err);
      toast('❌','Error al generar PDF: ' + err.message,'#ff4444');
    });

  }, 700);
}


// ============================================================
// EXPORTACIÓN EXCEL
// ============================================================
function exportCotExcel(){
  const wiz = {...cotWizard};
  wiz.obsLibre = document.getElementById('cot-obs-libre')?.value||'';
  exportCotExcelData(wiz);
}

function exportCotExcelById(id){
  const cot = db.cotizaciones.find(c=>c.id===id);
  if(cot) exportCotExcelData(cot);
}

function exportCotExcelData(wiz){
  if(typeof XLSX==='undefined'){ toast('⚠️','Librería Excel no disponible','#f5a623'); return; }
  const wb = XLSX.utils.book_new();

  wiz.lineas.forEach(svc=>{
    const bib = db.biblioteca[svc]||{grupos:[]};
    const grupos = wiz.items[svc]||{};
    const rows = [['Grupo','Servicio','Tarifa','Tipo','Observaciones']];

    bib.grupos.forEach(g=>{
      const grp = grupos[g.id];
      if(!grp||!grp.sel) return;
      grp.items.filter(i=>i.sel).forEach(i=>{
        rows.push([g.nombre, i.nombre, i.tarifa, i.tipoTarifa==='moneda'?'$COP':'%', i.obs||'']);
      });
    });

    const ws = XLSX.utils.aoa_to_sheet(rows);
    ws['!cols'] = [{wch:28},{wch:42},{wch:16},{wch:10},{wch:44}];
    XLSX.utils.book_append_sheet(wb, ws, svc.substring(0,31));
  });

  // Hoja resumen
  const resumen = [
    ['COTIZACIÓN', wiz.numero||'BORRADOR'],
    ['Empresa', wiz.empresa||''],
    ['NIT', wiz.nit||''],
    ['Contacto', wiz.contacto||''],
    ['Fecha', wiz.fecha||''],
    ['Vigencia', wiz.vigencia+' días'],
    ['Estado', wiz.estado||''],
    ['Comercial', db.comerciales.find(c=>c.id===wiz.comercialId)?.nombre||''],
  ];
  const wsRes = XLSX.utils.aoa_to_sheet(resumen);
  wsRes['!cols'] = [{wch:20},{wch:40}];
  XLSX.utils.book_append_sheet(wb, wsRes, 'Resumen');

  XLSX.writeFile(wb, `${wiz.numero||'Cotizacion'}_${wiz.empresa||'ZYMO'}.xlsx`);
}

// ============================================================
// LINK PÚBLICO
// ============================================================
function buildCotLink(cot){
  const base = window.location.href.split('?')[0];
  return base + '?ZYMO=' + (cot.numero||cot.id).replace(/-/g,'');
}

function copiarLinkCot(){
  if(!cotWizard.id){
    toast('⚠️','Guarda la cotización primero para generar el link','#f5a623');
    return;
  }
  const cot = db.cotizaciones.find(c=>c.id===cotWizard.id);
  if(!cot){ toast('⚠️','Guarda la cotización primero','#f5a623'); return; }
  const url = buildCotLink(cot);
  navigator.clipboard.writeText(url).then(()=>{
    toast('🔗','Link copiado: ...?ZYMO='+cot.numero.replace(/-/g,''),'#00c2ff');
  }).catch(()=>{ prompt('Copia este link:', url); });
}

function copiarLinkCotById(id){
  const cot = db.cotizaciones.find(c=>c.id===id);
  if(!cot){ toast('⚠️','Cotización no encontrada','#f5a623'); return; }
  const url = buildCotLink(cot);
  navigator.clipboard.writeText(url).then(()=>{
    toast('🔗','Link copiado: ...?ZYMO='+cot.numero.replace(/-/g,''),'#00c2ff');
  }).catch(()=>{ prompt('Copia este link:', url); });
}

