function notificarApertura(cot){
  const ahora = new Date();
  const fecha = ahora.toLocaleDateString('es-CO', { weekday:'long', year:'numeric', month:'long', day:'numeric' });
  const hora  = ahora.toLocaleTimeString('es-CO', { hour:'2-digit', minute:'2-digit' });
  const com   = db.comerciales.find(c=>c.id===cot.comercialId);

  emailjs.send('service_gjo0u8f', 'template_lsvvfce', {
    numero_cot:  cot.numero || '—',
    empresa:     cot.empresa || '—',
    contacto:    cot.contacto || '—',
    comercial:   com?.nombre || '—',
    fecha_hora:  `${fecha} a las ${hora}`,
    lineas:      (cot.lineas||[]).join(', ') || '—',
    asunto:      cot.asunto || '—',
  }).then(()=>{
    console.log('[ZYMO] Notificación de apertura enviada:', cot.numero);
  }).catch(err=>{
    console.warn('[ZYMO] No se pudo enviar notificación:', err);
  });
}


// Al cargar, verificar si hay ?ZYMO= en la URL
function checkCotLink(){
  const params = new URLSearchParams(window.location.search);
  // Soporta nuevo formato ?ZYMO=COT001 y legado ?cot=id
  const zymoCod = params.get('ZYMO');
  const legacyId = params.get('cot');
  if(!zymoCod && !legacyId) return;

  initBiblioteca();
  let cot = null;
  if(zymoCod){
    // Normalizar: COT001 → COT-001
    const normalized = zymoCod.replace(/^(COT)(\d+)$/i, 'COT-$2');
    cot = (db.cotizaciones||[]).find(c=>
      (c.numero||'').replace(/-/g,'').toUpperCase() === zymoCod.toUpperCase() ||
      c.numero === normalized
    );
  } else {
    cot = (db.cotizaciones||[]).find(c=>c.id===legacyId);
  }

  const hideInternal = ()=>{
    document.querySelector('nav.sidebar') && (document.querySelector('nav.sidebar').style.display='none');
    document.getElementById('btn-volver-listado').style.display = 'none';
    document.getElementById('btn-link-publica').style.display = 'none';
  };

  if(cot){
    currentPublicCotId = cot.id;
    _ensureEspItems(cot);
    document.getElementById('cot-publica-content').innerHTML = buildCotHTML(cot, true);
    document.title = `Oferta de Servicios — ${cot.empresa||'Grupo ZYMO'}`;
    hideInternal();
    showPage('cot-publica');
    notificarApertura(cot);
  } else {
    hideInternal();
    document.getElementById('cot-publica-content').innerHTML = `
      <div style="text-align:center;padding:80px 20px;color:var(--text2)">
        <div style="font-size:48px;margin-bottom:16px">📄</div>
        <div style="font-size:18px;font-weight:600;margin-bottom:8px">Cotización no disponible</div>
        <div style="font-size:14px">Este link solo funciona en el dispositivo donde fue creada la cotización.</div>
      </div>`;
    showPage('cot-publica');
  }
}
