let actCotizacion = null; // cotización base seleccionada
let actItemsSeleccionados = {}; // { 'svc|gid|idx': true/false }

function abrirActualizacionTarifas(){
  showPage('actualizar-tarifas');
}

function initActualizacionTarifas(){
  const searchEl = document.getElementById('act-cot-search');
  if(!searchEl) return;
  searchEl.value = '';
  document.getElementById('act-cot-results').style.display = 'none';
  document.getElementById('act-cot-selected').style.display = 'none';
  document.getElementById('act-items-panel').style.display = 'none';
  document.getElementById('act-porcentaje').value = '';
  actCotizacion = null;
  actItemsSeleccionados = {};
}

function filtrarActCot(query){
  const results = document.getElementById('act-cot-results');
  const q = query.trim().toLowerCase();
  if(!q){ results.style.display='none'; return; }

  const matches = (db.cotizaciones||[]).filter(c=>
    (c.numero||'').toLowerCase().includes(q) ||
    (c.empresa||'').toLowerCase().includes(q)
  ).sort((a,b)=>(b.fecha||'').localeCompare(a.fecha||'')).slice(0,8);

  if(!matches.length){
    results.innerHTML='<div style="padding:12px 14px;font-size:13px;color:var(--text2)">Sin resultados</div>';
    results.style.display='block';
    return;
  }

  results.innerHTML = matches.map(c=>`
    <div onclick="seleccionarActCot('${c.id}')"
      style="padding:10px 14px;cursor:pointer;border-bottom:1px solid var(--border);font-size:13px"
      onmouseover="this.style.background='var(--surface3)'" onmouseout="this.style.background=''">
      <span style="font-family:'Barlow Condensed',sans-serif;font-weight:700;color:var(--accent)">${c.numero}</span>
      &nbsp;·&nbsp;<strong>${c.empresa}</strong>
      <span style="color:var(--text2);font-size:11px;margin-left:8px">${c.fecha||''}</span>
      <span style="float:right;font-size:11px;color:var(--text2)">${(c.lineas||[]).join(', ')}</span>
    </div>`).join('');
  results.style.display='block';
}

function seleccionarActCot(id){
  const cot = db.cotizaciones.find(c=>c.id===id);
  if(!cot) return;
  document.getElementById('act-cot-search').value = '';
  document.getElementById('act-cot-results').style.display = 'none';
  const selBox = document.getElementById('act-cot-selected');
  selBox.style.display = 'flex';
  document.getElementById('act-cot-selected-label').innerHTML =
    `<span style="font-family:'Barlow Condensed',sans-serif;font-weight:700;color:var(--accent)">${cot.numero}</span>&nbsp;·&nbsp;<strong>${cot.empresa}</strong>&nbsp;<span style="color:var(--text2);font-size:12px">(${cot.fecha||''})</span>`;
  onActCotChange(id);
}

function limpiarActCot(){
  document.getElementById('act-cot-search').value = '';
  document.getElementById('act-cot-results').style.display = 'none';
  document.getElementById('act-cot-selected').style.display = 'none';
  document.getElementById('act-items-panel').style.display = 'none';
  actCotizacion = null;
  actItemsSeleccionados = {};
}

function onActCotChange(id){
  if(!id){ document.getElementById('act-items-panel').style.display='none'; return; }
  actCotizacion = JSON.parse(JSON.stringify(db.cotizaciones.find(c=>c.id===id)));
  if(!actCotizacion) return;
  // Cargar _espItems para servicios con tarifa especial antes de renderizar
  _ensureEspItems(actCotizacion);
  actItemsSeleccionados = {};
  document.getElementById('act-items-panel').style.display = 'block';
  renderActItems();
  previewIncremento();
}

// ── Helpers para iterar ítems de una cotización (general + especial) ──────
// Devuelve array de grupos con estructura uniforme:
//   { gid, nombre, items: [{nombre, tarifa, tipoTarifa, obs, sel, ...campos}] }
// El flag `fuente` indica si viene de 'general' o 'especial'.
function _actGetGruposDeLinea(cot, svc){
  const esEspecial = cot.tarifaTipo?.[svc] === 'especial';

  if(esEspecial){
    // Primero intentar _espItems cargados en memoria
    let espGrupos = cot._espItems?.[svc];
    // Si no están cargados (cotización guardada sin _espItems), reconstruirlos desde db
    if(!espGrupos || !espGrupos.length){
      _ensureEspItems(cot);
      espGrupos = cot._espItems?.[svc];
    }
    if(espGrupos && espGrupos.length){
      return { fuente:'especial', grupos: espGrupos.filter(g=>g.sel!==false).map(function(g){
        return { gid: g.id||g.nombre||'g', nombre: g.nombre||g.id||'—',
                 items: (g.items||[]).filter(function(i){ return i.sel!==false; }) };
      })};
    }
    // Tarifa especial referenciada pero sin grupos cargados → mostrar aviso
    return { fuente:'especial', grupos:[], sinDatos:true };
  }

  // Tarifa general: estructura items[svc][gid]
  const gruposObj = (cot.items && cot.items[svc]) ? cot.items[svc] : {};
  const bibSvc = db.biblioteca[svc]||{grupos:[]};
  const bibMap = {};
  (bibSvc.grupos||[]).forEach(function(g){ bibMap[g.id] = g.nombre||g.id; });

  const grupos = Object.keys(gruposObj).map(function(gid){
    const grp = gruposObj[gid];
    if(!grp || !grp.sel) return null;
    const selItems = (grp.items||[]).filter(function(i){ return i.sel; });
    if(!selItems.length) return null;
    return { gid: gid, nombre: bibMap[gid]||grp.nombre||('Grupo '+gid.slice(-6)), items: selItems };
  }).filter(Boolean);

  return { fuente:'general', grupos };
}

function renderActItems(){
  const c = document.getElementById('act-items-container');
  if(!actCotizacion || !c) return;

  // Asegurar que _espItems esté cargado para servicios especiales
  _ensureEspItems(actCotizacion);

  const lineas = actCotizacion.lineas||[];
  if(!lineas.length){
    c.innerHTML = '<div style="color:var(--text2);font-size:13px;padding:12px">Esta cotización no tiene líneas de servicio.</div>';
    return;
  }

  // Incluir también claves de items generales por si hay desincronía
  const todasLineas = new Set([...(lineas), ...Object.keys(actCotizacion.items||{})]);

  let html = '';
  let totalItems = 0;

  todasLineas.forEach(function(svc){
    const color = SVC_COLORS[svc]||'var(--accent)';
    const icon  = SVC_ICONS[svc]||'📋';
    const esEspecial = actCotizacion.tarifaTipo?.[svc] === 'especial';
    const { fuente, grupos, sinDatos } = _actGetGruposDeLinea(actCotizacion, svc);

    // Badge de tipo de tarifa
    const badgeEsp = esEspecial
      ? '<span style="background:rgba(245,166,35,0.15);color:var(--gold);border:1px solid rgba(245,166,35,0.4);border-radius:20px;font-size:10px;font-weight:700;padding:2px 8px;letter-spacing:0.5px">⭐ TARIFA ESPECIAL</span>'
      : '<span style="background:rgba(0,194,255,0.1);color:var(--accent);border:1px solid rgba(0,194,255,0.3);border-radius:20px;font-size:10px;font-weight:700;padding:2px 8px;letter-spacing:0.5px">📋 TARIFA GENERAL</span>';

    let gruposHtml = '';

    if(sinDatos){
      gruposHtml = '<div style="background:rgba(255,68,68,0.07);border:1px solid rgba(255,68,68,0.25);border-radius:8px;padding:14px 16px;font-size:13px;color:var(--text2)">'
        +'⚠️ No se pudieron cargar los grupos de esta tarifa especial. '
        +'Verifica que la tarifa especial siga existiendo en la biblioteca.</div>';
    } else {
      grupos.forEach(function(grp){
        if(!grp.items.length) return;

        let rowsHtml = '';
        grp.items.forEach(function(item, ii){
          const keyPrefix = svc + (esEspecial ? '|esp:' : '|') + grp.gid;

          // ── Transporte/Paqueteo: ítems con .campos (múltiples columnas tarifa) ──
          if(item.campos && item.tarifa === undefined){
            var schema = null;
            if(svc === 'Transporte'){
              var bibGrp = (db.biblioteca['Transporte']?.grupos||[]).find(function(bg){ return bg.id === grp.gid; });
              var tipo = (bibGrp && bibGrp.tipo) || grp.tipo || 'local';
              schema = TRANSP_SCHEMA[tipo] || TRANSP_SCHEMA.local;
            } else if(svc === 'Paqueteo' && typeof PAQUETEO_SCHEMA !== 'undefined'){
              var bibGrpP = (db.biblioteca['Paqueteo']?.grupos||[]).find(function(bg){ return bg.id === grp.gid; });
              var tipoP = (bibGrpP && bibGrpP.tipo) || grp.tipo;
              schema = tipoP ? PAQUETEO_SCHEMA[tipoP] : null;
            }
            var colsTarifa = schema
              ? schema.cols.filter(function(c){ return c.tipo==='tarifa'||c.tipo==='tarifa-mixta'||c.tipo==='tarifa-texto'; })
              : [];
            var colTexto = schema ? schema.cols.find(function(c){ return c.tipo==='texto'; }) : null;
            var nombreItem = (colTexto && item.campos[colTexto.id]) ? item.campos[colTexto.id] : ('Fila '+(ii+1));

            // Saltar filas seed/vacías: todos los campos tarifa están en blanco
            var todosVacios = colsTarifa.every(function(col){
              var v = item.campos[col.id];
              return v === '' || v === undefined || v === null || v === '0';
            });
            if(todosVacios && colsTarifa.length) return;

            if(!colsTarifa.length){
              var key0 = keyPrefix+'|'+ii;
              if(!(key0 in actItemsSeleccionados)) actItemsSeleccionados[key0] = true;
              totalItems++;
              rowsHtml += '<tr style="border-bottom:1px solid var(--border)">'
                +'<td style="padding:8px 12px;width:44px"><input type="checkbox"'+(actItemsSeleccionados[key0]?' checked':'')+' style="width:16px;height:16px;cursor:pointer;accent-color:var(--accent)" onchange="actItemsSeleccionados[\''+key0+'\']= this.checked;previewIncremento()"></td>'
                +'<td style="padding:8px 12px;font-size:13px" colspan="3">'+nombreItem+'</td>'
                +'</tr>';
            } else {
              colsTarifa.forEach(function(col){
                var val = item.campos[col.id];
                if(val === '' || val === undefined || val === null) return;
                var tipoCampo = (item.tiposCampo && item.tiposCampo[col.id]) || 'moneda';
                var esPorc2 = tipoCampo === 'porcentaje' || tipoCampo === 'texto';
                var keyCol = keyPrefix+'|'+ii+'|'+col.id;
                if(!(keyCol in actItemsSeleccionados)) actItemsSeleccionados[keyCol] = !esPorc2;
                var checked2 = actItemsSeleccionados[keyCol];
                totalItems++;
                rowsHtml += '<tr style="border-bottom:1px solid var(--border);'+(esPorc2?'opacity:0.55':'')+'">'
                  +'<td style="padding:8px 12px;width:44px"><input type="checkbox"'+(checked2?' checked':'')+' '+(esPorc2?'disabled':'')+' style="width:16px;height:16px;cursor:pointer;accent-color:var(--accent)" onchange="actItemsSeleccionados[\''+keyCol+'\']= this.checked;previewIncremento()"></td>'
                  +'<td style="padding:8px 12px;font-size:13px"><span style=\"color:var(--text2);font-size:11px\">'+nombreItem+' · </span>'+col.nombre+'</td>'
                  +'<td style="padding:8px 12px;font-weight:700;color:var(--gold);font-size:13px">'+String(val)+'</td>'
                  +'<td style="padding:8px 12px;font-size:11px;color:var(--text2)">'+(esPorc2?'No aplica':'')+'</td>'
                  +'</tr>';
              });
            }
            return;
          }

          // ── Ítem estándar con .tarifa directo ──
          // Saltar ítems placeholder sin datos reales
          if((item.nombre === 'Nuevo ítem' || item.nombre === 'Nuevo Item') && (item.tarifa === '0' || item.tarifa === '' || item.tarifa === undefined)) return;
          var tarifa = item.tarifa !== undefined ? item.tarifa : '—';
          var tipoTarifa = item.tipoTarifa || 'moneda';
          const esPorc = tipoTarifa === 'porcentaje';
          const key = keyPrefix+'|'+ii;
          if(!(key in actItemsSeleccionados)) actItemsSeleccionados[key] = !esPorc;
          const checked = actItemsSeleccionados[key];
          const nombre  = item.nombre||'Sin nombre';
          totalItems++;

          rowsHtml += '<tr style="border-bottom:1px solid var(--border);'+(esPorc?'opacity:0.5':'')+'">'
            +'<td style="padding:8px 12px;width:44px">'
            +'<input type="checkbox"'+(checked?' checked':'')+' '+(esPorc?'disabled':'')+' '
            +'style="width:16px;height:16px;cursor:pointer;accent-color:var(--accent)" '
            +'onchange="actItemsSeleccionados[\''+key+'\' ]=this.checked;previewIncremento()">'
            +'</td>'
            +'<td style="padding:8px 12px;font-size:13px">'+nombre+'</td>'
            +'<td style="padding:8px 12px;font-weight:700;color:var(--gold);font-size:13px">'+(tarifa||'—')+'</td>'
            +'<td style="padding:8px 12px;font-size:11px;color:var(--text2)">'+(esPorc?'No aplica (%)':'')+'</td>'
            +'</tr>';
        });

        if(!rowsHtml) return;

        gruposHtml += '<div style="margin-bottom:14px">'
          +'<div style="font-size:12px;font-weight:700;letter-spacing:1px;text-transform:uppercase;'
          +'color:'+color+';padding:8px 12px;background:var(--surface3);border-radius:6px 6px 0 0">'
          +grp.nombre+'</div>'
          +'<table style="width:100%;border-collapse:collapse;background:var(--surface2)">'
          +'<thead><tr>'
          +'<th style="padding:7px 12px;font-size:10px;color:var(--text2);text-align:left;width:44px">✓</th>'
          +'<th style="padding:7px 12px;font-size:10px;color:var(--text2);text-align:left">Ítem</th>'
          +'<th style="padding:7px 12px;font-size:10px;color:var(--text2);text-align:left">Tarifa Actual</th>'
          +'<th style="padding:7px 12px;font-size:10px;color:var(--text2);text-align:left">Nota</th>'
          +'</tr></thead>'
          +'<tbody>'+rowsHtml+'</tbody>'
          +'</table></div>';
      });

      if(!gruposHtml){
        gruposHtml = '<div style="font-size:12px;color:var(--text2);padding:8px 12px;font-style:italic">Sin ítems seleccionados en esta línea.</div>';
      }
    }

    html += '<div style="margin-bottom:24px">'
      +'<div style="display:flex;align-items:center;gap:10px;margin-bottom:10px">'
      +'<span style="font-size:18px">'+icon+'</span>'
      +'<span style="font-family:\'Barlow Condensed\',sans-serif;font-size:17px;font-weight:700;color:'+color+'">'+svc+'</span>'
      +badgeEsp
      +'</div>'
      +gruposHtml
      +'</div>';
  });

  c.innerHTML = html || '<div style="color:var(--text2);font-size:13px;padding:12px">Sin ítems para mostrar.</div>';

  if(totalItems===0){
    c.innerHTML = '<div style="background:rgba(245,166,35,0.08);border:1px solid rgba(245,166,35,0.4);border-radius:10px;padding:24px;text-align:center">'
      +'<div style="font-size:32px;margin-bottom:10px">⚠️</div>'
      +'<div style="font-size:15px;font-weight:700;color:var(--gold);margin-bottom:8px">Esta cotización no tiene ítems con tarifas configuradas</div>'
      +'<div style="font-size:13px;color:var(--text2);max-width:480px;margin:0 auto">Solo puedes actualizar tarifas en cotizaciones que fueron creadas completamente con el wizard de cotizaciones. '
      +'Abre la cotización correspondiente, completa los ítems y guárdala.</div>'
      +'</div>';
  }
}

function parseTarifaNum(val){
  // Returns number from tarifa string like "237.600" or "559.900"
  const clean = String(val).replace(/\./g,'').replace(',','.');
  return parseFloat(clean)||0;
}

function formatTarifaNum(num){
  // Format back to Colombian style: "248.280"
  return Math.round(num).toLocaleString('es-CO');
}

// Redondea una tarifa con incremento a la centena más cercana.
// Ej: 300.580 -> 300.600 (decena >=5 sube)   |   300.445 -> 300.400 (decena <5 baja a 0)
function redondearTarifaIncremento(num){
  return Math.round(num/100)*100;
}

// ── Helper interno: aplica incremento a un ítem y devuelve fila de preview ──
// ── Helper: genera filas de preview para un ítem (soporta .tarifa y .campos) ──
function _actRowsFromItem(svc, grp, item, ii, keyPrefix, pct, esEspecial){
  var rows = [];

  // ── Ítems con .campos (Transporte/Paqueteo tarifa general o especial) ──
  if(item.campos && item.tarifa === undefined){
    var schema = null;
    if(svc === 'Transporte'){
      var bibGrp = (db.biblioteca['Transporte']?.grupos||[]).find(function(bg){ return bg.id === grp.gid; });
      var tipo = (bibGrp && bibGrp.tipo) || grp.tipo || 'local';
      schema = TRANSP_SCHEMA[tipo] || TRANSP_SCHEMA.local;
    } else if(svc === 'Paqueteo' && typeof PAQUETEO_SCHEMA !== 'undefined'){
      var bibGrpP = (db.biblioteca['Paqueteo']?.grupos||[]).find(function(bg){ return bg.id === grp.gid; });
      var tipoP = (bibGrpP && bibGrpP.tipo) || grp.tipo;
      schema = tipoP ? PAQUETEO_SCHEMA[tipoP] : null;
    }
    var colsTarifa = schema
      ? schema.cols.filter(function(c){ return c.tipo==='tarifa'||c.tipo==='tarifa-mixta'||c.tipo==='tarifa-texto'; })
      : Object.keys(item.campos).map(function(k){ return {id:k, nombre:k, tipo:'tarifa'}; });
    var colTexto = schema ? schema.cols.find(function(c){ return c.tipo==='texto'; }) : null;
    var nombreItem = (colTexto && item.campos[colTexto.id]) ? item.campos[colTexto.id] : ('Fila '+(ii+1));

    // Saltar filas seed/vacías (todos los campos tarifa en blanco)
    var allEmptyR = colsTarifa.every(function(col){ var v=item.campos[col.id]; return v===''||v===undefined||v===null||v==='0'; });
    if(allEmptyR && colsTarifa.length) return rows;

    colsTarifa.forEach(function(col){
      var val = item.campos[col.id];
      if(val === '' || val === undefined || val === null) return;
      var tipoCampo = (item.tiposCampo && item.tiposCampo[col.id]) || 'moneda';
      var esPorc = tipoCampo === 'porcentaje' || tipoCampo === 'texto';
      var keyCol = keyPrefix+'|'+ii+'|'+col.id;
      var seleccionado = actItemsSeleccionados[keyCol];
      var tarifaActualNum = parseTarifaNum(String(val));
      var tarifaNuevaNum = seleccionado && !esPorc && pct > 0 ? redondearTarifaIncremento(tarifaActualNum*(1+pct/100)) : tarifaActualNum;
      rows.push({
        key: keyCol, svc,
        grupo: grp.nombre||grp.gid||'—',
        nombre: nombreItem+' · '+col.nombre,
        tipoTarifa: tipoCampo,
        tarifaActual: String(val),
        tarifaNueva: esPorc ? String(val) : formatTarifaNum(tarifaNuevaNum),
        cambio: !!(seleccionado && !esPorc && pct>0),
        pct, esPorc,
        _esCampo: true, _colId: col.id, _itemIdx: ii, _grpGid: grp.gid
      });
    });
    return rows;
  }

  // ── Ítem estándar con .tarifa ──
  var tarifa = item.tarifa !== undefined ? item.tarifa : '';
  var tipoTarifa = item.tipoTarifa || 'moneda';
  var esPorc = tipoTarifa === 'porcentaje';
  var key = keyPrefix+'|'+ii;
  var seleccionado = actItemsSeleccionados[key];
  var tarifaActualNum = parseTarifaNum(tarifa);
  var tarifaNuevaNum = seleccionado && !esPorc && pct > 0 ? redondearTarifaIncremento(tarifaActualNum*(1+pct/100)) : tarifaActualNum;
  rows.push({
    key, svc,
    grupo: grp.nombre||grp.gid||'—',
    nombre: item.nombre||'—',
    tipoTarifa,
    tarifaActual: tarifa,
    tarifaNueva: esPorc ? tarifa : formatTarifaNum(tarifaNuevaNum),
    cambio: !!(seleccionado && !esPorc && pct>0),
    pct, esPorc
  });
  return rows;
}

function previewIncremento(){
  if(!actCotizacion) return;
  const pct     = parseFloat(document.getElementById('act-porcentaje')?.value)||0;
  const preview = document.getElementById('act-preview-container');
  if(!preview) return;

  let rows = [];
  const todasLineas = new Set([...(actCotizacion.lineas||[]), ...Object.keys(actCotizacion.items||{})]);

  todasLineas.forEach(function(svc){
    const { grupos } = _actGetGruposDeLinea(actCotizacion, svc);
    const esEspecial = actCotizacion.tarifaTipo?.[svc] === 'especial';
    grupos.forEach(function(grp){
      var keyPrefix = svc + (esEspecial ? '|esp:' : '|') + grp.gid;
      (grp.items||[]).forEach(function(item, ii){
        _actRowsFromItem(svc, grp, item, ii, keyPrefix, pct, esEspecial).forEach(function(r){ rows.push(r); });
      });
    });
  });

  if(!rows.length){
    preview.innerHTML='<div style="color:var(--text2);font-size:13px">Selecciona una cotización con ítems primero.</div>';
    return;
  }

  // Guardar rows en variable global para que aplicar pueda leer valores editados
  window._actPreviewRows = rows;

  preview.innerHTML = '<table style="width:100%;border-collapse:collapse">'
    +'<thead><tr>'
    +'<th style="padding:9px 12px;background:var(--surface3);font-size:11px;color:var(--text2);text-align:left">Ítem</th>'
    +'<th style="padding:9px 12px;background:var(--surface3);font-size:11px;color:var(--text2);text-align:right">Tarifa Actual</th>'
    +'<th style="padding:9px 12px;background:var(--surface3);font-size:11px;color:var(--text2);text-align:right">Tarifa Nueva ✏️</th>'
    +'<th style="padding:9px 12px;background:var(--surface3);font-size:11px;color:var(--text2);text-align:center">Cambio</th>'
    +'</tr></thead><tbody>'
    + rows.map(function(r, ridx){
        var inputNueva = r.esPorc
          ? '<span style="color:var(--text2);font-size:12px">'+fmtTarifa(r.tarifaNueva,r.tipoTarifa)+'</span>'
          : '<input type="text" id="act-row-'+ridx+'" value="'+r.tarifaNueva+'" '
            +'onchange="window._actPreviewRows['+ridx+'].tarifaNueva=this.value" '
            +'style="width:90px;text-align:right;background:var(--surface2);border:1px solid var(--border);border-radius:5px;color:var(--gold);font-size:13px;font-weight:700;padding:3px 7px;outline:none">';
        return '<tr style="border-bottom:1px solid var(--border)'+(r.esPorc?';opacity:0.55':'')+'">'
          +'<td style="padding:8px 12px;font-size:13px">'+r.nombre+'</td>'
          +'<td style="padding:8px 12px;font-size:13px;text-align:right;color:var(--text2)">'+fmtTarifa(r.tarifaActual,r.tipoTarifa)+'</td>'
          +'<td style="padding:8px 12px;text-align:right">'+inputNueva+'</td>'
          +'<td style="padding:8px 12px;text-align:center;font-size:12px">'
          +(r.esPorc ? '<span style="color:var(--text2);font-size:10px">No aplica</span>'
            : r.cambio ? '<span style="color:var(--green);font-weight:700">+'+r.pct+'%</span>'
            : '<span style="color:var(--text2)">—</span>')
          +'</td></tr>';
      }).join('')
    +'</tbody></table>'
    +'<div style="font-size:11px;color:var(--text2);margin-top:8px;padding:0 4px">💡 Puedes editar cualquier tarifa nueva directamente antes de aplicar.</div>';
}

function aplicarActualizacionTarifas(){
  if(!actCotizacion){ toast('⚠️','Selecciona una cotización primero','#f5a623'); return; }
  const pct = parseFloat(document.getElementById('act-porcentaje')?.value)||0;
  if(pct<=0){ toast('⚠️','Ingresa un porcentaje mayor a 0','#f5a623'); return; }

  // Leer valores editados desde los inputs del preview
  const editedRows = window._actPreviewRows || [];
  editedRows.forEach(function(r, ridx){
    var inp = document.getElementById('act-row-'+ridx);
    if(inp) r.tarifaNueva = inp.value;
    // Redondear: quitar decimales del valor editado
    if(!r.esPorc){
      var n = parseTarifaNum(r.tarifaNueva);
      r.tarifaNueva = formatTarifaNum(Math.round(n));
    }
  });

  const nueva = JSON.parse(JSON.stringify(actCotizacion));
  nueva.id = 'cot'+Date.now();
  nueva.numero = nextCotNumero();
  nueva.fecha = today();
  nueva.estado = 'borrador';
  nueva.createdAt = Date.now(); // sort first in list

  // Construir mapa key → valor editado por el usuario en el preview
  var tarifasEditadasMap = {};
  (window._actPreviewRows||[]).forEach(function(r){
    if(!r.esPorc) tarifasEditadasMap[r.key] = r.tarifaNueva;
  });

  const todasLineas = new Set([...(nueva.lineas||[]), ...Object.keys(nueva.items||{})]);

  todasLineas.forEach(function(svc){
    const esEspecial = nueva.tarifaTipo?.[svc] === 'especial';

    if(esEspecial){
      if(!nueva._espItems) nueva._espItems = {};
      const espGrupos = nueva._espItems[svc];
      if(espGrupos && espGrupos.length){
        espGrupos.forEach(function(grp){
          if(grp.sel === false) return;
          var keyPrefix = svc+'|esp:'+(grp.id||grp.nombre||'g');
          (grp.items||[]).forEach(function(item, ii){
            if(item.sel === false) return;
            if(item.campos && item.tarifa === undefined){
              Object.keys(item.campos).forEach(function(ck){
                var tipoCampo = (item.tiposCampo && item.tiposCampo[ck]) || 'moneda';
                if(tipoCampo === 'porcentaje' || tipoCampo === 'texto') return;
                var keyCol = keyPrefix+'|'+ii+'|'+ck;
                if(!actItemsSeleccionados[keyCol]) return;
                // Usar valor editado si existe, sino calcular
                if(tarifasEditadasMap[keyCol] !== undefined){
                  item.campos[ck] = tarifasEditadasMap[keyCol];
                } else {
                  var val = item.campos[ck];
                  if(val===''||val===null||val===undefined) return;
                  var num = parseTarifaNum(String(val));
                  if(num > 0) item.campos[ck] = formatTarifaNum(Math.round(num*(1+pct/100)));
                }
              });
              return;
            }
            var key = keyPrefix+'|'+ii;
            if(actItemsSeleccionados[key] && item.tipoTarifa !== 'porcentaje' && item.tarifa !== undefined){
              if(tarifasEditadasMap[key] !== undefined){
                item.tarifa = tarifasEditadasMap[key];
              } else {
                var num = parseTarifaNum(item.tarifa);
                item.tarifa = formatTarifaNum(Math.round(num*(1+pct/100)));
              }
            }
          });
        });
      }
    } else {
      const grupos = (nueva.items && nueva.items[svc]) || {};
      Object.keys(grupos).forEach(function(gid){
        const grp = grupos[gid];
        if(!grp || !grp.sel) return;
        (grp.items||[]).filter(function(i){ return i.sel; }).forEach(function(item, ii){
          var keyPrefix = svc+'|'+gid;
          if(item.campos && item.tarifa === undefined){
            Object.keys(item.campos).forEach(function(ck){
              var tipoCampo = (item.tiposCampo && item.tiposCampo[ck]) || 'moneda';
              if(tipoCampo === 'porcentaje' || tipoCampo === 'texto') return;
              var keyCol = keyPrefix+'|'+ii+'|'+ck;
              if(!actItemsSeleccionados[keyCol]) return;
              if(tarifasEditadasMap[keyCol] !== undefined){
                item.campos[ck] = tarifasEditadasMap[keyCol];
              } else {
                var val = item.campos[ck];
                if(val===''||val===null||val===undefined) return;
                var num = parseTarifaNum(String(val));
                if(num > 0) item.campos[ck] = formatTarifaNum(Math.round(num*(1+pct/100)));
              }
            });
            return;
          }
          var key = keyPrefix+'|'+ii;
          if(actItemsSeleccionados[key] && item.tipoTarifa !== 'porcentaje'){
            if(tarifasEditadasMap[key] !== undefined){
              item.tarifa = tarifasEditadasMap[key];
            } else {
              var num = parseTarifaNum(item.tarifa);
              item.tarifa = formatTarifaNum(Math.round(num*(1+pct/100)));
            }
          }
        });
      });
    }
  });

  db.cotizaciones.push(nueva);
  save();
  renderCotizaciones();
  toast('✅',`Nueva cotización ${nueva.numero} creada con +${pct}% en tarifas seleccionadas`,'#00e676');
  setTimeout(()=>showPage('cotizaciones'),1500);
}

