  var hoy = new Date().toISOString().slice(0,10);
  var headers = ['Tipo','Empresa *','NIT','Categoria','Contacto','Cargo','Telefono','Email','Direccion','Ciudad','Comercial *','Servicios de Interes','Estado','Cumpleanos','Recibe Regalo','Observaciones','Fecha'];
  var ejP = ['prospecto','Empresa Ejemplo S.A.S.','900.123.456-7','B','Juan Perez','Gerente Logistico','+57 300 000 0000','juan@empresa.com','Calle 123 # 45-67','Bogota',comNombre,'Zona Franca, Transporte','seguimiento','1990-03-15','si','Primer contacto realizado',hoy];
  var ejC = ['cliente','Distribuidora ABC Ltda.','800.456.789-1','A','Maria Lopez','Directora Operaciones','+57 310 111 2222','maria@abc.com','Av. El Dorado # 90-10','Medellin',comNombre,'CEDI, Aduana','activo','1985-07-22','si','Cliente desde 2022',hoy];
