function normalizeImportKey(str){ return (str||'').toString().toLowerCase().replace(/[^a-z0-9]/gi,''); }

function procesarArchivoImport(file){
  if(!file) return;
  if(typeof XLSX === 'undefined'){ toast('⚠️','Cargando librería, intenta en 2 segundos','#f5a623'); return; }
  var reader = new FileReader();
  reader.onload = function(ev){
    try{
      var wb = XLSX.read(new Uint8Array(ev.target.result), {type:'array'});
      var ws = wb.Sheets[wb.SheetNames[0]];
      var rows = XLSX.utils.sheet_to_json(ws, {defval:''});
      if(!rows.length){ toast('⚠️','El archivo está vacío','#f5a623'); return; }
      _importPreview = rows.map(function(r,i){ return parseImportRow(r, i+2); });
      mostrarPreviewImport();
    }catch(err){ toast('❌','Error al leer el archivo: '+err.message,'#ff4444'); }
  };
  reader.readAsArrayBuffer(file);
}

function parseImportRow(r, rowNum){
  function get(){
    var keys = Array.prototype.slice.call(arguments);
    for(var ki=0;ki<keys.length;ki++){
      var k=keys[ki];
      var cols = Object.keys(r);
      for(var ci=0;ci<cols.length;ci++){
        if(normalizeImportKey(cols[ci]).indexOf(normalizeImportKey(k))>=0) return (r[cols[ci]]||'').toString().trim();
      }
    }
    return '';
  }
  var tipoRaw = get('tipo','type').toLowerCase();
  var tipo = tipoRaw.indexOf('cliente')>=0 ? 'cliente' : 'prospecto';
  var empresa  = get('empresa','company','razon');
  var nit      = get('nit','identificacion','ruc');
  var contacto = get('contacto','contact');
  var cargo    = get('cargo','position','puesto');
  var telefono = get('telefono','tel','phone','celular');
  var email    = get('email','correo','mail');
  var ciudad   = get('ciudad','city');
  var comNom   = get('comercial','asesor','vendedor');
  var svcRaw   = get('servicios','services','interes');
  var estadoRaw= get('estado','status').toLowerCase();
  var categoria  = get('categoria','category','cat').toUpperCase();
  if(!['A','B','C'].includes(categoria)) categoria = '';
  var direccion  = get('direccion','direccion','address','dir');
  var cumpleanos = get('cumpleanos','cumpleaños','birthday','nacimiento');
  var recibeRegalos = get('recibe regalo','reciberegalo','regalo').toLowerCase();
  if(recibeRegalos.includes('si')||recibeRegalos.includes('sí')) recibeRegalos='si';
  else if(recibeRegalos.includes('no')) recibeRegalos='no';
  else recibeRegalos='';
  var obs      = get('observaciones','obs','notas','notes');
  var fecha    = get('fecha','date') || new Date().toISOString().slice(0,10);

  var com = db.comerciales.find(function(c){
    return c.nombre.toLowerCase().indexOf(comNom.toLowerCase())>=0 ||
      (comNom.length>2 && comNom.toLowerCase().indexOf(c.nombre.toLowerCase().split(' ')[0])>=0);
  });

  var servicios = svcRaw.split(/[,;\/]/).map(function(s){ return s.trim(); }).filter(Boolean).map(function(s){
    return SERVICES.find(function(sv){
      return sv.toLowerCase().indexOf(s.toLowerCase())>=0 || s.toLowerCase().indexOf(sv.toLowerCase().split(' ')[0])>=0;
    })||null;
  }).filter(Boolean);

  var estado = tipo==='cliente' ? 'activo' : 'prospecto';
  if(tipo==='cliente'){
    if(estadoRaw.indexOf('riesgo')>=0) estado='en-riesgo';
    else if(estadoRaw.indexOf('inactivo')>=0) estado='inactivo';
  } else {
    if(estadoRaw.indexOf('cerrado')>=0) estado='cerrado';
    else if(estadoRaw.indexOf('perdido')>=0) estado='perdido';
    else if(estadoRaw.indexOf('frio')>=0||estadoRaw.indexOf('frío')>=0) estado='frio';
  }

  var errors = [];
  if(!empresa) errors.push('Empresa vacía');
  if(!com) errors.push('Comercial "'+comNom+'" no encontrado');

  return {rowNum:rowNum,tipo:tipo,empresa:empresa,nit:nit,categoria:categoria,contacto:contacto,cargo:cargo,
    telefono:telefono,email:email,direccion:direccion,ciudad:ciudad,comercialId:com?com.id:'',
    comercialNombre:com?com.nombre:comNom,servicios:servicios,estado:estado,
    cumpleanos:cumpleanos,recibeRegalos:recibeRegalos,obs:obs,fecha:fecha,errors:errors};
}

function mostrarPreviewImport(){
  var section = document.getElementById('import-preview-section');
  var validos   = _importPreview.filter(function(r){ return r.errors.length===0; });
  var invalidos = _importPreview.filter(function(r){ return r.errors.length>0; });
  section.style.display = 'block';
  var btnStyle = validos.length ? 'background:var(--accent);color:#000;border:none;font-weight:700;padding:8px 18px' : 'background:var(--surface2);color:var(--text2);border:none;padding:8px 18px';
  var rows = _importPreview.map(function(r){
    return '<tr style="border-top:1px solid var(--border);background:'+(r.errors.length?'rgba(255,68,68,0.05)':'')+'">'+
      '<td style="padding:7px 10px;color:var(--text2)">'+r.rowNum+'</td>'+
      '<td style="padding:7px 10px">'+(r.errors.length?'<span style="color:#ff4444">✗</span>':'<span style="color:#00e676">✓</span>')+'</td>'+
      '<td style="padding:7px 10px">'+(r.tipo==='cliente'?'🏢':'🎯')+' '+r.tipo+'</td>'+
      '<td style="padding:7px 10px;font-weight:600">'+(r.empresa||'—')+'</td>'+
      '<td style="padding:7px 10px">'+(r.comercialNombre||'—')+'</td>'+
      '<td style="padding:7px 10px">'+(r.servicios.join(', ')||'—')+'</td>'+
      '<td style="padding:7px 10px;color:#ff6b6b;font-size:11px">'+r.errors.join(', ')+'</td>'+
    '</tr>';
  }).join('');
  section.innerHTML =
    '<div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;margin-bottom:14px">'+
      '<div style="display:flex;gap:16px;font-size:13px">'+
        '<span>✅ <strong style="color:#00e676">'+validos.length+'</strong> listos para importar</span>'+
        (invalidos.length ? '<span>⚠️ <strong style="color:#ff4444">'+invalidos.length+'</strong> con errores (se omitirán)</span>' : '')+
      '</div>'+
      '<div style="display:flex;gap:8px">'+
        '<button class="btn btn-secondary btn-sm" onclick="cerrarImportModal()">Cancelar</button>'+
        '<button class="btn btn-sm" style="'+btnStyle+'" '+(validos.length?'':'disabled')+' onclick="ejecutarImportMasivo()">✅ Importar '+validos.length+' registros</button>'+
      '</div>'+
    '</div>'+
    '<div style="max-height:300px;overflow-y:auto;border:1px solid var(--border);border-radius:8px">'+
      '<table style="width:100%;font-size:12px">'+
        '<thead><tr style="background:var(--surface3)">'+
          '<th style="padding:8px 10px;text-align:left">Fila</th>'+
          '<th style="padding:8px 10px;text-align:left">Estado</th>'+
          '<th style="padding:8px 10px;text-align:left">Tipo</th>'+
          '<th style="padding:8px 10px;text-align:left">Empresa</th>'+
          '<th style="padding:8px 10px;text-align:left">Comercial</th>'+
          '<th style="padding:8px 10px;text-align:left">Servicios</th>'+
          '<th style="padding:8px 10px;text-align:left">Error</th>'+
        '</tr></thead>'+
        '<tbody>'+rows+'</tbody>'+
      '</table>'+
    '</div>';
}

function ejecutarImportMasivo(){
  var validos = _importPreview.filter(function(r){ return r.errors.length===0; });
  if(!validos.length) return;
  validos.forEach(function(r){
    var rec = {
      id:'rec'+Date.now()+Math.random().toString(36).slice(2,6),
      tipo:r.tipo, empresa:r.empresa, nit:r.nit, categoria:r.categoria||'',
      ciudad:r.ciudad, comercialId:r.comercialId, comercialNombre:r.comercialNombre,
      servicios:r.servicios, fecha:r.fecha, observaciones:r.obs,
      contactos: r.contacto ? [{
        nombre:r.contacto, cargo:r.cargo, telefono:r.telefono,
        email:r.email, direccion:r.direccion||'',
        cumpleanos:r.cumpleanos||'', recibeRegalos:r.recibeRegalos||'',
        fotosEntrega:[]
      }] : [],
      actividades:[], facturacionLineas:{}
    };
    if(r.tipo==='prospecto'){
      rec.estadoProspecto=r.estado; rec.visita='no'; rec.facturadoP='no';
    } else {
      rec.estadoCliente=r.estado; rec.visitaCliente='no'; rec.nuevoServicio='no'; rec.facturado='no';
    }
    db.records.push(rec);
  });
  save();
  cerrarImportModal();
  renderProspectos(); renderClientes(); renderDashboard();
  toast('✅', validos.length+' registros importados correctamente','#00e676');
  setTimeout(function(){ showPage(_importTipo==='prospecto'?'prospectos':'clientes'); }, 800);
}

// ============================================================
// IMPORTAR COTIZACIÓN DESDE PDF — pdf.js client-side
// ============================================================
let _impExtracted = null;

function abrirImportarPDF(){
  imp_resetear();
  document.getElementById('modal-importar-pdf').style.display = 'flex';
}
function cerrarImportarPDF(){
  document.getElementById('modal-importar-pdf').style.display = 'none';
  // Don't null _impExtracted here — imp_abrirEnWizard needs it
}
function handleImportDrop(e){
  const file = e.dataTransfer.files[0];
  if(file && file.type==='application/pdf') handleImportFile(file);
  else toast('⚠️','Solo se aceptan archivos PDF','#f5a623');
}
function handleImportFile(file){
  if(!file) return;
  document.getElementById('imp-file-name').textContent='📄 '+file.name;
  document.getElementById('imp-dropzone').style.borderColor='var(--purple)';
  imp_showStep('processing');
  const reader = new FileReader();
  reader.onload = e => { imp_extraerTexto(e.target.result.split(',')[1], file.name); };
  reader.readAsDataURL(file);
}

let _impPendingPDF = null, _impPendingName = '', _impLinea = '';

function abrirImportarPDF(){
  imp_resetear();
  document.getElementById('modal-importar-pdf').style.display = 'flex';
}
function cerrarImportarPDF(){
  document.getElementById('modal-importar-pdf').style.display = 'none';
}
function handleImportDrop(e){
  const file = e.dataTransfer.files[0];
  if(file && file.type==='application/pdf') handleImportFile(file);
  else toast('⚠️','Solo se aceptan archivos PDF','#f5a623');
}
function handleImportFile(file){
  if(!file) return;
  _impLinea = document.getElementById('imp-linea-sel')?.value || '';
  if(!_impLinea){ alert('Selecciona primero la línea de negocio'); return; }
  document.getElementById('imp-file-name').textContent = '📄 ' + file.name;
  document.getElementById('imp-dropzone').style.borderColor = 'var(--purple)';
  imp_showStep('processing');
  const reader = new FileReader();
  reader.onload = e => {
    _impPendingPDF = e.target.result.split(',')[1];
    _impPendingName = file.name;
    imp_extraerTexto(_impPendingPDF, file.name);
  };
  reader.readAsDataURL(file);
}

async function imp_extraerTexto(base64PDF, fileName){
  try {
    imp_setStatus('Cargando PDF...');
    const pdfjsLib = window['pdfjs-dist/build/pdf'];
    if(!pdfjsLib) throw new Error('pdf.js no disponible — recarga la página');
    pdfjsLib.GlobalWorkerOptions.workerSrc =
      'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
    const uint8 = Uint8Array.from(atob(base64PDF), ch=>ch.charCodeAt(0));
    const pdf = await pdfjsLib.getDocument({data:uint8}).promise;
    imp_setStatus('Leyendo ' + pdf.numPages + ' página(s)...');

    // Extract with position data to reconstruct rows
    let pages = [];
    for(let p=1; p<=pdf.numPages; p++){
      const page = await pdf.getPage(p);
      const content = await page.getTextContent();
      pages.push(content.items);
    }

    imp_setStatus('Interpretando estructura...');
    const grupos = imp_extraerGrupos(pages, _impLinea);
    const empresa = imp_detectarEmpresa(pages);

    const extracted = {
      empresa, contacto:'', cargo:'', asunto:'', lineas:[_impLinea],
      grupos: grupos.length > 0 ? grupos : [{
        servicio: _impLinea, nombre: _impLinea,
        items:[{nombre:'(Sin datos detectados — agrega manualmente)', tarifa:'', tipoTarifa:'moneda', obs:'', sel:true}]
      }],
      observaciones:''
    };

    imp_mostrarFormulario(extracted);

  } catch(err){
    console.error('Import error:', err);
    imp_showStep('error');
    document.getElementById('imp-error-msg').textContent = err.message || 'No se pudo leer el PDF.';
  }
}

function imp_detectarEmpresa(pages){
  // Look for company name patterns in first page
  const firstPageText = pages[0]||[];
  const lines = imp_agruparLineas(firstPageText);
  for(const line of lines){
    const t = line.text.trim();
    const tl = t.toLowerCase();
    if(tl.includes('para:') || tl.includes('cliente:') || tl.includes('señores:') || tl.includes('empresa:')){
      const after = t.replace(/^(para|cliente|señores|empresa)\s*:\s*/i,'').trim();
      if(after.length > 2) return after.substring(0,80);
    }
  }
  return '';
}

function imp_agruparLineas(items){
  // Group items by Y position into logical lines
  const byY = {};
  items.forEach(item => {
    const y = Math.round(item.transform[5]);
    if(!byY[y]) byY[y] = [];
    byY[y].push({x: item.transform[4], text: item.str});
  });
  return Object.entries(byY)
    .sort((a,b) => parseFloat(b[0]) - parseFloat(a[0])) // top to bottom
    .map(([y, items]) => ({
      y: parseFloat(y),
      text: items.sort((a,b)=>a.x-b.x).map(i=>i.text).join(' ').trim()
    }))
    .filter(l => l.text.length > 0);
}

function imp_extraerGrupos(pages, linea){
  const grupos = [];
  const moneyRe = /\$?\s*([\d]{1,3}(?:[.,]\d{3})*(?:[.,]\d{1,2})?)\s*$/;
  const pctRe = /([\d.,]+)\s*%/;

  pages.forEach(pageItems => {
    const lines = imp_agruparLineas(pageItems);
    let curGrp = null;
    let skipNext = false;

    lines.forEach((line, i) => {
      const t = line.text;
      const tl = t.toLowerCase();

      // Skip header/footer patterns (page numbers, dates, company names at top)
      if(/^\d+$/.test(t.trim())) return; // page numbers
      if(tl.includes('página') || tl.includes('page ')) return;

      // Detect group headers: all caps or ends with : and no money
      const hasMoney = moneyRe.test(t) || /\$[\d.,]+/.test(t);
      const hasPct = pctRe.test(t);
      const isHeader = !hasMoney && !hasPct && t.length > 3 && t.length < 100 &&
        (t === t.toUpperCase() || /^[A-ZÁÉÍÓÚÑ]/.test(t)) &&
        !tl.includes('para:') && !tl.includes('fecha') && !tl.includes('vigencia') &&
        !tl.includes('contacto') && !tl.includes('comercial');

      if(isHeader && (hasMoney === false)){
        // Check next line has money — if so this is a group header
        const nextLine = lines[i+1]?.text || '';
        if(moneyRe.test(nextLine) || pctRe.test(nextLine) || /\$/.test(nextLine) || i===0){
          if(curGrp && curGrp.items.length > 0) grupos.push(curGrp);
          curGrp = {servicio: linea, nombre: t.trim(), items: []};
          return;
        }
      }

      // Extract item: line with money or percentage
      if(hasMoney || hasPct){
        if(!curGrp) curGrp = {servicio: linea, nombre: linea, items: []};

        let nombre = t, tarifa = '', tipoTarifa = 'moneda', obs = '';

        // Extract percentage first
        const pm = t.match(pctRe);
        if(pm){
          tarifa = pm[1].replace(',','.');
          tipoTarifa = 'porcentaje';
          nombre = t.replace(pctRe, '').trim();
        }
        // Extract money value — take the LAST number (usually tarifa is at end)
        if(!tarifa){
          const mm = t.match(/\$?\s*([\d]{1,3}(?:[.,]\d{3})*(?:[.,]\d{1,2})?)\s*$/);
          if(mm){
            tarifa = mm[1].replace(/\./g,'').replace(',','.');
            nombre = t.substring(0, t.lastIndexOf(mm[0])).trim();
          } else {
            // Try any number
            const any = t.match(/\$?\s*([\d.,]{3,})/);
            if(any){
              tarifa = any[1].replace(/\./g,'').replace(',','.');
              nombre = t.replace(any[0],'').replace(/\$/g,'').trim();
            }
          }
        }

        // Clean nombre
        nombre = nombre.replace(/^[\s:\-–]+/, '').replace(/[\s:\-–]+$/, '').trim();
        if(nombre.length < 2) nombre = 'Ítem ' + (curGrp.items.length + 1);

        // Get obs from next non-money line
        const nextL = lines[i+1];
        if(nextL && !moneyRe.test(nextL.text) && !pctRe.test(nextL.text) && nextL.text.length < 150){
          obs = nextL.text.trim();
        }

        curGrp.items.push({nombre, tarifa, tipoTarifa, obs, sel:true});
      }
    });

    if(curGrp && curGrp.items.length > 0) grupos.push(curGrp);
  });

  // Deduplicate items with same nombre
  return grupos.map(g => ({
    ...g,
    items: g.items.filter((it,i,arr) => arr.findIndex(x=>x.nombre===it.nombre)===i)
  })).filter(g => g.items.length > 0);
}

function imp_mostrarFormulario(data){
  window._impExtracted = data;

  const gruposHtml = (data.grupos||[]).map((g,gi) => `
    <div style="background:var(--surface3);border-radius:8px;padding:12px;margin-bottom:8px;border:1px solid var(--border)">
      <div style="display:flex;gap:8px;margin-bottom:8px;align-items:center">
        <input type="text" value="${g.nombre.replace(/"/g,'&quot;')}" placeholder="Nombre del grupo"
          style="flex:1;background:var(--surface2);border:1px solid var(--border);border-radius:6px;color:var(--gold);font-weight:700;padding:6px 10px;font-size:12px;outline:none"
          oninput="window._impExtracted.grupos[${gi}].nombre=this.value">
        <button onclick="imp_eliminarGrupo(${gi})" title="Eliminar grupo"
          style="background:none;border:none;color:var(--red);font-size:18px;cursor:pointer;flex-shrink:0">🗑</button>
      </div>
      <div style="display:grid;grid-template-columns:1fr auto auto auto;gap:4px;font-size:10px;color:var(--text2);font-weight:700;text-transform:uppercase;padding:0 2px;margin-bottom:4px">
        <span>Servicio / Ítem</span><span>Tarifa</span><span>Tipo</span><span></span>
      </div>
      ${(g.items||[]).map((it,ii) => `
        <div style="display:grid;grid-template-columns:1fr 80px 42px 24px;gap:4px;margin-bottom:3px;align-items:center">
          <input type="text" value="${it.nombre.replace(/"/g,'&quot;')}" placeholder="Ítem"
            style="background:var(--surface2);border:1px solid var(--border);border-radius:5px;color:var(--text);padding:5px 7px;font-size:12px;outline:none"
            oninput="window._impExtracted.grupos[${gi}].items[${ii}].nombre=this.value">
          <input type="text" value="${it.tarifa}" placeholder="0"
            style="background:var(--surface2);border:1px solid var(--border);border-radius:5px;color:var(--gold);padding:5px 6px;font-size:12px;font-weight:700;outline:none;text-align:right"
            oninput="window._impExtracted.grupos[${gi}].items[${ii}].tarifa=this.value">
          <select onchange="window._impExtracted.grupos[${gi}].items[${ii}].tipoTarifa=this.value"
            style="background:var(--surface2);border:1px solid var(--border);border-radius:5px;color:var(--text2);padding:4px 2px;font-size:11px;outline:none">
            <option value="moneda"${it.tipoTarifa==='moneda'?' selected':''}>$</option>
            <option value="porcentaje"${it.tipoTarifa==='porcentaje'?' selected':''}>%</option>
          </select>
          <button onclick="imp_eliminarItem(${gi},${ii})"
            style="background:none;border:none;color:var(--red);font-size:13px;cursor:pointer;padding:0">✕</button>
        </div>`).join('')}
      <button onclick="imp_agregarItem(${gi})"
        style="margin-top:6px;background:none;border:1px dashed var(--border);border-radius:5px;color:var(--text2);font-size:11px;padding:3px 10px;cursor:pointer;width:100%">+ Ítem</button>
    </div>`).join('');

  document.getElementById('imp-preview-content').innerHTML = `
    <div style="display:flex;gap:8px;margin-bottom:10px">
      <input type="text" id="imp-empresa-input" value="${data.empresa.replace(/"/g,'&quot;')}" placeholder="Empresa cliente"
        style="flex:1;background:var(--surface2);border:1px solid var(--border);border-radius:6px;color:var(--text);padding:7px 10px;font-size:13px;outline:none"
        oninput="window._impExtracted.empresa=this.value">
    </div>
    <div style="font-size:11px;color:var(--text2);margin-bottom:8px">
      Línea: <strong style="color:var(--accent)">${_impLinea}</strong> · Revisa y ajusta los datos extraídos:
    </div>
    <div id="imp-grupos-container">${gruposHtml}</div>
    <button onclick="imp_agregarGrupo()"
      style="margin-top:8px;background:none;border:1px dashed var(--border);border-radius:6px;color:var(--accent);font-size:12px;padding:6px 14px;cursor:pointer;width:100%">
      + Agregar grupo
    </button>`;

  imp_showStep('preview');
}

function imp_eliminarGrupo(gi){
  window._impExtracted.grupos.splice(gi,1);
  imp_mostrarFormulario(window._impExtracted);
}
function imp_eliminarItem(gi,ii){
  window._impExtracted.grupos[gi].items.splice(ii,1);
  imp_mostrarFormulario(window._impExtracted);
}
function imp_agregarItem(gi){
  window._impExtracted.grupos[gi].items.push({nombre:'',tarifa:'',tipoTarifa:'moneda',obs:'',sel:true});
  imp_mostrarFormulario(window._impExtracted);
}
function imp_agregarGrupo(){
  window._impExtracted.grupos.push({servicio:_impLinea,nombre:'Nuevo grupo',items:[{nombre:'',tarifa:'',tipoTarifa:'moneda',obs:'',sel:true}]});
  imp_mostrarFormulario(window._impExtracted);
}

function imp_abrirEnWizard(){
  const data = window._impExtracted;
  if(!data || !data.grupos) return;

  // Update empresa from input field
  const empEl = document.getElementById('imp-empresa-input');
  if(empEl) data.empresa = empEl.value.trim();

  cerrarImportarPDF();
  initBiblioteca();

  // Clean any leftover imported groups
  SERVICES.forEach(svc=>{
    if(db.biblioteca[svc]) db.biblioteca[svc].grupos = (db.biblioteca[svc].grupos||[]).filter(g=>!g._imported);
  });

  const defVig = new Date(); defVig.setDate(defVig.getDate()+30);
  cotWizard = {
    id:null, step:1,
    empresa:data.empresa||'', nit:'',
    contacto:data.contacto||'', cargo:data.cargo||'',
    email:'', telefono:'',
    comercialId:'', fecha:today(),
    vigencia:defVig.toISOString().slice(0,10),
    estado:'borrador', asunto:data.asunto||'',
    lineas:[_impLinea], paqueteadora:'',
    tarifaTipo:{}, tarifaEspecialId:{},
    items:{}, obsPlantillas:{},
    obsLibre:data.observaciones||'',
    _espEdit:{}, _espItems:{}, _espEditId:{}
  };

  // Build groups for the selected line
  const grupos = (data.grupos||[]).map(g=>({
    id: 'impg'+Date.now()+Math.random().toString(36).slice(2),
    nombre: g.nombre||'Grupo importado',
    tipo:'', sel:true,
    items: (g.items||[]).map((it,ii)=>({
      id:'impi'+Date.now()+ii,
      nombre:it.nombre||'',
      tarifa:it.tarifa||'',
      tipoTarifa:it.tipoTarifa||'moneda',
      obs:it.obs||'',
      sel:true
    }))
  }));

  const svc = _impLinea;
  cotWizard.items[svc] = {};
  cotWizard.tarifaTipo[svc] = 'especial';
  cotWizard.tarifaEspecialId[svc] = 'nueva';
  cotWizard._espEdit[svc] = grupos;

  // Inject into biblioteca temporarily so paso 3 renders them
  if(!db.biblioteca[svc]) db.biblioteca[svc] = {grupos:[],observaciones:[],columnas:[],colHeaders:{}};
  grupos.forEach(g => db.biblioteca[svc].grupos.push({...g, _imported:true}));

  // Setup wizard fields
  const fechaEl = document.getElementById('cot-fecha');
  const vigEl = document.getElementById('cot-vigencia');
  if(fechaEl) fechaEl.value = today();
  if(vigEl) vigEl.value = defVig.toISOString().slice(0,10);

  const comSel = document.getElementById('cot-comercial');
  if(comSel) comSel.innerHTML = '<option value="">— Seleccionar —</option>' +
    db.comerciales.map(c=>`<option value="${c.id}">${c.nombre}</option>`).join('');

  const empSel = document.getElementById('cot-empresa-sel');
  if(empSel) empSel.innerHTML = '<option value="">— Empresa nueva / manual —</option>' +
    [...new Map(db.records.map(r=>[r.empresa,r])).values()]
      .map(r=>`<option value="${r.empresa}|${r.nit||''}">${r.empresa}</option>`).join('');

  const csg = document.getElementById('cot-contacto-sel-group');
  if(csg) csg.style.display = 'none';

  document.getElementById('nueva-cot-titulo').innerHTML = '📂 <span>Cotización importada — '+svc+'</span>';
  buildStepBar();
  showPage('nueva-cot');
  cotStep(1);

  setTimeout(()=>{
    const e = document.getElementById('cot-empresa');
    if(e && data.empresa){ e.value=data.empresa; e.dispatchEvent(new Event('input')); }
  }, 200);

  toast('✅','PDF importado como '+svc+' — completa los datos del cliente','#a855f7');
}

function imp_setStatus(msg){const e=document.getElementById('imp-status-msg');if(e)e.textContent=msg;}
function imp_showStep(step){
  ['upload','processing','preview','error'].forEach(s=>{
    const e=document.getElementById('imp-step-'+s);
    if(e)e.style.display=s===step?'block':'none';
  });
}
function imp_resetear(){
  window._impExtracted=null; _impLinea='';
  const fi=document.getElementById('imp-file-input');if(fi)fi.value='';
  const fn=document.getElementById('imp-file-name');if(fn)fn.textContent='';
  const dz=document.getElementById('imp-dropzone');if(dz)dz.style.borderColor='var(--border)';
  imp_showStep('upload');
}


function imp_mapSvc(raw){
  if(!raw) return 'Zona Franca';
  const r=raw.toLowerCase();
  if(r.includes('zona')) return 'Zona Franca';
  if(r.includes('dep')&&(r.includes('aduan')||r.includes('ósito'))) return 'Depósito Aduanero';
  if(r.includes('cedi')||r.includes('distribu')) return 'CEDI';
  if(r.includes('transport')) return 'Transporte';
  if(r.includes('paquet')) return 'Paqueteo';
  if(r.includes('aduan')||r.includes('arancel')) return 'Aduana';
  if(SERVICES.includes(raw)) return raw;
  return 'Zona Franca';
}
function imp_setStatus(msg){const e=document.getElementById('imp-status-msg');if(e)e.textContent=msg;}
function imp_showStep(step){['upload','processing','preview','error'].forEach(s=>{const e=document.getElementById('imp-step-'+s);if(e)e.style.display=s===step?'block':'none';});}
function imp_resetear(){
  _impExtracted = null;
  const fi=document.getElementById('imp-file-input');if(fi)fi.value='';
  document.getElementById('imp-file-name').textContent='';
  document.getElementById('imp-dropzone').style.borderColor='var(--border)';
  imp_showStep('upload');
}



function sacInitMes(){
  const sel = document.getElementById('sac-mes-sel');
  if(sel && sel.value === '0' && new Date().getMonth() !== 0){
    sel.value = new Date().getMonth();
  }
}

// ============================================================
// SAC — SERVICIO AL CLIENTE
// ============================================================
let _sacRecordId = null, _sacContactoIdx = null;

const SAC_MESES = ['Enero','Febrero','Marzo','Abril','Mayo','Junio',
                   'Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];

function renderSAC(){
  const mes = parseInt(document.getElementById('sac-mes-sel')?.value ?? new Date().getMonth());
  sacRenderStats(mes);
  sacRenderCumpleanos(mes);
  renderFinDeAno();
}

function sacRenderStats(mes){
  const el = document.getElementById('sac-stats');
  if(!el) return;

  // Total contacts with birthday
  const totalConBd = sacGetAllContactosBd().length;
  const delMes = sacGetContactosMes(mes).length;

  // Entregas registradas (fotos) — solo contactos con cumpleaños ESTE mes
  let entregasMes = 0, entregasTotal = 0;
  const contactosMes = sacGetContactosMes(mes);
  db.records.forEach(r => {
    (r.contactos||[]).forEach(ct => {
      entregasTotal += (ct.fotosEntrega||[]).length;
    });
  });
  // Count deliveries for this month's birthday contacts
  contactosMes.forEach(({ct}) => {
    if((ct.fotosEntrega||[]).length > 0) entregasMes++;
  });

  const pendientes = delMes - entregasMes;

  const stats = [
    { icon:'🎂', label:'Cumpleaños este mes', val:delMes, color:'var(--gold)' },
    { icon:'📸', label:'Entregas registradas', val:entregasMes, color:'var(--green)' },
    { icon:'⏳', label:'Pendientes de entrega', val:Math.max(0,pendientes), color:'var(--red)' },
    { icon:'👥', label:'Contactos con cumpleaños', val:totalConBd, color:'var(--accent)' },
    { icon:'🎁', label:'Total entregas históricas', val:entregasTotal, color:'var(--purple)' },
  ];

  el.innerHTML = stats.map(s=>`
    <div style="background:var(--surface2);border:1px solid var(--border);border-radius:12px;padding:16px 18px">
      <div style="font-size:24px;margin-bottom:6px">${s.icon}</div>
      <div style="font-family:'Barlow Condensed',sans-serif;font-size:28px;font-weight:800;color:${s.color}">${s.val}</div>
      <div style="font-size:12px;color:var(--text2)">${s.label}</div>
    </div>`).join('');
}

function sacGetAllContactosBd(){
  const result = [];
  db.records.forEach(r => {
    (r.contactos||[]).forEach((ct,idx) => {
      if(ct.cumpleanos) result.push({r, ct, idx});
    });
  });
  return result;
}

function sacGetContactosMes(mes){
  return sacGetAllContactosBd().filter(({ct}) => {
    if(!ct.cumpleanos) return false;
    try {
      const d = new Date(ct.cumpleanos + 'T12:00');
      return d.getMonth() === mes;
    } catch(e){ return false; }
  });
}

function sacRenderCumpleanos(mes){
  const el = document.getElementById('sac-cumple-lista');
  if(!el) return;

  const contactos = sacGetContactosMes(mes);

  if(!contactos.length){
    el.innerHTML = `<div style="text-align:center;padding:40px;color:var(--text2);font-size:14px">
      😊 No hay cumpleaños registrados en ${SAC_MESES[mes]}.<br>
      <small style="font-size:12px">Agrega fechas de cumpleaños en los registros de clientes.</small>
    </div>`;
    return;
  }

  // Sort by day of month
  contactos.sort((a,b) => {
    try{
      return new Date(a.ct.cumpleanos+'T12:00').getDate() - new Date(b.ct.cumpleanos+'T12:00').getDate();
    }catch(e){return 0;}
  });

  el.innerHTML = contactos.map(({r, ct, idx}) => {
    const fecha = (() => {
      try{
        const d = new Date(ct.cumpleanos+'T12:00');
        return d.getDate() + ' de ' + SAC_MESES[d.getMonth()];
      }catch(e){return ct.cumpleanos;}
    })();

    const fotos = ct.fotosEntrega||[];
    const entregado = fotos.length > 0;
    const com = db.comerciales.find(x=>x.id===r.comercialId);

    const fotosHtml = fotos.slice(0,3).map(f=>
      `<img src="${f.data}" style="width:40px;height:40px;object-fit:cover;border-radius:6px;border:2px solid var(--border)">`
    ).join('');

    return `
    <div style="display:flex;align-items:center;gap:14px;padding:14px 16px;background:var(--surface2);border-radius:12px;margin-bottom:8px;border:1px solid ${entregado?'var(--green)':'var(--border)'};flex-wrap:wrap">
      <!-- Fecha -->
      <div style="min-width:52px;text-align:center;background:${entregado?'rgba(0,230,118,0.1)':'var(--surface3)'};border-radius:8px;padding:8px;border:1px solid ${entregado?'var(--green)':'var(--border)'}">
        <div style="font-family:'Barlow Condensed',sans-serif;font-size:22px;font-weight:800;color:${entregado?'var(--green)':'var(--gold)'}">
          ${(() => { try{ return new Date(ct.cumpleanos+'T12:00').getDate(); }catch(e){return '?';} })()}
        </div>
        <div style="font-size:9px;color:var(--text2);text-transform:uppercase;letter-spacing:0.5px">${SAC_MESES[mes].substring(0,3)}</div>
      </div>

      <!-- Info -->
      <div style="flex:1;min-width:200px">
        <div style="font-size:14px;font-weight:700;color:var(--text)">${ct.nombre||'Sin nombre'}</div>
        <div style="font-size:12px;color:var(--text2)">${ct.cargo||'—'} · <span style="color:var(--accent)">${r.empresa}</span> ${r.categoria?categoriaBadge(r.categoria):''}</div>
        <div style="font-size:11px;color:var(--text2);margin-top:2px">
          ${ct.telefono ? '📱 '+ct.telefono : ''}
          ${ct.email ? ' · ✉️ '+ct.email : ''}
        </div>
        ${com ? `<div style="font-size:11px;color:var(--text2);margin-top:2px">👤 Comercial: ${com.nombre}</div>` : ''}
        ${ct.recibeRegalos==='si' ? '<div style="font-size:11px;color:var(--gold);margin-top:2px">🎁 Recibe regalo</div>' : ''}
      </div>

      <!-- Fotos -->
      ${fotos.length ? `<div style="display:flex;gap:4px;align-items:center">${fotosHtml}${fotos.length>3?`<span style="font-size:11px;color:var(--text2)">+${fotos.length-3}</span>`:''}</div>` : ''}

      <!-- Estado entrega -->
      <div style="display:flex;flex-direction:column;gap:6px;align-items:flex-end">
        <span style="font-size:11px;font-weight:700;padding:3px 8px;border-radius:6px;background:${entregado?'rgba(0,230,118,0.15)':'rgba(245,166,35,0.15)'};color:${entregado?'var(--green)':'var(--gold)'}">
          ${entregado ? '✅ Entregado' : '⏳ Pendiente'}
        </span>
        <button onclick="sacAbrirModal('${r.id}',${idx})"
          style="background:var(--surface3);border:1px solid var(--border);border-radius:8px;color:var(--text);font-size:12px;padding:5px 12px;cursor:pointer">
          ✏️ Ver / Editar
        </button>
      </div>
    </div>`;
  }).join('');
}

function sacAbrirModal(recordId, contactoIdx){
  const r = db.records.find(x=>x.id===recordId);
  if(!r) return;
  const ct = r.contactos?.[contactoIdx];
  if(!ct) return;

  _sacRecordId = recordId;
  _sacContactoIdx = contactoIdx;
  _sacModo = 'cumple';

  // Fill read-only info
  document.getElementById('sac-modal-nombre').textContent = ct.nombre||'Contacto';
  document.getElementById('sac-info-empresa').textContent = r.empresa||'—';
  document.getElementById('sac-info-tipo').textContent = r.tipo==='cliente'?'🏢 Cliente':'🎯 Prospecto';
  const com = db.comerciales.find(x=>x.id===r.comercialId);
  document.getElementById('sac-info-comercial').textContent = com?.nombre||'—';
  document.getElementById('sac-info-cumple').textContent = (() => {
    try{
      const d = new Date(ct.cumpleanos+'T12:00');
      return d.getDate()+' de '+SAC_MESES[d.getMonth()];
    }catch(e){return ct.cumpleanos||'—';}
  })();

  // Fill editable fields
  document.getElementById('sac-edit-cargo').value = ct.cargo||'';
  document.getElementById('sac-edit-telefono').value = ct.telefono||'';
  document.getElementById('sac-edit-email').value = ct.email||'';
  document.getElementById('sac-edit-direccion').value = ct.direccion||'';

  // Show existing photos
  sacRenderFotosModal(ct);

  document.getElementById('sac-modal').style.display = 'flex';
}

function sacRenderFotosModal(ct){
  const fotos = ct.fotosEntrega||[];
  const grid = document.getElementById('sac-fotos-grid');
  if(!grid) return;
  grid.innerHTML = fotos.map((f,fi)=>`
    <div style="position:relative">
      <img src="${f.data}" style="width:70px;height:70px;object-fit:cover;border-radius:8px;border:2px solid var(--border)">
      <div style="position:absolute;bottom:2px;left:0;right:0;text-align:center;font-size:9px;color:var(--text2);background:rgba(0,0,0,0.5);border-radius:0 0 6px 6px;padding:1px">
        ${f.fecha ? new Date(f.fecha).toLocaleDateString('es-CO') : ''}
      </div>
      <button onclick="sacEliminarFoto(${fi})"
        style="position:absolute;top:-4px;right:-4px;background:var(--red);border:none;border-radius:50%;width:18px;height:18px;color:#fff;font-size:11px;cursor:pointer;display:flex;align-items:center;justify-content:center;line-height:1">✕</button>
    </div>`).join('');
}

function sacSubirFoto(input){
  if(_sacModo === 'fda'){ fdaSubirFoto(input); return; }
  const r = db.records.find(x=>x.id===_sacRecordId);
  if(!r || _sacContactoIdx===null) return;
  const ct = r.contactos[_sacContactoIdx];
  if(!ct.fotosEntrega) ct.fotosEntrega = [];

  const files = Array.from(input.files);
  let loaded = 0;
  files.forEach(file => {
    const reader = new FileReader();
    reader.onload = e => {
      ct.fotosEntrega.push({ data: e.target.result, fecha: new Date().toISOString() });
      loaded++;
      if(loaded===files.length){
        save();
        sacRenderFotosModal(ct);
      }
    };
    reader.readAsDataURL(file);
  });
  input.value = '';
}

function sacEliminarFoto(fi){
  if(!confirm('¿Eliminar esta foto?')) return;
  const r = db.records.find(x=>x.id===_sacRecordId);
  if(!r || _sacContactoIdx===null) return;
  const ct = r.contactos[_sacContactoIdx];
  if(ct.fotosEntrega) ct.fotosEntrega.splice(fi,1);
  save();
  sacRenderFotosModal(ct);
}

function sacGuardarContacto(){
  const r = db.records.find(x=>x.id===_sacRecordId);
  if(!r || _sacContactoIdx===null) return;
  const ct = r.contactos[_sacContactoIdx];

  ct.cargo     = document.getElementById('sac-edit-cargo').value.trim();
  ct.telefono  = document.getElementById('sac-edit-telefono').value.trim();
  ct.email     = document.getElementById('sac-edit-email').value.trim();
  ct.direccion = document.getElementById('sac-edit-direccion').value.trim();

  save();
  sacCerrarModal();
  renderSAC();
  toast('✅', 'Contacto actualizado correctamente', '#00e676');
}

// Fix sacSubirFoto to respect _sacModo
const _sacSubirFotoOriginal = sacSubirFoto;

function sacCerrarModal(){
  document.getElementById('sac-modal').style.display = 'none';
  _sacRecordId = null;
  _sacContactoIdx = null;
}

function sacDescargarReporte(){
  const XLSX = window.XLSX;
  if(!XLSX){ toast('⚠️','SheetJS no disponible','#f5a623'); return; }

  const mes = parseInt(document.getElementById('sac-mes-sel')?.value ?? new Date().getMonth());
  const nombreMes = SAC_MESES[mes];
  const contactos = sacGetContactosMes(mes);

  if(!contactos.length){
    toast('⚠️','No hay cumpleaños en '+nombreMes,'#f5a623');
    return;
  }

  const rows = contactos.map(({r, ct}) => {
    const cumple = (() => {
      try{
        const d = new Date(ct.cumpleanos+'T12:00');
        return d.getDate()+'/'+String(d.getMonth()+1).padStart(2,'0');
      }catch(e){ return ct.cumpleanos||''; }
    })();
    const com = db.comerciales.find(x=>x.id===r.comercialId);
    return {
      'Empresa':              r.empresa||'',
      'Categoría':            r.categoria||'Sin categoría',
      'Persona de Contacto':  ct.nombre||'',
      'Cargo':                ct.cargo||'',
      'Correo Electrónico':   ct.email||'',
      'Celular':              ct.telefono||'',
      'Dirección':            ct.direccion||'',
      'Fecha Cumpleaños':     cumple,
      'Recibe Regalo':        ct.recibeRegalos==='si'?'Sí':ct.recibeRegalos==='no'?'No':'Sin definir',
      'Entrega Registrada':   (ct.fotosEntrega||[]).length>0?'✅ Entregado':'⏳ Pendiente',
      'Comercial':            com?.nombre||'—',
    };
  });

  const ws = XLSX.utils.json_to_sheet([]);
  XLSX.utils.sheet_add_aoa(ws, [
    ['REPORTE SAC — CUMPLEAÑOS ' + nombreMes.toUpperCase() + ' — GRUPO ZYMO'],
    ['Generado: ' + new Date().toLocaleDateString('es-CO',{day:'2-digit',month:'long',year:'numeric'})],
    []
  ], {origin:'A1'});
  XLSX.utils.sheet_add_json(ws, rows, {origin:'A4'});
  ws['!cols'] = [
    {wch:35},{wch:12},{wch:28},{wch:22},{wch:32},
    {wch:18},{wch:35},{wch:16},{wch:15},{wch:20},{wch:22}
  ];

  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Cumpleaños '+nombreMes);
  const fileName = 'SAC_Cumpleanos_'+nombreMes+'_ZYMO.xlsx';
  XLSX.writeFile(wb, fileName);
  toast('✅','Reporte descargado: '+fileName,'#00e676');
}




// ============================================================
// FIN DE AÑO — Control de Detalles
// ============================================================

function renderFinDeAno(){
  fdaRenderStats();
  fdaRenderLista();
}

function fdaRenderStats(){
  const el = document.getElementById('fda-stats');
  if(!el) return;
  const all = fdaGetAllContactos();
  const seleccionados = all.filter(({r,ct}) => fdaEstaSeleccionado(r.id, ct._idx));
  const entregados = all.filter(({r,ct}) => (ct.fotasFda||[]).length > 0 || ct.fdaEntregado);

  el.innerHTML = [
    {icon:'👥', label:'Total contactos', val:all.length, color:'var(--accent)'},
    {icon:'✅', label:'Seleccionados', val:seleccionados.length, color:'var(--gold)'},
    {icon:'🎁', label:'Entregas realizadas', val:entregados.length, color:'var(--green)'},
    {icon:'⏳', label:'Pendientes', val:Math.max(0,seleccionados.length-entregados.length), color:'var(--red)'},
  ].map(s=>`
    <div style="background:var(--surface2);border:1px solid var(--border);border-radius:10px;padding:14px 16px">
      <div style="font-size:22px;margin-bottom:4px">${s.icon}</div>
      <div style="font-family:'Barlow Condensed',sans-serif;font-size:26px;font-weight:800;color:${s.color}">${s.val}</div>
      <div style="font-size:11px;color:var(--text2)">${s.label}</div>
    </div>`).join('');
}

function fdaGetAllContactos(){
  const result = [];
  db.records.forEach(r => {
    (r.contactos||[]).forEach((ct,idx) => {
      result.push({r, ct:{...ct, _idx:idx}, idx});
    });
  });
  return result;
}

function fdaEstaSeleccionado(recordId, ctIdx){
  if(!db.fdaSeleccionados) db.fdaSeleccionados = {};
  return !!(db.fdaSeleccionados[recordId+'_'+ctIdx]);
}

function fdaToggleSeleccion(recordId, ctIdx){
  if(!db.fdaSeleccionados) db.fdaSeleccionados = {};
  const key = recordId+'_'+ctIdx;
  db.fdaSeleccionados[key] = !db.fdaSeleccionados[key];
  save();
  renderFinDeAno();
}

function fdaRenderLista(){
  const el = document.getElementById('fda-lista');
  if(!el) return;
  const search = document.getElementById('fda-search')?.value.toLowerCase()||'';
  const catFil = document.getElementById('fda-filter-cat')?.value||'';

  let contactos = fdaGetAllContactos();

  if(search) contactos = contactos.filter(({r,ct}) =>
    r.empresa.toLowerCase().includes(search) ||
    (ct.nombre||'').toLowerCase().includes(search));
  if(catFil) contactos = contactos.filter(({r}) => r.categoria === catFil);

  if(!contactos.length){
    el.innerHTML = '<div style="text-align:center;padding:30px;color:var(--text2)">No se encontraron contactos.</div>';
    return;
  }

  el.innerHTML = contactos.map(({r, ct}) => {
    const sel = fdaEstaSeleccionado(r.id, ct._idx);
    const fotos = ct.fotasFda||[];
    const entregado = ct.fdaEntregado || fotos.length > 0;
    const com = db.comerciales.find(x=>x.id===r.comercialId);

    return `
    <div style="display:flex;align-items:center;gap:12px;padding:12px 14px;background:var(--surface2);border-radius:10px;margin-bottom:6px;border:1px solid ${sel?'var(--gold)':entregado?'var(--green)':'var(--border)'};flex-wrap:wrap">
      <!-- Checkbox selección -->
      <input type="checkbox" ${sel?'checked':''} style="width:18px;height:18px;accent-color:var(--gold);flex-shrink:0;cursor:pointer"
        onchange="fdaToggleSeleccion('${r.id}',${ct._idx})" title="Seleccionar para detalle">

      <!-- Info -->
      <div style="flex:1;min-width:180px">
        <div style="font-size:13px;font-weight:700;color:var(--text)">${ct.nombre||'Sin nombre'}</div>
        <div style="font-size:12px;color:var(--text2)">${ct.cargo||'—'} · <span style="color:var(--accent)">${r.empresa}</span> ${r.categoria?categoriaBadge(r.categoria):''}</div>
        <div style="font-size:11px;color:var(--text2);">${ct.telefono?'📱 '+ct.telefono:''} ${ct.email?'· ✉️ '+ct.email:''}</div>
        ${com?`<div style="font-size:11px;color:var(--text2)">👤 ${com.nombre}</div>`:''}
      </div>

      <!-- Fotos entrega -->
      ${fotos.length?`<div style="display:flex;gap:4px">${fotos.slice(0,2).map(f=>`<img src="${f.data}" style="width:36px;height:36px;object-fit:cover;border-radius:6px;border:1px solid var(--border)">`).join('')}${fotos.length>2?`<span style="font-size:10px;color:var(--text2);align-self:center">+${fotos.length-2}</span>`:''}</div>`:''}

      <!-- Estado -->
      <div style="display:flex;flex-direction:column;gap:4px;align-items:flex-end;flex-shrink:0">
        <span style="font-size:11px;font-weight:700;padding:2px 8px;border-radius:5px;background:${entregado?'rgba(0,230,118,0.15)':sel?'rgba(245,166,35,0.15)':'var(--surface3)'};color:${entregado?'var(--green)':sel?'var(--gold)':'var(--text2)'}">
          ${entregado?'✅ Entregado':sel?'🎁 Seleccionado':'—'}
        </span>
        <button onclick="sacAbrirModalFda('${r.id}',${ct._idx})"
          style="background:var(--surface3);border:1px solid var(--border);border-radius:6px;color:var(--text);font-size:11px;padding:4px 10px;cursor:pointer">
          📸 Registrar entrega
        </button>
      </div>
    </div>`;
  }).join('');
}

function sacAbrirModalFda(recordId, ctIdx){
  // Reuse the SAC modal but for FDA
  const r = db.records.find(x=>x.id===recordId);
  if(!r) return;
  const ct = r.contactos?.[ctIdx];
  if(!ct) return;

  _sacRecordId = recordId;
  _sacContactoIdx = ctIdx;
  _sacModo = 'fda';

  document.getElementById('sac-modal-nombre').textContent = ct.nombre||'Contacto';
  document.getElementById('sac-info-empresa').textContent = r.empresa||'—';
  document.getElementById('sac-info-tipo').textContent = r.categoria ? ('Categoría '+r.categoria) : (r.tipo==='cliente'?'🏢 Cliente':'🎯 Prospecto');
  const com = db.comerciales.find(x=>x.id===r.comercialId);
  document.getElementById('sac-info-comercial').textContent = com?.nombre||'—';
  document.getElementById('sac-info-cumple').textContent = '🎄 Detalle Fin de Año';
  document.getElementById('sac-edit-cargo').value = ct.cargo||'';
  document.getElementById('sac-edit-telefono').value = ct.telefono||'';
  document.getElementById('sac-edit-email').value = ct.email||'';
  document.getElementById('sac-edit-direccion').value = ct.direccion||'';

  // Show FDA photos
  const fotos = ct.fotasFda||[];
  const grid = document.getElementById('sac-fotos-grid');
  if(grid) grid.innerHTML = fotos.map((f,fi)=>`
    <div style="position:relative">
      <img src="${f.data}" style="width:70px;height:70px;object-fit:cover;border-radius:8px;border:2px solid var(--border)">
      <button onclick="fdaEliminarFoto(${fi})"
        style="position:absolute;top:-4px;right:-4px;background:var(--red);border:none;border-radius:50%;width:18px;height:18px;color:#fff;font-size:11px;cursor:pointer">✕</button>
    </div>`).join('');

  document.getElementById('sac-foto-input').onchange = function(){ fdaSubirFoto(this); };
  document.getElementById('sac-modal').style.display = 'flex';
}

let _sacModo = 'cumple'; // 'cumple' or 'fda'

function fdaSubirFoto(input){
  const r = db.records.find(x=>x.id===_sacRecordId);
  if(!r || _sacContactoIdx===null) return;
  const ct = r.contactos[_sacContactoIdx];
  if(!ct.fotasFda) ct.fotasFda = [];
  const files = Array.from(input.files);
  let loaded = 0;
  files.forEach(file => {
    const reader = new FileReader();
    reader.onload = e => {
      ct.fotasFda.push({data:e.target.result, fecha:new Date().toISOString()});
      ct.fdaEntregado = true;
      loaded++;
      if(loaded===files.length){
        save();
        sacAbrirModalFda(_sacRecordId, _sacContactoIdx);
      }
    };
    reader.readAsDataURL(file);
  });
  input.value='';
}

function fdaEliminarFoto(fi){
  if(!confirm('¿Eliminar esta foto?')) return;
  const r = db.records.find(x=>x.id===_sacRecordId);
  if(!r || _sacContactoIdx===null) return;
  const ct = r.contactos[_sacContactoIdx];
  if(ct.fotasFda) ct.fotasFda.splice(fi,1);
  if((ct.fotasFda||[]).length===0) ct.fdaEntregado = false;
  save();
  sacAbrirModalFda(_sacRecordId, _sacContactoIdx);
}

function fdaDescargarReporte(){
  const XLSX = window.XLSX;
  if(!XLSX){ toast('⚠️','SheetJS no disponible','#f5a623'); return; }

  const all = fdaGetAllContactos();
  const rows = all.map(({r,ct}) => ({
    'Empresa':            r.empresa||'',
    'Categoría':          r.categoria||'Sin categoría',
    'Persona de Contacto': ct.nombre||'',
    'Cargo':              ct.cargo||'',
    'Correo Electrónico': ct.email||'',
    'Celular':            ct.telefono||'',
    'Dirección':          ct.direccion||'',
    'Seleccionado':       fdaEstaSeleccionado(r.id,ct._idx)?'✅ Sí':'No',
    'Entrega Realizada':  (ct.fdaEntregado||(ct.fotasFda||[]).length>0)?'✅ Entregado':'⏳ Pendiente',
    'Comercial':          (db.comerciales.find(x=>x.id===r.comercialId)?.nombre)||'—',
  }));

  const ws = XLSX.utils.json_to_sheet([]);
  XLSX.utils.sheet_add_aoa(ws,[
    ['REPORTE FIN DE AÑO — DETALLES — GRUPO ZYMO'],
    ['Generado: '+new Date().toLocaleDateString('es-CO',{day:'2-digit',month:'long',year:'numeric'})],
    []
  ],{origin:'A1'});
  XLSX.utils.sheet_add_json(ws, rows, {origin:'A4'});
  ws['!cols'] = [{wch:30},{wch:12},{wch:25},{wch:20},{wch:30},{wch:16},{wch:35},{wch:14},{wch:18},{wch:20}];

  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Fin de Año');
  XLSX.writeFile(wb, 'DetallesFinDeAno_ZYMO.xlsx');
  toast('✅','Reporte descargado','#00e676');
}


// ============================================================
// BACKUP / RESTORE DE DATOS
// ============================================================
function exportarDatos(){
  const json = localStorage.getItem('zymo-db');
  if(!json){ toast('⚠️','No hay datos para exportar','#f5a623'); return; }
  const blob = new Blob([json], {type:'application/json'});
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = 'backup_zymo_' + new Date().toISOString().slice(0,10) + '.json';
  a.click();
  URL.revokeObjectURL(a.href);
  toast('✅','Backup exportado correctamente','#00e676');
  document.getElementById('backup-status').textContent = 'Último backup: ' + new Date().toLocaleTimeString('es-CO');
}

function importarDatos(input){
  const file = input.files[0];
  if(!file) return;
  const reader = new FileReader();
  reader.onload = e => {
    try {
      const data = JSON.parse(e.target.result);
      // Validate it's a zymo db
      if(!data.records && !data.comerciales && !data.biblioteca){
        toast('⚠️','Archivo no válido — no parece un backup de ZYMO','#f5a623');
        return;
      }
      if(!confirm('¿Importar este backup? Se reemplazarán los datos actuales.')) return;
      localStorage.setItem('zymo-db', JSON.stringify(data));
      // Reload db in memory
      Object.assign(db, data);
      initBiblioteca();
      renderDashboard();
      renderProspectos();
      renderClientes();
      renderEquipo();
      renderCotizaciones();
      renderBiblioteca();
      toast('✅','Datos importados correctamente','#00e676');
      document.getElementById('backup-status').textContent = 'Importado: ' + file.name;
    } catch(err) {
      toast('❌','Error al importar: ' + err.message,'#ff5252');
    }
    input.value = '';
  };
  reader.readAsText(file);
}


