// Ciudades principales (zona 1)
const ZONA1 = ['Bogotá','Medellín','Cali','Barranquilla','Cartagena','Bucaramanga','Pereira','Manizales','Cúcuta','Ibagué'];
// Ciudades medianas (zona 2) — el resto es zona 3

function cotizadorGetZona(municipio) {
  if(ZONA1.includes(municipio)) return 1;
  const z2 = ['Villavicencio','Neiva','Pasto','Santa Marta','Valledupar','Montería','Sincelejo','Armenia','Popayán','Florencia','Tunja','Yopal','Riohacha','Soledad','Bello','Itagüí','Envigado','Palmira','Buenaventura','Soacha','Zipaquirá','Dosquebradas','Floridablanca','Girón','Barrancabermeja'];
  if(z2.includes(municipio)) return 2;
  return 3;
}

function cotizadorInit() {
  const deps = Object.keys(COL_DEPTS).sort();
  ['cot-origen-dep','cot-destino-dep'].forEach(id => {
    const sel = document.getElementById(id);
    if(!sel) return;
    sel.innerHTML = '<option value="">Seleccione departamento</option>' +
      deps.map(d => `<option value="${d}">${d}</option>`).join('');
  });
}

function cotizadorOnDepChange(tipo) {
  const depSel = document.getElementById(`cot-${tipo}-dep`);
  const munSel = document.getElementById(`cot-${tipo}-mun`);
  if(!depSel || !munSel) return;
  const dep = depSel.value;
  const muns = dep ? (COL_DEPTS[dep]||[]).sort() : [];
  munSel.innerHTML = '<option value="">Seleccione municipio</option>' +
    muns.map(m => `<option value="${m}">${m}</option>`).join('');
}

let _cotTab = 'estandar';

function cotizadorSetTab(tab) {
  _cotTab = tab;
  document.getElementById('cot-panel-estandar').style.display = tab==='estandar'?'block':'none';
  document.getElementById('cot-panel-custom').style.display   = tab==='custom'?'block':'none';
  document.getElementById('cot-tab-estandar').style.background = tab==='estandar'?'var(--gold)':'var(--surface3)';
  document.getElementById('cot-tab-estandar').style.color      = tab==='estandar'?'#000':'var(--text2)';
  document.getElementById('cot-tab-custom').style.background   = tab==='custom'?'var(--gold)':'var(--surface3)';
  document.getElementById('cot-tab-custom').style.color        = tab==='custom'?'#000':'var(--text2)';
}

function cotizadorOnStdSize() {
  const sel = document.getElementById('cot-size-std');
  const info = document.getElementById('cot-std-info');
  const pesoEl = document.getElementById('cot-peso');
  if(!sel.value){ info.style.display='none'; return; }
  const [dims, peso] = sel.value.split('|');
  const [l,a,h] = dims.split('x');
  const labels = {
    '20x15x10': 'Ideal para celulares, accesorios, documentos',
    '35x25x15': 'Ideal para zapatos, libros, ropa',
    '60x40x30': 'Ideal para electrodomésticos pequeños, juguetes',
    '100x100x120': 'Ideal para electrodomésticos grandes, muebles'
  };
  info.style.display = 'block';
  info.innerHTML = `<strong>Dimensiones:</strong> ${l} × ${a} × ${h} cm<br><span style="color:var(--text2)">${labels[dims]||''}</span>`;
  pesoEl.value = peso;
}

function cotizadorCalcVolWeight() {
  // Calculates volumetric weight for info purposes
}

function cotizadorCalcular() {
  const origenDep = document.getElementById('cot-origen-dep').value;
  const origenMun = document.getElementById('cot-origen-mun').value;
  const destinoDep = document.getElementById('cot-destino-dep').value;
  const destinoMun = document.getElementById('cot-destino-mun').value;
  const pesoReal = parseFloat(document.getElementById('cot-peso').value)||0;
  const valorDeclarado = parseFloat(document.getElementById('cot-valor').value)||0;

  if(!origenMun){ toast('⚠️','Selecciona el municipio de origen','#f5a623'); return; }
  if(!destinoMun){ toast('⚠️','Selecciona el municipio de destino','#f5a623'); return; }
  if(pesoReal <= 0){ toast('⚠️','Ingresa el peso del paquete','#f5a623'); return; }

  // Calcular peso volumétrico
  let pesoVol = 0;
  if(_cotTab === 'estandar') {
    const sel = document.getElementById('cot-size-std');
    if(sel.value){
      const [dims] = sel.value.split('|');
      const [l,a,h] = dims.split('x').map(Number);
      pesoVol = (l * a * h) / 5000;
    }
  } else {
    const l = parseFloat(document.getElementById('cot-largo').value)||0;
    const a = parseFloat(document.getElementById('cot-ancho').value)||0;
    const h = parseFloat(document.getElementById('cot-alto').value)||0;
    pesoVol = (l * a * h) / 5000;
  }

  const pesoCobrable = Math.max(pesoReal, pesoVol);
  const zona = cotizadorGetZona(destinoMun);
  const mismoMun = origenMun === destinoMun;

  // Calcular tarifas para cada paqueteadora
  const resultados = Object.values(COURIER_TARIFAS).map(courier => {
    const t = courier.tarifas[zona];
    const pesoExtra = Math.max(0, pesoCobrable - t.minKg);
    let tarifa = t.base + (pesoExtra * t.extraKg);
    // Seguro sobre valor declarado
    if(valorDeclarado > 0) tarifa += valorDeclarado * courier.seguro;
    // Mismo municipio = descuento
    if(mismoMun) tarifa *= 0.7;
    tarifa = Math.round(tarifa);
    const dias = mismoMun ? 1 : courier.tiempos[zona];
    return {
      courier: courier.nombre,
      servicio: courier.servicio,
      color: courier.color,
      tarifa,
      pesoCobrable: pesoCobrable.toFixed(2),
      dias,
      trayecto: mismoMun ? 'LOCAL' : 'NACIONAL',
    };
  }).sort((a,b) => a.tarifa - b.tarifa);

  // Render resultados
  const fmt = n => new Intl.NumberFormat('es-CO').format(n);
  const tabla = `
    <div style="overflow-x:auto">
      <table style="width:100%;border-collapse:collapse">
        <thead>
          <tr style="border-bottom:2px solid var(--border)">
            <th style="text-align:left;padding:10px 14px;font-size:12px;color:var(--text2);font-weight:700;text-transform:uppercase">Courier</th>
            <th style="text-align:left;padding:10px 14px;font-size:12px;color:var(--text2);font-weight:700;text-transform:uppercase">Servicio</th>
            <th style="text-align:center;padding:10px 14px;font-size:12px;color:var(--text2);font-weight:700;text-transform:uppercase">⏱ Tiempo</th>
            <th style="text-align:right;padding:10px 14px;font-size:12px;color:var(--text2);font-weight:700;text-transform:uppercase">$ Tarifa</th>
            <th style="text-align:center;padding:10px 14px;font-size:12px;color:var(--text2);font-weight:700;text-transform:uppercase">Kg-Courier</th>
            <th style="text-align:center;padding:10px 14px;font-size:12px;color:var(--text2);font-weight:700;text-transform:uppercase">Trayecto</th>
          </tr>
        </thead>
        <tbody>
          ${resultados.map((r,i) => `
            <tr style="border-bottom:1px solid var(--border);${i===0?'background:rgba(245,166,35,0.05)':''}">
              <td style="padding:14px;font-weight:700;font-size:14px">
                <span style="color:${r.color}">${r.courier}</span>
                ${i===0?'<span style="font-size:10px;background:var(--gold);color:#000;padding:1px 6px;border-radius:4px;margin-left:6px;font-weight:700">MEJOR PRECIO</span>':''}
              </td>
              <td style="padding:14px;font-size:13px;color:var(--text2)">${r.servicio}</td>
              <td style="padding:14px;font-size:13px;color:var(--text);text-align:center">${r.dias} ${r.dias===1?'día':'días'}</td>
              <td style="padding:14px;font-size:16px;font-weight:800;color:var(--green);text-align:right">$ ${fmt(r.tarifa)}</td>
              <td style="padding:14px;font-size:13px;color:var(--text2);text-align:center">${r.pesoCobrable} kg</td>
              <td style="padding:14px;text-align:center">
                <span style="font-size:11px;font-weight:700;padding:3px 8px;border-radius:5px;background:${r.trayecto==='LOCAL'?'rgba(0,230,118,0.15)':'rgba(0,194,255,0.12)'};color:${r.trayecto==='LOCAL'?'var(--green)':'var(--accent)'}">
                  ${r.trayecto}
                </span>
              </td>
            </tr>`).join('')}
        </tbody>
      </table>
    </div>`;

  const info = `
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:4px">
      <div style="background:rgba(0,194,255,0.06);border:1px solid rgba(0,194,255,0.2);border-radius:8px;padding:12px 14px;font-size:12px;color:var(--text2)">
        <span style="color:var(--accent);font-weight:700">ℹ️ Información:</span> El peso cobrable (Kg-Courier) es el mayor entre el peso real y el peso volumétrico. El peso volumétrico se calcula como: (Largo × Ancho × Alto) / 5000.
      </div>
      <div style="background:rgba(0,230,118,0.06);border:1px solid rgba(0,230,118,0.2);border-radius:8px;padding:12px 14px;font-size:12px;color:var(--text2)">
        <span style="color:var(--green);font-weight:700">📊 Comparación:</span> Se muestran las tarifas de ${resultados.length} paqueterías. Puedes elegir la que mejor se ajuste a tus necesidades de precio y tiempo de entrega.
      </div>
    </div>`;

  document.getElementById('cot-resultados-tabla').innerHTML = tabla;
  document.getElementById('cot-resultados-info').innerHTML = info;
  document.getElementById('cot-resultados').style.display = 'block';
  document.getElementById('cot-resultados').scrollIntoView({behavior:'smooth', block:'start'});
}



