function preliqInit(){
  var search = document.getElementById('preliq-cot-search');
  if(search) search.value = '';
  var sel = document.getElementById('preliq-cot-sel');
  if(sel) sel.value = '';
  var dd = document.getElementById('preliq-cot-dropdown');
  if(dd) dd.style.display = 'none';
  document.getElementById('preliq-cot-info').innerHTML = '';
  document.getElementById('preliq-svcs-row').style.display = 'none';
  document.getElementById('preliq-form-card').style.display = 'none';
  document.getElementById('preliq-resultado').style.display = 'none';
  window._preliqItemsSeleccionados = [];
  window._preliqState = null;
  preliqRenderHistorial();
  document.addEventListener('click', function(e){
    if(!e.target.closest('#preliq-cot-search') && !e.target.closest('#preliq-cot-dropdown')){
      var dd2 = document.getElementById('preliq-cot-dropdown');
      if(dd2) dd2.style.display = 'none';
    }
  });
}

function preliqSearchCot(){
  var q = (document.getElementById('preliq-cot-search').value||'').toLowerCase().trim();
  var cots = (db.cotizaciones||[]).filter(function(c){ return c.lineas && c.lineas.length > 0; });
  var filtered = q ? cots.filter(function(c){
    return (c.empresa||'').toLowerCase().includes(q) || (c.numero||'').toLowerCase().includes(q);
  }) : cots;
  var dd = document.getElementById('preliq-cot-dropdown');
  if(!filtered.length){
    dd.innerHTML = '<div style="padding:12px 16px;color:var(--text2);font-size:13px">Sin resultados</div>';
    dd.style.display = 'block';
    return;
  }
  var html = '';
  filtered.slice(0,20).forEach(function(c){
    html += '<div onclick="preliqSelectCot(\'' + c.id + '\')" style="padding:10px 16px;cursor:pointer;border-bottom:1px solid var(--border)" onmouseover="this.style.background=\'rgba(0,194,255,0.08)\'" onmouseout="this.style.background=\'\'">';
    html += '<div style="font-size:14px;font-weight:600;color:var(--text)">' + (c.empresa||'Sin empresa') + '</div>';
    html += '<div style="font-size:11px;color:var(--text2);margin-top:2px">' + (c.numero||c.id) + ' &middot; ' + (c.fecha||'') + ' &middot; <span style="color:var(--accent)">' + (c.lineas||[]).join(', ') + '</span></div>';
    html += '</div>';
  });
  dd.innerHTML = html;
  dd.style.display = 'block';
}

function preliqSelectCot(id){
  document.getElementById('preliq-cot-sel').value = id;
  document.getElementById('preliq-cot-dropdown').style.display = 'none';
  var cot = (db.cotizaciones||[]).find(function(c){ return c.id === id; });
  if(cot) document.getElementById('preliq-cot-search').value = (cot.empresa||'Sin empresa') + ' \u2014 ' + (cot.numero||cot.id);
  preliqOnCotChange();
}

function preliqOnCotChange(){
  var id = document.getElementById('preliq-cot-sel').value;
  var infoEl  = document.getElementById('preliq-cot-info');
  var svcsRow = document.getElementById('preliq-svcs-row');
  var formCard = document.getElementById('preliq-form-card');
  document.getElementById('preliq-resultado').style.display = 'none';
  formCard.style.display = 'none';
  if(!id){ svcsRow.style.display='none'; infoEl.innerHTML=''; return; }
  var cot = (db.cotizaciones||[]).find(function(c){ return c.id===id; });
  if(!cot) return;

  infoEl.innerHTML = '<span style="color:var(--accent);font-weight:600">' + (cot.empresa||'') + '</span>';

  var svcColors = {'Zona Franca':'#00c2ff','CEDI':'#00e676','Deposito Aduanero':'#a78bfa','Transporte':'#f5a623','Paqueteo':'#ff6b6b','Aduana':'#ffd700'};
  var svcs = cot.lineas||[];
  var html = '';

  for(var si=0; si<svcs.length; si++){
    var svc = svcs[si];
    var items = preliqGetAllItems(cot, svc);
    if(!items.length) continue;
    var col = svcColors[svc]||'#00c2ff';
    var logoSvc = SVC_LOGOS[svc] || null;
    html += '<div style="margin-bottom:16px;background:var(--surface2);border:1px solid var(--border);border-radius:12px;padding:14px">';
    html += '<div style="display:flex;align-items:center;gap:12px;margin-bottom:10px;padding-bottom:10px;border-bottom:1px solid var(--border)">';
    if(logoSvc) html += '<img src="'+logoSvc+'" style="height:36px;width:auto;object-fit:contain;border-radius:6px;flex-shrink:0" alt="'+svc+'">';
    html += '<span style="font-size:13px;font-weight:800;letter-spacing:2px;text-transform:uppercase;color:' + col + '">' + svc + '</span>';
    html += '</div>';
    html += '<div style="display:flex;flex-direction:column;gap:6px">';
    for(var ii=0; ii<items.length; ii++){
      var item = items[ii];
      // Todos los ítems se muestran — el cálculo resuelve cuál cobrar
      var chkId = 'pchk' + si + '_' + ii;
      html += '<label for="' + chkId + '" style="display:flex;align-items:center;gap:10px;padding:9px 14px;border-radius:8px;border:1px solid var(--border);background:var(--surface2);cursor:pointer">';
      html += '<input type="checkbox" id="' + chkId + '" data-svc="' + svc + '" data-idx="' + ii + '" data-col="' + col + '" onchange="preliqChkChange(this)" style="width:16px;height:16px;cursor:pointer;accent-color:' + col + ';flex-shrink:0">';
      html += '<div style="flex:1">';
      html += '<span style="font-size:13px;font-weight:600;color:var(--text)">' + item.nombre + '</span>';
      if(item.tarifa) html += ' <span style="font-size:12px;color:var(--gold)">' + item.tarifa + '</span>';
      if(item.obs)    html += '<div style="font-size:11px;color:var(--text2)">' + item.obs + '</div>';
      html += '</div></label>';
    }
    html += '</div>';  // cierre flex items
    html += '</div>';  // cierre tarjeta servicio
  }

  if(!html) html = '<div style="color:var(--text2);font-size:13px;padding:12px">Sin items disponibles.</div>';
  document.getElementById('preliq-svcs-btns').innerHTML = html;
  svcsRow.style.display = 'block';
  window._preliqItemsSeleccionados = [];
}

function preliqChkChange(chk){
  var col = chk.dataset.col||'var(--accent)';
  var label = chk.closest('label');
  if(chk.checked){
    label.style.borderColor = col;
    label.style.background = col + '18';
  } else {
    label.style.borderColor = 'var(--border)';
    label.style.background = 'var(--surface2)';
  }
}

function preliqConfirmarServicios(){
  var checked = document.querySelectorAll('#preliq-svcs-btns input[type=checkbox]:checked');
  if(!checked.length){ toast('\u26a0\ufe0f','Selecciona al menos un item a preliquidar','#f5a623'); return; }
  var cotId = document.getElementById('preliq-cot-sel').value;
  var cot = (db.cotizaciones||[]).find(function(c){ return c.id===cotId; });
  if(!cot){ toast('\u26a0\ufe0f','Cotizacion no encontrada','#f5a623'); return; }
  var itemsSeleccionados = [];
  checked.forEach(function(chk){
    var svc = chk.dataset.svc;
    var idx = parseInt(chk.dataset.idx);
    var todos = preliqGetAllItems(cot, svc);
    if(todos[idx]) itemsSeleccionados.push(Object.assign({}, todos[idx], {_svc: svc}));
  });
  // Todos los ítems seleccionados pasan — el cálculo resuelve cuál cobrar
  window._preliqItemsSeleccionados = itemsSeleccionados;
  preliqRenderForm(cot, itemsSeleccionados);
  document.getElementById('preliq-form-card').style.display = 'block';
  document.getElementById('preliq-form-card').scrollIntoView({behavior:'smooth',block:'start'});
}

// Obtiene todos los items seleccionados de un servicio en la cotizacion
function preliqEsMinima(nombre){
  var n = (nombre||'').toLowerCase();
  return n.includes('minim') || n.includes('mínimo') || n.includes('minimo');
}

// Retorna solo ítems de CÁLCULO (no mínimas).
// Cada ítem de cálculo lleva su mínima del mismo _gid en _minimaItem.
// Las mínimas NUNCA aparecen como ítems independientes.
function preliqGetAllItems(cot, svc){
  var svcItems = cot.items && cot.items[svc];
  if(!svcItems) return [];
  var bib = db.biblioteca && db.biblioteca[svc];
  var result = [];
  Object.keys(svcItems).forEach(function(gid){
    var gs = svcItems[gid];
    if(!gs) return;
    var bibGrupo = (bib && bib.grupos||[]).find(function(g){ return g.id===gid; });
    var gNombre = (bibGrupo && bibGrupo.nombre)||gid;
    (gs.items||[]).filter(function(i){ return i.sel; }).forEach(function(item){
      result.push(Object.assign({}, item, {_grupo: gNombre, _gid: gid, _svc: svc}));
    });
  });
  return result;
}

// Detecta que campos se necesitan y renderiza el formulario
function preliqRenderForm(cot, items){
  var needCif=false, needPeso=false, needTipo=false, needPallets=false, needDias=false, needUnidades=false;

  items.forEach(function(item){
    var nom   = (item.nombre||'').toLowerCase();
    var grupo = (item._grupo||'').toLowerCase();
    var esPct = item.tipoTarifa==='porcentaje' || String(item.tarifa||'').includes('%');

    // Ad Valorem: necesita CIF + tipo de ingreso
    var esAdv = nom==='ad valorem' || nom.startsWith('ad valorem');
    if(esAdv){ needCif=true; needTipo=true; }

    // Seguro con porcentaje: necesita CIF (pero NO tipo de ingreso)
    var esSeg = grupo.includes('segur') || nom.includes('seguro') || nom.includes('tasa de segur');
    if(esSeg && esPct && !esAdv) needCif = true;

    // Minima de contenedor en manipulacion/almacenamiento: necesita tipo de ingreso
    var esMinCont = (nom.includes('contenedor')||nom.includes('cont')) &&
                    (grupo.includes('manipul')||grupo.includes('almacen'));
    if(esMinCont) needTipo = true;

    // Manipulacion / Valor Kilo: necesita peso
    var esManip = grupo.includes('manipul')||grupo.includes('recib')||
                  nom.includes('kilo')||nom.includes('/kg')||nom.includes('valor kilo');
    if(esManip) needPeso = true;

    // Almacenamiento por pallet/posicion: necesita pallets + dias
    var esPallet = grupo.includes('almacen')||grupo.includes('posici')||grupo.includes('pallet')||
                   nom.includes('pallet')||nom.includes('posici');
    if(esPallet){ needPallets=true; }

    // Despacho/alistamiento: necesita unidades
    var esDespach = grupo.includes('despach')||grupo.includes('alistam')||grupo.includes('picking')||
                    nom.includes('despach')||nom.includes('alistam')||nom.includes('picking');
    if(esDespach) needUnidades = true;
  });

  var inp = 'width:100%;background:var(--surface2);border:1px solid var(--border);border-radius:8px;padding:10px 14px;color:var(--text);font-size:14px;outline:none;box-sizing:border-box';
  var lbl = 'font-size:11px;color:var(--text2);letter-spacing:1px;text-transform:uppercase;display:block;margin-bottom:6px';

  // Resumen de items seleccionados
  var svcColors = {'Zona Franca':'#00c2ff','CEDI':'#00e676','Deposito Aduanero':'#a78bfa','Transporte':'#f5a623','Paqueteo':'#ff6b6b','Aduana':'#ffd700'};
  var porSvc = {};
  items.forEach(function(i){ if(!porSvc[i._svc]) porSvc[i._svc]=[]; porSvc[i._svc].push(i); });
  var resumen = '<div style="grid-column:1/-1;background:var(--surface2);border:1px solid var(--border);border-radius:10px;padding:14px;margin-bottom:4px">';
  resumen += '<div style="font-size:11px;color:var(--text2);letter-spacing:1px;text-transform:uppercase;font-weight:700;margin-bottom:10px">Items a Preliquidar</div>';
  Object.keys(porSvc).forEach(function(svc){
    var col = svcColors[svc]||'var(--accent)';
    resumen += '<div style="margin-bottom:8px"><span style="font-size:11px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:' + col + '">' + svc + '</span>';
    resumen += '<div style="display:flex;flex-wrap:wrap;gap:5px;margin-top:4px">';
    porSvc[svc].forEach(function(i){
      resumen += '<span style="background:var(--surface);border:1px solid var(--border);border-radius:6px;padding:3px 10px;font-size:12px;color:var(--text)">';
      if(i._grupo) resumen += '<small style="color:var(--text2)">' + i._grupo + '</small> &middot; ';
      resumen += i.nombre;
      if(i.tarifa) resumen += ' <span style="color:var(--gold);font-weight:600">' + i.tarifa + '</span>';
      resumen += '</span>';
    });
    resumen += '</div></div>';
  });
  resumen += '</div>';

  // Campos del formulario
  var html = resumen;
  html += '<div><label style="' + lbl + '">Producto / Mercancia</label><input type="text" id="preliq-f-producto" placeholder="Ej: Paneles Solares" style="' + inp + '"></div>';
  if(needCif)      html += '<div><label style="' + lbl + '">Valor CIF / Mercancia (COP)</label><input type="text" id="preliq-f-cif" placeholder="Ej: 50.000.000" oninput="fmtPreliqNum(this)" style="' + inp + '"></div>';
  if(needTipo)     html += '<div><label style="' + lbl + '">Tipo de Ingreso</label><select id="preliq-f-tipo" onchange="preliqOnTipoChange()" style="' + inp + '"><option value="">-- Selecciona --</option><option value="lcl">Aerea / LCL (Consolidado)</option><option value="cont20">Contenedor 20 pies</option><option value="cont40">Contenedor 40 pies (Std / HC)</option></select></div><div id="preliq-num-cont-wrap" style="display:none"><label style="' + lbl + '">N de Contenedores</label><input type="number" id="preliq-f-numcont" value="1" min="1" style="' + inp + '"></div>';
  if(needPeso)     html += '<div><label style="' + lbl + '">Peso total (kg)</label><input type="number" id="preliq-f-peso" placeholder="Ej: 2500" min="0" style="' + inp + '"></div>';
  if(needPallets)  html += '<div><label style="' + lbl + '">N de Pallets / Posiciones</label><input type="number" id="preliq-f-pallets" placeholder="Ej: 10" min="0" style="' + inp + '"></div>';
  if(needUnidades) html += '<div><label style="' + lbl + '">N de Unidades / Cajas</label><input type="number" id="preliq-f-unidades" placeholder="Ej: 50" min="0" style="' + inp + '"></div>';

  document.getElementById('preliq-form-fields').innerHTML = html;
}

function preliqOnTipoChange(){
  var tipo = document.getElementById('preliq-f-tipo') && document.getElementById('preliq-f-tipo').value;
  var wrap = document.getElementById('preliq-num-cont-wrap');
  if(wrap) wrap.style.display = (tipo==='cont20'||tipo==='cont40') ? 'block' : 'none';
}

function fmtPreliqNum(el){
  var raw = el.value.replace(/\D/g,'');
  if(raw) el.value = parseInt(raw).toLocaleString('es-CO');
}

function parsePreliqNum(str){
  return parseFloat(String(str||'0').replace(/\./g,'').replace(',','.')) || 0;
}

// Agrupa items por _grupo (concepto): calcula cada uno, devuelve solo el de mayor valor.
// Así ALMACENAMIENTO x2, MANIPULACION x2, SEGURO x2 → 1 fila por concepto con el mayor.
function preliqAgruparPorConcepto(items, opts){
  // Regla de negocio:
  // - Agrupar ítems por _grupo (nombre del concepto)
  // - Si hay exactamente 2 ítems en el mismo grupo:
  //     · El de TARIFA MÁS ALTA = ítem de cálculo (se multiplica × pallets, × CIF%, etc.)
  //     · El de TARIFA MÁS BAJA = mínima (piso del cálculo)
  //   → Solo se muestra UN valor: el mayor entre el cálculo y la mínima
  // - Si hay 1 ítem: pasa directo
  // - Si hay >2 ítems del mismo grupo: todos pasan (caso raro, se muestran todos)

  var porGrupo = {};
  items.forEach(function(it){
    var g = it._grupo || it.nombre || 'otro';
    if(!porGrupo[g]) porGrupo[g] = [];
    porGrupo[g].push(it);
  });

  // Paso 1: resolver cada grupo
  var paso1 = [];
  Object.keys(porGrupo).forEach(function(g){
    var grupo = porGrupo[g];

    if(grupo.length === 1){
      paso1.push(grupo[0]);
      return;
    }

    if(grupo.length === 2){
      var esMin0 = preliqEsMinima(grupo[0].nombre);
      var esMin1 = preliqEsMinima(grupo[1].nombre);
      var esPct0 = grupo[0].tipoTarifa==='porcentaje'||String(grupo[0].tarifa||'').includes('%');
      var esPct1 = grupo[1].tipoTarifa==='porcentaje'||String(grupo[1].tarifa||'').includes('%');

      // Caso 1: uno tiene "minim" explícito → fusionar con ese como mínima
      if(esMin0 || esMin1){
        var itemCalculo = esMin1 ? grupo[0] : grupo[1];
        var itemMinima  = esMin0 ? grupo[0] : grupo[1];
        paso1.push(Object.assign({}, itemCalculo, {_minimaItem: itemMinima}));
        return;
      }

      // Caso 2: uno es porcentaje/kg y el otro es fijo → el fijo es la mínima
      var esKg0 = (grupo[0].nombre||'').toLowerCase().includes('/kg');
      var esKg1 = (grupo[1].nombre||'').toLowerCase().includes('/kg');
      var esCalc0 = esPct0 || esKg0;
      var esCalc1 = esPct1 || esKg1;
      if(esCalc0 !== esCalc1){
        var itemCalculo2 = esCalc0 ? grupo[0] : grupo[1];
        var itemMinima2  = esCalc0 ? grupo[1] : grupo[0];
        paso1.push(Object.assign({}, itemCalculo2, {_minimaItem: itemMinima2}));
        return;
      }

      // Caso 3: ambos fijos con diferente tarifa → tarifa baja=cálculo, tarifa alta=mínima
      // EXCEPTO si los nombres son claramente distintos (ej: ingreso vs salida)
      var nom0 = (grupo[0].nombre||'').toLowerCase();
      var nom1 = (grupo[1].nombre||'').toLowerCase();
      var nombresDistintos = nom0 !== nom1 &&
        !nom0.includes('minim') && !nom1.includes('minim') &&
        (nom0.includes('ingreso') || nom0.includes('salida') ||
         nom1.includes('ingreso') || nom1.includes('salida') ||
         nom0.includes('entrada') || nom1.includes('entrada'));
      if(nombresDistintos){
        grupo.forEach(function(it){ paso1.push(it); });
        return;
      }

      // Fusionar por tarifa: baja=cálculo, alta=mínima
      var ordenado = grupo.slice().sort(function(a,b){
        return parsePreliqNum(a.tarifa) - parsePreliqNum(b.tarifa);
      });
      paso1.push(Object.assign({}, ordenado[0], {_minimaItem: ordenado[1]}));
      return;
    }

    grupo.forEach(function(it){ paso1.push(it); });
  });

  // Paso 2: vincular mínima de seguro (grupo separado) con la tasa de seguro
  // La mínima de seguro es un ítem fijo sin porcentaje cuyo _grupo contiene "minim" y "seg"
  // La tasa de seguro es un ítem porcentual cuyo _grupo contiene "seg"
  return paso1;
}

// CALCULAR
function preliqCalcular(){
  var cotId = document.getElementById('preliq-cot-sel').value;
  var items = window._preliqItemsSeleccionados||[];
  if(!cotId)        { toast('\u26a0\ufe0f','Selecciona una cotizacion primero','#f5a623'); return; }
  if(!items.length) { toast('\u26a0\ufe0f','No hay items seleccionados','#f5a623'); return; }
  var cot = (db.cotizaciones||[]).find(function(c){ return c.id===cotId; });
  if(!cot){ toast('\u26a0\ufe0f','Cotizacion no encontrada','#f5a623'); return; }

  var producto = (document.getElementById('preliq-f-producto') && document.getElementById('preliq-f-producto').value)||'--';
  var cifRaw   = document.getElementById('preliq-f-cif') && document.getElementById('preliq-f-cif').value;
  var pesoRaw  = document.getElementById('preliq-f-peso') && document.getElementById('preliq-f-peso').value;
  var tipoEl   = document.getElementById('preliq-f-tipo');
  var tipo     = tipoEl ? tipoEl.value : '';
  var numContEl= document.getElementById('preliq-f-numcont');
  var numCont  = numContEl ? (parseInt(numContEl.value)||1) : 1;
  var palletsEl= document.getElementById('preliq-f-pallets');
  var pallets  = palletsEl ? (parseInt(palletsEl.value)||0) : 0;
  var diasEl   = document.getElementById('preliq-f-dias');
  var dias     = diasEl ? (parseInt(diasEl.value)||1) : 1;
  var unidEl   = document.getElementById('preliq-f-unidades');
  var unidades = unidEl ? (parseInt(unidEl.value)||0) : 0;
  var cif      = cifRaw ? parsePreliqNum(cifRaw) : 0;
  var peso     = parseFloat(pesoRaw)||0;

  // Agrupar items por servicio
  var porSvc = {};
  items.forEach(function(item){
    if(!porSvc[item._svc]) porSvc[item._svc]=[];
    porSvc[item._svc].push(item);
  });

  var todasLineas = [];
  var svcsUsados  = [];
  Object.keys(porSvc).forEach(function(svc){
    svcsUsados.push(svc);
    todasLineas.push({_seccion: svc});
    var todosItemsSvc = preliqGetAllItems(cot, svc);
    // Agrupar por concepto (_grupo): cada concepto produce UNA sola línea (el mayor valor)
    var itemsAgrupados = preliqAgruparPorConcepto(porSvc[svc], {});
    itemsAgrupados.forEach(function(item){
      var linea = preliqCalcItem(item, {cif:cif, peso:peso, tipo:tipo, numCont:numCont, pallets:pallets, dias:dias, unidades:unidades, todosItemsSvc:todosItemsSvc});
      if(linea) todasLineas.push(linea);
    });
  });

  window._preliqState = {cot:cot, svc:svcsUsados, producto:producto, cif:cif, peso:peso, tipo:tipo, numCont:numCont, pallets:pallets, lineas:todasLineas};
  preliqMostrarResultado(cot, svcsUsados, producto, cif, peso, tipo, numCont, pallets, todasLineas);
}

// Calcula una linea para un item
function preliqCalcItem(item, opts){
  var cif=opts.cif, peso=opts.peso, tipo=opts.tipo, numCont=opts.numCont, pallets=opts.pallets;
  var dias=opts.dias, unidades=opts.unidades, todosItemsSvc=opts.todosItemsSvc;

  var nom       = (item.nombre||'').toLowerCase();
  var grupo     = (item._grupo||'').toLowerCase();
  var tarifaRaw = String(item.tarifa||'0');
  var esPct     = item.tipoTarifa==='porcentaje' || tarifaRaw.includes('%');
  var tarifaNum = esPct
    ? parseFloat(tarifaRaw.replace('%','').replace(',','.')) / 100
    : parsePreliqNum(tarifaRaw);
  // Formatear tasa porcentual: siempre 2 decimales con coma y símbolo %
  // Ejemplo: "0.36%" → "0,36%"  |  "0.1800" → "0,18%"  |  "0,19" → "0,19%"
  var tarifaPct = esPct
    ? (tarifaNum * 100).toFixed(2).replace('.', ',') + '%'
    : tarifaRaw;

  var esAdv     = nom==='ad valorem' || nom.startsWith('ad valorem');
  var esSeg     = grupo.includes('segur') || nom.includes('tasa de segur') || nom.includes('seguro');
  var esMinSeg  = esSeg && !esPct;
  var esAlmac   = grupo.includes('almacen')||grupo.includes('posici')||grupo.includes('pallet');
  var esPallet  = nom.includes('pallet')||nom.includes('posici')||esAlmac;
  var esManip   = grupo.includes('manipul')||grupo.includes('recib');
  var esKg      = nom.includes('kilo')||nom.includes('/kg')||nom.includes('valor kilo')||nom.includes('kg');
  var esDespach = grupo.includes('despach')||grupo.includes('alistam')||grupo.includes('picking')||
                  nom.includes('despach')||nom.includes('alistam')||nom.includes('picking');
  var esCont    = tipo==='cont20'||tipo==='cont40';

  var resultado=0, base='', nota=item.obs||'';

  // Si el item tiene una minima asociada (_minimaItem), resolver cual cobrar
  var minimaAsociada = item._minimaItem ? parsePreliqNum(item._minimaItem.tarifa) : 0;

  if(esAdv && esPct){
    // Ad Valorem % x CIF, con minima segun tipo de ingreso
    resultado = cif * tarifaNum;
    base = tarifaPct + ' × $' + cif.toLocaleString('es-CO') + ' CIF';
    if(tipo && todosItemsSvc){
      var frag = tipo==='lcl'   ? ['aer','lcl','consolid','minima aer','minima lcl']
               : tipo==='cont20' ? ['20 pie','20p','cont 20']
               : tipo==='cont40' ? ['40 pie','40p','cont 40','40 pies'] : [];
      var minItem = todosItemsSvc.find(function(i){
        if(i.id===item.id || i.tipoTarifa==='porcentaje') return false;
        var n=(i.nombre||'').toLowerCase();
        return frag.some(function(f){ return n.includes(f); });
      });
      if(minItem){
        var minVal = parsePreliqNum(minItem.tarifa) * (esCont ? numCont : 1);
        if(resultado < minVal){
          nota = 'Calculado $' + Math.round(resultado).toLocaleString('es-CO') + ' < minima. Se cobra minima' + (esCont?' x '+numCont+' cont.':'');
          resultado = minVal;
        }
      }
    }

  } else if(esSeg && esPct){
    // Tasa de seguro % x CIF — comparar con mínima, mostrar solo el mayor
    var calcSeg = cif * tarifaNum;
    // Buscar mínima: primero en _minimaItem, luego en todosItemsSvc
    var minValSeg = minimaAsociada;
    if(!minValSeg && todosItemsSvc){
      var minSegItem = todosItemsSvc.find(function(i){
        var g=(i._grupo||'').toLowerCase(), n=(i.nombre||'').toLowerCase();
        var iPct = i.tipoTarifa==='porcentaje'||String(i.tarifa||'').includes('%');
        return !iPct && (g.includes('segur')||n.includes('segur')||g.includes('minim')||n.includes('minim'));
      });
      if(minSegItem) minValSeg = parsePreliqNum(minSegItem.tarifa);
    }
    if(minValSeg > 0){
      if(calcSeg >= minValSeg){
        resultado = calcSeg;
        base = tarifaPct + ' × $' + cif.toLocaleString('es-CO');
        nota = 'Mayor que la mínima ($' + Math.round(minValSeg).toLocaleString('es-CO') + ').';
      } else {
        resultado = minValSeg;
        base = 'Mínima de seguro';
        nota = 'Calculado $' + Math.round(calcSeg).toLocaleString('es-CO') + ' < mínima.';
      }
    } else {
      resultado = calcSeg;
      base = tarifaPct + ' × $' + cif.toLocaleString('es-CO');
    }
    // Marcar la mínima de seguro como absorbida para no mostrarla como fila aparte
    if(todosItemsSvc) todosItemsSvc._segMinAbsorbida = true;

  } else if(esMinSeg){
    // Mínima de seguro — solo mostrar si NO fue absorbida por la tasa
    if(todosItemsSvc && todosItemsSvc._segMinAbsorbida) return null;
    resultado = tarifaNum;
    base = 'Mínima de seguro';

  } else if(esPallet && !esPct){
    // Almacenamiento por pallet — comparar con mínima, mostrar solo el mayor
    var n = pallets||1;
    var calcPal = tarifaNum * n;
    if(minimaAsociada > 0 && calcPal < minimaAsociada){
      resultado = minimaAsociada;
      base = 'Mínima de almacenamiento';
      nota = 'Calculado $'+Math.round(calcPal).toLocaleString('es-CO')+' ('+n+' pallets) < mínima. Se cobra mínima.';
    } else {
      resultado = calcPal;
      base = '$'+tarifaNum.toLocaleString('es-CO')+' x '+n+' pallets/posiciones';
      if(minimaAsociada>0) nota = 'Mayor que mínima ($'+Math.round(minimaAsociada).toLocaleString('es-CO')+').';
    }

  } else if(esKg && !esPct){
    // Por kilo (Valor Kilo) — comparar con minima si existe, cobrar el mayor
    var calcKg = tarifaNum * peso;
    if(minimaAsociada > 0){
      if(calcKg >= minimaAsociada){
        resultado = calcKg;
        base = '$' + tarifaNum.toLocaleString('es-CO') + '/kg x ' + peso.toLocaleString('es-CO') + ' kg';
        nota = 'Mayor que la minima ($' + Math.round(minimaAsociada).toLocaleString('es-CO') + '). Se cobra el calculo.';
      } else {
        resultado = minimaAsociada;
        base = 'Minima de manipulacion';
        nota = 'Calculado $' + Math.round(calcKg).toLocaleString('es-CO') + ' < minima. Se cobra minima.';
      }
    } else {
      resultado = calcKg;
      base = '$' + tarifaNum.toLocaleString('es-CO') + '/kg x ' + peso.toLocaleString('es-CO') + ' kg';
    }

  } else if(esManip && !esPct){
    // Minima de manipulacion sola (sin Valor Kilo asociado)
    var mult = esCont ? numCont : 1;
    resultado = tarifaNum * mult;
    base = mult>1 ? ('$'+tarifaNum.toLocaleString('es-CO')+' x '+mult+' contenedor(es)')
                  : ('$'+tarifaNum.toLocaleString('es-CO')+' (minima)');

  } else if(esDespach && !esPct){
    var multU = (nom.includes('unidad')||nom.includes('caja')||nom.includes('und')) ? (unidades||1) : 1;
    resultado = tarifaNum * multU;
    base = multU>1 ? ('$'+tarifaNum.toLocaleString('es-CO')+' x '+multU+' unidades')
                   : ('$'+tarifaNum.toLocaleString('es-CO'));

  } else if(esPct){
    resultado = cif * tarifaNum;
    base = tarifaPct + ' × $' + cif.toLocaleString('es-CO');

  } else {
    resultado = tarifaNum;
    base = '$' + tarifaNum.toLocaleString('es-CO') + ' (tarifa fija)';
  }

  var concepto = item._grupo || item.nombre;
  return {concepto: concepto, base: base, resultado: Math.round(resultado), nota: nota};
}

// MOSTRAR RESULTADO
function preliqMostrarResultado(cot, svc, producto, cif, peso, tipo, numCont, pallets, lineas){
  var svcsArr  = Array.isArray(svc) ? svc : [svc];
  var svcLabel = svcsArr.join(' + ');
  window._preliqState = {cot:cot, svc:svc, producto:producto, cif:cif, peso:peso, tipo:tipo, numCont:numCont, pallets:pallets, lineas:lineas};

  var total = lineas.filter(function(l){ return !l._seccion; }).reduce(function(s,l){ return s+(l.resultado||0); }, 0);
  var now   = new Date();
  var fecha = now.toLocaleDateString('es-CO',{day:'2-digit',month:'long',year:'numeric'});
  var hora  = now.toLocaleTimeString('es-CO',{hour:'2-digit',minute:'2-digit'});
  var tipoLabel = tipo==='lcl'?'Aerea / LCL':tipo==='cont20'?('Cont. 20\' x '+numCont):tipo==='cont40'?('Cont. 40\' x '+numCont):'';
  var svcColors = {'Zona Franca':'#00c2ff','CEDI':'#00e676','Deposito Aduanero':'#a78bfa','Transporte':'#f5a623','Paqueteo':'#ff6b6b','Aduana':'#ffd700'};

  var lineasHTML = '';
  lineas.forEach(function(l){
    if(l._seccion){
      var col = svcColors[l._seccion]||'var(--accent)';
      var logoR2 = SVC_LOGOS[l._seccion] || null;
      var logoTag2 = logoR2 ? '<img src="'+logoR2+'" style="height:22px;width:auto;object-fit:contain;vertical-align:middle;margin-right:8px;border-radius:3px" alt="'+l._seccion+'">' : '';
      lineasHTML += '<tr><td colspan="4" style="padding:12px 16px 6px;background:rgba(0,0,0,0.2)">'+logoTag2+'<span style="font-size:12px;font-weight:800;letter-spacing:2px;text-transform:uppercase;color:' + col + '">' + l._seccion + '</span></td></tr>';
    } else {
      var valColor = l.resultado>0 ? 'var(--green)' : 'var(--text2)';
      var valStr   = l.resultado>0 ? '$'+Math.round(l.resultado).toLocaleString('es-CO') : '--';
      lineasHTML += '<tr>';
      lineasHTML += '<td style="padding:11px 16px;border-bottom:1px solid var(--border);font-size:13px;color:var(--text);font-weight:500">' + l.concepto + '</td>';
      lineasHTML += '<td style="padding:11px 16px;border-bottom:1px solid var(--border);font-size:12px;color:var(--text2)">' + l.base + '</td>';
      lineasHTML += '<td style="padding:11px 16px;border-bottom:1px solid var(--border);font-size:12px;color:var(--text2);font-style:italic">' + (l.nota||'') + '</td>';
      lineasHTML += '<td style="padding:11px 16px;border-bottom:1px solid var(--border);font-size:14px;font-weight:700;color:' + valColor + ';text-align:right;white-space:nowrap">' + valStr + '</td>';
      lineasHTML += '</tr>';
    }
  });

  var chips = '';
  if(producto&&producto!=='--') chips += '<div style="background:rgba(0,194,255,0.08);border:1px solid rgba(0,194,255,0.2);border-radius:8px;padding:8px 14px"><div style="font-size:10px;color:var(--text2);text-transform:uppercase;letter-spacing:1px">Producto</div><div style="font-size:13px;font-weight:600;color:var(--text);margin-top:2px">'+producto+'</div></div>';
  if(cif>0)    chips += '<div style="background:rgba(0,194,255,0.08);border:1px solid rgba(0,194,255,0.2);border-radius:8px;padding:8px 14px"><div style="font-size:10px;color:var(--text2);text-transform:uppercase;letter-spacing:1px">Valor CIF</div><div style="font-size:13px;font-weight:600;color:var(--text);margin-top:2px">$'+cif.toLocaleString('es-CO')+'</div></div>';
  if(peso>0)   chips += '<div style="background:rgba(0,194,255,0.08);border:1px solid rgba(0,194,255,0.2);border-radius:8px;padding:8px 14px"><div style="font-size:10px;color:var(--text2);text-transform:uppercase;letter-spacing:1px">Peso</div><div style="font-size:13px;font-weight:600;color:var(--text);margin-top:2px">'+peso.toLocaleString('es-CO')+' kg</div></div>';
  if(tipoLabel) chips += '<div style="background:rgba(0,194,255,0.08);border:1px solid rgba(0,194,255,0.2);border-radius:8px;padding:8px 14px"><div style="font-size:10px;color:var(--text2);text-transform:uppercase;letter-spacing:1px">Tipo Ingreso</div><div style="font-size:13px;font-weight:600;color:var(--text);margin-top:2px">'+tipoLabel+'</div></div>';
  if(pallets>0) chips += '<div style="background:rgba(0,194,255,0.08);border:1px solid rgba(0,194,255,0.2);border-radius:8px;padding:8px 14px"><div style="font-size:10px;color:var(--text2);text-transform:uppercase;letter-spacing:1px">Pallets</div><div style="font-size:13px;font-weight:600;color:var(--text);margin-top:2px">'+pallets+'</div></div>';

  var html = '';
  html += '<div id="preliq-result-box" style="background:var(--surface);border:1px solid var(--border);border-radius:14px;overflow:hidden">';
  html += '<div style="background:linear-gradient(135deg,#0d2a4a,#0a1f38);padding:24px 28px;border-bottom:2px solid var(--accent)">';
  html += '<div style="display:flex;align-items:flex-start;justify-content:space-between;flex-wrap:wrap;gap:12px">';
  html += '<div><div style="font-size:11px;letter-spacing:3px;color:var(--text2);text-transform:uppercase;margin-bottom:4px">Preliquidacion Estimada</div>';
  html += '<div style="font-size:22px;font-weight:800;color:var(--accent);letter-spacing:1px">'+svcLabel+'</div>';
  html += '<div style="font-size:12px;color:var(--text2);margin-top:3px">Cot. <strong style="color:var(--text)">'+(cot.numero||cot.id)+'</strong> &middot; '+(cot.empresa||'')+'</div></div>';
  html += '<div style="text-align:right;font-size:11px;color:var(--text2)">'+fecha+' &middot; '+hora+'<br>Referencial, sujeta a tarifas vigentes</div></div>';
  if(chips) html += '<div style="display:flex;flex-wrap:wrap;gap:10px;margin-top:16px">'+chips+'</div>';
  html += '</div>';
  html += '<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse">';
  html += '<thead><tr style="background:var(--surface2)">';
  html += '<th style="padding:10px 16px;text-align:left;font-size:11px;letter-spacing:1.5px;color:var(--text2);text-transform:uppercase">Concepto</th>';
  html += '<th style="padding:10px 16px;text-align:left;font-size:11px;letter-spacing:1.5px;color:var(--text2);text-transform:uppercase">Base de calculo</th>';
  html += '<th style="padding:10px 16px;text-align:left;font-size:11px;letter-spacing:1.5px;color:var(--text2);text-transform:uppercase">Nota</th>';
  html += '<th style="padding:10px 16px;text-align:right;font-size:11px;letter-spacing:1.5px;color:var(--text2);text-transform:uppercase">Valor (COP)</th>';
  html += '</tr></thead><tbody>'+lineasHTML+'</tbody></table></div>';
  html += '<div style="padding:18px 28px;background:var(--surface2);border-top:2px solid var(--border);display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px">';
  html += '<div><div style="font-size:11px;color:var(--text2);letter-spacing:1.5px;text-transform:uppercase;margin-bottom:2px">TOTAL ESTIMADO</div>';
  html += '<div style="font-size:32px;font-weight:800;color:var(--green)">$'+total.toLocaleString('es-CO')+' <span style="font-size:16px;color:var(--text2)">COP</span></div></div>';
  html += '<div style="display:flex;gap:10px;flex-wrap:wrap">';
  html += '<button onclick="preliqNuevo()" style="background:var(--surface2);border:1px solid var(--border);color:var(--text2);border-radius:8px;padding:10px 20px;font-size:13px;cursor:pointer">Nueva</button>';
  html += '<button onclick="preliqImprimir()" style="background:var(--surface2);border:1px solid var(--border);color:var(--text);border-radius:8px;padding:10px 20px;font-size:13px;cursor:pointer">Imprimir</button>';
  html += '<button onclick="exportPreliqPDF()" style="background:linear-gradient(135deg,var(--accent),var(--accent2));color:#fff;border:none;border-radius:8px;padding:10px 22px;font-size:14px;font-weight:700;cursor:pointer">PDF</button>';
  html += '</div></div>';
  html += '<div style="padding:12px 24px;background:rgba(245,166,35,0.06);border-top:1px solid rgba(245,166,35,0.2);font-size:12px;color:#f5a623">Estos valores son estimados. La facturacion final puede variar segun las condiciones reales de la operacion.</div>';
  html += '</div>';

  document.getElementById('preliq-resultado').style.display = 'block';
  document.getElementById('preliq-resultado').innerHTML = html;
  document.getElementById('preliq-resultado').scrollIntoView({behavior:'smooth',block:'start'});
  // Guardar en historial
  preliqGuardar(window._preliqState);
}

// HTML para PDF/Impresion
function buildPreliqHTML(state){
  var cot=state.cot, svc=state.svc, producto=state.producto, cif=state.cif, peso=state.peso;
  var tipo=state.tipo, numCont=state.numCont, pallets=state.pallets, lineas=state.lineas;
  var svcsArr  = Array.isArray(svc) ? svc : [svc];
  var svcLabel = svcsArr.join(' + ');
  var total = (lineas||[]).filter(function(l){ return !l._seccion; }).reduce(function(s,l){ return s+(l.resultado||0); }, 0);
  var now   = new Date();
  var fecha = now.toLocaleDateString('es-CO',{day:'2-digit',month:'long',year:'numeric'});
  var hora  = now.toLocaleTimeString('es-CO',{hour:'2-digit',minute:'2-digit'});
  var comercial = db.comerciales.find(function(c){ return c.id===cot.comercialId; });
  var tipoLabel = tipo==='lcl'?'Aérea / LCL':tipo==='cont20'?('Cont. 20\' x '+numCont):tipo==='cont40'?('Cont. 40\' x '+numCont):'';
  var svcColors2 = {'Zona Franca':'#0057a8','CEDI':'#00875a','Depósito Aduanero':'#5b21b6','Transporte':'#b45309','Paqueteo':'#c0392b','Aduana':'#854d0e'};

  var logoHtml = '<img src="'+IMG_LOGO_COT+'" alt="Grupo ZYMO" style="height:80px;max-width:220px;object-fit:contain;display:block">';

  var filasTabla = '';
  (lineas||[]).forEach(function(l){
    if(l._seccion){
      var col = svcColors2[l._seccion]||'#002366';
      var logoP = SVC_LOGOS[l._seccion] || null;
      var logoTag = logoP ? '<img src="'+logoP+'" style="height:22px;width:auto;object-fit:contain;vertical-align:middle;margin-right:8px;border-radius:3px" alt="'+l._seccion+'">' : '';
      filasTabla += '<tr><td colspan="4" style="padding:10px 16px 5px;background:#eef2fb;border-bottom:1px solid #c8d0e8">'+logoTag+'<span style="font-size:11px;font-weight:800;letter-spacing:2px;text-transform:uppercase;color:'+col+'">'+ l._seccion+'</span></td></tr>';
    } else {
      var vc = l.resultado>0?'#00875a':'#999';
      var vs = l.resultado>0?'$'+Math.round(l.resultado).toLocaleString('es-CO'):'--';
      filasTabla += '<tr>'
        + '<td style="padding:9px 16px;border-bottom:1px solid #e8ecf5;font-size:13px;color:#222;font-weight:500">'+l.concepto+'</td>'
        + '<td style="padding:9px 16px;border-bottom:1px solid #e8ecf5;font-size:12px;color:#555">'+l.base+'</td>'
        + '<td style="padding:9px 16px;border-bottom:1px solid #e8ecf5;font-size:11px;color:#888;font-style:italic">'+(l.nota||'')+'</td>'
        + '<td style="padding:9px 16px;border-bottom:1px solid #e8ecf5;font-size:14px;font-weight:700;color:'+vc+';text-align:right;white-space:nowrap">'+vs+'</td>'
        + '</tr>';
    }
  });

  var datosItems = [];
  if(producto&&producto!=='--') datosItems.push({label:'Producto/Mercancía', value:producto});
  if(cif>0)     datosItems.push({label:'Valor CIF', value:'$'+cif.toLocaleString('es-CO')+' COP'});
  if(peso>0)    datosItems.push({label:'Peso Total', value:peso.toLocaleString('es-CO')+' kg'});
  if(tipoLabel) datosItems.push({label:'Tipo de Ingreso', value:tipoLabel});
  if(pallets>0) datosItems.push({label:'Pallets/Posiciones', value:pallets});
  // Comercial solo aparece en la firma al final

  var datosHtml = datosItems.map(function(d){
    return '<div style="min-width:140px">'
      + '<div style="font-size:10px;color:#888;text-transform:uppercase;letter-spacing:1px;font-weight:600;margin-bottom:3px">'+d.label+'</div>'
      + '<div style="font-size:13px;font-weight:700;color:#002366">'+d.value+'</div>'
      + '</div>';
  }).join('');

  // Logos de línea(s) de negocio — igual que en cotizaciones
  var SVC_LOGO_STYLE2 = {
    'Zona Franca':       'max-width:200px;width:auto;height:auto;display:block',
    'Depósito Aduanero': 'max-height:90px;width:auto;display:block',
    'CEDI':              'max-height:90px;width:auto;display:block',
    'Transporte':        'max-height:90px;width:auto;display:block',
    'Paqueteo':          'max-height:90px;width:auto;display:block',
    'Aduana':            'max-width:210px;width:auto;height:auto;display:block',
  };
  var seenLogos2 = {};
  var svcLogosHeader = svcsArr.map(function(s){
    var logo = SVC_LOGOS[s] || null;
    if(logo && !seenLogos2[logo]){
      seenLogos2[logo] = true;
      var st = SVC_LOGO_STYLE2[s] || 'max-width:200px;max-height:90px;width:auto;height:auto;display:block';
      return '<img src="'+logo+'" alt="'+s+'" style="'+st+'">';
    }
    return '';
  }).filter(Boolean).join('');

  var out = '';
  out += '<div style="font-family:Barlow,sans-serif;background:#fff;color:#1a1a2e;padding:48px;max-width:820px;margin:0 auto">';

  // ── ENCABEZADO: mismo layout que cotizaciones ──
  out += '<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:32px;padding-bottom:24px;border-bottom:3px solid #002366">';
  out += '<div>'+logoHtml+'</div>';
  out += '<div style="display:flex;flex-direction:column;align-items:flex-end;gap:10px">';
  out += svcLogosHeader;
  out += '<div style="text-align:right;font-size:13px;color:#555">';
  out += '<strong style="display:block;font-size:18px;color:#002366;font-family:Barlow Condensed,sans-serif;letter-spacing:1px;margin-bottom:4px">PRELIQUIDACIÓN ESTIMADA</strong>';
  out += '<span>Cot. <strong style="color:#002366">'+(cot.numero||cot.id)+'</strong></span><br>';
  out += '<span>Fecha: '+fecha+'</span>';
  out += '</div></div></div>';

  // ── CAJA CLIENTE ──
  out += '<div style="background:#f0f4ff;border-left:4px solid #002366;border-radius:4px;padding:16px 20px;margin-bottom:28px;font-size:13px;color:#333">';
  out += '<strong style="font-size:16px;color:#002366;display:block;margin-bottom:4px">'+(cot.empresa||'—')+'</strong>';
  if(cot.nit) out += '<div style="font-size:12px;color:#666;margin-top:2px">NIT: '+cot.nit+'</div>';
  out += '</div>';

  // ── DATOS DE LA OPERACIÓN ──
  if(datosItems.length > 0){
    out += '<div style="display:flex;flex-wrap:wrap;gap:20px;margin-bottom:28px;padding:16px 20px;background:#fafbff;border:1px solid #e8ecf5;border-radius:6px">';
    out += datosHtml;
    out += '</div>';
  }
  out += '<div>';
  out += '<div style="font-size:11px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:#002366;margin:0 0 12px;padding-bottom:6px;border-bottom:2px solid #002366">Detalle de Cálculo</div>';
  out += '<table style="width:100%;border-collapse:collapse">';
  out += '<thead><tr style="background:#002366;color:#fff">';
  out += '<th style="padding:10px 16px;text-align:left;font-size:11px;letter-spacing:1.5px;text-transform:uppercase">Concepto</th>';
  out += '<th style="padding:10px 16px;text-align:left;font-size:11px;letter-spacing:1.5px;text-transform:uppercase">Base de Cálculo</th>';
  out += '<th style="padding:10px 16px;text-align:left;font-size:11px;letter-spacing:1.5px;text-transform:uppercase">Nota</th>';
  out += '<th style="padding:10px 16px;text-align:right;font-size:11px;letter-spacing:1.5px;text-transform:uppercase">Valor (COP)</th>';
  out += '</tr></thead><tbody>'+filasTabla+'</tbody></table></div>';
  out += '<div style="margin:20px 0;background:linear-gradient(135deg,#002366,#001a50);border-radius:10px;padding:18px 28px;display:flex;align-items:center;justify-content:space-between">';
  out += '<div>';
  out += '<div style="font-size:11px;letter-spacing:2px;text-transform:uppercase;color:rgba(255,255,255,0.7);font-weight:600">Total Estimado</div>';
  out += '<div style="font-size:11px;color:rgba(255,255,255,0.5);margin-top:2px">Sujeto a tarifas y condiciones vigentes</div>';
  out += '</div>';
  out += '<div style="font-size:32px;font-weight:800;color:#00e676">$'+total.toLocaleString('es-CO')+' <span style="font-size:15px;color:rgba(255,255,255,0.6)">COP</span></div>';
  out += '</div>';
  out += '<div style="margin:0 0 24px;background:#fff8e1;border-left:4px solid #f5a623;padding:12px 16px;font-size:12px;color:#7a5c00;border-radius:0 6px 6px 0">';
  out += '<strong>Nota:</strong> Esta preliquidación es estimada y de carácter referencial. Los valores finales pueden variar según las condiciones reales de la operación.';
  out += '</div>';
  if(comercial){
    out += '<div style="margin:0 0 32px;display:flex;justify-content:flex-end">';
    out += '<div style="min-width:260px;text-align:center">';
    out += _firmaImg(comercial.nombre);
    out += '<div style="border-bottom:2px solid #002366;margin-bottom:10px"></div>';
    out += '<div style="font-size:14px;font-weight:700;color:#002366">'+comercial.nombre+'</div>';
    out += '<div style="font-size:12px;color:#555;margin-top:3px">'+(comercial.cargo||'Asesor Comercial')+' &middot; Grupo ZYMO</div>';
    if(comercial.email) out += '<div style="font-size:11px;color:#888;margin-top:2px">'+comercial.email+'</div>';
    if(comercial.tel)   out += '<div style="font-size:11px;color:#888">'+comercial.tel+'</div>';
    out += '</div></div>';
  }
  out += '<div style="margin:0 -48px -48px;padding:14px 48px;background:#002366;display:flex;justify-content:space-between;align-items:center;border-radius:0 0 8px 8px">';
  out += '<span style="font-size:11px;color:rgba(255,255,255,0.6)">Grupo ZYMO &mdash; www.logimat.com.co</span>';
  out += '<span style="font-size:11px;color:rgba(255,255,255,0.6)">Preliq. basada en Cot. '+(cot.numero||cot.id)+' &middot; Generado el '+fecha+'</span>';
  out += '</div>';
  out += '</div>';
  return '<div class="cot-preview" id="preliq-doc" style="max-width:860px">' + out + '</div>';
}


function exportPreliqPDF(){
  if(!window._preliqState){ toast('⚠️','No hay preliquidación activa','#f5a623'); return; }
  if(typeof html2canvas==='undefined'||typeof jspdf==='undefined'){ toast('⚠️','Cargando librerías, intenta en 3s','#f5a623'); return; }
  var jsPDF = jspdf.jsPDF;
  var state = window._preliqState;
  var cotContent = document.getElementById('cot-publica-content');
  var prevHtml   = cotContent.innerHTML;
  var prevTitle  = document.title;
  cotContent.innerHTML = buildPreliqHTML(state);
  document.title = 'Preliquidación ' + (state.cot.numero||state.cot.id);
  var allPages = document.querySelectorAll('.page');
  var prevActive = [];
  allPages.forEach(function(p){ if(p.classList.contains('active')){ prevActive.push(p.id); p.classList.remove('active'); } });
  document.getElementById('page-cot-publica').classList.add('active');
  var btnBar = document.getElementById('cot-publica-actions');
  if(btnBar) btnBar.style.visibility = 'hidden';
  toast('⏳','Generando PDF...','#00c2ff');
  var restoreView = function(){
    if(btnBar) btnBar.style.visibility = '';
    cotContent.innerHTML = prevHtml;
    document.title = prevTitle;
    document.getElementById('page-cot-publica').classList.remove('active');
    prevActive.forEach(function(id){ var el=document.getElementById(id); if(el) el.classList.add('active'); });
  };
  setTimeout(function(){
    var target = document.querySelector('#page-cot-publica .cot-preview') || cotContent;
    var prevPad = target.style.padding; var prevRad = target.style.borderRadius; var prevSha = target.style.boxShadow;
    target.style.padding='24px 28px'; target.style.borderRadius='0'; target.style.boxShadow='none';
    html2canvas(target,{
      scale:3, useCORS:true, allowTaint:true, backgroundColor:'#ffffff', logging:false,
      scrollX:0, scrollY:-window.scrollY, windowWidth:target.scrollWidth, windowHeight:target.scrollHeight
    }).then(function(canvas){
      target.style.padding=prevPad; target.style.borderRadius=prevRad; target.style.boxShadow=prevSha;
      restoreView();
      var ctx=canvas.getContext('2d'), trimH=canvas.height;
      for(var row=canvas.height-1;row>=0;row--){
        var rd=ctx.getImageData(0,row,canvas.width,1).data, allW=true;
        for(var i=0;i<rd.length;i+=4){ if(rd[i]<240||rd[i+1]<240||rd[i+2]<240){allW=false;break;} }
        if(!allW){trimH=row+1;break;}
      }
      var tc=document.createElement('canvas'); tc.width=canvas.width; tc.height=trimH;
      tc.getContext('2d').drawImage(canvas,0,0,canvas.width,trimH,0,0,canvas.width,trimH);
      var pdf=new jsPDF({orientation:'portrait',unit:'mm',format:'a4'});
      var pw=210,ph=297,mg=8,iw=pw-mg*2,ih=ph-mg*2,mmPx=iw/tc.width,totMM=tc.height*mmPx;
      if(totMM<=ih){
        pdf.addImage(tc.toDataURL('image/png'),'PNG',mg,mg,iw,totMM);
      } else {
        var ctx2=tc.getContext('2d'),ppP=Math.floor(ih/mmPx),offPx=0,pg=0;
        while(offPx<tc.height){
          if(pg>0) pdf.addPage();
          var cutPx=Math.min(offPx+ppP,tc.height);
          if(cutPx<tc.height){ var sr=Math.floor(ppP*0.05),bR=cutPx,mW=-1;
            for(var r=cutPx-sr;r<=cutPx+sr&&r<tc.height;r++){
              var rd2=ctx2.getImageData(0,r,tc.width,1).data,ws=0;
              for(var k=0;k<rd2.length;k+=4){ if(rd2[k]>240&&rd2[k+1]>240&&rd2[k+2]>240)ws++; }
              if(ws>mW){mW=ws;bR=r;}
            } cutPx=bR;
          }
          var sh=cutPx-offPx,sm=sh*mmPx;
          var sl=document.createElement('canvas'); sl.width=tc.width; sl.height=sh;
          sl.getContext('2d').drawImage(tc,0,offPx,tc.width,sh,0,0,tc.width,sh);
          pdf.addImage(sl.toDataURL('image/png'),'PNG',mg,mg,iw,sm);
          offPx=cutPx; pg++;
        }
      }
      pdf.save('Preliquidacion_'+(state.cot.numero||state.cot.id).replace(/\s/g,'_')+'.pdf');
      toast('✅','PDF descargado','#00e676');
    }).catch(function(){
      restoreView();
      toast('⚠️','Error generando PDF','#ff6b6b');
    });
  },500);
}


function preliqImprimir(){
  if(!window._preliqState){ toast('\u26a0\ufe0f','No hay preliquidacion activa','#f5a623'); return; }
  var state=window._preliqState;
  var cotContent=document.getElementById('cot-publica-content'),prevHtml=cotContent.innerHTML,prevTitle=document.title;
  cotContent.innerHTML=buildPreliqHTML(state);
  document.title='Preliquidacion '+(state.cot.numero||state.cot.id);
  var allPages=document.querySelectorAll('.page'),prevActive=[];
  allPages.forEach(function(p){ if(p.classList.contains('active')){ prevActive.push(p.id); p.classList.remove('active'); } });
  document.getElementById('page-cot-publica').classList.add('active');
  var btnBar=document.getElementById('cot-publica-actions'); if(btnBar) btnBar.style.visibility='hidden';
  setTimeout(function(){
    window.print();
    setTimeout(function(){
      if(btnBar) btnBar.style.visibility='';
      cotContent.innerHTML=prevHtml; document.title=prevTitle;
      document.getElementById('page-cot-publica').classList.remove('active');
      prevActive.forEach(function(id){ var el=document.getElementById(id); if(el) el.classList.add('active'); });
    },1000);
  },400);
}

function preliqNuevo(){
  var s = document.getElementById('preliq-cot-search'); if(s) s.value='';
  document.getElementById('preliq-cot-sel').value = '';
  var dd = document.getElementById('preliq-cot-dropdown'); if(dd) dd.style.display='none';
  document.getElementById('preliq-cot-info').innerHTML = '';
  document.getElementById('preliq-svcs-row').style.display = 'none';
  document.getElementById('preliq-form-card').style.display = 'none';
  document.getElementById('preliq-resultado').style.display = 'none';
  var ff = document.getElementById('preliq-form-fields'); if(ff) ff.innerHTML='';
  var bb = document.getElementById('preliq-svcs-btns'); if(bb) bb.innerHTML='';
  window._preliqItemsSeleccionados = [];
  window._preliqState = null;
  preliqRenderHistorial();
}


// ============================================================
// HISTORIAL DE PRELIQUIDACIONES
// ============================================================

function preliqGuardar(state){
  var hist = JSON.parse(localStorage.getItem('zymo-preliq-hist')||'[]');
  var entry = {
    id:      'plq-' + Date.now(),
    fecha:   new Date().toLocaleDateString('es-CO',{day:'2-digit',month:'2-digit',year:'numeric'}),
    hora:    new Date().toLocaleTimeString('es-CO',{hour:'2-digit',minute:'2-digit'}),
    empresa: state.cot.empresa||'',
    cot:     state.cot.numero||state.cot.id,
    svcs:    Array.isArray(state.svc) ? state.svc.join(', ') : state.svc,
    total:   (state.lineas||[]).filter(function(l){return !l._seccion;}).reduce(function(s,l){return s+(l.resultado||0);},0),
    state:   state
  };
  hist.unshift(entry);
  // Mantener maximo 50 registros
  if(hist.length > 50) hist = hist.slice(0,50);
  localStorage.setItem('zymo-preliq-hist', JSON.stringify(hist));
  preliqRenderHistorial();
}

function preliqEliminar(id){
  if(!confirm('Eliminar esta preliquidacion del historial?')) return;
  var hist = JSON.parse(localStorage.getItem('zymo-preliq-hist')||'[]');
  hist = hist.filter(function(e){ return e.id !== id; });
  localStorage.setItem('zymo-preliq-hist', JSON.stringify(hist));
  preliqRenderHistorial();
  toast('🗑️','Preliquidacion eliminada','#f5a623');
}

function preliqVerHistorial(id){
  var hist = JSON.parse(localStorage.getItem('zymo-preliq-hist')||'[]');
  var entry = hist.find(function(e){ return e.id===id; });
  if(!entry) return;
  window._preliqState = entry.state;
  var s = entry.state;
  preliqMostrarResultado(s.cot, s.svc, s.producto, s.cif, s.peso, s.tipo, s.numCont, s.pallets, s.lineas);
  document.getElementById('preliq-resultado').scrollIntoView({behavior:'smooth',block:'start'});
}

function preliqRenderHistorial(){
  var el = document.getElementById('preliq-historial-lista');
  if(!el) return;
  var hist = JSON.parse(localStorage.getItem('zymo-preliq-hist')||'[]');
  if(!hist.length){
    el.innerHTML = '<div style="color:var(--text2);font-size:13px;padding:16px;text-align:center;background:var(--surface);border:1px solid var(--border);border-radius:12px">No hay preliquidaciones guardadas.</div>';
    return;
  }
  var html = '<div style="display:flex;flex-direction:column;gap:10px">';
  hist.forEach(function(e){
    html += '<div style="background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:16px 20px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px">';
    html += '<div style="flex:1;min-width:0">';
    html += '<div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:4px">';
    html += '<span style="font-size:14px;font-weight:700;color:var(--text)">'+e.empresa+'</span>';
    html += '<span style="font-size:11px;color:var(--text2);background:var(--surface2);border:1px solid var(--border);border-radius:6px;padding:2px 8px">Cot. '+e.cot+'</span>';
    html += '<span style="font-size:11px;color:var(--accent);background:rgba(0,194,255,0.08);border:1px solid rgba(0,194,255,0.2);border-radius:6px;padding:2px 8px">'+e.svcs+'</span>';
    html += '</div>';
    html += '<div style="font-size:12px;color:var(--text2)">'+e.fecha+' '+e.hora+'</div>';
    html += '</div>';
    html += '<div style="display:flex;align-items:center;gap:16px">';
    html += '<div style="text-align:right"><div style="font-size:10px;color:var(--text2);text-transform:uppercase;letter-spacing:1px">Total</div>';
    html += '<div style="font-size:18px;font-weight:800;color:var(--green);font-family:\'Barlow Condensed\',sans-serif">$'+e.total.toLocaleString('es-CO')+'</div></div>';
    html += '<div style="display:flex;gap:8px">';
    html += '<button onclick="preliqVerHistorial(\''+e.id+'\')" style="background:var(--surface2);border:1px solid var(--border);color:var(--text);border-radius:8px;padding:8px 14px;font-size:12px;cursor:pointer">Ver</button>';
    html += '<button onclick="preliqEliminar(\''+e.id+'\')" style="background:rgba(255,107,107,0.1);border:1px solid rgba(255,107,107,0.3);color:#ff6b6b;border-radius:8px;padding:8px 14px;font-size:12px;cursor:pointer">🗑️</button>';
    html += '</div></div></div>';
  });
  html += '</div>';
  el.innerHTML = html;
}

