// Calcular % de cumplimiento ponderado de un cliente
function gdCumplimientoPct(clienteId){
  var gd = gdGetData(clienteId);
  var r  = db.records.find(function(x){ return x.id===clienteId; });
  var tc = r ? (r.tipoCliente||'directo') : 'directo';
  var esReferido = tc === 'referido';
  var docsApl = GD_DOCS.filter(function(d){ return esReferido ? d.aplica === 'todos' : true; });
  // Si el ciclo es de año anterior → todos los docs valen 0
  var ciclo = gdCicloActual(clienteId);
  var desact = ciclo < new Date().getFullYear();
  var totalPond = 0, cumplido = 0;
  docsApl.forEach(function(d){
    var pond = esReferido ? d.pond_ref : d.pond_di;
    if(!pond) return;
    totalPond += pond;
    if(desact) return;
    var est = (gd.docs[d.id]||{}).estado||'';
    if(est === 'completo') cumplido += pond;
    else if(est === 'incompleto') cumplido += pond * 0.5;
  });
  if(totalPond === 0) return 0;
  return Math.round((cumplido / totalPond) * 100);
}

// Color semáforo para el % de cumplimiento
function gdColorPct(pct){
  if(pct >= 80) return '#00e676';
  if(pct >= 50) return '#f5a623';
  return '#ff4444';
}

// Obtener compañías logísticas de un cliente (array de labels, sin duplicados)
function gdCompaniasCliente(r){
  if(!r || !r.servicios) return [];
  var seen = {};
  var result = [];
  r.servicios.forEach(function(s){
    var c = COMPANIAS_LOGISTICAS.find(function(cl){ return cl.key === s; });
    if(c && !seen[c.label]){
      seen[c.label] = true;
      result.push(c.label);
    }
  });
  return result;
}

var GD_STATUS_DOC = {
  completo:  {label:'Completo',             color:'#00e676'},
  incompleto:{label:'Incompleto',           color:'#f5a623'},
  pendiente: {label:'Pendiente por entregar', color:'#ff4444'},
};

var _gdClienteId = null;

function gdGetData(clienteId){
  if(!db.gestionDocumental) db.gestionDocumental = {};
  if(!db.gestionDocumental[clienteId]) db.gestionDocumental[clienteId] = {docs:{}, fechaActualizacion:'', historial:{}};
  if(!db.gestionDocumental[clienteId].historial) db.gestionDocumental[clienteId].historial = {};
  return db.gestionDocumental[clienteId];
}

function gdCicloActual(clienteId){
  var gd = gdGetData(clienteId);
  return gd.cicloActual || new Date().getFullYear();
}

function gdIniciarCiclo(clienteId){
  var anoNuevo = new Date().getFullYear();
  var gd = gdGetData(clienteId);
  var cicloAnterior = gdCicloActual(clienteId);
  if(cicloAnterior >= anoNuevo){ toast('Aviso','El ciclo '+anoNuevo+' ya está activo','#f59e0b'); return; }
  if(!confirm('¿Iniciar ciclo '+anoNuevo+'?\n\nLos documentos del ciclo '+cicloAnterior+' quedarán archivados y todos los estados pasarán a Pendiente.')){ return; }
  if(!gd.historial) gd.historial = {};
  gd.historial[cicloAnterior] = {
    ano: cicloAnterior,
    docs: JSON.parse(JSON.stringify(gd.docs)),
    fechaActualizacion: gd.fechaActualizacion,
    archivedAt: new Date().toISOString()
  };
  GD_DOCS.forEach(function(doc){
    gd.docs[doc.id] = {estado:'pendiente', obs:'', fecha:'', archivos:[]};
  });
  gd.fechaActualizacion = '';
  gd.cicloActual = anoNuevo;
  try { save(); } catch(e){}
  if(_gdClienteId === clienteId){ abrirModalGD(clienteId); }
  renderGestionDocumental();
  toast('Ciclo iniciado','Ciclo '+anoNuevo+' activo — docs del '+cicloAnterior+' archivados','#34d399');
}

function gdAbrirHistorial(clienteId){
  var gd = gdGetData(clienteId);
  var r  = db.records.find(function(x){ return x.id===clienteId; });
  var empresa = r ? r.empresa : '—';
  var historial = gd.historial || {};
  var anos = Object.keys(historial).map(Number).sort(function(a,b){return b-a;});
  var ECOL = {completo:'#34d399', incompleto:'#f59e0b', pendiente:'#f87171'};
  var ELBL = {completo:'Completo', incompleto:'Incompleto', pendiente:'Pendiente'};
  var modal = document.getElementById('modal-gd-historial');
  if(!modal){
    modal = document.createElement('div');
    modal.id = 'modal-gd-historial';
    modal.style.cssText = 'display:none;position:fixed;inset:0;background:rgba(0,0,0,0.75);backdrop-filter:blur(3px);z-index:99999;overflow-y:auto;padding:24px 16px';
    document.body.appendChild(modal);
  }
  var anosHTML = anos.length === 0
    ? '<div style="text-align:center;padding:48px 20px;color:var(--text2);font-size:14px">Sin ciclos archivados. El historial se crea al iniciar un nuevo ciclo anual.</div>'
    : anos.map(function(ano){
        var h = historial[ano];
        var archivedDate = h.archivedAt ? new Date(h.archivedAt).toLocaleDateString('es-CO',{day:'2-digit',month:'long',year:'numeric'}) : '—';
        var completos=0,incompletos=0,pendientes=0;
        GD_DOCS.forEach(function(d){ var est=(h.docs[d.id]||{}).estado||''; if(est==='completo')completos++; else if(est==='incompleto')incompletos++; else pendientes++; });
        var pctComp = Math.round((completos/GD_DOCS.length)*100);
        return '<details style="background:var(--surface2);border:1px solid var(--border);border-radius:10px;margin-bottom:14px;overflow:hidden" open>'
          +'<summary style="background:var(--surface3);border-bottom:1px solid var(--border);padding:12px 18px;cursor:pointer;display:flex;align-items:center;justify-content:space-between;gap:10px;list-style:none">'
          +'<div><span style="font-family:Barlow Condensed,sans-serif;font-size:19px;font-weight:800;color:var(--accent)">Ciclo '+ano+'</span>'
          +'<span style="font-size:11px;color:var(--text2);margin-left:12px">Archivado el '+archivedDate+'</span></div>'
          +'<div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center">'
          +'<span style="font-size:10px;background:#34d39918;color:#34d399;border:1px solid #34d39938;padding:2px 8px;border-radius:8px;font-weight:700">Completos: '+completos+'</span>'
          +'<span style="font-size:10px;background:#f59e0b18;color:#f59e0b;border:1px solid #f59e0b38;padding:2px 8px;border-radius:8px;font-weight:700">Incompletos: '+incompletos+'</span>'
          +'<span style="font-size:10px;background:#f8717118;color:#f87171;border:1px solid #f8717138;padding:2px 8px;border-radius:8px;font-weight:700">Pendientes: '+pendientes+'</span>'
          +'<span style="font-size:13px;font-weight:800;color:var(--text);margin-left:4px">'+pctComp+'%</span>'
          +'</div></summary>'
          +'<div style="padding:10px 18px;display:flex;flex-direction:column;gap:5px">'
          +GD_DOCS.map(function(doc){
              var d=h.docs[doc.id]||{};
              var est=d.estado||'';
              var col=ECOL[est]||'#64748b';
              var lbl=ELBL[est]||'Sin gestionar';
              var nA=(d.archivos||[]).length;
              return '<div style="display:flex;align-items:center;gap:8px;padding:5px 6px;border-radius:6px">'
                +'<span style="width:7px;height:7px;border-radius:50%;background:'+col+';flex-shrink:0"></span>'
                +'<span style="font-size:12px;color:var(--text);flex:1;line-height:1.3">'+doc.nombre+'</span>'
                +(d.fecha?'<span style="font-size:10px;color:var(--text2);white-space:nowrap">'+d.fecha+'</span>':'')
                +(nA?'<span style="font-size:10px;background:rgba(56,189,248,0.1);color:var(--accent);border:1px solid rgba(56,189,248,0.2);padding:1px 6px;border-radius:6px;white-space:nowrap">Archivos: '+nA+'</span>':'')
                +'<span style="font-size:10px;font-weight:700;background:'+col+'18;color:'+col+';border:1px solid '+col+'35;padding:1px 7px;border-radius:7px;white-space:nowrap">'+lbl+'</span>'
                +'</div>';
            }).join('')
          +'</div></details>';
      }).join('');
  modal.innerHTML = '<div style="max-width:900px;margin:0 auto;background:var(--surface);border:1px solid var(--border);border-radius:12px;overflow:hidden">'
    +'<div style="border-bottom:1px solid var(--border);padding:14px 22px;display:flex;align-items:center;justify-content:space-between">'
    +'<div><div style="font-family:Barlow Condensed,sans-serif;font-size:17px;font-weight:700;letter-spacing:1px;text-transform:uppercase">Historial Documental por Ciclo</div>'
    +'<div style="font-size:13px;color:var(--text2);margin-top:1px">'+empresa+'</div></div>'
    +'<button onclick="document.getElementById(\'modal-gd-historial\').style.display=\'none\'" style="background:none;border:1px solid var(--border);color:var(--text2);border-radius:6px;padding:6px 14px;cursor:pointer;font-size:13px">Cerrar</button>'
    +'</div><div style="padding:18px 22px">'+anosHTML+'</div></div>';
  modal.style.display = 'block';
}

function gdAsignarVisitaCRM(clienteId){
  var r = db.records.find(function(x){ return x.id===clienteId; });
  if(!r){ toast('Aviso','Cliente no encontrado','#f59e0b'); return; }
  var fecha = prompt('Fecha para la visita (YYYY-MM-DD):', new Date().toISOString().slice(0,10));
  if(!fecha) return;
  if(fecha.length!==10){ toast('Aviso','Formato inválido. Usa YYYY-MM-DD','#f59e0b'); return; }
  var meta = crmGetMeta(clienteId);
  if(!meta.actividades) meta.actividades = [];
  var yaExiste = meta.actividades.some(function(a){ return a.tipo==='visita' && a.desc==='Realizar Visita — FR-004-GC' && !a.done; });
  if(yaExiste){ toast('Aviso','Ya existe una visita pendiente en el CRM','#f59e0b'); return; }
  meta.actividades.push({tipo:'visita', desc:'Realizar Visita — FR-004-GC', fecha:fecha, done:false, creadoEn:new Date().toISOString(), origen:'gestion-documental'});
  crmSaveMeta(clienteId, meta);
  try { save(); } catch(e){}
  toast('Visita asignada','Visita asignada al Comercial para '+fecha,'#34d399');
  renderCRM();
}

function gdFechaActualizacion(clienteId){
  var gd = gdGetData(clienteId);
  // Usar la fecha del FR-001-GC si está marcado como completo
  if(gd.docs['fr001'] && gd.docs['fr001'].estado==='completo' && gd.docs['fr001'].fecha){
    return gd.docs['fr001'].fecha;
  }
  return gd.fechaActualizacion || '';
}

function gdStatusVencimiento(clienteId, diasAlerta){
  diasAlerta = diasAlerta || (gdGetConfigCorreo().dias || 60);
  var fecha = gdFechaActualizacion(clienteId);
  if(!fecha) return {status:'sin-fecha', label:'Sin fecha', color:'#888', dias: null};
  var ultima = new Date(fecha);
  var proxima = new Date(ultima);
  proxima.setFullYear(proxima.getFullYear() + 1);
  var hoy = new Date();
  hoy.setHours(0,0,0,0);
  var diasRestantes = Math.ceil((proxima - hoy) / (1000*60*60*24));
  if(diasRestantes < 0)           return {status:'vencido',    label:'Vencido',               color:'#ff4444', dias: diasRestantes, proxima: proxima};
  if(diasRestantes <= diasAlerta) return {status:'por-vencer', label:'⚠️ Por Vencer',         color:'#f5a623', dias: diasRestantes, proxima: proxima};
  return                                 {status:'con-tiempo', label:'Con Tiempo',             color:'#00e676', dias: diasRestantes, proxima: proxima};
}

function gdStatusDocs(clienteId){
  var gd = gdGetData(clienteId);
  var r  = db.records.find(function(x){ return x.id===clienteId; });
  var tc = r ? (r.tipoCliente||'directo') : 'directo';
  var ciclo = gdCicloActual(clienteId);
  var anoActual = new Date().getFullYear();
  if(ciclo < anoActual){ return {key:'desactualizado', label:'Requiere actualización '+anoActual, color:'#f87171'}; }
  var docsApl = GD_DOCS.filter(function(d){ return tc==='referido' ? d.aplica==='todos' : true; });
  var estados = docsApl.map(function(d){ return (gd.docs[d.id]||{}).estado||''; });
  var tienePendiente  = estados.some(function(e){ return e==='pendiente'; });
  var tieneIncompleto = estados.some(function(e){ return e==='incompleto'; });
  var todosCompletos  = estados.every(function(e){ return e==='completo'; });
  if(tienePendiente)  return {key:'pendiente',  label:'Pendiente por entregar', color:'#f87171'};
  if(tieneIncompleto) return {key:'incompleto', label:'Incompleto',             color:'#f59e0b'};
  if(todosCompletos)  return {key:'completo',   label:'Completo',               color:'#34d399'};
  return {key:'pendiente', label:'Pendiente por entregar', color:'#f87171'};
}

function fmtFechaGD(dateStr){
  if(!dateStr) return '—';
  var p = dateStr.split('-');
  return p[2]+'/'+p[1]+'/'+p[0];
}

function syncGDScroll(wrap){
  var track = document.getElementById('gd-scroll-track');
  if(track) track.scrollLeft = wrap.scrollLeft;
}
function initGDScrollSync(){
  var wrap  = document.getElementById('gd-wrap-scroll');
  var track = document.getElementById('gd-scroll-track');
  var inner = document.getElementById('gd-scroll-inner');
  var bar   = document.getElementById('gd-fixed-scroll');
  if(!wrap||!track||!inner||!bar) return;
  function updateWidth(){
    inner.style.width = wrap.scrollWidth + 'px';
  }
  updateWidth();
  track.addEventListener('scroll', function(){ wrap.scrollLeft = track.scrollLeft; });
  var ro = new ResizeObserver(updateWidth);
  ro.observe(wrap);
  bar.style.display = 'block';
}

// ============================================================
// ALERTAS DE VENCIMIENTO — 90 DÍAS
// ============================================================

// Clave para saber cuándo se enviaron alertas por última vez (evitar spam)
function gdGetAlertKey(clienteId){ return 'zymo-gd-alerta-'+clienteId; }

function gdClientesEnAlerta(){
  var cfg = gdGetConfigCorreo();
  var diasAlerta = cfg.dias || 60;
  var todosClientes = db.records.filter(function(r){ return r.tipo==='cliente'; });
  var porVencer = [], vencidos = [];
  todosClientes.forEach(function(r){
    var sv = gdStatusVencimiento(r.id, diasAlerta);
    if(sv.status === 'vencido')     vencidos.push({r:r, sv:sv});
    else if(sv.status === 'por-vencer') porVencer.push({r:r, sv:sv});
  });
  return { alerta90: [], porVencer: porVencer, vencidos: vencidos };
}

// ============================================================
// CONFIGURACIÓN DE CORREO — GESTIÓN DOCUMENTAL
// ============================================================

var GD_CFG_KEY = 'zymo-gd-email-config';

var GD_PLANTILLA_DEFAULT_ASUNTO = '\u26a0\ufe0f Alerta Gesti\u00f3n Documental BASC \u2014 {{empresa}}';

var GD_PLANTILLA_DEFAULT_CUERPO =
'Estimado/a {{nombre_contacto}},\n\n' +
'Le informamos que los documentos de gesti\u00f3n documental BASC de la empresa {{empresa}} (NIT: {{nit}}) requieren atenci\u00f3n.\n\n' +
'\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n' +
'ESTADO DEL VENCIMIENTO:\n' +
'{{estado_vencimiento}}\n' +
'Fecha de vencimiento: {{fecha_vencimiento}}\n' +
'D\u00edas restantes: {{dias_restantes}}\n' +
'\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n' +
'{{detalle_documentos}}\n\n' +
'Le solicitamos gestionar la actualizaci\u00f3n de los documentos correspondientes a la mayor brevedad posible para mantener la certificaci\u00f3n BASC vigente.\n\n' +
'Para cualquier consulta, no dude en comunicarse con nuestro equipo de Gesti\u00f3n Documental.\n\n' +
'Atentamente,\n' +
'Equipo de Gesti\u00f3n Documental BASC\n' +
'Grupo ZYMO\n\n' +
'Fecha de env\u00edo: {{fecha_envio}}';

function gdGetConfigCorreo(){
  try{
    var c = JSON.parse(localStorage.getItem(GD_CFG_KEY)||'{}');
    return {
      serviceId:  c.serviceId  || 'service_gjo0u8f',
      templateId: c.templateId || 'template_lsvvfce',
      publicKey:  c.publicKey  || 'MNYTfOz76NqoOxZp8',
      testEmail:  c.testEmail  || '',
      ccEmail:    c.ccEmail    || '',
      dias:       c.dias       || 60,
      asunto:     c.asunto     || GD_PLANTILLA_DEFAULT_ASUNTO,
      cuerpo:     c.cuerpo     || GD_PLANTILLA_DEFAULT_CUERPO,
    };
  }catch(e){
    return {serviceId:'service_gjo0u8f',templateId:'template_lsvvfce',publicKey:'MNYTfOz76NqoOxZp8',
            testEmail:'',ccEmail:'',dias:60,asunto:GD_PLANTILLA_DEFAULT_ASUNTO,cuerpo:GD_PLANTILLA_DEFAULT_CUERPO};
  }
}

function gdResolverPlantilla(tpl, datos){
  return tpl
    .replace(/\{\{nombre_contacto\}\}/g, datos.nombre_contacto || '\u2014')
    .replace(/\{\{empresa\}\}/g,         datos.empresa         || '\u2014')
    .replace(/\{\{nit\}\}/g,             datos.nit             || '\u2014')
    .replace(/\{\{fecha_vencimiento\}\}/g,datos.fecha_vencimiento|| '\u2014')
    .replace(/\{\{dias_restantes\}\}/g,  datos.dias_restantes  || '\u2014')
    .replace(/\{\{estado_vencimiento\}\}/g,datos.estado_vencimiento|| '\u2014')
    .replace(/\{\{fecha_envio\}\}/g,     datos.fecha_envio     || '\u2014')
    .replace(/\{\{detalle_documentos\}\}/g,datos.detalle_documentos|| '');
}

var GD_PREVIEW_DATOS = {
  nombre_contacto:   'Mar\u00eda Garc\u00eda',
  empresa:           'Importaciones XYZ S.A.S.',
  nit:               '900.123.456-7',
  fecha_vencimiento: '15/08/2025',
  dias_restantes:    '42 d\u00edas',
  estado_vencimiento:'\u26a0\ufe0f Por Vencer',
  fecha_envio:       new Date().toLocaleDateString('es-CO',{day:'2-digit',month:'long',year:'numeric'}),
  detalle_documentos:'Documentos pendientes de actualizaci\u00f3n:\n\u2022 FR-001-GC \u2014 Formulario de Registro\n\u2022 Certificado RUT vigente\n\u2022 C\u00e1mara de Comercio (renovaci\u00f3n anual)',
};

function gdActualizarPreview(){
  var asunto = (document.getElementById('gd-cfg-asunto')||{}).value || '';
  var cuerpo = (document.getElementById('gd-cfg-cuerpo')||{}).value || '';
  var preview = document.getElementById('gd-cfg-preview');
  if(!preview) return;
  var asuntoResuelto = gdResolverPlantilla(asunto, GD_PREVIEW_DATOS);
  var cuerpoResuelto = gdResolverPlantilla(cuerpo, GD_PREVIEW_DATOS);
  preview.innerHTML =
    '<div style="border-bottom:1px solid #ddd;padding-bottom:10px;margin-bottom:14px">'
    + '<div style="font-size:11px;color:#666;margin-bottom:3px">ASUNTO:</div>'
    + '<div style="font-size:14px;font-weight:700;color:#111">'+escHtml(asuntoResuelto)+'</div>'
    + '</div>'
    + '<div style="white-space:pre-wrap;color:#222;font-size:13px;line-height:1.7">'+escHtml(cuerpoResuelto)+'</div>';
}

function gdInsertarVariable(variable){
  var textarea = document.getElementById('gd-cfg-cuerpo');
  if(!textarea) return;
  var start = textarea.selectionStart;
  var end   = textarea.selectionEnd;
  textarea.value = textarea.value.slice(0,start) + variable + textarea.value.slice(end);
  textarea.selectionStart = textarea.selectionEnd = start + variable.length;
  textarea.focus();
  gdActualizarPreview();
}

function gdResetearPlantilla(){
  if(!confirm('\u00bfRestaurar la plantilla por defecto? Se perder\u00e1n los cambios actuales.')) return;
  var ta = document.getElementById('gd-cfg-cuerpo');
  var as = document.getElementById('gd-cfg-asunto');
  if(ta) ta.value = GD_PLANTILLA_DEFAULT_CUERPO;
  if(as) as.value = GD_PLANTILLA_DEFAULT_ASUNTO;
  gdActualizarPreview();
  toast('\u21ba','Plantilla restaurada','#a855f7');
}

function gdToggleConfigCorreo(){
  var panel = document.getElementById('gd-config-correo');
  if(!panel) return;
  var abierto = panel.style.display !== 'none';
  if(abierto){ panel.style.display='none'; return; }
  var cfg = gdGetConfigCorreo();
  document.getElementById('gd-cfg-service').value    = cfg.serviceId;
  document.getElementById('gd-cfg-template').value   = cfg.templateId;
  document.getElementById('gd-cfg-pubkey').value     = cfg.publicKey;
  document.getElementById('gd-cfg-test-email').value = cfg.testEmail;
  document.getElementById('gd-cfg-cc').value         = cfg.ccEmail;
  document.getElementById('gd-cfg-dias').value       = cfg.dias;
  document.getElementById('gd-cfg-dias-label').textContent = cfg.dias+' d\u00edas';
  document.getElementById('gd-cfg-asunto').value     = cfg.asunto;
  document.getElementById('gd-cfg-cuerpo').value     = cfg.cuerpo;
  document.getElementById('gd-cfg-status').textContent = '';
  panel.style.display = 'block';
  setTimeout(gdActualizarPreview, 50);
  panel.scrollIntoView({behavior:'smooth', block:'start'});
}

function gdGuardarConfigCorreo(){
  var cfg = {
    serviceId:  document.getElementById('gd-cfg-service').value.trim()    || 'service_gjo0u8f',
    templateId: document.getElementById('gd-cfg-template').value.trim()   || 'template_lsvvfce',
    publicKey:  document.getElementById('gd-cfg-pubkey').value.trim()     || 'MNYTfOz76NqoOxZp8',
    testEmail:  document.getElementById('gd-cfg-test-email').value.trim() || '',
    ccEmail:    document.getElementById('gd-cfg-cc').value.trim()         || '',
    dias:       parseInt(document.getElementById('gd-cfg-dias').value)    || 60,
    asunto:     document.getElementById('gd-cfg-asunto').value            || GD_PLANTILLA_DEFAULT_ASUNTO,
    cuerpo:     document.getElementById('gd-cfg-cuerpo').value            || GD_PLANTILLA_DEFAULT_CUERPO,
  };
  try{ localStorage.setItem(GD_CFG_KEY, JSON.stringify(cfg)); }catch(e){}
  emailjs.init({ publicKey: cfg.publicKey });
  document.getElementById('gd-cfg-dias-label').textContent = cfg.dias+' d\u00edas';
  var st = document.getElementById('gd-cfg-status');
  if(st){ st.style.color='#00e676'; st.textContent='\u2705 Guardado'; setTimeout(function(){ if(st) st.textContent=''; },3000); }
  toast('\u2705','Configuraci\u00f3n guardada','#00e676');
  renderGestionDocumental();
}

function gdEnviarCorreoPrueba(){
  var cfg = gdGetConfigCorreo();
  var destino = cfg.testEmail || '';
  if(!destino){
    toast('\u26a0\ufe0f','Ingresa un correo de prueba en el campo "Correo de prueba"','#f5a623');
    document.getElementById('gd-cfg-test-email').focus();
    return;
  }
  var st = document.getElementById('gd-cfg-status');
  if(st){ st.style.color='var(--text2)'; st.textContent='\u23f3 Enviando prueba...'; }
  var hoy = new Date().toLocaleDateString('es-CO',{day:'2-digit',month:'long',year:'numeric'});
  var datosPrueba = Object.assign({}, GD_PREVIEW_DATOS, { fecha_envio: hoy });
  var asuntoFinal = gdResolverPlantilla(cfg.asunto, datosPrueba);
  var cuerpoFinal = gdResolverPlantilla(cfg.cuerpo, datosPrueba);
  emailjs.send(cfg.serviceId, cfg.templateId, {
    to_name:          datosPrueba.nombre_contacto,
    to_email:         destino,
    cc_email:         cfg.ccEmail || '',
    empresa:          datosPrueba.empresa,
    fecha_hora:       hoy,
    detalle_clientes: cuerpoFinal,
    total_alertas:    '1 cliente en alerta [PRUEBA]',
    numero_cot: 'PRUEBA-GD',
    contacto:   datosPrueba.nombre_contacto,
    comercial:  'Sistema ZYMO',
    lineas:     '1 cliente en alerta',
    asunto:     asuntoFinal + '\n\n' + cuerpoFinal,
  }).then(function(){
    if(st){ st.style.color='#00e676'; st.textContent='\u2705 Prueba enviada a '+destino; }
    toast('\u2705','Correo de prueba enviado a '+destino,'#00e676');
  }).catch(function(err){
    console.warn('[ZYMO] Error prueba:', err);
    if(st){ st.style.color='#ff4444'; st.textContent='\u274c Error: revisa Service ID, Template ID y Public Key'; }
    toast('\u274c','Error al enviar. Revisa la configuraci\u00f3n','#ff4444');
  });
}

// Inicializar EmailJS con config guardada al cargar
(function(){
  try{
    var cfg = gdGetConfigCorreo();
    emailjs.init({ publicKey: cfg.publicKey });
  }catch(e){}
})();

function gdMostrarBannerAlertas(){
  var el = document.getElementById('gd-banner-alertas');
  if(!el) return;
  var cfg = gdGetConfigCorreo();
  var diasAlerta = cfg.dias || 60;
  var grupos = gdClientesEnAlerta();
  var total = grupos.porVencer.length + grupos.vencidos.length;
  if(total === 0){ el.innerHTML = ''; el.style.display='none'; return; }

  var html = '<div style="background:linear-gradient(135deg,#1a0800,#1a1000);border:1px solid #f5a623;border-radius:14px;padding:20px 24px;margin-bottom:20px">'
    + '<div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;margin-bottom:16px">'
    + '<div style="display:flex;align-items:center;gap:12px">'
    + '<span style="font-size:24px">🔔</span>'
    + '<div>'
    + '<div style="font-family:\'Barlow Condensed\',sans-serif;font-size:17px;font-weight:800;letter-spacing:1.5px;text-transform:uppercase;color:#f5a623">Alertas de Vencimiento Documental</div>'
    + '<div style="font-size:12px;color:var(--text2);margin-top:2px">'+total+' cliente(s) con documentos vencidos o por vencer en los próximos '+diasAlerta+' días</div>'
    + '</div></div>'
    + '<div style="display:flex;gap:10px;flex-wrap:wrap">'
    + '<button onclick="gdFiltrarAlerta(\'por-vencer\')" style="background:rgba(245,166,35,0.15);color:#f5a623;border:1px solid #f5a62360;border-radius:8px;padding:7px 16px;font-size:12px;font-weight:700;cursor:pointer;white-space:nowrap">👁 Ver por vencer</button>'
    + '<button onclick="gdEnviarCorreoAlertas()" id="btn-enviar-alerta-correo" style="background:rgba(0,194,255,0.15);color:var(--accent);border:1px solid rgba(0,194,255,0.4);border-radius:8px;padding:7px 16px;font-size:12px;font-weight:700;cursor:pointer;white-space:nowrap">📧 Enviar alerta por correo</button>'
    + '</div></div>';

  if(grupos.vencidos.length){
    html += '<div style="margin-bottom:12px">'
      + '<div style="font-size:11px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;color:#ff4444;margin-bottom:8px">🔴 Vencidos ('+grupos.vencidos.length+')</div>'
      + '<div style="display:flex;flex-wrap:wrap;gap:8px">'
      + grupos.vencidos.map(function(item){
          var prox = item.sv.proxima ? fmtFechaGD(item.sv.proxima.toISOString().slice(0,10)) : '—';
          return '<div style="background:rgba(255,68,68,0.1);border:1px solid rgba(255,68,68,0.35);border-radius:8px;padding:8px 14px;cursor:pointer" onclick="abrirModalGD(\''+item.r.id+'\')">'
            + '<div style="font-size:13px;font-weight:700;color:var(--text)">'+item.r.empresa+'</div>'
            + '<div style="font-size:11px;color:#ff4444;margin-top:2px">Venció: '+prox+' (hace '+Math.abs(item.sv.dias)+' días)</div>'
            + '</div>';
        }).join('')
      + '</div></div>';
  }

  if(grupos.porVencer.length){
    html += '<div>'
      + '<div style="font-size:11px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;color:#f5a623;margin-bottom:8px">⚠️ Por Vencer — menos de '+diasAlerta+' días ('+grupos.porVencer.length+')</div>'
      + '<div style="display:flex;flex-wrap:wrap;gap:8px">'
      + grupos.porVencer.map(function(item){
          var prox = item.sv.proxima ? fmtFechaGD(item.sv.proxima.toISOString().slice(0,10)) : '—';
          return '<div style="background:rgba(245,166,35,0.1);border:1px solid rgba(245,166,35,0.35);border-radius:8px;padding:8px 14px;cursor:pointer" onclick="abrirModalGD(\''+item.r.id+'\')">'
            + '<div style="font-size:13px;font-weight:700;color:var(--text)">'+item.r.empresa+'</div>'
            + '<div style="font-size:11px;color:#f5a623;margin-top:2px">Vence: '+prox+' (en '+item.sv.dias+' días)</div>'
            + '</div>';
        }).join('')
      + '</div></div>';
  }

  html += '</div>';
  el.innerHTML = html;
  el.style.display = 'block';
}

function gdAutoToastAlertas(){
  var grupos = gdClientesEnAlerta();
  if(grupos.vencidos.length > 0){
    toast('🔴', grupos.vencidos.length+' cliente(s) con documentos VENCIDOS', '#ff4444');
  } else if(grupos.porVencer.length > 0){
    toast('⚠️', grupos.porVencer.length+' cliente(s) con documentos por vencer en menos de 60 días', '#f5a623');
  }
}

function gdFiltrarAlerta(status){
  var sel = document.getElementById('gd-filter-status');
  if(sel){ sel.value = status; renderGestionDocumental(); }
  // Scroll suave a la tabla
  var tabla = document.getElementById('tabla-gd-table');
  if(tabla) tabla.scrollIntoView({behavior:'smooth', block:'start'});
}

function gdEnviarCorreoAlertas(){
  var btn = document.getElementById('btn-enviar-alerta-correo');
  if(btn){ btn.textContent = '⏳ Enviando...'; btn.disabled = true; }

  var cfg    = gdGetConfigCorreo();
  var grupos = gdClientesEnAlerta();
  var todos  = grupos.vencidos.concat(grupos.porVencer).concat(grupos.alerta90);
  var hoy    = new Date().toLocaleDateString('es-CO',{day:'2-digit',month:'long',year:'numeric'});

  // Modo prueba: todos los correos van al testEmail
  var modoTest = !!cfg.testEmail;

  // Agrupar por email del contacto GD de cada cliente
  var porCorreo = {};
  var sinCorreo = [];

  todos.forEach(function(item){
    var r    = item.r;
    var ctGD = r.contactos ? r.contactos.find(function(c){ return c.tipoContacto==='gestion-documental'; }) : null;
    var emailReal  = ctGD && ctGD.email ? ctGD.email.trim() : '';
    var nombre = ctGD && ctGD.nombre ? ctGD.nombre : 'Responsable Documental';
    var emailDest  = modoTest ? cfg.testEmail : emailReal;
    if(!emailDest){ sinCorreo.push(r.empresa); return; }
    var key = modoTest ? cfg.testEmail : emailReal; // agrupar todo en uno si modo test
    if(!porCorreo[key]) porCorreo[key] = { nombre: modoTest ? 'Equipo de prueba' : nombre, items: [], emailReal: emailReal };
    porCorreo[key].items.push(item);
  });

  var correos = Object.keys(porCorreo);
  if(!correos.length){
    toast('⚠️', sinCorreo.length ? 'Ningún cliente tiene contacto GD con correo registrado' : 'No hay clientes en alerta', '#f5a623');
    if(btn){ btn.textContent = '📧 Enviar alerta por correo'; btn.disabled = false; }
    return;
  }

  var enviados = 0, errores = 0;
  var promesas = correos.map(function(emailDest){
    var dest = porCorreo[emailDest];

    // Construir datos para resolver la plantilla — usa el primer cliente si hay varios
    var primeraItem = dest.items[0];
    var sv0  = primeraItem.sv;
    var prox0 = sv0.proxima ? fmtFechaGD(sv0.proxima.toISOString().slice(0,10)) : '—';
    var diasTxt0 = sv0.dias !== null ? (sv0.dias < 0 ? 'Vencido hace '+Math.abs(sv0.dias)+' días' : 'Faltan '+sv0.dias+' días') : '—';
    var estadoTxt0 = sv0.status === 'vencido' ? '🔴 VENCIDO' : '⚠️ Por Vencer';

    // Si hay varios clientes, construir el detalle con todos
    var detalleDoc = dest.items.map(function(item){
      var sv   = item.sv;
      var prox = sv.proxima ? fmtFechaGD(sv.proxima.toISOString().slice(0,10)) : '—';
      var icono = sv.status === 'vencido' ? '🔴' : '⚠️';
      var estadoItem = sv.status === 'vencido'
        ? 'VENCIDO el '+prox+' (hace '+Math.abs(sv.dias)+' días)'
        : 'Vence el '+prox+' (en '+sv.dias+' días)';
      return icono+' '+item.r.empresa+(modoTest && dest.emailReal?' [→'+dest.emailReal+']':'')+': '+estadoItem;
    }).join('\n');

    var datosPlantilla = {
      nombre_contacto:   dest.nombre,
      empresa:           dest.items.map(function(i){ return i.r.empresa; }).join(', '),
      nit:               primeraItem.r.nit || '—',
      fecha_vencimiento: prox0,
      dias_restantes:    diasTxt0,
      estado_vencimiento:estadoTxt0,
      fecha_envio:       hoy,
      detalle_documentos:detalleDoc,
    };

    var asuntoFinal = gdResolverPlantilla(cfg.asunto, datosPlantilla) + (modoTest?' [PRUEBA]':'');
    var cuerpoFinal = gdResolverPlantilla(cfg.cuerpo, datosPlantilla);

    return emailjs.send(cfg.serviceId, cfg.templateId, {
      to_name:          dest.nombre,
      to_email:         emailDest,
      cc_email:         cfg.ccEmail || '',
      empresa:          datosPlantilla.empresa,
      fecha_hora:       hoy,
      detalle_clientes: cuerpoFinal,
      total_alertas:    dest.items.length+' cliente(s)'+(modoTest?' [MODO PRUEBA]':''),
      numero_cot: 'ALERTA-GD'+(modoTest?' [PRUEBA]':''),
      contacto:   dest.nombre,
      comercial:  'Sistema ZYMO',
      lineas:     detalleDoc,
      asunto:     asuntoFinal+'\n\n'+cuerpoFinal,
    }).then(function(){ enviados++; })
      .catch(function(err){ console.warn('[ZYMO] Error enviando a '+emailDest+':', err); errores++; });
  });

  Promise.all(promesas).then(function(){
    var msg = (modoTest?'[PRUEBA] ':'')+enviados+' correo(s) enviado(s)';
    if(sinCorreo.length) msg += ' · '+sinCorreo.length+' sin correo GD';
    if(errores) msg += ' · '+errores+' error(es)';
    toast(enviados>0?'✅':'⚠️', msg, errores&&!enviados?'#f5a623':'#00e676');
    try{ localStorage.setItem('zymo-gd-ultima-alerta', new Date().toISOString()); }catch(e){}
    if(btn){ btn.textContent='✅ Enviado'; setTimeout(function(){ if(btn){ btn.textContent='📧 Enviar alerta por correo'; btn.disabled=false; } },4000); }
  });
}

function renderGestionDocumental(){
  var search      = (document.getElementById('gd-search')?.value||'').toLowerCase();
  var filtTipo    = document.getElementById('gd-filter-tipo')?.value||'';
  var filtSt      = document.getElementById('gd-filter-status')?.value||'';
  var filtDocs    = document.getElementById('gd-filter-docs')?.value||'';
  var filtPct     = document.getElementById('gd-filter-pct')?.value||'';
  var filtCompany = document.getElementById('gd-filter-company')?.value||'';

  var todosClientes = db.records.filter(function(r){ return r.tipo==='cliente'; });
  var clientes = todosClientes.slice();

  if(search)      clientes = clientes.filter(function(r){ return (r.empresa||'').toLowerCase().includes(search)||(r.nit||'').includes(search); });
  if(filtTipo)    clientes = clientes.filter(function(r){ return (r.tipoCliente||'directo')===filtTipo; });
  if(filtSt)      clientes = clientes.filter(function(r){ return gdStatusVencimiento(r.id).status === filtSt; });
  if(filtDocs)    clientes = clientes.filter(function(r){ return gdStatusDocs(r.id).key === filtDocs; });
  if(filtCompany) clientes = clientes.filter(function(r){
    return gdCompaniasCliente(r).includes(filtCompany);
  });

  if(filtPct){
    clientes = clientes.filter(function(r){
      var p = gdCumplimientoPct(r.id);
      if(filtPct === '80') return p >= 80;
      if(filtPct === '50-79') return p >= 50 && p < 80;
      if(filtPct === '0-49')  return p < 50;
      return true;
    });
  }

  // ====== DASHBOARD KPIs ======
  var totalActivos = todosClientes.length;
  var pcts = todosClientes.map(function(r){ return gdCumplimientoPct(r.id); });
  var sobre80  = pcts.filter(function(p){ return p >= 80; }).length;
  var entre50  = pcts.filter(function(p){ return p >= 50 && p < 80; }).length;
  var bajo50   = pcts.filter(function(p){ return p < 50; }).length;
  var promedio = totalActivos > 0 ? Math.round(pcts.reduce(function(a,b){ return a+b; },0) / totalActivos) : 0;

  // KPIs por compañía — agrupados por label (IMC Cargo incluye Transporte+Paqueteo+CEDI)
  var compLabels = [...new Set(COMPANIAS_LOGISTICAS.map(function(c){ return c.label; }))];
  var compKpis = compLabels.map(function(label){
    var inComp = todosClientes.filter(function(r){ return gdCompaniasCliente(r).includes(label); });
    var sobre = inComp.filter(function(r){ return gdCumplimientoPct(r.id) >= 80; }).length;
    return {label: label, total: inComp.length, sobre80: sobre};
  }).filter(function(c){ return c.total > 0; });

  var dashEl = document.getElementById('gd-dashboard');
  if(dashEl){
    dashEl.innerHTML =
      // Fila KPI principal
      '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin-bottom:10px">'
      + gdKpiCard('Total Clientes Activos', totalActivos, '', '#00c2ff')
      + gdKpiCard('Promedio Cumplimiento', promedio+'%', '', gdColorPct(promedio))
      + gdKpiCard('≥ 80% (Gestionados)', sobre80, 'de '+totalActivos+' clientes', '#00e676')
      + gdKpiCard('50–79% (En proceso)', entre50, 'de '+totalActivos+' clientes', '#f5a623')
      + gdKpiCard('< 50% (Críticos)', bajo50, 'de '+totalActivos+' clientes', '#ff4444')
      + gdKpiCard('Índice Gestión 80%', totalActivos>0?Math.round((sobre80/totalActivos)*100)+'%':'—', 'clientes al 80%+', '#a855f7')
      + '</div>'
      // Barra de progreso general
      + '<div style="background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:18px 22px;margin-bottom:20px">'
      + '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px">'
      + '<span style="font-size:12px;color:var(--text2);font-weight:600;letter-spacing:1.5px;text-transform:uppercase">Distribución de Cumplimiento</span>'
      + '<span style="font-size:12px;color:var(--text2)">'+totalActivos+' clientes activos</span>'
      + '</div>'
      + (totalActivos > 0 ?
        '<div style="display:flex;height:14px;border-radius:7px;overflow:hidden;gap:2px">'
        + (sobre80>0 ? '<div style="flex:'+(sobre80/totalActivos)+';background:#00e676;border-radius:4px" title="'+sobre80+' clientes ≥80%"></div>' : '')
        + (entre50>0 ? '<div style="flex:'+(entre50/totalActivos)+';background:#f5a623;border-radius:4px" title="'+entre50+' clientes 50-79%"></div>' : '')
        + (bajo50>0  ? '<div style="flex:'+(bajo50/totalActivos)+';background:#ff4444;border-radius:4px" title="'+bajo50+' clientes <50%"></div>' : '')
        + '</div>'
        + '<div style="display:flex;gap:16px;margin-top:8px">'
        + '<span style="font-size:11px;color:#00e676">🟢 ≥80%: <strong>'+sobre80+'</strong></span>'
        + '<span style="font-size:11px;color:#f5a623">🟡 50–79%: <strong>'+entre50+'</strong></span>'
        + '<span style="font-size:11px;color:#ff4444">🔴 &lt;50%: <strong>'+bajo50+'</strong></span>'
        + '</div>'
        : '<div style="color:var(--text2);font-size:13px">Sin clientes registrados</div>')
      + '</div>'
      // KPIs por compañía
      + (compKpis.length > 0 ?
        '<div style="margin-bottom:8px">'
        + '<div style="font-size:11px;color:var(--text2);font-weight:700;letter-spacing:2px;text-transform:uppercase;margin-bottom:12px">📦 Cumplimiento por Compañía Logística</div>'
        + '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px">'
        + compKpis.map(function(c){
          var pctComp = c.total>0?Math.round((c.sobre80/c.total)*100):0;
          var col = gdColorPct(pctComp);
          return '<div style="background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:14px 16px">'
            + '<div style="font-size:11px;color:var(--text2);font-weight:700;letter-spacing:1px;text-transform:uppercase;margin-bottom:8px">'+c.label+'</div>'
            + '<div style="display:flex;align-items:baseline;gap:8px;margin-bottom:6px">'
            + '<span style="font-family:\'Barlow Condensed\',sans-serif;font-size:28px;font-weight:800;color:'+col+'">'+c.sobre80+'</span>'
            + '<span style="font-size:12px;color:var(--text2)">de '+c.total+' al 80%+</span>'
            + '</div>'
            + '<div style="background:var(--surface2);border-radius:4px;height:6px;overflow:hidden">'
            + '<div style="height:100%;background:'+col+';width:'+pctComp+'%;border-radius:4px"></div>'
            + '</div>'
            + '<div style="font-size:11px;color:'+col+';font-weight:700;margin-top:4px">'+pctComp+'% gestionados</div>'
            + '</div>';
        }).join('')
        + '</div></div>'
        : '');
  }

  var tbody = document.getElementById('tabla-gd');
  if(!tbody) return;

  if(!clientes.length){
    tbody.innerHTML = '<tr><td colspan="13"><div class="empty-state"><div class="empty-icon">📁</div><div class="empty-title">Sin clientes que coincidan con los filtros</div></div></td></tr>';
    return;
  }

  tbody.innerHTML = clientes.map(function(r){
    var sv      = gdStatusVencimiento(r.id);
    var sd      = gdStatusDocs(r.id);
    var tc      = r.tipoCliente||'directo';
    var refs    = tc==='referido' ? (r.clienteIndirectoNombre||r.clienteIndirecto||'—') : '';
    var prox    = sv.proxima ? fmtFechaGD(sv.proxima.toISOString().slice(0,10)) : '—';
    var diasTxt = sv.dias!==null ? (sv.dias<0?'Vencido hace '+Math.abs(sv.dias)+' días':sv.dias+' días') : '—';
    var fechaAct = fmtFechaGD(gdFechaActualizacion(r.id));
    var pct     = gdCumplimientoPct(r.id);
    var colPct  = gdColorPct(pct);
    var companias = gdCompaniasCliente(r);
    var compHTML = companias.length
      ? companias.map(function(c){ return '<span style="background:rgba(0,194,255,0.1);color:var(--accent);border:1px solid rgba(0,194,255,0.3);padding:1px 5px;border-radius:8px;font-size:9px;font-weight:700;display:inline-block;margin:1px;white-space:nowrap">'+c+'</span>'; }).join('')
      : '<span style="color:var(--text2);font-size:10px">—</span>';

    return '<tr>'
      + '<td style="color:var(--text2)">'+(r.nit||'—')+'</td>'
      + '<td><strong>'+r.empresa+'</strong></td>'
      + '<td style="text-transform:capitalize">'+tc+'</td>'
      + '<td style="color:var(--text2)">'+(refs||'—')+'</td>'
      + '<td style="white-space:normal"><div style="display:flex;flex-wrap:wrap;gap:2px">'+compHTML+'</div></td>'
      // % Cumplimiento con barra
      + '<td>'
      + '<div style="display:flex;flex-direction:column;align-items:center;gap:3px">'
      + '<div style="background:var(--surface2);border-radius:3px;height:6px;width:56px;overflow:hidden">'
      + '<div style="height:100%;background:'+colPct+';width:'+pct+'%;border-radius:3px"></div>'
      + '</div>'
      + '<span style="font-family:\'Barlow Condensed\',sans-serif;font-size:15px;font-weight:800;color:'+colPct+'">'+pct+'%</span>'
      + '</div>'
      + '</td>'
      + '<td>'+fechaAct+'</td>'
      + '<td>'+prox+'</td>'
      + '<td style="font-weight:700;color:'+sv.color+'">'+diasTxt+'</td>'
      + '<td><span style="background:'+sv.color+'22;color:'+sv.color+';border:1px solid '+sv.color+'44;padding:3px 8px;border-radius:20px;font-size:11px;font-weight:700;white-space:nowrap">'+sv.label+'</span></td>'
      + '<td><button class="btn btn-secondary btn-sm" onclick="abrirModalGD(\''+r.id+'\')" style="white-space:nowrap">📋 Docs</button></td>'
      + '</tr>';
  }).join('');
  setTimeout(initGDScrollSync, 50);
  gdMostrarBannerAlertas();
}

function gdKpiCard(label, value, sub, color){
  return '<div style="background:var(--surface);border:1px solid var(--border);border-top:3px solid '+color+';border-radius:12px;padding:18px 20px">'
    + '<div style="font-size:11px;color:var(--text2);letter-spacing:1.5px;text-transform:uppercase;margin-bottom:8px">'+label+'</div>'
    + '<div style="font-family:\'Barlow Condensed\',sans-serif;font-size:36px;font-weight:800;color:'+color+';line-height:1">'+value+'</div>'
    + (sub ? '<div style="font-size:12px;color:var(--text2);margin-top:4px">'+sub+'</div>' : '')
    + '</div>';
}

function exportGestionDocumentalExcel(){
  if(typeof XLSX === 'undefined'){ toast('⚠️','Librería Excel no disponible','#f5a623'); return; }

  // Leer filtros activos para exportar exactamente lo que se ve
  var search      = (document.getElementById('gd-search')?.value||'').toLowerCase();
  var filtTipo    = document.getElementById('gd-filter-tipo')?.value||'';
  var filtSt      = document.getElementById('gd-filter-status')?.value||'';
  var filtDocs    = document.getElementById('gd-filter-docs')?.value||'';
  var filtPct     = document.getElementById('gd-filter-pct')?.value||'';
  var filtCompany = document.getElementById('gd-filter-company')?.value||'';

  var clientes = db.records.filter(function(r){ return r.tipo==='cliente'; });
  if(search)      clientes = clientes.filter(function(r){ return (r.empresa||'').toLowerCase().includes(search)||(r.nit||'').includes(search); });
  if(filtTipo)    clientes = clientes.filter(function(r){ return (r.tipoCliente||'directo')===filtTipo; });
  if(filtSt)      clientes = clientes.filter(function(r){ return gdStatusVencimiento(r.id).status===filtSt; });
  if(filtDocs)    clientes = clientes.filter(function(r){ return gdStatusDocs(r.id).key===filtDocs; });
  if(filtCompany) clientes = clientes.filter(function(r){ return gdCompaniasCliente(r).includes(filtCompany); });
  if(filtPct){
    clientes = clientes.filter(function(r){
      var p = gdCumplimientoPct(r.id);
      if(filtPct==='80')    return p>=80;
      if(filtPct==='50-79') return p>=50&&p<80;
      if(filtPct==='0-49')  return p<50;
      return true;
    });
  }

  var wb = XLSX.utils.book_new();

  // ── Hoja 1: Resumen por cliente ──────────────────────────────
  var docNames = GD_DOCS.map(function(d){ return d.nombre.substring(0,40); });
  var header = [
    'NIT','Empresa','Tipo Cliente','Referido por',
    'Compañías Logísticas','% Cumplimiento',
    'Última Actualización','Próx. Actualización','Días p/Vencer','Status Vencimiento',
    'Estado Documental'
  ].concat(docNames);

  var rows = clientes.map(function(r){
    var gd  = gdGetData(r.id);
    var sv  = gdStatusVencimiento(r.id);
    var sd  = gdStatusDocs(r.id);
    var tc  = r.tipoCliente||'directo';
    var pct = gdCumplimientoPct(r.id);
    var companias = gdCompaniasCliente(r).join(' / ');
    var refs = tc==='referido'?(r.clienteIndirectoNombre||r.clienteIndirecto||''):'';
    var proxFmt = sv.proxima ? sv.proxima.toISOString().slice(0,10) : '';
    var diasTxt = sv.dias!==null?(sv.dias<0?'Vencido hace '+Math.abs(sv.dias)+' días':sv.dias+' días'):'Sin fecha';

    var base = [
      r.nit||'',
      r.empresa||'',
      tc.charAt(0).toUpperCase()+tc.slice(1),
      refs,
      companias,
      pct+'%',
      gdFechaActualizacion(r.id)||'',
      proxFmt,
      diasTxt,
      sv.label,
      sd.label
    ];

    // Estado de cada documento
    var esRef = tc==='referido';
    var docEstados = GD_DOCS.map(function(doc){
      if(esRef && doc.aplica!=='todos') return 'N/A';
      var est = (gd.docs[doc.id]||{}).estado||'';
      var LABELS = {completo:'Completo',incompleto:'Incompleto',pendiente:'Pendiente'};
      return LABELS[est]||'Sin gestionar';
    });

    return base.concat(docEstados);
  });

  var ws = XLSX.utils.aoa_to_sheet([header].concat(rows));

  // Ancho de columnas
  ws['!cols'] = [
    {wch:14},{wch:35},{wch:12},{wch:30},
    {wch:28},{wch:14},
    {wch:18},{wch:18},{wch:16},{wch:14},
    {wch:24}
  ].concat(GD_DOCS.map(function(){ return {wch:18}; }));

  XLSX.utils.book_append_sheet(wb, ws, 'Control Documental');

  // ── Hoja 2: Dashboard KPIs ───────────────────────────────────
  var todosClientes = db.records.filter(function(r){ return r.tipo==='cliente'; });
  var pcts = todosClientes.map(function(r){ return gdCumplimientoPct(r.id); });
  var sobre80 = pcts.filter(function(p){ return p>=80; }).length;
  var entre50 = pcts.filter(function(p){ return p>=50&&p<80; }).length;
  var bajo50  = pcts.filter(function(p){ return p<50; }).length;
  var promedio = todosClientes.length>0 ? Math.round(pcts.reduce(function(a,b){return a+b;},0)/todosClientes.length) : 0;

  var compLabels = [...new Set(COMPANIAS_LOGISTICAS.map(function(c){ return c.label; }))];
  var kpiRows = [
    ['INDICADOR','VALOR','DETALLE'],
    ['Total Clientes Activos', todosClientes.length, ''],
    ['Promedio de Cumplimiento', promedio+'%', ''],
    ['Clientes ≥ 80% (Gestionados)', sobre80, sobre80+' de '+todosClientes.length],
    ['Clientes 50–79% (En proceso)', entre50, entre50+' de '+todosClientes.length],
    ['Clientes < 50% (Críticos)', bajo50, bajo50+' de '+todosClientes.length],
    ['Índice Gestión 80%', todosClientes.length>0?Math.round((sobre80/todosClientes.length)*100)+'%':'—', 'clientes al 80%+'],
    ['','',''],
    ['COMPAÑÍA','TOTAL CLIENTES','CLIENTES ≥ 80%']
  ].concat(compLabels.map(function(label){
    var inComp = todosClientes.filter(function(r){ return gdCompaniasCliente(r).includes(label); });
    var s = inComp.filter(function(r){ return gdCumplimientoPct(r.id)>=80; }).length;
    return [label, inComp.length, s+' ('+( inComp.length>0?Math.round(s/inComp.length*100):0 )+'%)'];
  }));

  var wsKpi = XLSX.utils.aoa_to_sheet(kpiRows);
  wsKpi['!cols'] = [{wch:35},{wch:22},{wch:25}];
  XLSX.utils.book_append_sheet(wb, wsKpi, 'Dashboard KPIs');

  // ── Nombre del archivo con fecha y filtros ───────────────────
  var fecha = new Date().toISOString().slice(0,10);
  var sufijo = filtCompany ? '_'+filtCompany.replace(/\s/g,'-') : '';
  sufijo += filtPct==='80'?'_80pct-mas':filtPct==='50-79'?'_50a79pct':filtPct==='0-49'?'_criticos':'';
  XLSX.writeFile(wb, 'GestionDocumental_ZYMO'+sufijo+'_'+fecha+'.xlsx');
  toast('✅','Excel exportado ('+clientes.length+' clientes)','#00e676');
}

function abrirModalGD(clienteId){
  _gdClienteId = clienteId;
  var r  = db.records.find(function(x){ return x.id===clienteId; });
  var gd = gdGetData(clienteId);
  var empresa   = r ? r.empresa : '—';
  var nit       = r ? (r.nit||'') : '';
  var tc        = r ? (r.tipoCliente||'directo') : 'directo';
  var tcLabel   = tc.charAt(0).toUpperCase()+tc.slice(1);
  var comercial = r ? (r.comercialNombre||'—') : '—';

  // Contacto Gestión Documental
  var ctGD = r && r.contactos ? r.contactos.find(function(c){ return c.tipoContacto==='gestion-documental'; }) : null;
  var ctGDNom = ctGD ? ctGD.nombre : 'No registrado';
  var ctGDSub = ctGD ? [(ctGD.cargo||''),(ctGD.telefono||''),(ctGD.email||'')].filter(Boolean).join(' · ') : '';

  // Referido por (si aplica)
  var refHTML = '';
  if(tc==='referido'){
    var refNom = r.clienteIndirectoNombre || r.clienteIndirecto || '—';
    // Buscar contacto del cliente indirecto
    var refRec = db.records.find(function(x){ return x.id===r.clienteIndirecto || x.empresa===r.clienteIndirectoNombre; });
    var refCt  = refRec && refRec.contactos ? refRec.contactos[0] : null;
    var refCtTxt = refCt ? refCt.nombre+(refCt.telefono?' · '+refCt.telefono:'')+(refCt.email?' · '+refCt.email:'') : '';
    refHTML = '<div style="background:var(--surface2);border:1px solid var(--border);border-radius:10px;padding:14px 18px;margin-top:16px">'
      + '<div style="font-size:11px;letter-spacing:1.5px;text-transform:uppercase;color:var(--text2);font-weight:600;margin-bottom:8px">Referido por</div>'
      + '<div style="font-size:16px;font-weight:700;color:var(--text)">'+refNom+'</div>'
      + (refCtTxt?'<div style="font-size:13px;color:var(--text2);margin-top:4px">'+refCtTxt+'</div>':'')
      + '</div>';
  }

  document.getElementById('gd-modal-empresa').innerHTML =
    // Fila principal: nombre + badges
    '<div style="display:flex;align-items:flex-start;justify-content:space-between;flex-wrap:wrap;gap:12px;margin-bottom:16px">'
    + '<div>'
    + '<div style="font-size:26px;font-weight:800;color:var(--accent);line-height:1.1">'+empresa+'</div>'
    + (nit?'<div style="font-size:13px;color:var(--text2);margin-top:4px">NIT: '+nit+'</div>':'')
    + '</div>'
    + '<span style="background:var(--accent);color:#000;padding:6px 20px;border-radius:20px;font-size:14px;font-weight:800;white-space:nowrap;letter-spacing:0.5px">'+tcLabel+'</span>'
    + '</div>'
    // Grid de info
    + '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px">'
    // Comercial
    + '<div style="background:var(--surface2);border:1px solid var(--border);border-radius:10px;padding:14px 18px">'
    + '<div style="font-size:11px;letter-spacing:1.5px;text-transform:uppercase;color:var(--text2);font-weight:600;margin-bottom:6px">Comercial a cargo</div>'
    + '<div style="font-size:16px;font-weight:700;color:var(--text)">'+comercial+'</div>'
    + '</div>'
    // Contacto GD
    + '<div style="background:var(--surface2);border:1px solid var(--border);border-radius:10px;padding:14px 18px">'
    + '<div style="font-size:11px;letter-spacing:1.5px;text-transform:uppercase;color:var(--text2);font-weight:600;margin-bottom:6px">Contacto Gestión Documental</div>'
    + '<div style="font-size:16px;font-weight:700;color:var(--text)">'+ctGDNom+'</div>'
    + (ctGDSub?'<div style="font-size:12px;color:var(--text2);margin-top:4px">'+ctGDSub+'</div>':'')
    + '</div>'
    + '</div>'
    + refHTML;

  // Banner de ciclo anual
  var ciclo = gdCicloActual(clienteId);
  var anoSistema = new Date().getFullYear();
  var desact = ciclo < anoSistema;
  var cicloColor = desact ? '#f87171' : '#34d399';
  var gdModalCicloEl = document.getElementById('gd-modal-ciclo');
  if(gdModalCicloEl){
    gdModalCicloEl.innerHTML = '<div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:14px;padding:12px 16px;background:'+(desact?'rgba(248,113,113,0.07)':'rgba(52,211,153,0.07)')+';border:1px solid '+cicloColor+'30;border-radius:8px">'
      +'<span style="font-size:11px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:'+cicloColor+'">Ciclo documental</span>'
      +'<span style="background:'+cicloColor+'18;color:'+cicloColor+';border:1px solid '+cicloColor+'40;padding:3px 12px;border-radius:10px;font-size:12px;font-weight:700">Ciclo '+ciclo+(desact?' — DESACTUALIZADO':' activo')+'</span>'
      +(desact?'<span style="font-size:11px;color:var(--text2)">Los documentos del '+ciclo+' requieren actualización para '+anoSistema+'</span>':'')
      +'<div style="margin-left:auto;display:flex;gap:8px">'
      +(desact?'<button onclick="gdIniciarCiclo(\'' + clienteId + '\')" style="background:#34d399;color:#000;border:none;border-radius:6px;padding:6px 14px;font-size:12px;font-weight:700;cursor:pointer">Iniciar ciclo '+anoSistema+'</button>':'')
      +'<button onclick="gdAbrirHistorial(\'' + clienteId + '\')" style="background:var(--surface2);border:1px solid var(--border);color:var(--text2);border-radius:6px;padding:6px 12px;font-size:12px;cursor:pointer">Ver historial</button>'
      +'</div>'
      +'</div>';
  }

  document.getElementById('gd-chk-all').checked = false;
  gdRenderDocLista(gd);
  document.getElementById('modal-gd-docs').style.display = 'block';
  document.body.style.overflow = 'hidden';
}

function gdRenderDocLista(gd){
  var ESTADO_COLORS = {completo:'#00e676', incompleto:'#f5a623', pendiente:'#ff4444'};
  var ESTADO_LABELS = {completo:'Completo', incompleto:'Incompleto', pendiente:'Pendiente'};

  var r  = db.records.find(function(x){ return x.id===_gdClienteId; });
  var tc = r ? (r.tipoCliente||'directo') : 'directo';
  var esReferido = tc === 'referido';
  var docsAplicables = GD_DOCS.filter(function(doc){
    if(esReferido) return doc.aplica === 'todos';
    return true;
  });

  // Calcular % acumulado
  var pct = gdCumplimientoPct(_gdClienteId);
  var colPct = gdColorPct(pct);

  // Encabezado con % global del cliente
  var headerHTML = '<div style="background:var(--surface2);border:1px solid var(--border);border-radius:10px;padding:14px 20px;margin-bottom:16px;display:flex;align-items:center;gap:20px">'
    + '<div style="flex:1">'
    + '<div style="font-size:11px;color:var(--text2);font-weight:700;letter-spacing:1.5px;text-transform:uppercase;margin-bottom:6px">% Cumplimiento Ponderado</div>'
    + '<div style="background:var(--surface);border-radius:6px;height:12px;overflow:hidden;margin-bottom:6px">'
    + '<div style="height:100%;background:'+colPct+';width:'+pct+'%;border-radius:6px;transition:width 0.5s"></div>'
    + '</div>'
    + '<div style="font-size:12px;color:var(--text2)">Documentos marcados como <strong style="color:#00e676">Completo</strong> suman el 100% de su peso; <strong style="color:#f5a623">Incompleto</strong> suma el 50%</div>'
    + '</div>'
    + '<div style="text-align:center;flex-shrink:0">'
    + '<div style="font-family:\'Barlow Condensed\',sans-serif;font-size:52px;font-weight:800;color:'+colPct+';line-height:1">'+pct+'%</div>'
    + '<div style="font-size:12px;color:var(--text2)">cumplimiento</div>'
    + '</div>'
    + '</div>';

  var html = headerHTML + docsAplicables.map(function(doc){
    var data   = gd.docs[doc.id] || {};
    var estado = data.estado || '';
    var obs    = data.obs    || '';
    var fecha  = data.fecha  || '';
    var col    = ESTADO_COLORS[estado] || 'var(--text2)';
    var bg     = estado ? col+'15' : 'var(--surface2)';
    var pond   = esReferido ? doc.pond_ref : doc.pond_di;
    var pctDoc = Math.round((pond||0) * 100 * 10) / 10;

    // Archivos cargados para este documento
    var archivos = (data.archivos || []);
    var archivosHTML = '';
    if(archivos.length > 0){
      archivosHTML = '<div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:6px">'
        + archivos.map(function(a, idx){
          var esImg = /\.(jpg|jpeg|png|gif|webp)$/i.test(a.name);
          var esPdf = /\.pdf$/i.test(a.name);
          var iconoTipo = esPdf ? '📄' : (esImg ? '🖼️' : '📎');
          return '<div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:5px 10px;display:inline-flex;align-items:center;gap:6px;font-size:11px">'
            + '<span>'+iconoTipo+' '+a.name+'</span>'
            + '<span style="color:var(--text2)">'+(a.size?(a.size/1024).toFixed(0)+' KB':'')+'</span>'
            + '<button onclick="gdVerArchivo(\''+doc.id+'\','+idx+')" title="Visualizar" style="background:rgba(0,194,255,0.15);color:var(--accent);border:none;border-radius:5px;padding:2px 7px;font-size:11px;cursor:pointer">👁 Ver</button>'
            + '<button onclick="gdDescargarArchivo(\''+doc.id+'\','+idx+')" title="Descargar" style="background:rgba(0,230,118,0.15);color:#00e676;border:none;border-radius:5px;padding:2px 7px;font-size:11px;cursor:pointer">⬇ Descargar</button>'
            + '<button onclick="gdEliminarArchivo(\''+doc.id+'\','+idx+')" title="Eliminar" style="background:rgba(255,68,68,0.12);color:#ff4444;border:none;border-radius:5px;padding:2px 7px;font-size:11px;cursor:pointer">✕</button>'
            + '</div>';
        }).join('')
        + '</div>';
    }

    var uploadBtnId = 'gd-upload-btn-'+doc.id;

    return '<div style="background:'+bg+';border:1px solid '+(estado?col+'40':'var(--border)')+';border-radius:8px;padding:10px 12px;display:flex;align-items:flex-start;gap:10px">'
      + '<input type="checkbox" class="gd-doc-chk" data-doc="'+doc.id+'" style="margin-top:3px;width:15px;height:15px;cursor:pointer;accent-color:var(--accent);flex-shrink:0">'
      + '<div style="flex:1;min-width:0">'
      // Fila título + peso
      + '<div style="display:flex;align-items:baseline;justify-content:space-between;margin-bottom:6px;gap:8px;flex-wrap:wrap">'
      + '<div style="font-size:12px;font-weight:600;color:var(--text);line-height:1.4">'+doc.nombre+'</div>'
      + '<span style="background:rgba(0,194,255,0.1);color:var(--accent);border:1px solid rgba(0,194,255,0.25);padding:2px 8px;border-radius:10px;font-size:10px;font-weight:800;white-space:nowrap;flex-shrink:0">Peso: '+pctDoc+'%</span>'
      + '</div>'
      // Controles estado / fecha / observación
      + '<div style="display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin-bottom:6px">'
      + '<select data-doc="'+doc.id+'" data-field="estado" onchange="gdOnDocChange(this)" style="background:var(--surface);border:1px solid var(--border);color:var(--text);border-radius:6px;padding:4px 8px;font-size:11px">'
      + '<option value="">— Estado —</option>'
      + '<option value="completo"'+(estado==='completo'?' selected':'')+'>✅ Completo (+'+pctDoc+'%)</option>'
      + '<option value="incompleto"'+(estado==='incompleto'?' selected':'')+'>⚠️ Incompleto (+'+Math.round(pctDoc*5)/10+'%)</option>'
      + '<option value="pendiente"'+(estado==='pendiente'?' selected':'')+'>🔴 Pendiente (+0%)</option>'
      + '</select>'
      + (doc.esReferencia
        ? '<input type="date" data-doc="'+doc.id+'" data-field="fecha" onchange="gdOnDocChange(this)" value="'+fecha+'" title="Fecha del documento" style="background:var(--surface);border:1px solid var(--border);color:var(--text);border-radius:6px;padding:4px 8px;font-size:11px">'
        : '')
      + '<input type="text" data-doc="'+doc.id+'" data-field="obs" onchange="gdOnDocChange(this)" value="'+(obs).replace(/"/g,'&quot;')+'" placeholder="Observación..." style="flex:1;min-width:160px;background:var(--surface);border:1px solid var(--border);color:var(--text);border-radius:6px;padding:4px 8px;font-size:11px">'
      // Botón cargar archivo por fila
      + '<label id="'+uploadBtnId+'" style="background:rgba(0,194,255,0.12);color:var(--accent);border:1px solid rgba(0,194,255,0.3);border-radius:6px;padding:4px 10px;font-size:11px;font-weight:700;cursor:pointer;display:inline-flex;align-items:center;gap:5px;white-space:nowrap" title="Cargar archivo(s) para este documento">'
      + '📁 Cargar'
      + '<input type="file" multiple accept=".pdf,.jpg,.jpeg,.png,.doc,.docx,.xls,.xlsx" onchange="gdCargarArchivoDoc(this,\''+doc.id+'\')" style="display:none">'
      + '</label>'
      + (doc.id==='fr004' && estado!=='completo' ? '<button onclick="gdAsignarVisitaCRM(\'' + _gdClienteId + '\')" style="background:rgba(245,158,11,0.12);color:#f59e0b;border:1px solid rgba(245,158,11,0.35);border-radius:6px;padding:4px 10px;font-size:11px;font-weight:700;cursor:pointer;white-space:nowrap">📋 Asignar visita al Comercial</button>' : '')
      + '</div>'
      // Archivos cargados
      + archivosHTML
      + '</div>'
      + (estado ? '<span style="background:'+col+'20;color:'+col+';border:1px solid '+col+'40;padding:2px 8px;border-radius:12px;font-size:10px;font-weight:700;white-space:nowrap;flex-shrink:0">'+ESTADO_LABELS[estado]+'</span>' : '')
      + '</div>';
  }).join('');

  document.getElementById('gd-docs-lista').innerHTML = html;
}

// Carga archivos para un documento específico (almacena en base64 en gd.docs[docId].archivos)
function gdCargarArchivoDoc(input, docId){
  var archivos = Array.from(input.files);
  if(!archivos.length) return;

  // Asegurar estructura en db
  if(!db.gestionDocumental) db.gestionDocumental = {};
  if(!db.gestionDocumental[_gdClienteId]) db.gestionDocumental[_gdClienteId] = {docs:{}, fechaActualizacion:''};
  var docData = db.gestionDocumental[_gdClienteId].docs;
  if(!docData[docId]) docData[docId] = {};
  if(!docData[docId].archivos) docData[docId].archivos = [];

  var promesas = archivos.map(function(f){
    return new Promise(function(resolve){
      var reader = new FileReader();
      reader.onload = function(e){
        docData[docId].archivos.push({ name: f.name, size: f.size, type: f.type, data: e.target.result });
        resolve();
      };
      reader.readAsDataURL(f);
    });
  });

  Promise.all(promesas).then(function(){
    // Cambiar estado a completo directamente en db
    docData[docId].estado = 'completo';
    // Intentar guardar (puede fallar por tamaño de archivos en base64)
    try { save(); } catch(e){}
    // Re-renderizar la lista leyendo desde db (referencia directa)
    var gd = db.gestionDocumental[_gdClienteId];
    gdRenderDocLista(gd);
    toast('✅','Archivo cargado — Estado: Completo','#00e676');
  });

  input.value = '';
}

// Visualiza un archivo cargado (abre en nueva pestaña)
function gdVerArchivo(docId, idx){
  var gd = gdGetData(_gdClienteId);
  var archivo = ((gd.docs[docId]||{}).archivos||[])[idx];
  if(!archivo) return;
  var win = window.open();
  if(!win) { toast('⚠️','Permite ventanas emergentes para ver el archivo','#f5a623'); return; }
  if(archivo.type && archivo.type.startsWith('image/')){
    win.document.write('<html><body style="margin:0;background:#111;display:flex;justify-content:center;align-items:center;min-height:100vh"><img src="'+archivo.data+'" style="max-width:100%;max-height:100vh;object-fit:contain"></body></html>');
  } else if(archivo.type === 'application/pdf' || /\.pdf$/i.test(archivo.name)){
    win.document.write('<html><body style="margin:0"><embed src="'+archivo.data+'" type="application/pdf" width="100%" height="100%" style="min-height:100vh"></body></html>');
  } else {
    // Descarga directa para otros tipos
    win.close();
    gdDescargarArchivo(docId, idx);
  }
}

// Descarga un archivo cargado
function gdDescargarArchivo(docId, idx){
  var gd = gdGetData(_gdClienteId);
  var archivo = ((gd.docs[docId]||{}).archivos||[])[idx];
  if(!archivo) return;
  var a = document.createElement('a');
  a.href = archivo.data;
  a.download = archivo.name;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
}

// Elimina un archivo cargado de un documento
function gdEliminarArchivo(docId, idx){
  if(!db.gestionDocumental || !db.gestionDocumental[_gdClienteId]) return;
  var docData = db.gestionDocumental[_gdClienteId].docs;
  if(!(docData[docId]||{}).archivos) return;
  docData[docId].archivos.splice(idx, 1);
  try { save(); } catch(e){}
  gdRenderDocLista(db.gestionDocumental[_gdClienteId]);
  toast('🗑️','Archivo eliminado','#f5a623');
}

function gdSeleccionarTodos(chkAll){
  document.querySelectorAll('.gd-doc-chk').forEach(function(chk){
    chk.checked = chkAll.checked;
  });
}

function gdCambiarEstadoMasivo(estado){
  var gd = gdGetData(_gdClienteId);
  var seleccionados = document.querySelectorAll('.gd-doc-chk:checked');
  if(!seleccionados.length){ toast('⚠️','Selecciona al menos un documento','#f5a623'); return; }
  seleccionados.forEach(function(chk){
    var docId = chk.dataset.doc;
    if(!gd.docs[docId]) gd.docs[docId] = {};
    gd.docs[docId].estado = estado;
    // Actualizar el select visible
    var sel = document.querySelector('select[data-doc="'+docId+'"][data-field="estado"]');
    if(sel) sel.value = estado;
  });
  // Re-renderizar con colores actualizados
  gdRenderDocLista(gd);
  // Restaurar estado de checkboxes
  document.getElementById('gd-chk-all').checked = false;
}

function gdOnDocChange(el){
  var doc   = el.dataset.doc;
  var field = el.dataset.field;
  var gd    = gdGetData(_gdClienteId);
  if(!gd.docs[doc]) gd.docs[doc] = {};
  gd.docs[doc][field] = el.value;
  if(doc==='fr001' && field==='fecha') gd.fechaActualizacion = el.value;
  // Actualizar color de fila
  var ESTADO_COLORS = {completo:'#00e676', incompleto:'#f5a623', pendiente:'#ff4444'};
  if(field==='estado'){
    var row = el.closest('div[style*="border-radius:8px"]');
    var col = ESTADO_COLORS[el.value] || 'var(--text2)';
    if(row && el.value){
      row.style.background = col+'15';
      row.style.borderColor = col+'40';
    }
  }
}

function guardarDocsGD(){
  if(!_gdClienteId) return;
  if(!db.gestionDocumental) db.gestionDocumental = {};
  var gd = gdGetData(_gdClienteId);

  // Sincronizar todos los campos del DOM al objeto db antes de guardar
  document.querySelectorAll('select[data-doc][data-field="estado"]').forEach(function(el){
    var docId = el.dataset.doc;
    if(!gd.docs[docId]) gd.docs[docId] = {};
    gd.docs[docId].estado = el.value;
  });
  document.querySelectorAll('input[data-doc][data-field="obs"]').forEach(function(el){
    var docId = el.dataset.doc;
    if(!gd.docs[docId]) gd.docs[docId] = {};
    gd.docs[docId].obs = el.value;
  });
  document.querySelectorAll('input[data-doc][data-field="fecha"]').forEach(function(el){
    var docId = el.dataset.doc;
    if(!gd.docs[docId]) gd.docs[docId] = {};
    gd.docs[docId].fecha = el.value;
  });

  try {
    save();
  } catch(e){
    // localStorage lleno (archivos grandes en base64): guardar sin archivos como fallback
    toast('⚠️','Archivos muy grandes para almacenamiento local. Guardando solo estados.','#f5a623');
    // Guardar copia sin datos base64 de archivos
    var dbCopia = JSON.parse(JSON.stringify(db));
    if(dbCopia.gestionDocumental){
      Object.keys(dbCopia.gestionDocumental).forEach(function(cid){
        var docs = dbCopia.gestionDocumental[cid].docs || {};
        Object.keys(docs).forEach(function(did){
          if(docs[did].archivos) docs[did].archivos = docs[did].archivos.map(function(a){
            return { name: a.name, size: a.size, type: a.type };
          });
        });
      });
    }
    try { localStorage.setItem('zymo-db', JSON.stringify(dbCopia)); } catch(e2){}
  }

  renderGestionDocumental();
  renderClientes();
  cerrarModalGD();
  toast('✅','Documentos guardados','#00e676');
}

function cerrarModalGD(){
  document.getElementById('modal-gd-docs').style.display = 'none';
  document.body.style.overflow = '';
  _gdClienteId = null;
}

// Exponer estado documental para la lista de clientes
function gdBadgeCliente(clienteId){
  var sd = gdStatusDocs(clienteId);
  return '<span style="background:'+sd.color+'22;color:'+sd.color+';border:1px solid '+sd.color+'44;padding:2px 8px;border-radius:12px;font-size:10px;font-weight:700">'+sd.label+'</span>';
}

// ============================================================
// MÓDULO CRM — KANBAN PIPELINE
// ============================================================

var CRM_ESTADOS = [
  {key:'prospecto',            label:'Prospecto',                     color:'#38bdf8'},
  {key:'reconocimiento',       label:'Visita',                        color:'#818cf8'},
  {key:'propuesta',            label:'Propuesta Comercial',           color:'#f472b6'},
  {key:'aceptacion_propuesta', label:'Aceptación Propuesta Comercial',color:'#fb923c'},
  {key:'creacion_sop',         label:'Creación Ficha Cliente',        color:'#facc15'},
  {key:'facturado',            label:'Facturado',                     color:'#34d399'},
];

var CRM_ACT_ICONS = {llamada:'📞',reunion:'🤝',reunion_virtual:'💻',email:'📧',visita:'🏢',visita_presencial:'🏢',tarea:'✅',reconocimiento:'🏢',seguimiento:'🔄'};

var _crmDragId  = null;
var _crmModalId = null;

// ── Inicializar storage CRM ──────────────────────────────────
function crmGetMeta(recId){
  // Primero intentar desde db.records (nueva estrategia)
  var rec = db.records.find(function(r){ return r.id===recId; });
  if(rec && rec.crmMeta) return rec.crmMeta;
  // Migrar desde localStorage si existe
  try {
    var raw = localStorage.getItem('crm-meta-'+recId);
    if(raw){
      var migrated = JSON.parse(raw);
      if(rec){ rec.crmMeta = migrated; save(); }
      try { localStorage.removeItem('crm-meta-'+recId); } catch(e){}
      return migrated;
    }
  } catch(e){}
  return {obs:'', actividades:[], tiempos:[]};
}
function crmSaveMeta(recId, meta){
  var rec = db.records.find(function(r){ return r.id===recId; });
  if(rec){ rec.crmMeta = meta; save(); }
}

// ── Helpers ──────────────────────────────────────────────────
function crmDiasEnEstado(rec){
  var meta = crmGetMeta(rec.id);
  var tiempos = meta.tiempos||[];
  var ultimo = tiempos.filter(function(t){ return t.estado===rec.estadoProspecto; });
  if(!ultimo.length) return 0;
  var entrada = new Date(ultimo[ultimo.length-1].entrada);
  return Math.floor((Date.now()-entrada.getTime())/(1000*60*60*24));
}

function crmRegistrarCambioEstado(recId, estadoNuevo){
  var meta = crmGetMeta(recId);
  var tiempos = meta.tiempos||[];
  var ahora = new Date().toISOString();
  // Cerrar etapa anterior
  var rec = db.records.find(function(r){ return r.id===recId; });
  var estadoAnterior = rec ? (rec.estadoProspecto||'prospecto') : 'prospecto';
  if(estadoAnterior !== estadoNuevo){
    // Registrar salida del estado anterior
    for(var i=tiempos.length-1;i>=0;i--){
      if(tiempos[i].estado===estadoAnterior && !tiempos[i].salida){
        tiempos[i].salida = ahora;
        tiempos[i].dias = Math.max(0, Math.floor((new Date(ahora)-new Date(tiempos[i].entrada))/(1000*60*60*24)));
        break;
      }
    }
    // Registrar entrada al nuevo estado
    tiempos.push({estado:estadoNuevo, entrada:ahora, salida:null, dias:null});
    meta.tiempos = tiempos;
    crmSaveMeta(recId, meta);
  }
}

function crmInitEstado(recId){
  // Si nunca tuvo registro de tiempo, inicializar con estado actual
  var meta = crmGetMeta(recId);
  if(!meta.tiempos||!meta.tiempos.length){
    var rec = db.records.find(function(r){ return r.id===recId; });
    if(rec){
      meta.tiempos = [{estado:rec.estadoProspecto||'prospecto', entrada: rec.fecha ? rec.fecha+'T00:00:00.000Z' : new Date().toISOString(), salida:null, dias:null}];
      crmSaveMeta(recId, meta);
    }
  }
}

function crmAvatarColor(nombre){
  var cols = ['#00c2ff','#a855f7','#f5a623','#00e676','#ff6b6b','#34d399','#fb923c','#60a5fa'];
  var h = 0;
  for(var i=0;i<(nombre||'').length;i++) h = (nombre.charCodeAt(i)+h*31)%cols.length;
  return cols[Math.abs(h)%cols.length];
}

function crmServiciosLabel(rec){
  var labels = gdCompaniasCliente(rec);
  return labels.length ? labels.join(', ') : (rec.servicios||[]).join(', ')||'—';
}

// ── Render principal ─────────────────────────────────────────
function renderCRM(){
  // Poblar filtro comercial una sola vez
  var selCom = document.getElementById('crm-filter-comercial');
  if(selCom && selCom.options.length===1){
    db.comerciales.forEach(function(c){
      var o=document.createElement('option'); o.value=c.id; o.textContent='👤 '+c.nombre; selCom.appendChild(o);
    });
  }

  var filtCom  = (document.getElementById('crm-filter-comercial')||{}).value||'';
  var filtServ = (document.getElementById('crm-filter-servicio')||{}).value||'';

  // SOLO prospectos — los clientes activos (tipo==='cliente') no aparecen aquí
  var prospectos = db.records.filter(function(r){
    if(r.tipo !== 'prospecto') return false;
    if(filtCom  && r.comercialId !== filtCom) return false;
    if(filtServ && !gdCompaniasCliente(r).includes(filtServ)) return false;
    return true;
  });

  prospectos.forEach(function(r){
    // Normalizar estados legacy al nuevo sistema
    if(!r.estadoProspecto || r.estadoProspecto === 'seguimiento') r.estadoProspecto = 'prospecto';
    if(r.estadoProspecto === 'cerrado') r.estadoProspecto = 'facturado';
    crmInitEstado(r.id);
  });

  // KPIs
  var total      = prospectos.length;
  var ACTIVOS    = ['prospecto','reconocimiento','propuesta','aceptacion_propuesta','creacion_sop'];
  var enPipeline = prospectos.filter(function(r){ return ACTIVOS.includes(r.estadoProspecto||'prospecto'); }).length;
  var facturados = prospectos.filter(function(r){ return r.estadoProspecto==='facturado'; }).length;
  var perdidos   = prospectos.filter(function(r){ return r.estadoProspecto==='perdido'||r.estadoProspecto==='frio'; }).length;
  var diasTotal  = prospectos.reduce(function(a,r){ return a+crmDiasEnEstado(r); },0);
  var promDias   = total>0?Math.round(diasTotal/total):0;
  var totalIngresos = prospectos.reduce(function(a,r){ return a+(Number(r.ingresosEsperados)||0); },0);

  var kpiEl = document.getElementById('crm-kpis');
  if(kpiEl) kpiEl.innerHTML = [
    {label:'Total Prospectos',   val:total,                                                        col:'#00c2ff'},
    {label:'En Pipeline',        val:enPipeline,                                                   col:'#a855f7'},
    {label:'Facturados',         val:facturados,                                                   col:'#00e676'},
    {label:'Frío / Perdido',     val:perdidos,                                                     col:'#ff4444'},
    {label:'Prom. Días/Etapa',   val:promDias+'d',                                                 col:'#f5a623'},
    {label:'Ingresos Esperados', val:totalIngresos?'$'+Math.round(totalIngresos/1000000)+'M':'—', col:'#f5a623'},
  ].map(function(k){
    return '<div style="background:var(--surface);border:1px solid var(--border);border-top:3px solid '+k.col+';border-radius:10px;padding:12px 14px">'
      +'<div style="font-size:10px;color:var(--text2);letter-spacing:1.2px;text-transform:uppercase;font-weight:700;margin-bottom:6px">'+k.label+'</div>'
      +'<div style="font-family:\'Barlow Condensed\',sans-serif;font-size:28px;font-weight:800;color:'+k.col+'">'+k.val+'</div>'
      +'</div>';
  }).join('');

  // Board
  // ── Alerta global de actividades vencidas ──────────────────────────────────
  var globalAlert = document.getElementById('crm-global-alert');
  if(globalAlert){
    var hoyStr = new Date().toISOString().slice(0,10);
    var todasVencidas = [];
    (db.records||[]).forEach(function(r){
      var meta = crmGetMeta(r.id);
      (meta.actividades||[]).forEach(function(a){
        if(!a.done && a.fecha && a.fecha <= hoyStr){
          todasVencidas.push({empresa:r.empresa, id:r.id, desc:a.desc, fecha:a.fecha});
        }
      });
    });
    if(todasVencidas.length){
      globalAlert.style.display = 'flex';
      var detalles = todasVencidas.slice(0,5).map(function(v){
        return '<div style="display:flex;align-items:center;gap:8px;margin-top:6px">'
          +'<span style="font-size:11px;background:rgba(248,113,113,0.15);color:#f87171;border:1px solid rgba(248,113,113,0.3);padding:1px 8px;border-radius:6px;white-space:nowrap">'+v.fecha+'</span>'
          +'<span style="font-size:12px;color:var(--text);font-weight:600">'+v.empresa+'</span>'
          +'<span style="font-size:12px;color:var(--text2)">— '+v.desc+'</span>'
          +'<button onclick="crmAbrirModalActividades(\'' + v.id + '\')" style="margin-left:auto;background:rgba(248,113,113,0.12);border:1px solid rgba(248,113,113,0.3);color:#f87171;border-radius:5px;padding:2px 10px;font-size:11px;cursor:pointer;white-space:nowrap;font-weight:700">Ver Actividad</button>'
          +'</div>';
      }).join('');
      var extras = todasVencidas.length>5 ? '<div style="font-size:11px;color:#f8717188;margin-top:6px">+ '+(todasVencidas.length-5)+' más...</div>' : '';
      globalAlert.innerHTML = '<span style="font-size:22px;flex-shrink:0">⚠️</span>'
        +'<div style="flex:1;min-width:0">'
        +'<div style="font-size:14px;font-weight:700;color:#f87171">'+todasVencidas.length+' actividad'+(todasVencidas.length>1?'es vencidas':' vencida')+' sin completar</div>'
        +detalles+extras+'</div>';
    } else {
      globalAlert.style.display = 'none';
    }
  }

  var board = document.getElementById('crm-board');
  if(!board) return;
  board.innerHTML = '';

  CRM_ESTADOS.forEach(function(est){
    var cards = prospectos.filter(function(r){ return (r.estadoProspecto||'prospecto')===est.key; });
    var totalCol = cards.reduce(function(a,r){ return a+(Number(r.ingresosEsperados)||0); },0);

    var col = document.createElement('div');
    col.className = 'crm-col';
    col.innerHTML =
      '<div class="crm-col-header">'
      +'<div class="crm-col-bar" style="background:'+est.color+'"></div>'
      +'<div class="crm-col-header-inner">'
      +'<div class="crm-col-title" style="color:'+est.color+'">'+est.label+'</div>'
      +'<div class="crm-col-meta">'
      +'<span style="background:'+est.color+'18;color:'+est.color+';border:1px solid '+est.color+'30;padding:2px 8px;border-radius:8px;font-size:10px;font-weight:600">'+cards.length+' oportunidad'+(cards.length!==1?'es':'')+'</span>'
      +(totalCol?'<span class="crm-col-total" style="color:'+est.color+'">$'+Math.round(totalCol/1000).toLocaleString('es-CO')+'k</span>':'')
      +'</div>'
      +'</div>'
      +'</div>'
      +'<div class="crm-cards" data-estado="'+est.key+'">'
      + cards.map(function(r){ return crmBuildCard(r, est.color); }).join('')
      +'</div>';
    board.appendChild(col);

  }); // end CRM_ESTADOS.forEach

  // ── Mouse-event drag + click para abrir ─────────────────────────────────────
  board.querySelectorAll('.crm-card').forEach(function(card){
    card.style.cursor = 'grab';

    card.addEventListener('mousedown', function(e){
      if(e.button !== 0) return;
      var startX = e.clientX, startY = e.clientY;
      var moved = false, ghost = null;
      _crmDragId = card.dataset.id;

      function onMove(ev){
        if(!moved && Math.abs(ev.clientX-startX)<3 && Math.abs(ev.clientY-startY)<3) return;
        if(!moved){
          moved = true;
          card.style.opacity = '0.2';
          ghost = card.cloneNode(true);
          ghost.style.cssText = 'position:fixed;z-index:9999;pointer-events:none;width:'+card.offsetWidth+'px;opacity:0.9;transform:rotate(2deg) scale(1.03);transition:none;box-shadow:0 8px 32px rgba(0,0,0,0.5)';
          document.body.appendChild(ghost);
        }
        if(ghost){ ghost.style.left=(ev.clientX-card.offsetWidth/2)+'px'; ghost.style.top=(ev.clientY-20)+'px'; }
        board.querySelectorAll('.crm-cards').forEach(function(z){ z.classList.remove('drag-over'); });
        var el = document.elementFromPoint(ev.clientX, ev.clientY);
        var zone = el ? el.closest('.crm-cards') : null;
        if(zone) zone.classList.add('drag-over');
      }

      function onUp(ev){
        document.removeEventListener('mousemove', onMove);
        document.removeEventListener('mouseup', onUp);
        if(ghost){ ghost.remove(); ghost=null; }
        card.style.opacity = '';
        card.style.cursor = 'grab';
        board.querySelectorAll('.crm-cards').forEach(function(z){ z.classList.remove('drag-over'); });
        if(!moved){
          _crmDragId = null;
          crmAbrirModal(card.dataset.id);
          return;
        }
        var el = document.elementFromPoint(ev.clientX, ev.clientY);
        var zone = el ? el.closest('.crm-cards') : null;
        if(zone){
          var nuevoEstado = zone.dataset.estado;
          var rec = db.records.find(function(r){ return r.id===_crmDragId; });
          if(rec && rec.estadoProspecto !== nuevoEstado){
            crmRegistrarCambioEstado(rec.id, nuevoEstado);
            rec.estadoProspecto = nuevoEstado;
            save();
            var est = CRM_ESTADOS.find(function(x){ return x.key===nuevoEstado; });
            toast('✅', est?est.label:nuevoEstado, '#00e676');
            renderCRM(); renderProspectos();
          }
        }
        _crmDragId = null;
      }

      document.addEventListener('mousemove', onMove);
      document.addEventListener('mouseup', onUp);
    });
  });
}


function crmBuildCard(r, color){
  var meta     = crmGetMeta(r.id);
  var dias     = crmDiasEnEstado(r);
  var actPend  = (meta.actividades||[]).filter(function(a){ return !a.done; }).length;
  var actVenc  = (meta.actividades||[]).filter(function(a){ return !a.done && a.fecha && new Date(a.fecha+'T23:59:59')<new Date(); }).length;
  var initials = (r.comercialNombre||'?').split(' ').map(function(w){return w[0];}).join('').substring(0,2).toUpperCase();
  var avatarCol= crmAvatarColor(r.comercialNombre);
  var companias= gdCompaniasCliente(r);
  var diasColor= dias>14?'#ff4444':dias>7?'#f5a623':'var(--text2)';

  var ingresos = Number(r.ingresosEsperados)||0;
  var estrellas = ingresos > 50000000 ? 3 : ingresos > 10000000 ? 2 : ingresos > 0 ? 1 : 0;
  var starsHtml = estrellas > 0
    ? '<span class="crm-star">'+'★'.repeat(estrellas)+'<span style="color:var(--border)">'+'★'.repeat(3-estrellas)+'</span></span>'
    : '<span style="color:var(--border)">★★★</span>';

  // Próxima actividad
  var hoyStr = new Date().toISOString().slice(0,10);
  var proxAct = (meta.actividades||[]).filter(function(a){ return !a.done && a.fecha; }).sort(function(a,b){ return a.fecha.localeCompare(b.fecha); })[0];
  var proxHTML = '';
  if(proxAct){
    var esHoyOAntes = proxAct.fecha <= hoyStr;
    var esVencida   = proxAct.fecha < hoyStr;
    var badgeColor  = esVencida ? '#ff4444' : esHoyOAntes ? '#f5a623' : 'var(--text2)';
    var badgeBg     = esVencida ? 'rgba(255,68,68,0.12)' : esHoyOAntes ? 'rgba(245,166,35,0.12)' : 'transparent';
    var badgeBorder = esVencida ? '1px solid rgba(255,68,68,0.35)' : esHoyOAntes ? '1px solid rgba(245,166,35,0.35)' : 'none';
    var badgeLabel  = esVencida ? '⚠️ Vencida' : esHoyOAntes ? '🔔 Hoy' : '';
    proxHTML = '<div style="display:flex;align-items:center;gap:4px;background:'+badgeBg+';border:'+badgeBorder+';border-radius:5px;padding:'+(esHoyOAntes?'2px 6px':'0')+'">'
      +'<span style="font-size:10px;color:'+badgeColor+';font-weight:'+(esHoyOAntes?'700':'400')+'">'+CRM_ACT_ICONS[proxAct.tipo]+' '+proxAct.fecha+'</span>'
      +(badgeLabel ? '<span style="font-size:9px;font-weight:800;color:'+badgeColor+'">'+badgeLabel+'</span>' : '')
      +'</div>';
  } else {
    proxHTML = '<span style="font-size:10px;color:var(--border)">Sin actividad</span>';
  }

  return '<div class="crm-card" data-id="'+r.id+'" style="border-left-color:'+color+'">'
    +'<div class="crm-card-title">'+r.empresa+'</div>'
    +(r.contacto?'<div class="crm-card-sub">'+r.contacto+'</div>':'')
    +(ingresos?'<div class="crm-card-amount">$ '+Math.round(ingresos/1000).toLocaleString('es-CO')+'k / mes</div>':'')
    +'<hr class="crm-card-divider">'
    +'<div class="crm-card-footer">'
    +proxHTML
    +'<div style="display:flex;align-items:center;gap:6px;flex-shrink:0">'
    +(actVenc>0?'<span style="font-size:9px;font-weight:800;color:#ff4444;background:rgba(255,68,68,0.1);border:1px solid rgba(255,68,68,0.3);border-radius:4px;padding:1px 5px">'+actPend+'⚠</span>':actPend>0?'<span style="font-size:9px;font-weight:700;color:#f5a623;background:rgba(245,166,35,0.1);border:1px solid rgba(245,166,35,0.3);border-radius:4px;padding:1px 5px">'+actPend+'✓</span>':'')
    +(dias>0?'<span style="font-size:10px;color:'+diasColor+';font-weight:600">'+dias+'d</span>':'')
    +'<div class="crm-avatar" style="background:'+avatarCol+';width:22px;height:22px;font-size:9px" title="'+r.comercialNombre+'">'+initials+'</div>'
    +'<button class="crm-ver-btn" data-rid="'+r.id+'" style="background:rgba(0,194,255,0.12);border:1px solid rgba(0,194,255,0.3);color:var(--accent);border-radius:5px;padding:2px 8px;font-size:10px;cursor:pointer;font-weight:700">Ver</button>'
    +'</div>'
    +'</div>'
    +'</div>';
}

// ── Detalle pantalla completa estilo Odoo ───────────────────
function crmAbrirModal(recId){
  _crmModalId = recId;
  var rec  = db.records.find(function(r){ return r.id===recId; });
  if(!rec) return;
  var meta = crmGetMeta(recId);

  // Título
  var _s = function(id, val){ var el=document.getElementById(id); if(el) el.textContent=val; };
  var _v = function(id, val){ var el=document.getElementById(id); if(el) el.value=val; };
  var _h = function(id, val){ var el=document.getElementById(id); if(el) el.innerHTML=val; };
  _s('crm-det-titulo', rec.empresa);
  _s('crm-det-nombre-bc', rec.empresa);

  // Barra de etapas
  var stagesEl = document.getElementById('crm-det-stages');
  var estAct = rec.estadoProspecto||'prospecto';
  var idxAct = CRM_ESTADOS.findIndex(function(e){ return e.key===estAct; });
  stagesEl.innerHTML = CRM_ESTADOS.map(function(est, idx){
    var isPast    = idx < idxAct;
    var isCurrent = idx === idxAct;
    var bg = isCurrent ? est.color : isPast ? est.color+'55' : 'transparent';
    var col= isCurrent ? '#000'    : isPast ? '#fff'          : 'var(--text2)';
    var fw = isCurrent ? '800' : '600';
    return '<div onclick="crmDetCambiarEstado(\''+est.key+'\')" style="flex:1;min-width:0;padding:8px 6px;text-align:center;background:'+bg+';color:'+col+';font-size:10px;font-weight:'+fw+';cursor:pointer;letter-spacing:0.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;transition:background 0.2s" title="'+est.label+'">'+est.label+'</div>';
  }).join('');

  // Ingresos
  var ingresos = Number(rec.ingresosEsperados)||0;
  _v('crm-det-ingresos', ingresos||'');
  _s('crm-det-ingresos-fmt', ingresos ? '$ '+ingresos.toLocaleString('es-CO') : '$ 0,00');


  // Datos contacto
  // Datos contacto
  _s('crm-det-contacto', rec.contacto||'—');
  _s('crm-det-email', rec.email||'—');
  _s('crm-det-telefono', rec.telefono||rec.tel||'—');
  _s('crm-det-ciudad', rec.ciudad||'—');
  _s('crm-det-fecha', rec.fecha||'—');

  // Servicios
  _h('crm-det-servicios', (rec.servicios||[]).map(function(s){ return '<span class="crm-tag">'+s+'</span>'; }).join(''));

  // Compañías
  _h('crm-det-companias', gdCompaniasCliente(rec).map(function(c){ return '<span class="crm-tag">'+c+'</span>'; }).join('') || '<span style="color:var(--text2);font-size:12px">—</span>');

  // Comercial avatar
  var initials = (rec.comercialNombre||'?').split(' ').map(function(w){return w[0];}).join('').substring(0,2).toUpperCase();
  var avEl = document.getElementById('crm-det-avatar');
  if(avEl){ avEl.textContent = initials; avEl.style.background = crmAvatarColor(rec.comercialNombre); }
  _s('crm-det-comercial', rec.comercialNombre||'—');


  // Notas / obs
  _v('crm-det-obs', meta.obs||'');

  // Actividades
  crmRenderActividades(meta);

  // Tiempos
  crmRenderTiempos(meta);

  // Tab por defecto
  crmDetTab('actividades');
  setTimeout(crmCheckActividadesVencidas, 50);

  // Mostrar página de detalle (no overlay — usa el sistema de páginas)
  document.querySelectorAll('.page').forEach(function(p){ p.classList.remove('active'); });
  document.getElementById('page-crm-detalle').classList.add('active');
  window.scrollTo({top:0, behavior:'instant'});
}

function closeCRMDetalle(){
  _crmModalId = null;
  document.querySelectorAll('.page').forEach(function(p){ p.classList.remove('active'); });
  document.getElementById('page-crm').classList.add('active');
  window.scrollTo({top:0, behavior:'instant'});
  renderCRM();
}

// alias para compatibilidad
function closeCRMModal(){ closeCRMDetalle(); }

function crmDetTab(tab){
  // El nuevo layout muestra actividades siempre en la columna derecha
  // Esta función se mantiene para compatibilidad pero no oculta paneles
}

function crmDetCambiarEstado(nuevoEstado){
  if(!_crmModalId) return;
  var rec = db.records.find(function(r){ return r.id===_crmModalId; });
  if(!rec) return;
  crmRegistrarCambioEstado(rec.id, nuevoEstado);
  rec.estadoProspecto = nuevoEstado;
  save();
  crmAbrirModal(rec.id); // refrescar
  renderCRM();
}

function crmGuardarDetalle(){
  if(!_crmModalId) return;
  var rec = db.records.find(function(r){ return r.id===_crmModalId; });
  if(!rec) return;
  // Ingresos
  var ingEl = document.getElementById('crm-det-ingresos');
  if(ingEl) rec.ingresosEsperados = Number(ingEl.value)||0;

  // Observaciones
  var obsEl = document.getElementById('crm-det-obs');
  var meta  = crmGetMeta(_crmModalId);
  if(obsEl) meta.obs = obsEl.value;
  crmSaveMeta(_crmModalId, meta);
  save();
  toast('✅','Cambios guardados','#00e676');
  closeCRMDetalle();
}

function crmGuardarModal(){ crmGuardarDetalle(); }
function crmCambiarEstado(){ /* handled by crmDetCambiarEstado */ }

function crmRenderTiempos(meta){
  var el = document.getElementById('crm-modal-tiempos');
  if(!el) return;
  var tiempos = meta.tiempos||[];
  if(!tiempos.length){ el.innerHTML='<span style="font-size:12px;color:var(--text2)">Sin historial de etapas aún</span>'; return; }
  el.innerHTML = tiempos.map(function(t){
    var est = CRM_ESTADOS.find(function(e){ return e.key===t.estado; });
    var col = est ? est.color : 'var(--text2)';
    var lbl = est ? est.label : t.estado;
    var dur = t.dias!==null ? t.dias+'d' : (t.entrada ? Math.max(0,Math.floor((Date.now()-new Date(t.entrada).getTime())/(1000*60*60*24)))+'d (actual)' : '—');
    return '<div style="background:'+col+'18;border:1px solid '+col+'40;border-radius:8px;padding:10px 14px;min-width:130px">'
      +'<div style="color:'+col+';font-weight:700;font-size:12px;margin-bottom:4px">'+lbl+'</div>'
      +'<div style="color:var(--text2);font-size:13px;font-family:\'Barlow Condensed\',sans-serif;font-weight:700">⏱ '+dur+'</div>'
      +'</div>';
  }).join('');
}

function crmRenderActividades(meta){
  var lista = document.getElementById('crm-actividades-lista');
  if(!lista) return;
  var acts = meta.actividades||[];
  if(!acts.length){ lista.innerHTML='<div style="font-size:13px;color:var(--text2);padding:20px 0">Sin actividades registradas</div>'; return; }
  lista.innerHTML = acts.map(function(a,i){
    var icon = CRM_ACT_ICONS[a.tipo]||'📋';
    var fechaStr = a.fecha ? ' · 📅 '+a.fecha : '';
    var vencida = a.fecha && !a.done && new Date(a.fecha+'T23:59:59') < new Date();
    return '<div class="crm-act-item '+(a.done?'crm-act-done':'')+'" style="'+(vencida?'border-color:#ff444460':'')+'">'
      +'<div style="font-size:20px;flex-shrink:0;margin-top:2px">'+icon+'</div>'
      +'<div style="flex:1;min-width:0">'
      +'<div class="crm-act-desc" style="font-size:13px;font-weight:600;color:var(--text)">'+a.desc+'</div>'
      +'<div style="font-size:11px;color:'+(vencida?'#ff4444':'var(--text2)')+'">'+a.tipo.charAt(0).toUpperCase()+a.tipo.slice(1)+fechaStr+(vencida?' ⚠️ Vencida':'')+'</div>'
      +'</div>'
      +'<div style="display:flex;gap:6px;flex-shrink:0">'
      +(a.done
        ? '<span style="font-size:11px;color:#00e676;font-weight:700">✓ Hecho</span>'
        : '<button onclick="crmMarcarHecha('+i+')" style="background:rgba(0,230,118,0.1);border:1px solid rgba(0,230,118,0.3);color:#00e676;border-radius:6px;padding:4px 10px;font-size:11px;cursor:pointer">✓</button>')
      +'<button onclick="crmEliminarActividad('+i+')" style="background:rgba(255,68,68,0.1);border:1px solid rgba(255,68,68,0.3);color:#ff4444;border-radius:6px;padding:4px 10px;font-size:11px;cursor:pointer">✕</button>'
      +'</div></div>';
  }).join('');
}

function crmActTipoChange(val){
  var horaRow = document.getElementById('crm-act-hora-row');
  if(horaRow) horaRow.style.display = (val==='visita_presencial'||val==='reunion_virtual') ? 'block' : 'none';
}

function crmAgregarActividad(){
  var form = document.getElementById('crm-act-form');
  if(!form) return;
  form.dataset.recId = _crmModalId || '';
  form.style.display = 'block';
  document.getElementById('crm-act-fecha').value = new Date().toISOString().slice(0,10);
  document.getElementById('crm-act-desc').value = '';
  document.getElementById('crm-act-tipo').value = 'llamada';
  var horaRow = document.getElementById('crm-act-hora-row');
  if(horaRow) horaRow.style.display = 'none';
  var horaEl = document.getElementById('crm-act-hora');
  if(horaEl) horaEl.value = '';
  setTimeout(function(){ document.getElementById('crm-act-desc').focus(); }, 50);
}

function crmGuardarActividad(){
  try {
    var recId = _crmModalId;
    if(!recId){
      alert('Error: no hay cliente activo. Por favor cierra y vuelve a abrir el cliente.');
      return;
    }

    var descEl = document.getElementById('crm-act-desc');
    var desc   = descEl ? descEl.value.trim() : '';
    if(!desc){
      alert('Escribe una descripción para la actividad.');
      return;
    }

    var tipoEl  = document.getElementById('crm-act-tipo');
    var fechaEl = document.getElementById('crm-act-fecha');
    var tipo  = tipoEl  ? tipoEl.value  : 'llamada';
    var fecha = fechaEl ? fechaEl.value : new Date().toISOString().slice(0,10);

    var meta = crmGetMeta(recId);
    meta.actividades = meta.actividades || [];
    var horaEl2 = document.getElementById('crm-act-hora');
    var hora = (tipo==='visita_presencial'||tipo==='reunion_virtual') && horaEl2 ? horaEl2.value : '';
    meta.actividades.push({
      tipo: tipo,
      desc: desc,
      fecha: fecha,
      hora: hora,
      done: false,
      creadoEn: new Date().toISOString()
    });
    crmSaveMeta(recId, meta);

    // Limpiar form
    if(descEl) descEl.value = '';
    var formEl = document.getElementById('crm-act-form');
    if(formEl) formEl.style.display = 'none';

    // Feedback y volver
    toast('✅', 'Actividad guardada', '#00e676');
    setTimeout(function(){
      closeCRMDetalle();
    }, 900);

  } catch(e) {
    alert('Error al guardar: ' + e.message);
  }
}

function crmMarcarHecha(idx){
  if(!_crmModalId) return;
  var meta = crmGetMeta(_crmModalId);
  if(meta.actividades[idx]) meta.actividades[idx].done = true;
  crmSaveMeta(_crmModalId, meta);
  crmRenderActividades(meta);
  crmCheckActividadesVencidas();
  renderCRM();
}

function crmEliminarActividad(idx){
  if(!_crmModalId) return;
  var meta = crmGetMeta(_crmModalId);
  meta.actividades.splice(idx,1);
  crmSaveMeta(_crmModalId, meta);
  crmRenderActividades(meta);
}

function crmCheckActividadesVencidas(){
  if(!_crmModalId) return;
  var meta = crmGetMeta(_crmModalId);
  var alertEl = document.getElementById('crm-act-alert-banner');
  if(!alertEl) return;
  var hoyStr = new Date().toISOString().slice(0,10);
  var vencidas = (meta.actividades||[]).filter(function(a){ return !a.done && a.fecha && a.fecha <= hoyStr; });
  if(vencidas.length){
    alertEl.style.display = 'flex';
    alertEl.innerHTML = '<span style="font-size:20px;flex-shrink:0">⚠️</span>'
      +'<div style="flex:1"><div style="font-size:14px;font-weight:700;color:#f87171">'+vencidas.length+' actividad'+(vencidas.length>1?'es vencidas':' vencida')+'</div>'
      +'<div style="font-size:12px;color:#f8717188;margin-top:3px">Ve a la pestaña <strong style="color:#f87171">Actividades</strong> y márcalas como completadas.</div></div>';
  } else {
    alertEl.style.display = 'none';
    alertEl.innerHTML = '';
  }
}
setInterval(crmCheckActividadesVencidas, 60000);

function crmAutoSave(){
  if(!_crmModalId) return;
  var meta = crmGetMeta(_crmModalId);
  var obsEl = document.getElementById('crm-det-obs');
  if(obsEl) meta.obs = obsEl.value;
  crmSaveMeta(_crmModalId, meta);
}






// ============================================================
// MÓDULO CALENDARIO DE VISITAS
// ============================================================
var _calAnio=new Date().getFullYear(),_calMes=new Date().getMonth(),_calDia=new Date().getDate(),_calVista='mes';
var MESES_ES_CAL=['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
var DIAS_LARGOS=['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'];
function calSetVista(v){_calVista=v;var bm=document.getElementById('cal-btn-mes'),bd=document.getElementById('cal-btn-dia');if(bm){bm.style.background=v==='mes'?'var(--accent2)':'transparent';bm.style.color=v==='mes'?'#fff':'var(--text2)';}if(bd){bd.style.background=v==='dia'?'var(--accent2)':'transparent';bd.style.color=v==='dia'?'#fff':'var(--text2)';}document.getElementById('cal-vista-mes').style.display=v==='mes'?'block':'none';document.getElementById('cal-vista-dia').style.display=v==='dia'?'block':'none';renderCalendario();}
function calPrevPeriodo(){if(_calVista==='dia'){var d=new Date(_calAnio,_calMes,_calDia-1);_calAnio=d.getFullYear();_calMes=d.getMonth();_calDia=d.getDate();}else{_calMes--;if(_calMes<0){_calMes=11;_calAnio--;}}renderCalendario();}
function calNextPeriodo(){if(_calVista==='dia'){var d=new Date(_calAnio,_calMes,_calDia+1);_calAnio=d.getFullYear();_calMes=d.getMonth();_calDia=d.getDate();}else{_calMes++;if(_calMes>11){_calMes=0;_calAnio++;}}renderCalendario();}
function calIrHoy(){var h=new Date();_calAnio=h.getFullYear();_calMes=h.getMonth();_calDia=h.getDate();renderCalendario();}
function calGetVisitasDia(fechaStr,filtCom){var r=[];(db.records||[]).forEach(function(rec){if(filtCom&&rec.comercialId!==filtCom)return;var meta=crmGetMeta(rec.id);(meta.actividades||[]).forEach(function(a){if(a.fecha===fechaStr&&(a.tipo==='visita'||a.tipo==='visita_presencial'||a.tipo==='reunion_virtual'))r.push({empresa:rec.empresa,comercial:rec.comercialNombre||'—',desc:a.desc,hora:a.hora||'',lugar:a.lugar||'',done:a.done,recId:rec.id});});});return r;}
function calGetVisitasMes(anio,mes,filtCom){var m={};(db.records||[]).forEach(function(rec){if(filtCom&&rec.comercialId!==filtCom)return;var meta=crmGetMeta(rec.id);(meta.actividades||[]).forEach(function(a){if((a.tipo==='visita'||a.tipo==='visita_presencial'||a.tipo==='reunion_virtual')&&a.fecha){var d=new Date(a.fecha+'T12:00:00');if(d.getFullYear()===anio&&d.getMonth()===mes){if(!m[a.fecha])m[a.fecha]=[];m[a.fecha].push({empresa:rec.empresa,comercial:rec.comercialNombre||'—',desc:a.desc,hora:a.hora||'',lugar:a.lugar||'',done:a.done,recId:rec.id});}}});});return m;}
function renderCalendario(){var selCom=document.getElementById('cal-filter-comercial');if(selCom&&selCom.options.length===1)(db.comerciales||[]).forEach(function(c){var o=document.createElement('option');o.value=c.id;o.textContent='👤 '+c.nombre;selCom.appendChild(o);});var filtCom=(selCom||{}).value||'';var labelEl=document.getElementById('cal-mes-label');if(_calVista==='dia'){var d=new Date(_calAnio,_calMes,_calDia);if(labelEl)labelEl.textContent=DIAS_LARGOS[d.getDay()]+', '+_calDia+' de '+MESES_ES_CAL[_calMes]+' '+_calAnio;renderCalendarioDia(filtCom);return;}if(labelEl)labelEl.textContent=MESES_ES_CAL[_calMes]+' '+_calAnio;var hoyStr=new Date().toISOString().slice(0,10);var visitasMes=calGetVisitasMes(_calAnio,_calMes,filtCom);var primerDia=new Date(_calAnio,_calMes,1);var offset=primerDia.getDay()===0?6:primerDia.getDay()-1;var diasEnMes=new Date(_calAnio,_calMes+1,0).getDate();var totalCeldas=Math.ceil((offset+diasEnMes)/7)*7;var grid=document.getElementById('cal-grid');if(!grid)return;var html='';for(var i=0;i<totalCeldas;i++){var diaNum=i-offset+1;var esMes=diaNum>=1&&diaNum<=diasEnMes;var fechaStr='';var visitas=[];var esHoy=false;var esFin=(i%7===5||i%7===6);if(esMes){fechaStr=_calAnio+'-'+String(_calMes+1).padStart(2,'0')+'-'+String(diaNum).padStart(2,'0');visitas=visitasMes[fechaStr]||[];esHoy=fechaStr===hoyStr;}var bgDia=esMes?'var(--surface)':'var(--surface2)';var numBg=esHoy?'var(--accent)':'transparent';var numColor=esHoy?'#000':esFin?(i%7===6?'#f87171':'var(--accent2)'):'var(--text2)';var visitasHtml='';if(visitas.length>0){var shown=visitas.slice(0,3);shown.forEach(function(v){var col=v.done?'#64748b':'#34d399';visitasHtml+='<div onclick="event.stopPropagation();calAbrirDia(\'' + fechaStr + '\')" style="cursor:pointer;background:'+col+'18;border-left:2px solid '+col+';border-radius:3px;padding:2px 6px;margin-bottom:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:10px;color:'+col+';font-weight:600">'+v.empresa+'</div>';});if(visitas.length>3)visitasHtml+='<div style="font-size:9px;color:var(--text2);padding-left:4px">+'+(visitas.length-3)+' más</div>';}var clickHandler=esMes?'onclick="calAbrirDia(\'' + fechaStr + '\')"':'';var bgCell = !esMes ? 'var(--surface2)' : (i%7===5||i%7===6) ? 'rgba(56,189,248,0.03)' : 'var(--surface)';
var borderTop = esHoy ? '3px solid var(--accent)' : '1px solid var(--border)';
html+='<div '+clickHandler+' style="height:100%;box-sizing:border-box;padding:8px;background:'+bgCell+';border-top:'+borderTop+';border-right:1px solid var(--border);border-bottom:1px solid var(--border);cursor:'+(esMes?'pointer':'default')+'">'
  +(esMes?'<div style="font-family:Barlow Condensed,sans-serif;width:28px;height:28px;border-radius:50%;background:'+numBg+';display:flex;align-items:center;justify-content:center;font-size:15px;font-weight:800;color:'+numColor+';margin-bottom:6px">'+diaNum+'</div>':'')
  +visitasHtml+'</div>';}grid.innerHTML=html;document.getElementById('cal-detalle-panel').style.display='none';}
function calAbrirDia(fechaStr){var d=new Date(fechaStr+'T12:00:00');_calAnio=d.getFullYear();_calMes=d.getMonth();_calDia=d.getDate();calSetVista('dia');}
function renderCalendarioDia(filtCom){var fechaStr=_calAnio+'-'+String(_calMes+1).padStart(2,'0')+'-'+String(_calDia).padStart(2,'0');var visitas=calGetVisitasDia(fechaStr,filtCom);var tl=document.getElementById('cal-timeline');var nombreEl=document.getElementById('cal-dia-nombre');if(nombreEl){var dn=new Date(_calAnio,_calMes,_calDia);nombreEl.textContent=DIAS_LARGOS[dn.getDay()]+' '+_calDia+' de '+MESES_ES_CAL[_calMes]+' '+_calAnio;}if(!tl)return;var HORA_INICIO=6,HORA_FIN=21,ALTURA_HORA=64;var html='';for(var h=HORA_INICIO;h<=HORA_FIN;h++){var hStr=String(h).padStart(2,'0')+':00';var esAhora=h===new Date().getHours()&&fechaStr===new Date().toISOString().slice(0,10);html+='<div style="display:flex;min-height:'+ALTURA_HORA+'px;border-top:1px solid var(--border);position:relative"><div style="width:52px;flex-shrink:0;padding:4px 8px 0;font-size:11px;font-weight:600;color:var(--text2);text-align:right;line-height:1">'+hStr+'</div><div style="flex:1;border-left:1px solid var(--border);position:relative;min-height:'+ALTURA_HORA+'px">'+(esAhora?'<div style="position:absolute;top:0;left:0;right:0;height:2px;background:var(--red);z-index:2"></div>':'')+'<div id="cal-slot-'+h+'"></div></div></div>';}html+='<div style="display:flex;border-top:1px solid var(--border)"><div style="width:52px;flex-shrink:0;padding:4px 8px 0;font-size:10px;color:var(--text2);text-align:right">Sin hora</div><div style="flex:1;border-left:1px solid var(--border);padding:8px;min-height:40px" id="cal-slot-sin"></div></div>';tl.innerHTML=html;visitas.forEach(function(v){var col=v.done?'#64748b':'#34d399';var card='<div onclick="crmAbrirModalActividades(\'' + v.recId + '\')" style="cursor:pointer;margin:4px 6px;background:'+col+'18;border-left:3px solid '+col+';border-radius:6px;padding:6px 10px"><div style="font-size:12px;font-weight:700;color:'+col+'">'+v.empresa+'</div>'+(v.desc?'<div style="font-size:11px;color:var(--text2);margin-top:1px">'+v.desc+'</div>':'')+(v.lugar?'<div style="font-size:10px;color:var(--text2);margin-top:1px">📍 '+v.lugar+'</div>':'')+'<div style="font-size:10px;color:var(--text2);margin-top:2px">'+v.comercial+'</div></div>';if(v.hora){var h=parseInt(v.hora.split(':')[0]);var slotEl=document.getElementById('cal-slot-'+h);if(slotEl)slotEl.innerHTML+=card;else{var sinEl=document.getElementById('cal-slot-sin');if(sinEl)sinEl.innerHTML+=card;}}else{var sinEl=document.getElementById('cal-slot-sin');if(sinEl)sinEl.innerHTML+=card;}});}
function crmAbrirModalActividades(recId){crmAbrirModal(recId);setTimeout(function(){crmDetTab('actividades');},80);}

// ============================================================
// MÓDULO MATRIZ DE RIESGOS — FR-002-GC
// Fórmula exacta del Excel:
// puntaje = VLOOKUP(mercancia)*0.45 + tipoPersona*0.5 + tiempo*0.5
//         + capital*0.5 + frecuencia*0.15 + facturacion*0.25
//         + cert_adj + anFin_adj
// ============================================================
var MR_MERCANCIAS={'Textiles':4,'Farmacéuticos':4,'Tecnología':5,'Dispositivos Médicos':5,'Cosméticos':5,'Juguetería':5,'Electrodomésticos':4,'Repuestos automotrices':4,'Herramientas':4,'Calzado':4,'Industrial':3,'Consumo masivo':3,'Accesorios':3,'Decoración':3,'Hogar y cocina':3,'Misceláneos':2,'Alimentos secos':2,'Bebidas':2,'Papelería':2,'Material POP':2};
var MR_CONTROLES={'Bajo':'Control documental + Listas cautelares','Medio':'Control documental + Listas cautelares','Alto':'Visitas regulares a sus instalaciones + Control documental + Listas cautelares','Crítico':'Visitas regulares a sus instalaciones + Validación beneficiarios finales clientes + proveedores'};
var MR_FREC_CONTROL={'Bajo':'Anual','Medio':'Anual','Alto':'Semestral','Crítico':'Trimestral'};
var MR_OPCIONES={mercancia:['Textiles','Farmacéuticos','Tecnología','Dispositivos Médicos','Cosméticos','Juguetería','Electrodomésticos','Repuestos automotrices','Herramientas','Calzado','Industrial','Consumo masivo','Accesorios','Decoración','Hogar y cocina','Misceláneos','Alimentos secos','Bebidas','Papelería','Material POP'],tipoPersona:['Jurídica','Natural'],tiempo:['< 1 año','1 - 3 años','> 3 años'],capital:['1 M - 50M','>50M - 100M','> 100M'],frecuencia:['Bajo','Medio','Alta'],facturacion:['Bajo','Medio','Alta'],cert:['Sí','No'],anFin:['Favorable','Desfavorable','No disponible'],frecControl:['Anual','Semestral','Trimestral']};
var MR_RIESGO_COLORS={'BAJO':{bg:'rgba(52,211,153,0.1)',color:'#34d399',border:'rgba(52,211,153,0.3)'},'MEDIO':{bg:'rgba(245,158,11,0.1)',color:'#f59e0b',border:'rgba(245,158,11,0.3)'},'ALTO':{bg:'rgba(248,113,113,0.12)',color:'#f87171',border:'rgba(248,113,113,0.35)'},'CRÍTICO':{bg:'rgba(239,68,68,0.18)',color:'#ef4444',border:'rgba(239,68,68,0.5)'},'PENDIENTE':{bg:'rgba(100,116,139,0.08)',color:'#94a3b8',border:'rgba(100,116,139,0.25)'}};
function mrGetData(recordId){if(!db.matrizRiesgos)db.matrizRiesgos={};if(!db.matrizRiesgos[recordId]){var r=(db.records||[]).find(function(x){return x.id===recordId;});var cias=[];if(r&&r.servicios){var svcs=r.servicios;if(svcs.some(function(s){return ['Zona Franca','CEDI','Transporte'].indexOf(s)>=0;}))cias.push('Logimat');if(svcs.some(function(s){return ['Aduana','Depósito Aduanero'].indexOf(s)>=0;}))cias.push('IMC Cargo');if(svcs.some(function(s){return ['Paqueteo'].indexOf(s)>=0;}))cias.push('IMC Depósito');}db.matrizRiesgos[recordId]={companias:cias,mercancia:'',tipoPersona:'',tiempo:'',capital:'',frecuencia:'',facturacion:'',cert:'',anFin:'',puntaje:0,riesgo:'PENDIENTE',control:'',frecControl:''};}return db.matrizRiesgos[recordId];}
function mrCalcPuntaje(m){var p=(MR_MERCANCIAS[m.mercancia]||0)*0.45;p+=(m.tipoPersona==='Natural'?3:m.tipoPersona==='Jurídica'?1:0)*0.5;p+=(m.tiempo==='< 1 año'?5:m.tiempo==='1 - 3 años'?3:m.tiempo==='> 3 años'?1:0)*0.5;p+=(m.capital==='1 M - 50M'?5:m.capital==='>50M - 100M'?3:m.capital==='> 100M'?1:0)*0.5;p+=(m.frecuencia==='Bajo'?1:m.frecuencia==='Medio'?3:m.frecuencia==='Alta'?5:0)*0.15;p+=(m.facturacion==='Bajo'?1:m.facturacion==='Medio'?3:m.facturacion==='Alta'?5:0)*0.25;p+=(m.cert==='Sí'?-1:0);p+=(m.anFin==='Desfavorable'?1:m.anFin==='Favorable'?-0.5:0);return Math.round(p*100)/100;}
function mrCalcRiesgo(puntaje){var p=parseFloat(puntaje)||0;if(p<=0)return 'PENDIENTE';if(p>=5)return 'CRÍTICO';if(p>=4)return 'ALTO';if(p>=3)return 'MEDIO';return 'BAJO';}
function mrNivelLabel(r){return {'CRÍTICO':'Crítico','ALTO':'Alto','MEDIO':'Medio','BAJO':'Bajo'}[r]||'Bajo';}
function mrAutoControl(riesgo){var n=mrNivelLabel(riesgo);return{control:MR_CONTROLES[n]||MR_CONTROLES['Bajo'],frecControl:MR_FREC_CONTROL[n]||'Anual'};}
function mrEsCompleta(m){return !!(m.mercancia&&m.tipoPersona&&m.tiempo&&m.capital&&m.frecuencia&&m.facturacion&&m.cert&&m.anFin);}
function mrCheckAlertas(){var el=document.getElementById('mr-alerta-pendientes');if(!el)return;var sin=(db.records||[]).filter(function(r){return r.tipo==='cliente'&&!mrEsCompleta(mrGetData(r.id));});if(sin.length>0){el.style.display='flex';el.innerHTML='<span style="font-size:18px;flex-shrink:0">⚠️</span><div style="flex:1"><div style="font-size:13px;font-weight:700;color:#f87171">'+sin.length+' cliente'+(sin.length>1?'s sin':'sin')+' Matriz de Riesgos completada</div><div style="font-size:11px;color:#f8717188;margin-top:2px">Selecciona la opción correcta en cada columna para evaluar el nivel de riesgo.</div></div>';}else{el.style.display='none';}}
function mrSetTab(tab){document.getElementById('mr-panel-matriz').style.display=tab==='matriz'?'block':'none';document.getElementById('mr-panel-datos').style.display=tab==='datos'?'block':'none';var bm=document.getElementById('mr-tab-btn-matriz'),bd=document.getElementById('mr-tab-btn-datos');if(bm){bm.style.borderBottomColor=tab==='matriz'?'var(--accent)':'transparent';bm.style.color=tab==='matriz'?'var(--accent)':'var(--text2)';}if(bd){bd.style.borderBottomColor=tab==='datos'?'var(--accent)':'transparent';bd.style.color=tab==='datos'?'var(--accent)':'var(--text2)';}if(tab==='datos')renderMrDatos();setTimeout(initMRScrollSync,60);}
function renderMatrizRiesgos(){mrCheckAlertas();var search=((document.getElementById('mr-search')||{}).value||'').toLowerCase().trim();var filtRiesgo=(document.getElementById('mr-filter-riesgo')||{}).value||'';var filtCia=(document.getElementById('mr-filter-cia')||{}).value||'';var filtComp=(document.getElementById('mr-filter-completa')||{}).value||'';var clientes=(db.records||[]).filter(function(r){return r.tipo==='cliente';});var filtered=clientes.filter(function(r){var m=mrGetData(r.id);if(search&&!r.empresa.toLowerCase().includes(search)&&!(r.nit||'').includes(search))return false;if(filtRiesgo&&m.riesgo!==filtRiesgo)return false;if(filtCia&&!(m.companias||[]).includes(filtCia))return false;if(filtComp==='completa'&&!mrEsCompleta(m))return false;if(filtComp==='pendiente'&&mrEsCompleta(m))return false;return true;});var counts={'BAJO':0,'MEDIO':0,'ALTO':0,'CRÍTICO':0,'PENDIENTE':0};clientes.forEach(function(r){var m=mrGetData(r.id);counts[m.riesgo]=(counts[m.riesgo]||0)+1;});var kpiEl=document.getElementById('mr-kpis');if(kpiEl){var kpis=[{key:'PENDIENTE',label:'Sin evaluar',icon:'⏳'},{key:'BAJO',label:'Bajo',icon:'🟢'},{key:'MEDIO',label:'Medio',icon:'🟡'},{key:'ALTO',label:'Alto',icon:'🟠'},{key:'CRÍTICO',label:'Crítico',icon:'🔴'}];kpiEl.innerHTML=kpis.map(function(k){var c=MR_RIESGO_COLORS[k.key];return '<div style="background:'+c.bg+';border:1px solid '+c.border+';border-radius:8px;padding:12px 18px;display:flex;align-items:center;gap:12px;flex:1;min-width:110px"><span style="font-size:22px">'+k.icon+'</span><div><div style="font-family:Barlow Condensed,sans-serif;font-size:28px;font-weight:800;color:'+c.color+';line-height:1">'+counts[k.key]+'</div><div style="font-size:11px;color:var(--text2);font-weight:600;text-transform:uppercase;letter-spacing:0.5px;margin-top:3px">'+k.label+'</div></div></div>';}).join('');}var countEl=document.getElementById('mr-count');if(countEl)countEl.textContent=filtered.length+'/'+clientes.length+' clientes';var tbody=document.getElementById('mr-tbody');if(!tbody)return;if(!filtered.length){tbody.innerHTML='<tr><td colspan="15" style="padding:32px;text-align:center;color:var(--text2);font-size:13px">Sin clientes registrados aún. Los clientes aparecen aquí automáticamente al crearlos.</td></tr>';return;}var SS='background:var(--surface2);border:1px solid var(--border);color:var(--text);border-radius:6px;padding:6px 8px;font-size:12px;width:100%;cursor:pointer';tbody.innerHTML=filtered.map(function(r){var m=mrGetData(r.id);var cr=MR_RIESGO_COLORS[m.riesgo]||MR_RIESGO_COLORS['PENDIENTE'];var rid=r.id;var cias=(m.companias||[]).map(function(cia){return '<span style="display:inline-block;font-size:11px;font-weight:700;background:rgba(56,189,248,0.12);color:var(--accent);border:1px solid rgba(56,189,248,0.25);padding:2px 8px;border-radius:6px;margin:2px;white-space:nowrap">'+cia+'</span>';}).join('');if(!cias)cias='<span style="font-size:12px;color:var(--text2)">—</span>';function sel(field,val){var opts=MR_OPCIONES[field]||[];return '<select onchange="mrCellChange(\'' + rid + '\',\'' + field + '\',this.value)" style="'+SS+'"><option value="">— Seleccionar —</option>'+opts.map(function(o){return '<option value="'+o+'"'+(val===o?' selected':'')+'>'+o+'</option>';}).join('')+'</select>';}var TD='border-right:1px solid var(--border);';var TDP=TD+'padding:9px 12px;';var TDS=TD+'padding:5px 8px;';return '<tr style="border-bottom:1px solid var(--border);background:'+(mrEsCompleta(m)?'var(--surface)':'rgba(100,116,139,0.03)')+'">'+'<td style="'+TDP+'font-size:12px;color:var(--text2);white-space:nowrap">'+(r.nit||'—')+'</td>'+'<td style="'+TDP+'font-size:13px;font-weight:600;color:var(--text);min-width:170px;white-space:normal;line-height:1.4">'+r.empresa+'</td>'+'<td style="'+TDP+'text-align:center;min-width:140px"><div style="display:flex;flex-wrap:wrap;gap:3px;justify-content:center">'+cias+'</div></td>'+'<td style="'+TDS+'min-width:120px">'+sel('mercancia',m.mercancia)+'</td>'+'<td style="'+TDS+'min-width:90px">'+sel('tipoPersona',m.tipoPersona)+'</td>'+'<td style="'+TDS+'min-width:100px">'+sel('tiempo',m.tiempo)+'</td>'+'<td style="'+TDS+'min-width:95px">'+sel('capital',m.capital)+'</td>'+'<td style="'+TDS+'min-width:80px">'+sel('frecuencia',m.frecuencia)+'</td>'+'<td style="'+TDS+'min-width:80px">'+sel('facturacion',m.facturacion)+'</td>'+'<td style="'+TDS+'min-width:75px">'+sel('cert',m.cert)+'</td>'+'<td style="'+TDS+'min-width:100px">'+sel('anFin',m.anFin)+'</td>'+'<td style="'+TDP+'text-align:center;font-family:Barlow Condensed,sans-serif;font-size:20px;font-weight:800;color:'+cr.color+'">'+(m.puntaje>0?m.puntaje.toFixed(2):'—')+'</td>'+'<td style="'+TDP+'text-align:center"><span style="background:'+cr.bg+';color:'+cr.color+';border:1px solid '+cr.border+';padding:4px 12px;border-radius:8px;font-size:12px;font-weight:700;white-space:nowrap">'+m.riesgo+'</span></td>'+'<td style="'+TDS+'min-width:220px;white-space:normal"><input type="text" value="'+escHtml(m.control||'')+'" onblur="mrCellChange(\'' + rid + '\',\'control\',this.value)" placeholder="Control a aplicar..." style="background:var(--surface2);border:1px solid var(--border);color:var(--text);border-radius:6px;padding:6px 8px;font-size:12px;width:100%;box-sizing:border-box"></td>'+'<td style="'+TDS+'min-width:85px">'+sel('frecControl',m.frecControl)+'</td>'+'</tr>';}).join('');setTimeout(function(){var wrap=document.getElementById('mr-table-wrap'),inner=document.getElementById('mr-scroll-inner');if(wrap&&inner)inner.style.width=wrap.scrollWidth+'px';},60);}
function mrCellChange(recordId,field,value){if(!db.matrizRiesgos)db.matrizRiesgos={};var m=mrGetData(recordId);m[field]=value;if(['mercancia','tipoPersona','tiempo','capital','frecuencia','facturacion','cert','anFin'].indexOf(field)>=0){m.puntaje=mrCalcPuntaje(m);m.riesgo=mrCalcRiesgo(m.puntaje);if(!m._controlManual){var auto=mrAutoControl(m.riesgo);m.control=auto.control;m.frecControl=auto.frecControl;}}if(field==='control')m._controlManual=!!value;try{save();}catch(e){}renderMatrizRiesgos();}
function renderMrDatos(){var tbody=document.getElementById('mr-datos-tbody');if(!tbody)return;var DATOS=[{m:'Textiles',p:4,c:'Crítico',dian:'$16.000M decomisos 2026',rp:'Narcóticos fardos porosos'},{m:'Farmacéuticos',p:4,c:'Crítico',dian:'$16.000M decomisos 2026',rp:'Falsificación INVIMA'},{m:'Tecnología',p:5,c:'Crítico',dian:'80.000 artículos Buenaventura',rp:'Hurto organizado'},{m:'Dispositivos Médicos',p:5,c:'Crítico',dian:'Regulamentado INVIMA',rp:'Falsificación sanitaria'},{m:'Cosméticos',p:5,c:'Crítico',dian:'Precursores químicos [DIAN Res. 45/2018]',rp:'Líquidos cocaína frascos'},{m:'Juguetería',p:5,c:'Crítico',dian:'$16.000M decomisos 2026',rp:'Plásticos huecos narcóticos'},{m:'Electrodomésticos',p:4,c:'Alto',dian:'$330.000M contrabando',rp:'Hurto componentes'},{m:'Repuestos automotrices',p:4,c:'Alto',dian:'Contrabando piezas',rp:'Mercado negro autopartes'},{m:'Herramientas',p:4,c:'Alto',dian:'Hurto reventa informal',rp:'Alta liquidez mercado negro'},{m:'Calzado',p:4,c:'Alto',dian:'1M pares medias China',rp:'Cocaína suelas'},{m:'Industrial',p:3,c:'Medio',dian:'Daños estructura',rp:'Maquinaria pesada'},{m:'Consumo masivo',p:3,c:'Medio',dian:'Contaminación cruzada',rp:'Volumen masivo'},{m:'Accesorios',p:3,c:'Medio',dian:'Hurto acumulativo',rp:'Joyería pequeña'},{m:'Decoración',p:3,c:'Medio',dian:'Roturas',rp:'Frágil valor estético'},{m:'Hogar y cocina',p:3,c:'Medio',dian:'Hurto doméstico',rp:'Utensilios reventa'},{m:'Misceláneos',p:2,c:'Medio - Bajo',dian:'Daños manipulación',rp:'Carga general'},{m:'Alimentos secos',p:2,c:'Medio - Bajo',dian:'ICA básico',rp:'Arroz/pastas'},{m:'Bebidas',p:2,c:'Medio - Bajo',dian:'Derrames',rp:'Envases líquidos'},{m:'Papelería',p:2,c:'Medio - Bajo',dian:'Hurto mínimo',rp:'Bajo valor unitario'},{m:'Material POP',p:2,c:'Medio - Bajo',dian:'Daños',rp:'Bajo valor ilícito'}];var CC={'Crítico':'#ef4444','Alto':'#f87171','Medio':'#f59e0b','Medio - Bajo':'#94a3b8'};var FREQS=[{cat:'Bajo',ops:'<20',pond:1},{cat:'Medio',ops:'20-49',pond:3},{cat:'Alta',ops:'>50',pond:5}];var FACTS=[{cat:'Bajo',cop:'<100M',pond:1},{cat:'Medio',cop:'101M-300M',pond:3},{cat:'Alta',cop:'>300M',pond:5}];var CERTS=[{cat:'Sí (BASC/OEA)',pond:-1},{cat:'No',pond:0}];var ANFIN=[{cat:'Desfavorable',pond:1},{cat:'Favorable',pond:-0.5}];tbody.innerHTML=DATOS.map(function(d,i){var cc=CC[d.c]||'#94a3b8';var pc=d.p>=5?'#ef4444':d.p>=4?'#f87171':d.p>=3?'#f59e0b':'#94a3b8';var freq=FREQS[i]||{cat:'',ops:''};var fact=FACTS[i]||{cat:'',cop:''};var cert=CERTS[i]||{cat:'',pond:''};var anf=ANFIN[i]||{cat:'',pond:''};return '<tr style="border-bottom:1px solid var(--border)"><td style="padding:8px 12px;font-size:12px;font-weight:600;color:var(--text);border-right:1px solid var(--border);white-space:nowrap">'+d.m+'</td><td style="padding:8px 12px;text-align:center;font-family:Barlow Condensed,sans-serif;font-size:18px;font-weight:800;color:'+pc+';border-right:1px solid var(--border)">'+d.p+'</td><td style="padding:8px 12px;text-align:center;border-right:1px solid var(--border)"><span style="font-size:11px;font-weight:700;color:'+cc+'">'+d.c+'</span></td><td style="padding:8px 12px;font-size:11px;color:var(--text2);border-right:1px solid var(--border);max-width:150px;white-space:normal;line-height:1.3">'+d.dian+'</td><td style="padding:8px 12px;font-size:11px;color:var(--text2);border-right:2px solid var(--border);max-width:150px;white-space:normal;line-height:1.3">'+d.rp+'</td><td style="padding:8px 12px;font-size:12px;color:var(--text);border-right:1px solid var(--border);white-space:nowrap">'+freq.cat+'</td><td style="padding:8px 12px;font-size:12px;color:var(--text2);text-align:center;border-right:2px solid var(--border)">'+freq.ops+(freq.cat?' <span style="font-size:10px">('+freq.pond+')</span>':'')+'</td><td style="padding:8px 12px;font-size:12px;color:var(--text);border-right:1px solid var(--border);white-space:nowrap">'+fact.cat+'</td><td style="padding:8px 12px;font-size:12px;color:var(--text2);border-right:2px solid var(--border);white-space:nowrap">'+fact.cop+(fact.cat?' <span style="font-size:10px">('+fact.pond+')</span>':'')+'</td><td style="padding:8px 12px;font-size:12px;color:var(--text);border-right:1px solid var(--border);white-space:nowrap">'+cert.cat+'</td><td style="padding:8px 12px;text-align:center;font-family:Barlow Condensed,sans-serif;font-size:16px;font-weight:800;border-right:2px solid var(--border);color:'+(cert.pond<0?'#34d399':'#94a3b8')+'">'+(cert.cat!==''?cert.pond:'')+'</td><td style="padding:8px 12px;font-size:12px;color:var(--text);border-right:1px solid var(--border);white-space:nowrap">'+anf.cat+'</td><td style="padding:8px 12px;text-align:center;font-family:Barlow Condensed,sans-serif;font-size:16px;font-weight:800;color:'+(anf.pond>0?'#f87171':anf.pond<0?'#34d399':'#94a3b8')+'">'+(anf.cat!==''?(anf.pond>0?'+'+anf.pond:anf.pond):'')+'</td></tr>';}).join('');}
function initMRScrollSync(){
  var wrap=document.getElementById('mr-table-wrap'),track=document.getElementById('mr-scroll-track'),inner=document.getElementById('mr-scroll-inner');
  if(!track||!inner) return;
  // Sync whichever wrap is visible
  function getActiveWrap(){ return document.getElementById('mr-panel-datos').style.display!=='none' ? document.getElementById('mr-datos-wrap') : document.getElementById('mr-table-wrap'); }
  function updateInner(){ var w=getActiveWrap(); if(w&&inner) inner.style.width=w.scrollWidth+'px'; }
  updateInner();
  if(!track._mrSync){
    track._mrSync=true;
    track.addEventListener('scroll',function(){ var w=getActiveWrap(); if(w) w.scrollLeft=track.scrollLeft; });
  }
  if(wrap&&!wrap._mrSync){ wrap._mrSync=true; wrap.addEventListener('scroll',function(){track.scrollLeft=wrap.scrollLeft; updateInner();}); }
  var dw=document.getElementById('mr-datos-wrap');
  if(dw&&!dw._mrSync){ dw._mrSync=true; dw.addEventListener('scroll',function(){track.scrollLeft=dw.scrollLeft; updateInner();}); }
}

